// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":47,"question":"آيات في القرآن الكريم تتحدث بأن أولادنا ونساءنا فتنة، فإذا أحس الرجل بأن زوجته تلهيه عن الذكر، وتريده دائمًا بجوارها مما يجعل جهده في الدعوة وفي تحصيل العلم قليلًا؛ ولكنها في نفس الوقت تصلي وتصوم وتحفظه في ماله وعرضها، فما السبيل لإصلاح شأنها؟ وإن لم يكن هناك صلاح، فهل أطلِّقها حفاظًا على ديني وجهدي في سبيل الله؟ علما بأن لدي منها ولدًا.","title":"كيف السبيل لتجنب فتنة الزوجات والأولاد؟","answer":"الجواب: لكل داء له دواء يا ولدي، يقول النبي ﷺ، فإذا كانت الزوجة صالحة طيبة فإنها لن تشغلك إن شاء الله عن الخير، وإنما تشغلك إذا كانت غير صالحة.\nأما الصالحة فإذا ما بيّنت لها حاجاتك عذرتك وقنعت، يقول الرب جلَّ وعَلا: إِنَّ مِنْ أَزْوَاجِكُمْ وَأَوْلادِكُمْ عَدُوًّا لَكُمْ فَاحْذَرُوهُمْ [التغابن:14]، فإذا كانت الزوجة تعينك على المعاصي، والولد يعينك على المعاصي ويمنعك من الواجب، فهؤلاء أعداء؛ خالفهم وجاهدهم حتى تسلم من شرهم، ويقول سبحانه: إِنَّمَا أَمْوَالُكُمْ وَأَوْلادُكُمْ فِتْنَةٌ [التغابن:15] يعني: اختبار، الفتنة هذه اختبار وامتحان، الله اختبر الناس بأولادهم وأموالهم، فإذا أطاعوا أولادهم في الباطل، وأطاعوا أموالهم واشتغلوا بها في الباطل؛ فهذا شَرٌّ عليهم، وإذا استعانوا بالمال فيما ينفعهم، وفي طاعة الله؛ صار خيرًا في حقهم، وهكذا الأولاد، إن طاوعتهم في الباطل، وأخذت برأيهم في الباطل والحرام؛ صاروا شرًا عليك وعدوًا لك، وإن أخذت على أيديهم، وجاهدتهم في الله، وعلمتهم الخير، ومنعتهم من الشر؛ صرت سببًا لسعادتهم، وسببًا لنجاتهم، وسلمت من شرهم وفتنتهم.\nالفتنة: الاختبار والامتحان، المال فتنة، والولد فتنة، فاحذر هذه الفتنة، واستعن بها على طاعة الله، واحذر أن يصدّك المال أو الأولاد عن طاعة الله، كما قال الله تعالى: وَابْتَغِ فِيمَا آتَاكَ اللَّهُ الدَّارَ الْآخِرَةَ وَلا تَنْسَ نَصِيبَكَ مِنَ الدُّنْيَا وَأَحْسِنْ كَمَا أَحْسَنَ اللَّهُ إِلَيْكَ [القصص:77].\nوالزوجة الصالحة المطيعة لله لا تُطلَّق، بل تُكرم، ويُعتنى بها، ويحتفظ بها، وإذا أرادت بقاءك عندها فهذا من حبها لك، ومن حرصها عليك، فأقنعها بالأشياء التي تحتاج إليها، حتى تذهب للصلاة، وتذهب لطلب العلم، وتذهب للدعوة إلى الله، وللمصالح العامة، تقنعها وتبّين لها المصالح؛ حتى تكون على بينة، وحتى تقتنع بهدفك الطيب، وأعمالك الجميلة.","link":"https://binbaz.org.sa/fatwas/2827/كيف-السبيل-لتجنب-فتنة-الزوجات-والاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0020.mp3","categories":["الحقوق الزوجية"]},{"id":311,"question":"فضيلة الشيخ، إنني ولله الحمد من النِّساء اللاتي تفضّل الله عليهنَّ بالهداية إلى طريقه المُستقيم، وكذلك أنعم عليَّ بالزواج من شابٍّ كذلك من المُهتدين ولله الحمد، ومشكلتي التي أريد عرضها عليكم يا سماحة الشيخ هي أن زوجي كثيرًا ما يغضب عليَّ لأسبابٍ تافهةٍ أحيانًا، وأحيانًا تستحق الغضب، ونتيجة لكثرة هذا الغضب منه لم أتحمل البقاء معه، وخرجتُ من بيتي، ولم أعد إليه إلى الآن، ولكني بعد خروجي من بيت زوجي أنَّبَنِي الكثير من الصَّديقات، ونصحنني بالعودة بقولهنَّ: إنَّكِ آثمةٌ، وأن الملائكة تلعنُكِ إلى أن تُرضي زوجك، وأنا الآن في حيرةٍ من أمري: هل أتنازل وأذهب إلى بيتي وأتحمّل كل المآسي أم أبقى في بيت أهلي وأنتظر ورقةَ طلاقي؟","title":"ما النصيحة فيما يقع بين الزوجين من خلاف؟","answer":"الجواب: الذي أنصحك به العودة ما دام الله قد هداه إلى الإسلام، وهو طيب، وأنت كذلك طيبة، فاحمدي الله على ذلك، وكل إنسانٍ عنده تقصير، وعنده غلط، وعنده غضب، ما في الدنيا زوجٌ سالمٌ ما يغضب أبدًا ولا يحصل منه شيءٌ، كلٌّ فيه نقصٌ: كل بني آدم خطَّاء.\nفالواجب عليك أن ترجعي إلى بيته، وأن تُعامليه بالتي هي أحسن، وأن تكوني طيبة الأخلاق متحمّلةً لهذا الأمر، وأن تحرصي على الكلام الطيب الذي يُزيل عنه الغضب، يُخفف عنه الغضب، احرصي على الكلام الطيب، واللين في الكلام، والتماس أسباب رضاه، والحرص على ذلك، وأبشري بالخير والعاقبة الحميدة: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].\nهذه نصيحتي لك: العودة والحرص على بذل الأسباب التي تُرضيه عنك وتجعله دائمًا على حالٍ حسنةٍ، وعلى بِشْرٍ، وعلى كلامٍ طيبٍ، ومتى فعلت ما تستطيعين من الخير والتَّحمل والأسلوب الحسن والكلمات الطيبة ضدّ كلامه الشديد؛ فإنَّ العاقبة تكون لك إن شاء الله، وهو يهديه الله.","link":"https://binbaz.org.sa/fatwas/4314/ما-النصيحة-فيما-يقع-بين-الزوجين-من-خلاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0361.mp3","categories":["الحقوق الزوجية","المشكلات الزوجية"]},{"id":562,"question":"ضرب الوجه حرام في المرأة وغيرها؟","title":"ما حكم ضرب الوجه؟","answer":"الجواب: نعم، حتى في الدابة يَحْرُم ضرب الوجه مطلقًا، يقول ﷺ: إذا ضرب أحدكم فليتق الوجه في الدابة وفي غيرها، وفي المرأة والولد والخادم.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6393/ما-حكم-ضرب-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/maram128 - 02 - .mp3","categories":["الحقوق الزوجية"]},{"id":566,"question":"قوله: وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا بَيْنَ النِّسَاءِ وَلَوْ حَرَصْتُمْ [النساء:129]؟","title":"معنى {وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا بَيْنَ النِّسَاءِ}","answer":"الجواب: يعني العدل الكامل.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6397/معنى-ولن-تستطيعوا-ان-تعدلوا-بين-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/maram132 - 01 -  Start.mp3","categories":["الحقوق الزوجية"]},{"id":567,"question":"هل من العِشْرة أن يهدد أم الأولاد: إما أن تتنازلي عن ليلتك ونفقتك وإلا طلقتك؟","title":"حكم تخيير الزوجة بين منع نفقتها أو الطلاق","answer":"الجواب: له هذا، ما فيه شيء إذا خيَّرها، إن شاءت صبرت وإن شاءت طلقها.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6398/حكم-تخيير-الزوجة-بين-منع-نفقتها-او-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/maram133 - 01 -  Start.mp3","categories":["الحقوق الزوجية"]},{"id":568,"question":"بعض الأزواج إذا تزوج حديثًا أهمل الزوجة الأولى؟","title":"بم يُنصح من يهمل زوجته الأولى؟","answer":"الجواب: يُنصح ويُوجّه إلى الخير.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6399/بم-ينصح-من-يهمل-زوجته-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/maram134 - 01 -  Start.mp3","categories":["الحقوق الزوجية"]},{"id":571,"question":"في غضب الله  من الزوجة يبدأ بالهجر أم يضرب؟","title":"حكم تأديب الزوج زوجته لمعصيتها لله؟","answer":"الجواب: هذا غير النشوز، المعصية في حق الله ما هي في حق الزوج، إذا رأى تأديبها لأجل المعصية فلا بأس، لكن يكون تأديبًا يُرجى فيه النفع.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6402/حكم-تاديب-الزوج-زوجته-لمعصيتها-لله","audio":"https://files.zadapps.info/binbaz.org.sa/maram137 - 01 -  Start.mp3","categories":["الحقوق الزوجية"]},{"id":573,"question":"ضرب المرأة ضربًا مُبَرِّحًا يأثم به الرجل؟","title":"هل يأثم الرجل بضرب امرأته ضربًا مُبَرِّحًا؟","answer":"الجواب: نعم، نص عليه النبي ﷺ: فاضربوهن ضربًا غير مُبَرِّح لما خطب الناس في الحج عليه الصلاة والسلام.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6404/هل-ياثم-الرجل-بضرب-امراته-ضربا-مبرحا","audio":"https://files.zadapps.info/binbaz.org.sa/maram139 - 01 -  Start.mp3","categories":["الحقوق الزوجية"]},{"id":984,"question":"ما السَّبيل إلى إصلاح زوجةٍ لا تعترف بالحقوق الزوجية، وتُعامل زوجها معاملةَ الخادم، مع الألفاظ النَّابية، مع أنها تقرأ القرآن، وتُصلي، وتصوم، وهي متحجبة، وتتجنب سماع المعازف؟ أفيدونا جزاكم الله خيرًا.","title":"ما السبيل لنصح النساء بشأن حقوق الزوج؟","answer":"الجواب: هذه خصال طيبة فيها، وإنما التقصير في حقِّك، فعليك أن تُعالج حقَّك بالحكمة، والكلام الطيب، والأسلوب الحسن، وإعطائها ما يُرضيها إن كانت تدَّعي أنك مُقصِّر في حقِّها حتى ترضى عنك، وحتى تُعاملك بالتي هي أحسن؛ لأنَّ هذه فيها خير، فيها دين، فإذا عالجتها بالتي هي أحسن إن شاء الله ترجع إلى الصواب، وتستقيم.\nفعليك..... والكلام الطيب، والحلم، والأسلوب الحسن، والبذل بالمال والسَّخاء وعدم البخل، وأبشر بالخير إن شاء الله.\nوإذا استعنتَ بأبيها أو بأخيها لإصلاحها فلا بأس، أما إن كان ذكرُك لأخيها أو لأبيها يزيدها شرًّا فلا تذكر لهما شيئًا، ولكن بينك وبينها، وعليك بالكلام الطيب، والحلم، والأسلوب الحسن، وإرضائها بالمال، وتخويفها من الله جلَّ وعلا، وإخبارها بأنَّ الواجب عليها أن تقوم بحقِّك، وأن تُعاملك بالتي هي أحسن، اعمل ما تستطيع من الكلام الطيب، وإذا لم ينفع كل شيءٍ ما يبقى إلا الطلاق.","link":"https://binbaz.org.sa/fatwas/21024/ما-السبيل-لنصح-النساء-بشان-حقوق-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0821ما السبيل إلى اصلاح زوجة لاتعترف بالحقوق الزوجية مع أنها تقرأ القرآن وتصلي وتصوم؟ ابن باز.mp3","categories":["الحقوق الزوجية"]},{"id":991,"question":"ما حكم الدين في زوجٍ لا يطأ زوجته إلا قليلًا جدًّا، ولو وطأها يكون كارهًا لهذا الوطء، علمًا بأن الزوجة سوف يلحقها ضررٌ من هذا؟ جزاكم الله خيرًا.","title":"حكم الزوج الذي لا يطأ زوجته إلا قليلًا جدًّا","answer":"الجواب: ما دام يطؤها فالحمد لله، ولو بتكرُّهٍ، أما إذا امتنع من وطئها وأبى أن يطأها فهذا يرجع فيه إلى المحكمة إذا لم يتراضيا على الصلح في فراقها، أو يُعطيها شيئًا يُرضيها عنه، أو يصطلحان على فراقٍ بأن تُعطيه مهرها أو شيئًا منه ويُفارق، هذه المسائل بين المرأة وزوجها: إمَّا أن يصطلحا، وإما أن يرتفعا إلى الحاكم.\nوإذا كان معذورًا ليس له قدرة فالحاكم ينظر في الأمر، وإن كان قادرًا فالواجب عليه أن يطأها ويعفَّها، وليس له أن يُضارّ بها، ولو قصد الضِّرار أُلزم، والله جلَّ وعلا أمر بإنظار المولي أربعة أشهرٍ؛ الذي يحلف ألا يطأ زوجتَه الله أمهله أربعة أشهرٍ، قال سبحانه: لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِنْ فَاءُوا فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ  ۝  وَإِنْ عَزَمُوا الطَّلَاقَ فَإِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ [البقرة:226- 227]، فيُنْظَر أربعة أشهرٍ، فإن وفّى وجامع وإلا أُلزم بالطلاق.\nفهذه المرأة التي زوجها لا يطؤها إلا قليلًا هي مخيَّرة بين الصبر والانتظار؛ لعلَّ الله يشفيه، لعله يزول عنه إن كان به مرضٌ، وهو أيضًا يجب عليه أن يعتني بالأمر إذا كان في إمكانه شيءٌ من الدواء والعلاج؛ لعله يحصل المقصود من إعفافه زوجته، فإن لم يتيسر ذلك فهذا يرجع فيه إلى المحكمة؛ لأنَّ التفصيل في هذا الأمر والنظر في هذا الأمر يُزيل الضَّرر إذا لم تصبر المرأةُ، ولم يحصل من الزوج ما يُقنعها من مالٍ يُعطيها إياه، أو غير ذلك مما يُقنعها.","link":"https://binbaz.org.sa/fatwas/21045/حكم-الزوج-الذي-لا-يطا-زوجته-الا-قليلا-جدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0841ما وى حكم الشرع في زوج لا يجامع زوجته إلا قليلاً جداً؟ ابن باز فتاوى المحضرات.mp3","categories":["الحقوق الزوجية"]},{"id":1045,"question":"ما حكم جماع الرجل لزوجته بعد عقد النكاح وهي في بيت أهلها؟","title":"حكم جماع المعقود عليها قبل الدخول بها","answer":"الجواب: ينبغي له ألا يُجامعها حتى يحصل البناء بها، والدخول بها؛ لأنَّ هذا الجماع في الغالب يكون شرًّا، ويُخشى منه عواقب وخيمة: أن تُتَّهم بأنها زانية، أو يجحد هو، المقصود أنَّ هذا خطرٌ، فينبغي له ألا يُجامعها إلا بعد الدخول بها، ولو كان قد عقد عليها، إلا إذا كان ذلك عن علمٍ من أهلها، عن شيءٍ واضحٍ، يعني: فعله عند أهلها، أو أدخلوها عليه يعلمون ذلك، فالأمر أسهل، ولكن الصبر حتى يدخل بها، وحتى يكون الدخولُ المشهور، والإعلان المشهور، هذا هو الذي ينبغي، حتى لا تقع فتنةٌ، وحتى لا يقع ما لا تُحمد عُقباه: من جحده، أو اتِّهامها بالفاحشة.\nفالذي أراه أنه لا ينبغي أبدًا إلا على الوجه الذي عرفه الناسُ، وهو الدخول بها والإعلان.","link":"https://binbaz.org.sa/fatwas/21078/حكم-جماع-المعقود-عليها-قبل-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0874ما حكم جماع الرجل زوجته بعد عقد النكاح وقبل الدخول بها وهي عند أهلها؟ ابن باز فتاوى المحاضرات.mp3","categories":["الحقوق الزوجية"]},{"id":1103,"question":"يوجد لدي زوجة، وعندي منها أربعة أولاد، وأنا لا أحبها، ولم يمنعني من طلاقها سوى الأولاد، وخوفًا أن أرتكب ذنبًا في حقِّها، وأنا أُؤدي واجباتها الزوجية: من لبسٍ وأكلٍ وغير ذلك، لكن لم أكن مُرتاحًا معها، وقد لاحظتْ عليَّ ذلك، وأنا أحاول حبّها ولكن لم أستطع منذ عدَّة سنوات، أما هي فتُحبني وتُقدّم واجباتها كزوجةٍ، أفيدونا عن ذلك جزاكم الله خيرًا.","title":"ما يفعل من لا يحب زوجته وله منها أولاد؟","answer":"الجواب:\nإذا رحمتها وصبرتَ عليها فأنت مأجورٌ، والله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، والنبي ﷺ يقول: الراحمون يرحمهم الرحمن، ارحموا مَن في الأرض يرحمكم مَن في السماء، فإذا صبرتَ عليها، واجتهدتَ في أداء حقِّها، وإظهار المحبَّة لها، والرفق، وإعطاء حق العشرة؛ فأنت مأجورٌ على ذلك. وإن لم تستطع وطلَّقتها فلا بأس، إذا رأيتَ أن تُطلقها طلِّقها طلقةً واحدةً، وهي تحفظ أولادها، وتقوم على أولادها، وتجعل أولادها عندها، وتُنفق عليهم، وترحمهم، وتعطف عليهم، لا بأس بذلك، أنت مُخَيَّرٌ. لكن إذا استطعتَ أن ترحمها ما دامت تُحبُّك، وتعطف عليها، وتُبقيها في حبالك، وتؤدي ما استطعتَ، وإذا عجزتَ عن شيءٍ تقول لها: يا فلانة، أنا عاجزٌ عن هذا الشيء، سامحيني وإلا طلّقتُكِ، إن كنتَ تُريد ألا تَقْسِم لها، إن كانت عندك زوجة أخرى وتريد أن تزورها في النهار أو في الليل، لكن ما تبيتُ عندها، تقول: يا فلانة، إن سامحتني فلا بأس، وإن أردتِ الطلاقَ فلا بأس، تُخيِّرها، وإلا فاصبر وأعطها حقَّها كاملًا وارحمها، وأنت مأجورٌ.","link":"https://binbaz.org.sa/fatwas/21148/ما-يفعل-من-لا-يحب-زوجته-وله-منها-اولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0944مسألة في العلاقات الزوجية؟ ابن باز فتاوى المحاضرات.mp3","categories":["الحقوق الزوجية"]},{"id":1121,"question":"زوجة كتبها زوجها ناشزًا منذ أربعة وعشرين عامًا، وكانت حاملًا بالشهر الثالث، ولم يسأل عنها ولا الطفلة التي أنجبتها إلى هذا اليوم، هل الزوجة تُعتبر على ذمَّته أم أنها مُطلَّقة؟ وهل يقع التَّوارث بينهما؟ أفيدونا أثابكم الله، علمًا بأنه لم يدفع نفقةً: لا للزوجة، ولا للبنت.","title":"حكم من كتبها زوجها ناشزًا وتركها مُعلَّقة","answer":"الجواب:\nهذه المسألة تبع المحاكم، ولا يجوز أن تبقى المرأةُ هكذا مُعلَّقة، يجب: إما أن يستقيما، وإما أن يُفرَّق بينهما، هذا واجب المحكمة، أما أن تجلس أربعًا وعشرين سنةً أو عشر سنين أو خمس سنين؛ هذا منكر لا يجوز، هذا لأنَّ الواجب الإصلاح بينهما، فإن لم يستقيما ولم يصلحا فرّق بينهما، دفعت إليه مهره إن كانت لا تُريده وطلَّقها؛ لأنَّ ثابت بن قيس  لما اختلف مع زوجته ولم يكتب الله له المودة في قلبها أمرها النبيُّ ﷺ أن تُعطيه مهره، وقال: اقبل الحديقةَ، وطلِّقْها تطليقة.\nفالواجب على المحاكم النظر في هذا، وعندهم التعليمات في هذا، فإذا رفعت المرأةُ إلى المحكمة حاجتها وحالها مع زوجها، فالمحكمة تنظر في الأمر.\nأما إذا أحبت عدم الفسخ، وأن تبقى على نشوزها، وتركها الزوجُ؛ فهذا إليهما، لكن جلوسها هكذا لا ينبغي؛ لأنَّ هذا خطرٌ عظيمٌ -جلوسها بدون زوجٍ وبدون نفقةٍ- لأنه قد يضرُّها كثيرًا.\nفالحاصل أنَّ هذا يتعلق بالمحكمة، وفي إمكان المرأة أن تُراجع المحكمة فيما يتعلق بالنَّفقة والإرث وغير ذلك.","link":"https://binbaz.org.sa/fatwas/21183/حكم-من-كتبها-زوجها-ناشزا-وتركها-معلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0979زوجة كتبها زوجها ناشز منذ أربعة وعشرين عاماً وكانت حاملاً ولم يسأل عنها إلى هذا اليوم فما حكمها؟.mp3","categories":["الحقوق الزوجية"]},{"id":1208,"question":"ما رأيكم في أمٍّ تذهب مع ولدها دون إذن زوجها؟ أفيدونا جزاكم الله خيرًا.","title":"حكم خروج المرأة مع ولدها دون إذن زوجها","answer":"الجواب:\nليس للمرأة أن تذهب إلا بإذن زوجها، ليس لها أن تذهب لا مع ولدها ولا مع أخيها ولا مع أبيها ولا مع غيرهم إلا بإذن زوجها، إن أذن لها وأعطاها الإذنَ فلا بأس، إلا للضَّرورة، مثل: ما عندها عيشة، ولا استطاعت، ما أعطاها أكلًا؛ تخرج وتأكل، فهو المقصِّر هو، أو كان هجم عليها عدوٌّ فخرجت خوفًا من العدو، أو مَن يريدها في نفسها فهربت من البيت خوفًا من الفاحشة، أو من الظلم؛ لا بأس للضَّرورة، وأما أن تخرج بغير ضرورةٍ: تروح مع أبيها، أو مع أخيها، لا تخرج إلا بإذنه، إذا قال: لا بأس؛ تخرج، وإلا فلا تخرج إلا بإذنه، إلا بضرورةٍ لا حيلةَ فيها.","link":"https://binbaz.org.sa/fatwas/21261/حكم-خروج-المراة-مع-ولدها-دون-اذن-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1133ما رأيكم في أم تذهب مع ولدها بدون أذن زوجها؟ ابن باز فتاوى.mp3","categories":["قضايا المرأة","مسائل متفرقة في الصيام","الحقوق الزوجية"]},{"id":1504,"question":"الضابط في كذب الزوجة على زوجها أو الزوج على زوجته؟","title":"ما الضابط في الكذب بين الزوجين؟","answer":"الجواب:\nمثلما سمعت، يعني فيما يتعلق بهما، لا يضر الناس الآخرين، من باب: سأعطيكِ كذا، وأفعل لكِ كذا، وهي تقول: أبشر بالخير، أنا ما أخالفك، ولا أعصي لك أمرًا، ولا أفعل، ولا أفعل، فتُرضيه.\nس: طيب، لو وعد الزوجة أن يشتري لها شيئًا وأخلف وعده؟\nج: هذا من الكذب، أو وعدته وأخلفت؛ فكذلك.\nس: يعني: هذا لا بأس به؟\nج: لا بأس به بينهما خاصة. ما يتعلق بالناس الآخرين.\nس: حمل بعضُ العلماء كذب الرجل على امرأته والعكس على التورية؟\nج: لا، الكذب الصريح ما فيه بأس، وأيش يضر بينهما؟! هي تقول مثلًا: ابحث لنا عن بيتٍ غير هذا البيت، فيقول لها: سوف نشتري بيتًا أصلح من هذا، أعطني كذا، أعطني اللباس الفلاني، وهو يقول: إن شاء الله أبشري، فقط أمهليني وأنا أشتري إن شاء الله، وهكذا، وهو ناوٍ ألا يُسَوِّي شيئًا.\nس: يكون مثل المماطلة؟\nج: لا، ما هو مماطلة، يكذب أنه سيفعل هذا الشيء وما هو بفاعله، فقط لتظن أنه سيفعل؛ حتى ترضى وتزول الشحناء التي بينهم في الوقت الحاضر.","link":"https://binbaz.org.sa/fatwas/21603/ما-الضابط-في-الكذب-بين-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضابط كذب الزوجة على زوجها أو الزوج على زوجته.mp3","categories":["الحقوق الزوجية"]},{"id":1544,"question":"كيفية الهجر بالنسبة للزوجة؟","title":"كيف يكون هجر الزوج لزوجته؟","answer":"الجواب:\nمثلما جاء: ولا تهجر إلا في البيت إذا أعطاها قفاه، هذا هجر، وإذا هجرها بالكلام ثلاثة أيام؛ فهذا هجر، ولا يزيد على ثلاثة أيام في الكلام، فالهجر في الكلام ثلاثة أيام فأقل.  وأما في الفعل فكونه يُعطيها ظهره أو يحصل بعض التَّكدر عليها حتى تتأدَّب ما يُخالف، فالنبي ﷺ هجر نساءه شهرًا واعتزلهنَّ.","link":"https://binbaz.org.sa/fatwas/21645/كيف-يكون-هجر-الزوج-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هجر الزوج لزوجته.mp3","categories":["الحقوق الزوجية"]},{"id":1545,"question":"بعض العائلات تتدخل في أمورٍ ما بين الزوج والزوجة، يعني مثلًا: أهل الزوج، أو أهل الزوجة؟","title":"حكم التدخل العائلي بين الزوج والزوجة","answer":"الجواب:\nالتدخل بالخير ما فيه بأس، التدخل بالنصيحة. أما التدخل بالمشاغبة والتحريض على الشر فلا يجوز، لكن التدخل بالكلام الطيب والمشورة والنصيحة هذا أمرٌ مطلوبٌ.","link":"https://binbaz.org.sa/fatwas/21646/حكم-التدخل-العاىلي-بين-الزوج-والزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في العلاقات الأسرية.mp3","categories":["الحقوق الزوجية"]},{"id":1547,"question":"{التي} في سورة المجادلة هل تعني أنه خلاف عادي بين الزوج والزوجة أو خلاف طلاق؟","title":"معنى الجدال الذي جاء في سورة المجادلة","answer":"الجواب:\nتجادل في زوجها أنه فعل وأنه فعل، ثم جرى ما جرى من الظهار، المقصود أن الزوج يكون عنده حلم وصبر وتَحَمُّل، ولو مع المجادلة، لا يعجل في الظهار، ولا يعجل في الطلاق، يكون عنده حلم وصبر، فلا يُحَرِّم ولا يُطَلِّقْ، يكون عنده تَحَمُّل ولا يضرب.","link":"https://binbaz.org.sa/fatwas/21648/معنى-الجدال-الذي-جاء-في-سورة-المجادلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فائدة اجتماعية من سورة المجادلة.mp3","categories":["الحقوق الزوجية","المشكلات الزوجية"]},{"id":1552,"question":"إذا هجرت الزوجةُ فراشَ زوجها هل للزوج ضربها؟","title":"ما حكم ضرب الزوجة إذا هجرت الفراش؟","answer":"الجواب:\nله ضربها ضربًا غير مبرح، وله هجرها أيضًا، له هجرها وله ضربها، لكن ضربًا غير مبرح، خفيف.","link":"https://binbaz.org.sa/fatwas/21653/ما-حكم-ضرب-الزوجة-اذا-هجرت-الفراش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضرب الزوجة إذا هجرت الفراش.mp3","categories":["الحقوق الزوجية"]},{"id":1558,"question":"ما ورد في سنة النبي ﷺ من جواز ضرب المرأة؟","title":"ما الذي جاء في السُّنة بشأن ضرب المرأة؟","answer":"الجواب:\nما أعرف إلا ما جاء في القرآن، فالقرآن نصَّ على هذا: وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ [النساء:34]، والنبي ﷺ قال: لهنَّ عليكم رزقهنَّ وكسوتهنَّ بالمعروف، ولكم عليهنَّ ألا يُوطئن فرشَكم مَن تكرهون، وألا يأذَنَّ في بيوتكم لمن تكرهون، فإن فعلن فاضربوهنَّ ضربًا غير مبرِّحٍ يعني: غير شديدٍ، يحصل به التأديب، ولكن لا يحصل به الخطر.","link":"https://binbaz.org.sa/fatwas/21660/ما-الذي-جاء-في-السنة-بشان-ضرب-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ورد عن النبي شيء في جواز ضرب المرأة.mp3","categories":["الحقوق الزوجية"]},{"id":1560,"question":"هل على الرجل من طاعةٍ إذا هي دعته؟","title":"إذا دَعَت المرأة زوجها فهل عليه طاعتها؟","answer":"الجواب:\nعليه أن يجتهد في عفتها، لا يلزمه طاعتها، لكن عليه أن يجتهد في عفتها؛ حتى لا تقع الكارثة.","link":"https://binbaz.org.sa/fatwas/21662/اذا-دعت-المراة-زوجها-فهل-عليه-طاعتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا دعت المرأة زوجها فهل عليه طاعتها.mp3","categories":["الحقوق الزوجية"]},{"id":1857,"question":"حكم المرأة عند سفر زوجها ألا تصوم؟","title":"حكم صيام المرأة حال سفر زوجها دون إذن","answer":"الجواب:\nتصوم.\nس: تصوم ولا تستأذن؟\nج: الرسول ﷺ قال: وزوجها شاهد يعني: حاضر، أما إذا كان غائبًا فلا تحتاج إلى إذنٍ، تصوم تطوُّعًا ولا بأس.","link":"https://binbaz.org.sa/fatwas/21966/حكم-صيام-المراة-حال-سفر-زوجها-دون-اذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قضاء الصيام عند المرأة في سفره.mp3","categories":["صيام التطوع","الحقوق الزوجية"]},{"id":1860,"question":"بعض الأزواج يمنعون زوجاتهم من صيام التطوع؟","title":"حكم منع الزوج زوجته من صيام التطوع","answer":"الجواب:\nلا بأس عليهم، هو محتاج لها، يستمتع بها، فإذا منعها فلا بأس تمتنع.\nس: بعضهم يكون مسافرًا؟\nج: لا، إذا كان مسافرًا فليس له حقّ.\nس: يقول: لصحتك وجمالك وكذا لا تصومي؟\nج: لا، ما له حقّ، إذا سافر لها أن تصوم؛ بنصِّ الحديث.","link":"https://binbaz.org.sa/fatwas/21969/حكم-منع-الزوج-زوجته-من-صيام-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم منع الزوج لزوجته من صيام التطوع.mp3","categories":["صيام التطوع","الحقوق الزوجية","قضايا المرأة"]},{"id":1861,"question":"بعض الأزواج يسكنون في بيوت زوجاتهم، فهل له أن يمنع مَن شاء ويأذن لمَن شاء؟","title":"ما سلطانُ الرجل لو كان يسكن ببيت زوجته؟","answer":"الجواب:\nنعم، ولو كان البيتُ لها؛ لأنَّ السلطانَ له.","link":"https://binbaz.org.sa/fatwas/21970/ما-سلطان-الرجل-لو-كان-يسكن-ببيت-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ولاية الرجل على زوجته حتى وإن كان يسكن في بيتها.mp3","categories":["الحقوق الزوجية"]},{"id":1862,"question":"إذا كان لا يُصلِّي ودعاها هل يجوز لها أن ترفض؟","title":"حكم هجر المرأة فراش زوجها الذي لا يصلي","answer":"الجواب:\nإذا كان ما يُصلي فالنكاح باطل، ما تحلُّ له.\nس: طيب، وإذا كان لا يُصلي مع الجماعة وأرادت اجتنابَ فراشه تأديبًا له؟\nج: تسمع وتُطيع وتنصحه، أما إذا كان يترك الصلاة فتركها كفر.","link":"https://binbaz.org.sa/fatwas/21971/حكم-هجر-المراة-فراش-زوجها-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رجل لا يصلي ودعا زوجته للفراش فهل لها أن تمتنع.mp3","categories":["الحقوق الزوجية","المشكلات الزوجية"]},{"id":1863,"question":"بالنسبة للزوج المسافر الذي يمنع زوجته من صيام التطوع هل يأثم؟","title":"هل للمسافر منع زوجته من صوم التطوع؟","answer":"الجواب:\nيأثم، ولا تُطيعه.","link":"https://binbaz.org.sa/fatwas/21972/هل-للمسافر-منع-زوجته-من-صوم-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يأثم الزوج الذي يمنع زوجته من صيام التطوع وزيارة أهلها أو أهله.mp3","categories":["الحقوق الزوجية"]},{"id":2235,"question":"(ما حكم) كذب الزوج على زوجته؟","title":"ما حكم الكذب بين الزوجين؟","answer":"الجواب:\nفيما يتعلق بأمورهما: لها أن تكذب عليه، وله أن يكذب عليها.\nس: كيف؟\nج: فيما بينهم: والله أن أشتري لكِ كذا، والله إني ما فعلتُ كذا، إذا قالت له: فعلتَ كذا، فيكذب عليها أنَّه ما فعل الذي يُشوش عليها، مثل أن تقول له: إنَّك ذاهب لتخطب، أو أنت سائر إلى فلانة، وأنك تأتيها أكثر مني، وما أشبه ذلك.\nس: له أن يحلف بالله؟\nج: له أن يحلف.","link":"https://binbaz.org.sa/fatwas/22358/ما-حكم-الكذب-بين-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يحق للزوج أن يكذب على زوجته.mp3","categories":["الحقوق الزوجية"]},{"id":3053,"question":"في قَبْض النفقة: يُؤخذ بقول الزوجة وإلا قول الزوج؟","title":"مَنْ يُؤخذ بقوله من الزوجين في قبض النفقة؟","answer":"الجواب: يُوكَل إلى أمرها، ما دام اسْتَفْتَت فالعهدة عليها، ما يُقال: هاتي البينة، يُبيّن لها الحكم والعُهدة عليها، لو قال... بالبيّنة؛ عَظُم الأمرُ واشتد.","link":"https://binbaz.org.sa/fatwas/23213/من-يوخذ-بقوله-من-الزوجين-في-قبض-النفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يؤخذ بقول الزوجة أو قول الزوج في النفقة.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":3280,"question":"هجر الزوج لزوجته أكثر من ثلاثة أيام في أمر من أمور الدنيا؟","title":"حكم هجر الزوج لزوجته أكثر من ثلاثة أيام؟","answer":"الجواب: قال الله جل وعلا: واهجروهن والحديث مُقّيِّد الإطلاق، إذا كان لحَقِّه ثلاثة أيام، إذا كان لحق شخصي. وإن كان لمعصية ما يتقيّد بثلاثة أيام.\nس: هجر النبي ﷺ نساءه شهرا؟\nالشيخ: هذا هجرهن جميعًا؛ لأنهن طلبن شيئًا ما يَحِلّ، معصيةٌ منهن.","link":"https://binbaz.org.sa/fatwas/23444/حكم-هجر-الزوج-لزوجته-اكثر-من-ثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هجر الزوج لزوجته أكثر من ثلاثة أيام في أمر من أمور الدنيا.mp3","categories":["الحقوق الزوجية","قضايا المرأة"]},{"id":3682,"question":"قول الحافظ ابن حجر في سياق فوائد من الحديث، قال: وفيه إكرام الرجل بعض نسائه بحضور ضرائرها بما يخصها به من قول أو فعل، ومحله عند السلامة من الميل المفضي إلى الجور؟","title":"حكم إكرام إحدى الزوجات بخلاف البقية","answer":"الجواب: قوله ﷺ: كنت لك كأبي زرع لأم زرع.. هذا لا شك أنه يخبرها أنه اعتنى بها وأكرمها عليه الصلاة والسلام، وهذا شيء معروف؛ حبه لها وإكرامه لها؛ فهي أحب النساء إليه عليه الصلاة والسلام، ومع هذا كان يقسم فيعدل كما قالت عائشة رضي الله عنها: كان يقسم فيعدل فيقول: اللهم هذا قسمي فيما أملك فلا تلمني فيما تملك ولا أملك.","link":"https://binbaz.org.sa/fatwas/23871/حكم-اكرام-احدى-الزوجات-بخلاف-البقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حب النبي عليه الصلاة والسلام لعائشة رضي الله عنها.mp3","categories":["الحقوق الزوجية"]},{"id":3684,"question":"الهجر لمدة شهر هل هو من خصائص النبي ﷺ أو لأمته عامة؟","title":"حكم هجر الزوجة وهل هو خاص به ﷺ؟","answer":"الجواب: لا، ما هو من خصائصه، إذا رأى ذلك الزوج فلا بأس، إذا رأى أن يهجرهن، وله أن يزيد، لكن لا يزيد على أربعة أشهر لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ [البقرة: 226] إذا طَلَبَتْ يُوقف: إما أن يَفِي وإما أن يُصلح وإما أن يُطلّق. أما ما يعتريه من هجرها لشهر أو شهرين أو أكثر إلى أربعة؛ فلا بأس. س: المقصود بالهجر الجماع، أو مقاطعة نهائية؟\nالشيخ: هجرهن مرة واحدة شهرًا كاملًا . س: هجر الكلام والجماع؟\nالشيخ: كل شيء، هجرهن في مشربة. س: هجر النبي ﷺ هو الإيلاء المعروف؟\nالشيخ: غير الإيلاء. س: ما الفرق بينه وبين الإيلاء؟\nالشيخ: الإيلاء يحلف أنه ما يطأها يقول: والله ما يطؤها؛ هذا الإيلاء. س: وكان هذا الهجر بسبب النفقة؟\nالشيخ: المشهور أنه كان بسبب النفقة.","link":"https://binbaz.org.sa/fatwas/23873/حكم-هجر-الزوجة-وهل-هو-خاص-به-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الهجر للنساء شهرًا خاص بالنبي أو لأمته عامة.mp3","categories":["الحقوق الزوجية"]},{"id":3688,"question":"التأديب بالطلاق هل له وجه؟","title":"هل يجوز التأديب بالطلاق؟","answer":"الجواب: لا، بالكلام والنصيحة أو الضرب الخفيف، أما التأديب بالطلاق فقد يفضي إلى البينونة بالكلية؛ يطلق اليوم ثم يطلق بعد ثم تأتي الثالثة وتبين منه، ينبغي أنه يؤدبها بالكلام الطيب والنصيحة والتوجيه أو بالأدب الخفيف، كما قال تعالى: وَاضْرِبُوهُنَّ [النساء:34] هذا هو التأديب: الهجر يومًا أو يومين ثلاثًا، وهجرها أكثر من ذلك إذا دعت الحاجة إلى هذا.","link":"https://binbaz.org.sa/fatwas/23877/هل-يجوز-التاديب-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التأديب بالطلاق له وجه.mp3","categories":["الحقوق الزوجية"]},{"id":3690,"question":"للزوج أن يؤخر القضاء؟","title":"هل للزوج إلزام زوجته بتأخير القضاء؟","answer":"الجواب: مثل ما تقدم إذا كان فوريًّا لا، حق الله مقدم دين الله أحق بالقضاء،. أما القضاء لا بأس، قضاء رمضان تؤخر إلى شعبان، كما في حديث عائشة. أما الكفارات الواجبة الفورية والنذر الواجب لا، لكن قضاء رمضان لا بأس، تقول عائشة رضي الله عنها: (كان يكون عليّ الصوم من رمضان فما أستطيع أقضي إلا في شعبان لمكان رسول الله ﷺ) لأن هذا فيه سعة، والحمد لله.","link":"https://binbaz.org.sa/fatwas/23879/هل-للزوج-الزام-زوجته-بتاخير-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للزوج أن يؤخر القضاء.mp3","categories":["الحقوق الزوجية"]},{"id":3691,"question":"إذا كان عليه معاصٍ مثل شرب الخمر أو تفريط في بعض الصلوات هل لها أن تهجره لتؤدبه؟","title":"هل للزوجة هجر زوجها لاقترافه المنكرات؟","answer":"الجواب: الظاهر -والله أعلم- أن لها أن تطلب الطلاق؛ لأن معاشرة من أعلن المعاصي شر عظيم، ولا سيما الخمر قد يضرها وقد يقتلها بغير شعور؛ أما هجر الفراش لا تهجر الفراش إلا إذا خافت على نفسها لكن لها أن تطلب الطلاق، وأما ترك الصلاة فكفرٌ، يجب عليها، إذا ترك الصلاة كفر يجب عليها أن تبتعد وأن تذهب إلى أهلها على الصحيح؛ لأن تركها كفر، والله يقول: لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] فإذا ترك الصلاة فهذا كفر أكبر على الصحيح فيجب عليها حينئذ أن لا تمكّنه منها، وأن تبتعد عنه إلى أهلها، حتى يتوب إلى الله.\nس: بارك الله فيك يا شيخ، هل هذا مقيد بالليل أو يعم الليل والنهار؟\nالشيخ: الظاهر أنه عام لكن وصف أغلبي؛ لأن الغالب أن هذا يكون في البيتوتة في الغالب وإلا قد يكون في القائلة وقد يكون في الصباح.\nس: إذا كانت تكرهه لخلقه؟\nالشيخ: هذا فيه تفصيل؛ إذا كان سيئ الخلق يعني أنه قليل التبسم هذا سهل، أما إذا كان سوء خلقه يترتب عليه ضربها وإيذاؤه وظلمها فلها طلب الفراق.\nس: سلمكم الله يا شيخ، هجرها له... مثل حديث النبي ﷺ مع أزواجه؟\nالشيخ: ليس لها أن تهجره إلا بحق، الواجب عليها السمع والطاعة في المعروف. إلا إذا لم يؤد حقها.","link":"https://binbaz.org.sa/fatwas/23880/هل-للزوجة-هجر-زوجها-لاقترافه-المنكرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا كان الزوج عاصٍ، فهل للزوجة أن تهجره.mp3","categories":["الحقوق الزوجية"]},{"id":3692,"question":"حتى ولو لم يأذن لوالديها؟","title":"حكم منع الزوج زوجته من الإذن لوالديها","answer":"الجواب: نعم، حتى ولو والديها، بعض الوالدين شرٌّ عليها وعلى زوجها. لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/23881/حكم-منع-الزوج-زوجته-من-الاذن-لوالديها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا لم يأذن الزوج لزوجته بإدخال لوالديها.mp3","categories":["الحقوق الزوجية"]},{"id":3698,"question":"والمرأة لا يجوز لها الهجر؟","title":"هل يجوز للمرأة أن تهجر زوجها؟","answer":"الجواب: لا يجوز لها هجر زوجها، إذا هجرته لعنتها الملائكة حتى تصبح، إلا بحق، إذا كان بحق تطالب بحقها، إذا قصّر في حقها تخرج إلى أهلها وتطلب حقها؛ أما إذا كان قائمًا بحقها ما يجوز لها، ولهذا غضب النبي على نسائه لما فعلن ما فعلن مما أوجب هجرهن، غضب، اللهم صل عليه.","link":"https://binbaz.org.sa/fatwas/23887/هل-يجوز-للمراة-ان-تهجر-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للمرأة أن تهجر زوجها.mp3","categories":["الحقوق الزوجية"]},{"id":3702,"question":"لا بدّ من استئذان الزوجة عند العزل؟","title":"هل يلزمُ الزوجَ استئذانُ الزوجة عند العزل؟","answer":"الجواب: الأقرب -والله أعلم- أنه لا بدّ من ذلك؛ لأن لها حقًّا في الولد. وجاء في حديث فيه ضعف باستئذانها، ولكن المعنى واضح؛ ليس له العزل عنها إلا بإذنها إلا الأمة، الأمة لا بأس.","link":"https://binbaz.org.sa/fatwas/23892/هل-يلزم-الزوج-استىذان-الزوجة-عند-العزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تستأذن الزوجة عند العزل.mp3","categories":["الحقوق الزوجية"]},{"id":3704,"question":"الحديث الضعيف في المنع أو في الجواز؟ الحديث الضعيف في العزل؟","title":"الحكم على حديث النهى عن العزل إلا بإذن","answer":"الجواب: حديث أن الرسول ﷺ نهى أن يعزل الرجل إلا بإذن الحرة رواه أحمد وفي إسناده رجل مجهول، فيه النهي عن العزل عن الحرة إلا بإذنها؛ لكن المعنى صحيح من حيث المعنى؛ لأن لها حقًّا في الولد، هما شركاء في الولد.","link":"https://binbaz.org.sa/fatwas/23894/الحكم-على-حديث-النهى-عن-العزل-الا-باذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث أن الرسول نهى أن يعزل الرجل إلا بإذن الحرة.mp3","categories":["الحقوق الزوجية","تنظيم الحمل وموانعه"]},{"id":3706,"question":"إذا كان الرجل تزوج ثانية والأولى رفضت أن تبيت عنده وأن تجلس معه ثم رضيت بعد هل يقسم لها؟","title":"هل للزوجة طلب استرجاع حقها الذي أسقطته؟","answer":"الجواب: يلزمها.\nس: لكن يقضي لها أو ما في حاجة للقضاء؟\nالشيخ: يلزمها أن تخضع لحكم الشرع وأن ترضى بقسم الله، سواء اثنتين أو ثلاثة أو أربعة، وإذا امتنعت ما عاد لها قسم، إذا امتنعت سقط حقها، هي التي أسقطت حقها، ما يُقضى لها شيء.\nس: إذا وهبت يومها ثم رجعت؟\nالشيخ: لها الرجوع تقول: أبغي يومي وإلا طلقني؛ لأنها قد لا تصبر.","link":"https://binbaz.org.sa/fatwas/23896/هل-للزوجة-طلب-استرجاع-حقها-الذي-اسقطته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في التعدد، والقسم بين الزوجات.mp3","categories":["الحقوق الزوجية"]},{"id":3710,"question":"من جلس مع امرأته الأولى ولم يتزوج عليها وهي لا تنجب، هل يُؤجر على ذلك؟","title":"هل يُؤجر من اكتفى بزوجة لم تنجب؟","answer":"الجواب: أما الأجر الله أعلم..... لا بأس؛ لأن نكاح الثانية ما هو بلازم إلا إذا كان يخشى على نفسه إذا كان جلوسه معها يخشى على نفسه ما تعفه؛ يلزمه أن يتزوج ثانية إذا قدر أو ثالثة أو رابعة إذا قدر، إذا كان يخشى العنت، يخشى الفتنة أما إذا كان شهوته ضعيفة والمرأة تكفيه الواحدة، فالحمد لله.","link":"https://binbaz.org.sa/fatwas/23901/هل-يوجر-من-اكتفى-بزوجة-لم-تنجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يؤجر من جلس مع امرأته الأولى ولم يتزوج عليها وهي لا تنجب.mp3","categories":["الحقوق الزوجية"]},{"id":3713,"question":"الزوجة (غير البكر) لو أقام عندها سبعًا..؟","title":"حكم من أقام عند الزوجة غير البكرسبعًا؟","answer":"الجواب: يأثم إلا برضا الثانية التي معه، ما له يقيم عندها إلا ثلاثة أيام ثم يقسم، وإذا رضي صواحباتها قلن: ما يخالف أقم عندها عشرًا وإلا شهرًا، إذا رضين ما يخالف.\nس: إذا جلس عندها عشرًا ثم عوض الأخريات؟\nالشيخ: لا، ليس له إلا ثلاث.\nس: هنا تفريق بين العبارتين: إذا تزوج الرجل البكر على الثيب، والثانية: إذا تزوج الثيب على البكر، الأولى تكون بكرًا وتكون ثيبًا.....؟\nالشيخ: المقصود الأخيرة: إذا كانت بكرًا قسم لها سبعًا هذه الأخيرة، وإن كانت ثيبًا قسم لها ثلاثًا.\nس: إن شئت سبّعت لك ما يدل على جواز المكوث أكثر من ثلاث؟\nالشيخ: بلى، يدل على هذا؛ لو زاد لها يزيدن لهن.....\nحتى لا يُشكل معنا إن شئت سبّعت لك يعني معناه إنه إذا قسم لها سبعًا يقسم لهن على سبع سبع، تضيع الثلاث وراحت، هذا معناه إن شئت سبعت لك ثم يسبع لنسائه كل واحدة يقيم عندها سبعًا، حتى الثلاثة تضيع.\nس: ما يزيد على سبع؟\nالشيخ: هذا الذي جاء في الحديث سبع، هي تقول: سبّع لي مثل البكر؟ قال: إن شئت سبعت لك سبعت لنسائي.","link":"https://binbaz.org.sa/fatwas/23904/حكم-من-اقام-عند-الزوجة-غير-البكرسبعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإقامة عند الزوجة البكر الثانية.mp3","categories":["الحقوق الزوجية"]},{"id":3714,"question":"لو قسم الرجل على زوجاته ثلاثة أيام...؟","title":"حكم التراضي في القسمة بين الزوجات","answer":"الجواب: الأقرب -والله أعلم- أنه إذا تراضوا ما في شيء، الحق لهن، إذا تراضوا الحق لهن، لو تراضوا كل واحدة يعطيها يومين أو كل واحدة يعطيها ثلاثًا، وتراضوا على هذا فالحق لهن، مثل: إن شئت سبعت لك وسبعت لنسائي، متقارب في المعنى.","link":"https://binbaz.org.sa/fatwas/23905/حكم-التراضي-في-القسمة-بين-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التراضي في القسمة بين الزوجات.mp3","categories":["الحقوق الزوجية"]},{"id":3715,"question":"يبدأ القَسْم من غروب الشمس؟","title":"متى يبدأ وقت القَسْم بين الزوجات؟","answer":"الجواب: نعم، صاحبة الليلة من غروب الشمس.\nس: النهار ليس لهن حظ فيه؟\nالشيخ: الظاهر لا بدّ يعدل فيه مثل الليل. يقول النبي ﷺ: اللهم هذا قسمي فيما أملك فلا تلمني فيما تملك ولهذا كان يطوف عليهن في النهار جميعًا، ما يخص أحدًا، يطوف عليهن جميعا في العصر، والعدل يشمل ذلك.\nس: عماد القسم الليل؟\nالشيخ: في الغالب، وإلا بعض الناس ما يكون عنده ليل، ما عنده إلا نهار، فالواجب العدل في الليل والنهار، لكن غالب الناس عماده الليل، لكن بعض الناس قد يكون عمله في الليل قد يكون حارس، فما يكون عنده... إلا في النهار، فيكون مثل الليل بالنسبة إلى غيره.","link":"https://binbaz.org.sa/fatwas/23906/متى-يبدا-وقت-القسم-بين-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يبدأ القسم بين الزوجات.mp3","categories":["الحقوق الزوجية"]},{"id":3719,"question":"إذا كانت المرأة تقول أنا لست بخادمة عندك، وتقول لا بدّ أن تأتيني بخادمة، تلزم زوجها بأن يأتيها بخادمة؟","title":"حكم إلزام الزوجة لزوجها بخادم لها","answer":"الجواب: حسب العرف؛ إن كان مثلها يخدم يُخدِمها، وإن كان مثلها لا يُخدم لا يُخدِمها، لا يلزمه، وإذا تطوع وسمح لا بأس، الناس أقسام والبلاد تختلف.\nس: لكن إذا كان مثلها لا يُخدم؟\nالشيخ: ما يلزمه أن يأتيها بخادم.\nس: وعليها أن تخدمه؟\nالشيخ: عليها تخدمه إذا كان مثلها يَخدِم.\nس: لكن لو أصرت؟\nالشيخ: يصلحون، إن شاء الله إذا جاؤوك أصلح بينهم.","link":"https://binbaz.org.sa/fatwas/23910/حكم-الزام-الزوجة-لزوجها-بخادم-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إلزام الزوجة لزوجها إحضار خادم لها.mp3","categories":["الحقوق الزوجية"]},{"id":3720,"question":"خدمة الزوجة لأم زوجها فرض عليها؟","title":"ما حكم خدمة الزوجة لأم الزوج وبناته؟","answer":"الجواب: لا، تخدم زوجها بس، لكن من مكارم الأخلاق تخدم بناته وتخدم أمه، من مكارم الأخلاق إذا كان عندها في البيت.","link":"https://binbaz.org.sa/fatwas/23911/ما-حكم-خدمة-الزوجة-لام-الزوج-وبناته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم خدمة الزوجة لأم الزوج.mp3","categories":["الحقوق الزوجية"]},{"id":3721,"question":"هل للرجل أن يمنع زوجته من مقابلة من يحل لها إذا كان يرى أن في مقابلته يخشى عليها أو يخاف؟","title":"هل يجوز منع الزوجة من محارمها؟","answer":"الجواب: له يمنعها إذا كان يخشى شيئًا، ولو هو مَحْرم.","link":"https://binbaz.org.sa/fatwas/23912/هل-يجوز-منع-الزوجة-من-محارمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للرجل أن يمنع زوجته من مقابلة من يحل لها.mp3","categories":["الحقوق الزوجية"]},{"id":3729,"question":"يعني لا يجوز للزوج أن يمنعها من ذلك؟","title":"هل يجوز منع الزوجة من الذهاب للمسجد؟","answer":"الجواب: ليس له أن يمنعها، نعم. الرسول ﷺ قال: لا تمنعوهن، ليس له أن يعصي الرسول ﷺ.\nس: إذا منعها لحاجة؛ لتربية أولادها أو القيام بحاجة البيت؟\nالشيخ: لا، لا تمنعوا إماء الله مساجد الله.","link":"https://binbaz.org.sa/fatwas/23921/هل-يجوز-منع-الزوجة-من-الذهاب-للمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/منع الزوج زوجته من الذهاب للمسجد.mp3","categories":["الحقوق الزوجية"]},{"id":5038,"question":"هل يحق للزوج أن يمنع زوجته من زيارة أهلها أو أهله؟","title":"هل يحق للزوج منع زوجته من زيارة الأهل؟","answer":"الجواب: هذا فيه تفصيل: إن كانت فيه مضرَّة وإلا ما يحقّ له، إن كانت فيه مضرّة مثل أنَّهم ما فيهم خير، أو يُخبونها عليه؛ فهذا لا بأس، أما إن لم يكن فيه شيء فلا يمنعها، أيأمرها بقطيعة الرحم والعقوق؟!\nس: إذا كانت عند أهلها منكرات متفشية؟\nج: ولو، تزورهم ولا تُشاهد المنكرات، يُوصيها ألا تُشاهد المنكرات، ولا تخلّي والديها.","link":"https://binbaz.org.sa/fatwas/28999/هل-يحق-للزوج-منع-زوجته-من-زيارة-الاهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يحق للزوج منع زوجته من زيارة الأهل؟.mp3","categories":["الحقوق الزوجية"]},{"id":5055,"question":"تزور جارتها بدون إذنٍ، في الصباح يعني؟","title":"حكم من تزور جارتها بدون إذن زوجها؟","answer":"الجواب: لا تخرج إلا بإذنه، لكن إذا أذن لها لا يُشدد في المسألة.\nس: وإذا ما أذن لها؟\nج: لا تخرج إلا بإذنه، لكن ما يكون فيه أذى، تزور جيرانها الطيبين، أهلها، إذا اقتضت المصلحة ذلك، لا يُشدد، يقول ﷺ: خيركم خيركم لأهله، وأنا خيركم لأهلي، وفي الحديث الآخر: خياركم خياركم لنسائهم، البر حسن الخلق، فالتعبيس والتشديد ما هو من حُسن الخلق.\nس: حتى مع الأخوات من النساء؟\nج: نعم، إذا كنَّ طيِّبات ما في بأس، إذا كانت بيوتهن طيبة ما في بأس، أما البيوت الرديئة فلا يأذن لهن فيها.","link":"https://binbaz.org.sa/fatwas/29319/حكم-من-تزور-جارتها-بدون-اذن-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من تزور جارتها بدون إذن زوجها؟.mp3","categories":["الحقوق الزوجية"]},{"id":5057,"question":"إذا خرجت من غير إذنه؟","title":"ما المشروع لمن خرجت زوجته بغير إذنه؟","answer":"الجواب: يُوجِّهها ويُعلمها، فإذا كان خروجها فيه مصلحة -كعيادة مريض أو زيارةٍ لأهلها- فلا يُشدّد في الأمور، وإذا  كان خروجها يرتاب فيه يمنعها منه. \nأما إذا كان خروجًا مشروعًا وله وجهٌ فينبغي له ألا يُشدّد، فبعض الناس عنده تشدد وسوء ظن دائمًا، فإذا كانت المرأة صالحةً لا ينبغي أن يُساء الظنّ بها، وإذا كان خروجها خروجًا مشروعًا لأهلها في وقتٍ مناسبٍ، أو لجيرانها في وقتٍ مناسبٍ؛ لا حرج.","link":"https://binbaz.org.sa/fatwas/29320/ما-المشروع-لمن-خرجت-زوجته-بغير-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما المشروع لمن خرجت زوجته بغير إذنه؟.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":5115,"question":"هل يجوز للمرأة أن تأخذ من مال زوجها دون علمه وتشتري حاجاتها الخاصة، علمًا بأنه لا يلبي طلباتها من كسوة وغيرها أفيدونا؟","title":"حكم أخذ المرأة من مال زوجها دون علمه","answer":"الجواب: نعم، لا بأس أن تأخذ من ماله بغير علمه في حاجاتها التي تجب عليه من غير إسراف ولا تبذير، في الصحيحين عن هند بنت عتبة رضي الله عنها قالت: يا رسول الله، إن أبا سفيان - زوجها - رجل شحيح لا يعطيني من النفقة ما يكفيني ويكفي بني، فهل آخذ من ماله بغير علمه ما يكفيني ويكفي بني؟ قال النبي ﷺ: نعم خذي من ماله بالمعروف ما يكفيك ويكفي بنيك فإن أخذت من ماله بغير علمه حاجتها من دون إسراف ولا تبذير فلا بأس.","link":"https://binbaz.org.sa/fatwas/30023/حكم-اخذ-المراة-من-مال-زوجها-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 43.mp3","categories":["الحقوق الزوجية"]},{"id":5182,"question":"ماذا يجوز للرجل من زوجته أيام الحيض؟","title":"ماذا يجوز للرجل من زوجته أيام الحيض؟","answer":"الجواب: يجوز للرجل من زوجته كل شيءٍ إلا الجماع، قال النبيُّ ﷺ: اصنعوا كل شيءٍ إلا النكاح، لما قالوا له ﷺ: إنَّ اليهود لا يُجامعون المرأة إذا كانت حائضةً في البيوت، لا يُجامعوها في البيوت يعني: لا يُساكنونها، ولا يأكلون معها، ولا يشربون معها، فقال عليه الصلاة والسلام: اصنعوا كل شيءٍ إلا النكاح، وأنزل الله في ذلك: وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ [البقرة:222] يعني: الجماع، أما كونه يُضاجعها وينام معها ويُقبّلها ويضمّها إليه فلا بأس بذلك، إلا الجماع فقط. وكانت عائشة رضي الله عنها تشرب من الإناء، ثم يأخذه النبيُّ ﷺ ويضع فمه في موضع فمها، وتتعرّق العظم فيأخذ ذلك أيضًا ويتعرّقه؛ تطييبًا لقلبها، وإيناسًا لها، ومُداعبةً لها عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/30118/ماذا-يجوز-للرجل-من-زوجته-ايام-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 144.mp3","categories":["الحقوق الزوجية","الحيض والنفاس"]},{"id":5925,"question":"كيف الجمع بين قول الله تعالى: وَاضْرِبُوهُنَّ [النساء:34] وبين قول الرسول ﷺ: ليس من خياركم من يضرب زوجته أو كما قال؟","title":"التفصيل في حكم ضرب الزوجة","answer":"الجواب: لا منافاة؛ فإن الرسول ﷺ أراد بذلك أن لا يسارعوا بالضرب، وليس من الصفات الخيرة المسارعة إلى الضرب، بل الضرب آخر الطب، الضرب يكون هو آخر الطب، قبله الهجر، وقبله الوعظ.  فينبغي للزوج أن لا يلجأ إلى الضرب إلا عند الضرورة، وعند الحاجة، وعند عدم جدوى الوسائل الأخرى؛ لأن الضرب قد يغيرها عليه أكثر، وقد يسيئ أخلاقها، ويسبب فراقها، ويثير أهلها أيضًا، ولاسيما في هذا العصر، الضرب في هذا العصر يسبب مشاكل كثيرة، فينبغي للزوج أن لا يعجل، وألا يسارع إلى الضرب إلا عند الحاجة، وأمن العاقبة، أمن العواقب السيئة. فإذا كان ضربها يفضي إلى فراقه لها، وإلى قيام أهلها عليه، وإلى حصول مشكلة كبرى؛ فينبغي تجنب الضرب، والصبر على ما قد يقع من سوء الأخلاق، حتى يعجل الله الحال بطرق العلاج الذي هو الوعظ، والتذكير، أو الهجر، فالزوج ينبغي أن يكون حكيمًا؛ لأن الضرب يترتب عليه مشاكل، وربما أفضى إلى غير المطلوب، والمراد به التعديل، والمراد به أن تراجع خطأها، فإذا كان الضرب يفضي إلى خلاف ذلك، وإلى مزيد السوء، وإلى مزيد المشاكل، وإلى تفاقم الأمور، فينبغي تركه، وعدم فعله. الحاصل: أن الضرب رخصة، رخص فيها ربنا  للتأديب إذا دعت الحاجة إليه بعدما قدم عليه من الوعظ، والهجر، وليس من الأفضل أن يسارع إليه، أو يفرح به، أو يتخذه علاجًا دائمًا لا، بل الأفضل أن يؤخر، وأن لا يعجل؛ جمعًا بين النصوص.","link":"https://binbaz.org.sa/fatwas/1280/التفصيل-في-حكم-ضرب-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_267.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق"]},{"id":5940,"question":"لو مر واحد على امرأة ما يعرفها، يرد عليها السلام؟","title":"هل يجوز السلام على النساء؟","answer":"الجواب: لا بأس مر النبي ﷺ على نساء، وسلم عليهن، مر على جماعة من النساء، وسلم عليهن، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1313/هل-يجوز-السلام-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_282.mp3","categories":["الحقوق الزوجية","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":5951,"question":"لو مر واحد على امرأة ما يعرفها، يرد عليها السلام؟","title":"هل يجوز السلام على النساء؟","answer":"الجواب: لا بأس مر النبي ﷺ على نساء، وسلم عليهن، مر على جماعة من النساء، وسلم عليهن، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1313/هل-يجوز-السلام-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_282.mp3","categories":["الحقوق الزوجية","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6225,"question":"آخر يقول: أنا متزوج ولي امرأتان، وقد لاقيت من المرأة السابقة عدة مشاكل عائلية، قد حاولتُ بشتى الوسائل إصلاح كل الأشياء التي كنت أعاني منها، ولكن دون جدوى، وقد رزقت منها بأربعة أطفال، وعندما يئست من كل شيء اضطررت إلى أن أتزوج بأخرى، وقمت بتأثيث شقة بكل ما تحتاج من أثاث للزوجة الأولى، وأسكنتها فيها، وأصرف عليها بكل ما تحتاجه هي وأطفالها، إلا أنني لم أدخل عليها في شقتها، ولا أنام معها للأسباب المشار إليها سابقًا؟","title":"الرفق بالنساء والصبر عليهن","answer":"الجواب: هذه المرأة ينبغي أن تعطف عليها، وترحمها لسبقها، ولكونها أم أولادك، والنساء مثل ما قال الرسول ﷺ خلقن من ضلع، وإن أعوج شيء في الضلع أعلاه، فإن ذهبت تقيمه كسرته، وإن تركته؛ لم يزل أعوج فلا بدّ من الصبر، ولا بدّ من العفو عن بعض الأشياء، ولا بدّ من الاستمرار في العلاج، فاستمر، ولا تيأس، استمر في العلاج، ولعلها -بهذا الهجر لها- لعلها ترجع إلى صوابها، ولعلها تحس بخطئها، وتعرف أغلاطها، فراجعها، يعني ارجع إليها، ونم معها، واعدل بينها وبين ضرتها بالقسم، والنفقة، والوجه، ونحو ذلك، واستعن بالله، فلعلها تستقيم، فإن لم تستقم؛ فحينئذ أنت مخير إن شئت طلقتها، وإن شئت أبقيتها معك إذا كانت ترضى بذلك، تبقى معك على الإنفاق عليها، وتكون محرمًا لك لو دخلت عليها، ولا بأس عليك. لكن ليس لك أن تهجرها هذا الهجران إلا إذا رضيت بذلك، أما إذا قالت: لا، طلقني، أو اعدل بيني، وبين ضرتي؛ فأنت مخير، إما أن تعدل، وإما أن تطلق، أما إذا رضيت، وقالت: لا بأس أرضى، لا تطلقني، أرضى أجلس عند عيالي على حسب نفقتك، ولا تطلقني، ولا بأس أن لا تقسم لي، أنا راضية؛ فلا بأس. وقد كانت سودة بنت زمعة أم المؤمنين -رضي الله عنها- أراد النبي أن يطلقها، فقالت: يا رسول الله لا تطلقني، وأبقني في نسائك، وأنا أجعل يومي لعائشة، فاتفق معها ﷺ على ذلك، وجعلت يومها لعائشة، وبقيت على حساب نسائه، ولم يطلقها، ولم يقسم لها.  فإذا رضيت هذه الزوجة القديمة بأن تبقى معك على غير قسم لها مع ضرتها، ولا تطلب طلاقها؛ فلا حرج عليك، تنفق عليها، وعلى أولادها، ولا حاجة إلى القسم، ولا مانع أن تدخل عليها في النهار، أو بعض الأحيان كيف حالكم، كيف أنتم؟ ربما جعل الله في هذا الدخول سببًا للخير، والمحبة، والوئام بعد ذلك، تدخل عليها، تزورهم، كيف أنتم؟ كل يوم، كل يوم، بعد يوم، بعد يومين، بعد ثلاث، تزورها؛ لأنها محرمك، ما دام ما طلقتها زوجتك تدخل عليها، وترعى أحوالهم، وترى أولادك، تجلس عندهم بعض الوقت، تسأل عن أحوالهم، تأتي إليهم بحاجاتهم، والنوم مع تلك، والقسم لها وحدها؛ لا بأس. فإذا قالت الأولى: لا، أنا ما أرضى بهذا أبدًا، بل إما أن تقسم لي حقي، وإما أن تطلقني؛ لزمك أحد الأمرين، إما القسمة، وإما الطلاق، أما إذا سمحت، وقالت: لا تطلقني، ولا بأس؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/1725/الرفق-بالنساء-والصبر-عليهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_573.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة","قضايا المرأة"]},{"id":6375,"question":"لي ولد عم، وعنده سبعة أولاد، وحالته المادية ضعيفة، وأنا أستطيع مساعدته، ولي زوجة كلما علمت أني أرسلت له شيئًا من المال؛ تغضب علي غضبًا شديدًا، وتترك الطعام، والصلاة لمدة خمس أعوام على هذه الحال، فما رأي سماحتكم؟","title":"نصيحة لزوجة لا تعين زوجها على بر أقاربه","answer":"الجواب: هذه زوجة ظالمة -نسأل الله العافية- هذه لا يطيعها، ويتصدق على ابن عمه، ويحسن إليه، يمكن عنده بنات يتزوج، تخشى أن يتزوج منهن، لعل عنده بنات تخشى أن يتزوج منهن، هذا ظنها السيئ. فالمقصود: أنه يعتني بالأمر، ويتصدق عليه، ويحسن إليه من غير أن يعلمها، لا يخبرها، بالطرق الأخرى؛ حتى يجمع بين المصلحتين، يمكن أن يتصدق من طريق آخر، من طريق خفية، ولا يعلمها بشيء، وينصحها لله، ويخوفها من الله، وإذا كانت لا تصلي؛ يلزمه فراقها، لا خير فيها، ومع هذا تعينه على قطع الرحم، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1960/نصيحة-لزوجة-لا-تعين-زوجها-على-بر-اقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_747.mp3","categories":["الحقوق الزوجية","الأخلاق المذمومة"]},{"id":6385,"question":"لي ولد عم، وعنده سبعة أولاد، وحالته المادية ضعيفة، وأنا أستطيع مساعدته، ولي زوجة كلما علمت أني أرسلت له شيئًا من المال؛ تغضب علي غضبًا شديدًا، وتترك الطعام، والصلاة لمدة خمس أعوام على هذه الحال، فما رأي سماحتكم؟","title":"نصيحة لزوجة لا تعين زوجها على بر أقاربه","answer":"الجواب: هذه زوجة ظالمة -نسأل الله العافية- هذه لا يطيعها، ويتصدق على ابن عمه، ويحسن إليه، يمكن عنده بنات يتزوج، تخشى أن يتزوج منهن، لعل عنده بنات تخشى أن يتزوج منهن، هذا ظنها السيئ. فالمقصود: أنه يعتني بالأمر، ويتصدق عليه، ويحسن إليه من غير أن يعلمها، لا يخبرها، بالطرق الأخرى؛ حتى يجمع بين المصلحتين، يمكن أن يتصدق من طريق آخر، من طريق خفية، ولا يعلمها بشيء، وينصحها لله، ويخوفها من الله، وإذا كانت لا تصلي؛ يلزمه فراقها، لا خير فيها، ومع هذا تعينه على قطع الرحم، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1960/نصيحة-لزوجة-لا-تعين-زوجها-على-بر-اقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_747.mp3","categories":["الحقوق الزوجية","الأخلاق المذمومة"]},{"id":6400,"question":"أحد الإخوة بعث أسئلة من مصر، ولكنها أسئلة كثيرة عن الحد، ونختار منها هذه الأسئلة؛ لعلها الأهم كما ذكر ذلك: الناس يفرقون بين ما يحل بعقد الزواج، ويسمونه كتب الكتاب، وبين ما يحل في ليلة البناء، فهل هذا الفرق له أصل في الشرع؟ وهل إذا جامع العاقد زوجته في بيت أبيها أيكون آثمًا؟ وهل يجب استئذان الولي عند البناء بها، مع العلم بأن العقد الشرعي قد تم؟","title":"حكم الدخول على المرأة بعد العقد واستئذان الولي","answer":"الجواب: هذه أسئلة فيها بعض الغموض، والجواب: ما دام العقد الشرعي، تم عقد الزواج الشرعي، تم الإيجاب والقبول من الولي الشرعي، والقبول من الزوج، وحضور الشاهدين العدلين؛ فإن الزوجة تكون حلاً له إذا استوفت الشروط، ولا فرق بين كونه يجامعها في بيت مستقل، أو في بيت أهلها إذا جعلوا له محلًا في بيتهم هو وزوجته، لا حرج عليه أن ينام معها، وأن يجامعها، وكذلك لا حاجة لاستئذان الولي في الدخول بها إذا كان الأمر قد حصل؛ هيؤوا له المكان معها، وطابت نفوسهم بذلك.  أما ما يقع في ليلة البناء فهذا لا نعرف مراده به، إن كان المراد إذا بنى بها، يعني دخل عليها كما يسمى في اللغة العربية وفي العهد الأول، وقد بنى عليها، إذا دخل عليها، وعقد عليها، إذا أجرى العقد، فرضا العقد يحلها، والبناء عليها هو الدخول بها.  وقد يجري العقد، ولكن يمنع من الدخول لأسباب، فإذا كان العقد قد تم، ولكن أهلها لم يرضوا بالدخول؛ فلا يدخل عليها، بل يصبر، حتى يسمحوا له بالدخول عليها؛ لأنه إذا دخل عليها من دون علمهم، أو قهرًا عليهم؛ قد يفضي هذا إلى شر عظيم، وفتنة، وقد تتهم البنت بأنها اتصل بها غير زوجها؛ لأن الدخول هو إعلان النكاح، فإذا دخل عليها سرًا، أو بصفة غير معلومة، غير مألوفة؛ قد يقع ضرر بينه، وبين أهلها، وقد تتهم البنت إذا حملت بأن هذا ليس من زوجها؛ لأنهم لم يعلموا دخوله بها. فالذي ينبغي أن الزوج لا يعجل حتى تتم الأمور بالطرق المألوفة المعروفة، وحتى يدخل عليها الدخول المعروف الذي ليس فيه ريبة ولا شبهة. السؤال: لو جامعها يعني وقع مثل هذا الأمر، هل يكون آثمًا في ذلك؟ الجواب: إذا كان يترتب عليه شر؛ يأثم؛  لأن معناه ألجأهم إلى شر، أو ألجأها إلى شر، فيخشى عليها أن تتهم بالشر، وأن يظن بها أنها زنت؛ لأنهم لا يعرفون أنه دخل بها، ولا يعلمون ذلك، ما جرت المراسيم المعروفة، فهذا خطر، أما فيما بينها، وبين الله؛ فهي حل له، فينبغي أن تؤتى البيوت من أبوابها، ولا تؤتى من غير أبوابها؛ حتى لا يقع بينه، وبين أهلها مشاكل.","link":"https://binbaz.org.sa/fatwas/1965/حكم-الدخول-على-المراة-بعد-العقد-واستىذان-الولي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_752.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة"]},{"id":6482,"question":"أحد الإخوة يسأل أن امرأة حملت من سفاح، وجاءت بمولود منذ أربع سنوات، واعترفت لزوجها، وعرف الحقيقة وهو الآن لا يدري هل يطلقها، أم يمسكها؟ وليس لها أحد إلا هو، واعترفت وهي تصلي، وتصوم، واعترفت بغلطتها، فما رأي سماحتكم؟","title":"حكم إبقاء الزوجة إذا زنت وتابت","answer":"الجواب: عليها أن تحسن إلى هذا الطفل، وتربيه لعل الله يهديه، وينفع به بعد ذلك، والإثم على من فعل الزنا لا عليه، وأما الإثم على من فعل الزنا من الزاني، والمرأة عليهما هما أصحاب الإثم -نسأل الله السلامة- والطفل لا حرج عليها بتربيته، والإحسان إليه، والقيام بحقه حتى ينشئه الله في الإسلام.  والمرأة إذا تابت، ورجعت إلى الله -جل وعلا- فزوجها يمسكها كونها زنت، فلا يحرمها عليه، ولكن عليها أن تتوب إلى الله توبة صادقة، وعليها أن ترجع عن هذا الباطل، وأن تتحفظ بعد ذلك، وعلى زوجها أن يلاحظها، وأن يعتني بها، وأن يحرص على أسباب حفظها، وسلامتها، ونجاتها من هذا الشيء، ولا حرج عليه في بقائها، فليس زناها يحرمها عليه إذا تابت، واستقامت. أما إذا كان يتهمها، ويظن أنها تخونه؛ فلا خير في بقائها عنده، لكن ما دام أظهرت التوبة، وظن بها الظن الحسن، وظهر منها ما يدل على رجوعها في الصواب، والحق، والهدى؛فلا بأس أن يستر عليها، ولا يبين هذا الشيء، بل يكون بينه وبينها فقط، وأن يحسن إليها بالنصيحة، والتوجيه، والإرشاد، والتحذير إلى العودة إلى ما حرم الله عليها، والله يتوب على التائبين .","link":"https://binbaz.org.sa/fatwas/2227/حكم-ابقاء-الزوجة-اذا-زنت-وتابت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_847.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق"]},{"id":6497,"question":"أحد الإخوة يسأل أن امرأة حملت من سفاح، وجاءت بمولود منذ أربع سنوات، واعترفت لزوجها، وعرف الحقيقة وهو الآن لا يدري هل يطلقها، أم يمسكها؟ وليس لها أحد إلا هو، واعترفت وهي تصلي، وتصوم، واعترفت بغلطتها، فما رأي سماحتكم؟","title":"حكم إبقاء الزوجة إذا زنت وتابت","answer":"الجواب: عليها أن تحسن إلى هذا الطفل، وتربيه لعل الله يهديه، وينفع به بعد ذلك، والإثم على من فعل الزنا لا عليه، وأما الإثم على من فعل الزنا من الزاني، والمرأة عليهما هما أصحاب الإثم -نسأل الله السلامة- والطفل لا حرج عليها بتربيته، والإحسان إليه، والقيام بحقه حتى ينشئه الله في الإسلام.  والمرأة إذا تابت، ورجعت إلى الله -جل وعلا- فزوجها يمسكها كونها زنت، فلا يحرمها عليه، ولكن عليها أن تتوب إلى الله توبة صادقة، وعليها أن ترجع عن هذا الباطل، وأن تتحفظ بعد ذلك، وعلى زوجها أن يلاحظها، وأن يعتني بها، وأن يحرص على أسباب حفظها، وسلامتها، ونجاتها من هذا الشيء، ولا حرج عليه في بقائها، فليس زناها يحرمها عليه إذا تابت، واستقامت. أما إذا كان يتهمها، ويظن أنها تخونه؛ فلا خير في بقائها عنده، لكن ما دام أظهرت التوبة، وظن بها الظن الحسن، وظهر منها ما يدل على رجوعها في الصواب، والحق، والهدى؛فلا بأس أن يستر عليها، ولا يبين هذا الشيء، بل يكون بينه وبينها فقط، وأن يحسن إليها بالنصيحة، والتوجيه، والإرشاد، والتحذير إلى العودة إلى ما حرم الله عليها، والله يتوب على التائبين .","link":"https://binbaz.org.sa/fatwas/2227/حكم-ابقاء-الزوجة-اذا-زنت-وتابت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_847.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق"]},{"id":6603,"question":"قرأت في صحيح مسلم شرح النووي: أن الرجل لا يجوز له النظر إلى فرج امرأته مع التبرج في ذلك على حسب مذهب النووي، فقرأت في آداب الزفاف: أنه يجوز النظر لكل من الزوجين، أفتونا أثابكم الله؟","title":"حكم نظر كل من الزوجين إلى فرج الآخر","answer":"الجواب: النظر إلى زوجته جائز، مطلقًا، فرجها، وغير فرجها، وهو كذلك يجوز النظر إليها، قد أباح الله له جماعها، والجماع أشد من النظر، فالذي يقول: ما يجوز النظر هذا غلط، سواء النووي، أو غير النووي، والذي يقول: إنه جائز هو المصيب.  المقصود: أن نظر الرجل إلى زوجته، ونظرها إليه، إلى بدنه كله، عورته، وغير عورته، كل هذا جائز، والحمد لله، الله أباح لكل منهما النظر إلى الآخر، كان النبي يغتسل مع زوجاته -عليه الصلاة والسلام- والمغتسل تكشف العورة، ويجامعها، وترى عورته، ويرى عورتها، هذا القول: بأنه لا يجوز قول غلط، لا وجه له. السؤال: يغتسل مكشوف العورة؟ الجواب: مكشوف العورة.. مكشوف العورة نعم، ما عليه لا سراويل، ولا إزار يكفي.. والمغتسل يكشف عورته، إذا كان ما عنده أحد في حمام خاص؛ يكشف عورته، الحمد لله اغتسل النبي عريانًا، ًواغتسل موسى عريانًا، واغتسل أيوب عرياناً. السؤال: في الحديث تقول عائشة: (أنه لم ير مني، ولم أر منه)؟ الجواب: لا ما هو صحيح، هذا من كلام العامة، ما له أصل، هذا قول عائشة \"لم ير مني، ولم أر منه\" هذا غلط، ما له أصل، غير صحيح.","link":"https://binbaz.org.sa/fatwas/2450/حكم-نظر-كل-من-الزوجين-الى-فرج-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_977.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة"]},{"id":6608,"question":"قرأت في صحيح مسلم شرح النووي: أن الرجل لا يجوز له النظر إلى فرج امرأته مع التبرج في ذلك على حسب مذهب النووي، فقرأت في آداب الزفاف: أنه يجوز النظر لكل من الزوجين، أفتونا أثابكم الله؟","title":"حكم نظر كل من الزوجين إلى فرج الآخر","answer":"الجواب: النظر إلى زوجته جائز، مطلقًا، فرجها، وغير فرجها، وهو كذلك يجوز النظر إليها، قد أباح الله له جماعها، والجماع أشد من النظر، فالذي يقول: ما يجوز النظر هذا غلط، سواء النووي، أو غير النووي، والذي يقول: إنه جائز هو المصيب.  المقصود: أن نظر الرجل إلى زوجته، ونظرها إليه، إلى بدنه كله، عورته، وغير عورته، كل هذا جائز، والحمد لله، الله أباح لكل منهما النظر إلى الآخر، كان النبي يغتسل مع زوجاته -عليه الصلاة والسلام- والمغتسل تكشف العورة، ويجامعها، وترى عورته، ويرى عورتها، هذا القول: بأنه لا يجوز قول غلط، لا وجه له. السؤال: يغتسل مكشوف العورة؟ الجواب: مكشوف العورة.. مكشوف العورة نعم، ما عليه لا سراويل، ولا إزار يكفي.. والمغتسل يكشف عورته، إذا كان ما عنده أحد في حمام خاص؛ يكشف عورته، الحمد لله اغتسل النبي عريانًا، ًواغتسل موسى عريانًا، واغتسل أيوب عرياناً. السؤال: في الحديث تقول عائشة: (أنه لم ير مني، ولم أر منه)؟ الجواب: لا ما هو صحيح، هذا من كلام العامة، ما له أصل، هذا قول عائشة \"لم ير مني، ولم أر منه\" هذا غلط، ما له أصل، غير صحيح.","link":"https://binbaz.org.sa/fatwas/2450/حكم-نظر-كل-من-الزوجين-الى-فرج-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_977.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة"]},{"id":6772,"question":"أنا متزوج، وأريد منع زوجتي من الدراسة النظامية؛ لأنه يترتب على ذلك إهمال الحقوق الزوجية، وعدم القيام بها، فما فتواكم في هذا؟","title":"حكم منع الزوج زوجته من الدراسة","answer":"الجواب:  لا حرج إذا منعها الزوج من الدراسة، وقد حصل لها ما ينفعها من جنس المبادئ الدينية، فالحمد لله كافي إلا إذا كان مشروطًا عليه في الزواج، إذا كان مشروطًا عليه أن يبقيها حتى تكمل الدراسة الثانوية، أو الجامعية، فالمسلمون على شروطهم، أما إذا كان بدون شروط؛ فله أن يمنعها، وله أن يسمح لها بشروط الالتزام بالحجاب وعدم الخلوة بالأجنبي، فإذا سمح لها مع إكمال الشروط الشرعية؛ فلا بأس، وإن منعها؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/2658/حكم-منع-الزوج-زوجته-من-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1154.mp3","categories":["الحقوق الزوجية","الشروط والعيوب في النكاح"]},{"id":6773,"question":"لي زوجة قائم عليها بكسوتها، وأكلها، وشربها، ومسكنها، ولكن تطلب مني فلم أستطع، ويحصل بيني، وبينها مشاكل يوميًا، وإنني كرهت دخول المنزل بسببها، فطلبت مني الطلاق، وهي حامل في الشهر التاسع، وأنا مستحمل ذلك، وعملت معها المستحيل لأرضيها، ولكنها ترفض، أفيدوني جزاكم الله خيرًا؟","title":"كيفية التصرف مع الزوجة المكثرة من الطلبات","answer":"الجواب: العاقل كريم الأخلاق، يعينه الله على إرضاء زوجته بالكلام الطيب، والألفاظ المعسولة الحسنة، والسيرة الحميدة، والعشرة الطيبة، وتهدأ بعد ذلك، المرأة ضعيفة، متى رأت من زوجها اللطف، والإحسان، والعشرة الطيبة، ولين الكلام، والوعد الحسن؛ طابت أخلاقها، واستقامت أمورها، لكن مع العنف، والشدة، والتكبر، وعدم المبالاة بكلامها هذا يزيد الطين بلة، ويسبب طول المشاكل، واستمرار المشاكل. فينبغي للرجل أن يكون عنده دين، وعنده عطف، وعنده لطف، وعنده رفق، وأسلوب حسن، أبشري، إن شاء الله إذا تيسر، أمهليني، إن شاء الله أبشري بالخير، يا بنت فلان، يا أم فلان، أبشري بالخير، كلام طيب، لسان حسن، ولو كذب، ما يضر، لا بأس أن يحدثها وهو يكذب، حتى يفتح الله عليه .. تقول أم كلثوم بنت عقبة -رضي الله عنها-: سمعت النبي ﷺ يرخص في ثلاث، ما سمعته يرخص في شيء من الكذب إلا في ثلاث: ثم ذكر من الثلاث: حديث الرجل امرأته، والمرأة زوجها الأولى في الحرب، والثانية في الإصلاح بين الناس، والثالثة في حديث الرجل امرأته، والمرأة زوجها، فلا بأس أن يحدثها فيكذب، وأن تحدثه فتكذب، إذا كان فيما يتعلق بهما، وخاصتهما، وما يرضي أحدهما عن الآخر، فيقول: سوف أفعل، سوف أشتري لك كذا، وسوف أفعل كذا، وسوف كذا، وسوف نشتري فلة، ونشتري الفلة المناسبة كذا، يعني يعدها، أوعادًا حسنة، ولو في نيته أنه ما يفي بها؛ لأنه عاجز عنها، لكن من باب تطييب الخواطر، ومن باب الإحسان، ومن باب اللطف، ومن باب تلبية الرغبات، ولو بالكلام الطيب؛ حتى يفتح الله -جل وعلا- عليه، والمؤمن .. الخلق حسن الخلق، طيب الكلام، وعدم العنف والشدة. السؤال: هل الأولى تركه؟ الجواب: إذا ما دعت إليه الحاجة لا بأس، الأمر جائز، وإذا ما دعت إليه الحاجة لا حاجة للكذب، لكن إذا دعت إليه الحاجة لا بأس.","link":"https://binbaz.org.sa/fatwas/2636/كيفية-التصرف-مع-الزوجة-المكثرة-من-الطلبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1132.mp3","categories":["الحقوق الزوجية","المشكلات الزوجية"]},{"id":6779,"question":"زوجتي اشترطت في عقد الزوج أن تعمل، وبعد أن أنجبت طفلين أمرتها أن تترك العمل؛ فرفضت، وحصلت مشاكل كثيرة، وأنا الآن أمام أمرين: إما أن تعمل، أو أن أطلقها، أرشدوني جزاكم الله خيرًا؟","title":"حكم منع الزوجة من العمل رغم اشتراطها ذلك عند العقد","answer":"الجواب: اعمل الأصلح، إذا كانت طيبة، وجيدة، ومتأدبة بالآداب الإسلامية، وترغب في العمل لأجل الحاجة إلى المال، واكتساب المال، وهي مستقيمة في دينها، ويمكن أن تقوم بالأمرين؛ فلا بأس.  وإن لم يكن ذلك فالحمد لله، تسلك مسلكًا آخر، التمس زوجة صالحة طيبة تقوم بحاجتك، وهذه طلقها، وكلا يغنه الله من سعته، يقول الله سبحانه: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ [النساء:130] فانظر ما هو أصلح لقلبك، وأصلح لدينك نفعًا من طلاق، أو بقاء.","link":"https://binbaz.org.sa/fatwas/2659/حكم-منع-الزوجة-من-العمل-رغم-اشتراطها-ذلك-عند-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1155.mp3","categories":["الحقوق الزوجية","الشروط والعيوب في النكاح","قضايا المرأة"]},{"id":6871,"question":"أنا حريص على حضور دروس العلم، وأقيم مع زوجتي بمدينة الرياض، وعندما أخرج هي تخاف من الوحشة بالجلوس وحدها، وتريد أن تمنعني، فهل أجلس معها، أم أحضر لمجالسة العلم؟","title":"عدم حضور حلقات العلم بسبب الزوجة","answer":"الجواب: الأقرب -والله أعلم- أنك تجلس معها حتى لا تكون وحشة .. وتأتي في أوقات تحضر فيها العلم في الأوقات التي عندها من يؤنسها، أو تذهب إلى من يؤنسها؛ لأن بعض النساء ما تتحمل، ولأهلك عليك حق، فالأظهر، والأقرب أن تبقى عندها، وتؤنسها، ثم تلتمس وقتًا آخر يكون فيه السلامة من هذا الشيء، أو تحضر عندها في وقت الدرس الذي تريد من يؤنسها، ثم تذهب، ثم ترجع.  السؤال: لو أخذها إلى المسجد؟ الجواب: إذا تيسر أحسن، وأحسن؛ حتى يجمع بين الفائدتين.","link":"https://binbaz.org.sa/fatwas/2759/عدم-حضور-حلقات-العلم-بسبب-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1251.mp3","categories":["العالم والمتعلم","الحقوق الزوجية"]},{"id":7006,"question":"نرجو بيان الأحوال التي يكون للمرأة المطلقة السكنى، والنفقة، أو السكن وحده، أو النفقة وحدها؟ وهل نفقة المتوفي عنها زوجها واجبة، وكذلك سكناها؟","title":"حكم النفقة على المطلقة والمتوفى عنها زوجها","answer":"الجواب:\n\nالنفقة تكون للمطلقة الرجعية، طلقها واحدة، أو ثنتين، أما إذا كان طلقها آخر الثلاث -الطلقة الأخيرة آخر الثلاث- فلا نفقة لها، ولا سكنى بالمرة عن النبي ﷺ. \n\nوهكذا المتوفى عنها بائنة، ليس لها نفقة في مال الزوج، لأن مال الزوج صار للورثة، وإنما نفقتها في مالها، في نصيبها من الإرث، وهكذا المخلوعة التي طلقها على مال، هذه بائنة، ليس لها نفقة؛ لأنها غير رجعية، إنما النفقة كما قال النبي ﷺ للمرأة إذا كان لزوجها الرجوع إليها، أما إذا كان لا رجوع لها؛ فلا نفقة عليه، أما العدة فلا بد منها.\n\nالسؤال:...؟\n\nالجواب:  بعد العدة لا نفقة لها عند جميع العلماء، بعد خروجها من العدة لا نفقة لها عند جميع أهل العلم، وأما ما يوجد من طالب بالنفقة في الهند، فهذه طائفة كافرة، دولة كافرة، لا يستغرب ما يوقع منها، ..النفقة على المرأة المطلقة -ولو بعد العدة- إلى أن تموت، أو إلى أن تتزوج، هذا قول باطل، لا أساس له، وهو خلاف جميع أهل العلم.","link":"https://binbaz.org.sa/fatwas/2940/حكم-النفقة-على-المطلقة-والمتوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1388.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":7016,"question":"نرجو بيان الأحوال التي يكون للمرأة المطلقة السكنى، والنفقة، أو السكن وحده، أو النفقة وحدها؟ وهل نفقة المتوفي عنها زوجها واجبة، وكذلك سكناها؟","title":"حكم النفقة على المطلقة والمتوفى عنها زوجها","answer":"الجواب:\n\nالنفقة تكون للمطلقة الرجعية، طلقها واحدة، أو ثنتين، أما إذا كان طلقها آخر الثلاث -الطلقة الأخيرة آخر الثلاث- فلا نفقة لها، ولا سكنى بالمرة عن النبي ﷺ. \n\nوهكذا المتوفى عنها بائنة، ليس لها نفقة في مال الزوج، لأن مال الزوج صار للورثة، وإنما نفقتها في مالها، في نصيبها من الإرث، وهكذا المخلوعة التي طلقها على مال، هذه بائنة، ليس لها نفقة؛ لأنها غير رجعية، إنما النفقة كما قال النبي ﷺ للمرأة إذا كان لزوجها الرجوع إليها، أما إذا كان لا رجوع لها؛ فلا نفقة عليه، أما العدة فلا بد منها.\n\nالسؤال:...؟\n\nالجواب:  بعد العدة لا نفقة لها عند جميع العلماء، بعد خروجها من العدة لا نفقة لها عند جميع أهل العلم، وأما ما يوجد من طالب بالنفقة في الهند، فهذه طائفة كافرة، دولة كافرة، لا يستغرب ما يوقع منها، ..النفقة على المرأة المطلقة -ولو بعد العدة- إلى أن تموت، أو إلى أن تتزوج، هذا قول باطل، لا أساس له، وهو خلاف جميع أهل العلم.","link":"https://binbaz.org.sa/fatwas/2940/حكم-النفقة-على-المطلقة-والمتوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1388.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":7383,"question":"أنا شاب متزوج، وزوجتي حامل، ولقد تركتها عند أهلها، ولها الآن ما يقارب السنة، وأنا لا أحبها، وأكرهها، هل علي إثم في تركها؟","title":"حكم ترك الزوجة عند أهلها وعدم تطليقها","answer":"الجواب: نعم نعم، إذا كانت تطلب الطلاق عليك إثم؛ إما أن تطلقها، وإما أن تقوم بحقها، أما إذا كانت راضية وسامحة عنك، تقول: لا تطلقني، ترجو أن الله يهديك، وأنك ترجع إليها؛ فلا بأس، أما إذا كانت تقول: لا، إما قم بالواجب وإلا طلقني؛ فعليك أن تقوم بالواجب، أو الطلاق أحد الأمرين.  أما إذا كانت عند أهلها، ومسامحة، ولا تطلب طلاقها، ولا عندها خلاف، فأنت فكر واستخر الله، وشاور أصحابك، وأقاربك، إذا كانت طيبة ومن أهل الخير والصلاح والاستقامة؛ فلا تطلقها ولو كرهتها، الله يقول: فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا [النساء:19] ربما أنك إذا رجعت إليها تزكو في نفسك، وترى منها ما يسركن فتعجبك بعد ذلك، لا تعجل.","link":"https://binbaz.org.sa/fatwas/3464/حكم-ترك-الزوجة-عند-اهلها-وعدم-تطليقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1768.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة"]},{"id":7936,"question":"من المرسل أحمد عبد الله جاد من بورما، يقول: السلام عليكم ورحمة الله وبركاته، أرجو عرض هذا السؤال على فضيلة الشيخ عبد العزيز بن باز ، وإذاعة الرد مع جزيل الشكر، يقول: ابتليت بزوجة تكره المعاشرة الزوجية أي: الجنس، ولا تعرف حقوق الزوج وتنام في غرفة أخرى، ولا تعرف الزينة ونصحتها وأرشدتها ووجهتها، ولكن دون جدوى، فهل إذا تزوجت بأخرى وهجرتها أؤثم، علماً بأن لي منها أولاد وبنات على المدى الطويل ولا سبيل لإصلاحها أفيدوني جزاكم الله خير؟","title":"كيفية العمل مع المرأة التي لا تحسن معاشرة زوجها","answer":"الجواب: الواجب على المرأة السمع والطاعة لزوجها في المعروف، والواجب عليها أن تحسن العشرة، وأن تمكنه من نفسها إذا أراد قضاء حاجته منها، وأن تخاطبه بالتي هي أحسن، وأن تنام معه في الفراش إذا طلب ذلك، هذا هو الواجب عليها؛ لأن الله يقول : وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] لهن من المعاشرة الطيبة مثل الذي عليهن، الله أمر بالمعاشرة الطيبة فقال: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] فكما يجب على الزوج أن يعاشر بالمعروف فهي أيضاً عليها أن تعاشر بالمعروف، وللرجال على المرأة درجة، فعلم بذلك أن حق الرجل أكبر، وأن الواجب عليهما جميعاً التعاون على البر والتقوى والمعاشرة الطيبة بالكلام الطيب والفعل الطيب، عليها وعليه جميعاً، فإذا أصرت على أنها لا تمكنه من نفسها وعلى أنها تنفرد وحدها، وعلى أنها لا تعتني بنفسها من جهة الزينة والطيب، فهذا غلط منها وخطأ لا يجوز لها ذلك.\nولك -أيها السائل- أن تتزوج مطلقا، لك أن تتزوج بثانية وثالثة ورابعة لا حرج عليك، حتى ولو كانت من أحسن الناس طاعة وامتثالاً، لك أن تتزوج، لكن بهذه المثابة من باب أولى أن تتزوج؛ لأنها لم تقم بالواجب، ولم تمكنك مما يسبب عفتك وغض بصرك، فالمشروع لك في هذه الحال وأنت قادر أن تتزوج حتى تعف نفسك، وحتى تجد الراحة من هذا التعب، ولعلها بالزواج لعلها تنيب إلى رشدها، ولعلها ترجع عن غلطها هذا بسبب زواجك على غيرها، هذا هو الذي أرى في هذه المسألة، مع النصيحة لها والعناية بها وتوجيهها إلى الخير، وكذلك توصي أقاربها كأبيها وأخيها أو خالها أو عمها أن ينصحها وأن يوجهها إلى الخير، وكذلك أمها وجدتها وخالاتها يعني توصي من حولك من أقاربها بأن ينصحوها ويوجهوها إلى الخير؛ لأن هذا أمر يضرها ويضرك جميعا، ويضركما جميعاً، فإن استمعت واستقامت فالحمد لله، وإلا فأنت حر بحمد الله تستطيع أن تفارقها، تستطيع أن تتزوج ثانية وثالثة ورابعة، كل هذا بحمد الله لك ميسر إذا قدرت عليه، والله المستعان، ونسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/5457/كيفية-العمل-مع-المراة-التي-لا-تحسن-معاشرة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_066/06606.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":7945,"question":"هذه الرسالة -يا سماحة الشيخ- وردتنا من مقدم الأسئلة المستمع (ع. س. م) من الرياض يقول فيها: السلام عليكم ورحمة الله وبركاته.. وبعد:رجل مريض بشلل نصفي وتأتي الصرعة مرة واحدة في كل شهر -ربنا يحفظنا ويحفظكم من هذا المرض- وله رغبة في معاشرة وجماع زوجته ولكن زوجته ترفض ذلك وتقول: إذا أنا أنجبت أولاد معك فإنني كالذي زنت، ما حكم الشريعة في تلك الزوجة وفقكم الله؟","title":"حكم رفض المرأة معاشرة زوجها المصاب بالصرع","answer":"الجواب: الواجب عليها أن تمكنه من نفسها؛ لأنها زوجته وعليها أن تمكنه من نفسها، فإذا كانت يعني قد كرهته من أجل الصرع فترفع أمرها إلى الحاكم ما دامت في عصمته وزوجته فله الحق أن يجامعها ويتصل بها وعليها الحق أن تمكنه من نفسها، أما إذا كانت لما أصابه الصرع كرهته وأحبت الفراق فهذا يرجع إلى المحكمة، لكن إذا كانت قد رضيت واستقرت معه والصرع معه فإنه يلزمها أن تمكنه من نفسها حتى يقضي وطره من ذلك، وإن كانت حرمت وقالت: عليها الحرام وهي زانية إذا مكنته من نفسها فعليها كفارة اليمين، إذا كانت حرمت أن تمكنه من نفسها فهذا في حكم اليمين وعليها كفارة اليمين: إطعام عشر مساكين إذا كانت حرمت ذلك، وأما إذا كانت لم تحرم فعليها أن تمكنه من نفسها ولا بأس عليها في ذلك ولا حرج؛ لأن الصرع يعرض ويزول، أما إذا كانت كرهته وتريد فراقه فهذا إلى المحكمة والمحكمة تنظر في ذلك.","link":"https://binbaz.org.sa/fatwas/5477/حكم-رفض-المراة-معاشرة-زوجها-المصاب-بالصرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06808.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8046,"question":"هذه رسالة وردتنا من المستمع يقول: من الجمهورية العراقية محافظة نينوى، الأخ خ م أ يقول: ما حكم من يقبل نهود زوجته أي: الثدي، ويقوم بعض رءوس الثدي أثناء بداية الزواج وكذا ... إلى آخره، هل في ذلك شيء أم لا؟","title":"حكم تقبيل ثدي الزوجة وعضه من باب المداعبة","answer":"الجواب: لا نعلم في هذا شيء، أقول: لا نعلم في تقبيل الثدي أو عضه ما فيه شيء، أو مصه مصاً هكذا من باب المداعبة، أما شرب اللبن والحليب الذي فيه تركه أوْلى، ترك شرب اللبن أوْلى نعم، وأما مجرد التقبيل أو مص النهد من دون شيء، أو عض اللعب وما فيه شيء يؤذي: ما نعلم فيه شيء. نعم.","link":"https://binbaz.org.sa/fatwas/5845/حكم-تقبيل-ثدي-الزوجة-وعضه-من-باب-المداعبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08111.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8158,"question":"الرسالة التالية وصلت إلى البرنامج من العراق نينوى وباعثتها الأخت: حفصة يونس محمد ، أختنا تسأل مجموعة من الأسئلة، من بينها سؤال عن عمها الذي تزوج بامرأة جديدة فلم يهتم إلا بها وبأولادها وترك أولاد زوجته الأولى، الرأي لو تكرمتم سماحة الشيخ؟","title":"اهتمام الزوج بإحدى زوجتيه دون الأخرى","answer":"الجواب: الواجب نصيحته، الواجب نصيحته من إخوته ومن أصدقائه ينصحونه حتى يحسن في أم أولاده الأولى، وحتى يعرف لها حقها وفضلها، وأن لا ينساها ويعرض عنها ويبخسها حقها، فإن كان ولابد وليس له رغبة فيها فإنه يخيرها: إن شاءت صبرت على ما يسر الله منه وإن شاءت طلبت الطلاق، فإن طلبت الطلاق وجب عليه أن يطلق أو يعدل بينها وبين الجديدة، وليس له أن يحبسها ولا يعدل بل عليه أن يعدل بينهما أو يجيبها إلى طلب الطلاق فيطلق، وإذا طلقها أنفق عليها نفقة العدة طلقها طلقة واحدة السنة، أن يطلق واحدة فقط لا يطلق بالثلاث يطلق واحدة وينفق عليها نفقة العدة ويعرف لها فضلها، الله يقول: وَلا تَنسَوُا الْفَضْلَ بَيْنَكُمْ [البقرة:237].\nفينبغي له أن لا ينسى حالها الأولى وأنها أم أولاده، فينبغي له أن يكرمها ويلاحظها ويطيب خاطرها بما تيسر له من المساعدة هكذا ينبغي للرجال الأخيار ذوي مكارم الأخلاق وذوي النفوس الرفيعة الطيبة، ولكن لا يلزمه أن يبقيها في حباله إذا شاء أن يطلق فله أن يطلق، وإن صبرت هي ولم تطلب الطلاق رجاء أن يعود إليها أو لأنها ليست في حاجة إلى الطلاق لأنها لا ترغب الزواج على غيره، فإذا صبرت فلا بأس، وهو ينبغي له أن يحسن إليها وأن يعرف لها حالها الأولى، وأن يجود عليها بما يسر الله له ولا ينساها، هذا هو المشروع له.\nوعلى أقاربه الطيبين أن ينصحوه حتى يعدل أو يطلق إذا طلبت الطلاق.\nنعم والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/5961/اهتمام-الزوج-باحدى-زوجتيه-دون-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10403.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8164,"question":"الرسالة التالية وصلت إلى البرنامج من العراق نينوى وباعثتها الأخت: حفصة يونس محمد ، أختنا تسأل مجموعة من الأسئلة، من بينها سؤال عن عمها الذي تزوج بامرأة جديدة فلم يهتم إلا بها وبأولادها وترك أولاد زوجته الأولى، الرأي لو تكرمتم سماحة الشيخ؟","title":"اهتمام الزوج بإحدى زوجتيه دون الأخرى","answer":"الجواب: الواجب نصيحته، الواجب نصيحته من إخوته ومن أصدقائه ينصحونه حتى يحسن في أم أولاده الأولى، وحتى يعرف لها حقها وفضلها، وأن لا ينساها ويعرض عنها ويبخسها حقها، فإن كان ولابد وليس له رغبة فيها فإنه يخيرها: إن شاءت صبرت على ما يسر الله منه وإن شاءت طلبت الطلاق، فإن طلبت الطلاق وجب عليه أن يطلق أو يعدل بينها وبين الجديدة، وليس له أن يحبسها ولا يعدل بل عليه أن يعدل بينهما أو يجيبها إلى طلب الطلاق فيطلق، وإذا طلقها أنفق عليها نفقة العدة طلقها طلقة واحدة السنة، أن يطلق واحدة فقط لا يطلق بالثلاث يطلق واحدة وينفق عليها نفقة العدة ويعرف لها فضلها، الله يقول: وَلا تَنسَوُا الْفَضْلَ بَيْنَكُمْ [البقرة:237].\nفينبغي له أن لا ينسى حالها الأولى وأنها أم أولاده، فينبغي له أن يكرمها ويلاحظها ويطيب خاطرها بما تيسر له من المساعدة هكذا ينبغي للرجال الأخيار ذوي مكارم الأخلاق وذوي النفوس الرفيعة الطيبة، ولكن لا يلزمه أن يبقيها في حباله إذا شاء أن يطلق فله أن يطلق، وإن صبرت هي ولم تطلب الطلاق رجاء أن يعود إليها أو لأنها ليست في حاجة إلى الطلاق لأنها لا ترغب الزواج على غيره، فإذا صبرت فلا بأس، وهو ينبغي له أن يحسن إليها وأن يعرف لها حالها الأولى، وأن يجود عليها بما يسر الله له ولا ينساها، هذا هو المشروع له.\nوعلى أقاربه الطيبين أن ينصحوه حتى يعدل أو يطلق إذا طلبت الطلاق.\nنعم والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/5961/اهتمام-الزوج-باحدى-زوجتيه-دون-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10403.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8167,"question":"الرسالة التالية باعثها أخونا المهندس (س. ط) ويعمل في الكويت، يقول: خطبنا قبل سنة أنا وأخي بنات خالتنا، ولم يكن هناك أي شرط في عقد الزواج، وبعد كتب الكتاب يريد والدها أن نمتنع عن السكن مع أهلنا، مع العلم بأن عائلتنا صغيرة، ويريد كذلك أن نقطع المصروف عن أهلنا، وأن لا نكمل تعليم إخواننا، كما أنه يريد أن نمتنع عن زيارة أعمامنا وخالاتنا وأختنا وجميع الأقارب وأن لا يزورونا كذلك، ولقد أحضرناه للتفاهم بحضرة إمام المسجد إلا أنه تلفظ على والدتنا بكلام بذيء، وتطاول على الله عز وجل، ووسطنا له أكثر من شخص إلا أنه يصر على شروطه، ووالدي ووالدتنا يصران على تطليق البنات، ولا سيما الوالدة، هل نطيع والدتي ونطلق البنات أم ماذا، وما رأي الشرع في ذلك؟ أفيدونا أفادكم الله؟","title":"حكم طاعة الوالدين في طلاق الزوجة","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل فالأولى تطليق البنات ومراعاة خاطر الوالدين، وهذه الشروط شروط قبيحة تفضي إلى قطيعة الرحم وتفضي إلى الشحناء بين الأقارب، وهذا كله ليس بطيب، وعمل أبي البنتين عمل رديء لا ينبغي، فإن وافق على نقل البنتين إلى بيوتكما عند أهلكما فالحمد لله وإلا فطلاقهما أولى، وإذا كانت البنتان ترغبان في النكاح ففي إمكانهما أن يرفعا الأمر إلى المحكمة حتى تحول المحكمة بين والديهما وبين رأيه القبيح، فهذا هو الذي نرى في هذا، المحكمة تنظر في الأمر، فإن لم تريا محاكمته فلا بأس، والتطليق أولى، ولعل الله أن يرزقكما خيراً من هاتين البنتين في الدين والدنيا، أما التسبب في قطيعة أرحامكم وعقوق والديكم فهذا شيء لا ينبغي ولا ينصح به من يخاف الله ويرجوه سبحانه وتعالى.\nوفق الله الجميع وهدى الجميع.","link":"https://binbaz.org.sa/fatwas/5962/حكم-طاعة-الوالدين-في-طلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10404.mp3","categories":["بر الوالدين","المشكلات الزوجية","الحقوق الزوجية"]},{"id":8192,"question":"نبدأ أولاً برسالة المستمع (س. ع) من أبها، يقول: امرأة لعنت زوجها بسبب شجار بينهم، وحيث أن هذه يوجد لديها نوع الحمق، فهل تحرم على زوجها أم لا؟","title":"حكم لعن الزوجة لزوجها ولعن الزوج لزوجته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه.\nأما بعد: لا، لعنها له لا يحرمها عليه، ولعنه لها لا يحرمها عليه أيضاً، إذا لعن أحدهما الآخر فقد أخطأ وأساء وظلم، فعليه التوبة إلى الله ، واستسماح صاحبه، الزوج يستسمح زوجته إذا لعنها، وهي بالعكس كذلك تستسمحه وتتوب إلى الله مما فعلت والزوجية باقية، لا يفسد النكاح بذلك، فاللعن لا يبطل النكاح ولا يفسده، ولا يكون طلاقاً لها، سواء كان اللعن منه لها أو منها له، إلا أنه منكر ولا يجوز، وكبيرة من الكبائر، جاء في الحديث الصحيح أن النبي عليه الصلاة والسلام قال: لعن المؤمن كقتله، وقال: ليس المؤمن بالطعان ولا اللعان ولا الفاحش ولا البذيء، فاللعن ليس من صفة المؤمنين، بل هو منكر، فلا يجوز أن يقع من الزوج، ولا من الزوجة، وإذا وقع من أحدهما وجب عليه أن يستسمح الآخر؛ لأنه تعدى عليه وظلمه، مع التوبة إلى الله ، نعم.","link":"https://binbaz.org.sa/fatwas/6000/حكم-لعن-الزوجة-لزوجها-ولعن-الزوج-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_093/09301.mp3","categories":["الحقوق الزوجية","الأخلاق المذمومة"]},{"id":8234,"question":"إحدى الأخوات السودانيات تقول: إنها مقيمة في الخرطوم، ورمزت إلى اسمها بالحروف (أ. ب. ع) أختنا تصف نفسها بأنها كثيرة العناد لزوجها، وحاولت أن تتخلص من هذه الخطيئة، ولكنها لم تستطع حتى الآن، كيف ترون لها الطريق سماحة الشيخ؟","title":"وجوب طاعة المرأة لزوجها وترك مخالفته","answer":"الجواب: عليها أن تتقي الله سبحانه، وأن تجاهد نفسها في طاعة زوجها في المعروف، وعليها أن تستحضر دائماً أن الواجب عليها طاعة زوجها، وأنها بعنادها له تأثم وتغضب ربها، فالواجب عليها أن تحاسب هذه النفس، فإنها أمارة بالسوء إلا من رحم الله، فعليها أن تحاسب النفس وأن تتذكر وقوفها بين يدي الله، وأنها مسئولة عن طاعته ومعصيته، فإذا استحضرت هذه الأمور وكانت على بالها فالله يعينها على طاعته وترك العناد.\nأما إذا أرادت تنفيذ هواها أو تقليد النساء العاصيات اللاتي لا يبالين بأمر الله فإنها تخسر الدنيا والآخرة، ولكن عليها أن تتأسى بالأخيار السالفات على الهدى من أزواج النبي ﷺ ومن سائر أهل الخير من التقيات المؤمنات، عليها أن تتأسى بأهل الخير لا بأهل الشر.\nوعليها فوق ذلك أن تتذكر عظمة الله، وأن تخافه سبحانه وأن تطيع أمره في ذلك؛ لأن الله أمرها بطاعة زوجها، فلزوجها عليها الطاعة في المعروف. نعم.","link":"https://binbaz.org.sa/fatwas/6059/وجوب-طاعة-المراة-لزوجها-وترك-مخالفته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09719.mp3","categories":["الحقوق الزوجية"]},{"id":8282,"question":"أولى رسائل هذه الحلقة سماحة الشيخ! رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من الرياض يقول: أخوكم (م. ل. م) أخونا ملخص رسالته: أنه متزوج منذ فترة وأنه يصلي ولله الحمد وكذلك زوجته، إلا أنه يشك فيها، بم توجهونه سماحة الشيخ، والواقع الرسالة مطولة؟","title":"توجيه لمن يسيئ الظن بزوجته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالواجب على المؤمن اجتناب سوء الظن، إلا عند وجود أمارات واضحة ودلائل بينة تدل على ذلك؛ لأن الله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ [الحجرات:12]، ويقول النبي ﷺ: إياكم والظن فإن الظن أكذب الحديث، فالواجب على الزوج إحسان الظن بزوجته، وحملها على أحسن المحامل، ونصيحتها إذا شك في شيء، توجيهها إلى الخير، وعدم طاعة الشيطان في ظن السوء الذي لا أساس له ولا بينة عليه ولا شواهد له، أما إن كان هناك شيء يشهد لبعض الظن، فينبغي فيه النصيحة والتوجيه والتحذير مع المراقبة حتى يزول الشك، نسأل الله للجميع الهداية نعم.","link":"https://binbaz.org.sa/fatwas/6090/توجيه-لمن-يسيى-الظن-بزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_107/10701.mp3","categories":["الحقوق الزوجية"]},{"id":8327,"question":"الرسالة الثانية في حلقة هذه الليلة من المستمعة (ع. ف) مصرية الجنسية وتعمل بالمملكة، رسالتها طويلة ولكن خلاصتها، تقول: بأنها متزوجة وهي تعصي زوجها وجاهلة ودائماً تغضب منه، ودائماً لا تعطيه حقه كزوج، وتطلب منه الطلاق كثيراً، وقد طلقها مرتين، وعندما يذهبان للمأذون يرفض المأذون هذا الطلاق لأنه في حالة غضب، ولكنها تصر هي على طلب الطلاق فيوافق المأذون حتى أصبح عدد الطلقات ثلاث طلقات على يد المأذون، وبما أنها -كما تقول- تحبه وهو يحبها ويرغبان الرجوع إلى بعضهما فقد اعترض دون ذلك والدها، وهو من حملة الكتاب -كما تقول- ونصحها بأنها لا تحل لزوجها حتى تتزوج رجلاً غيره، في هذه الحالة ذهبا إلى مأذون بلدتهما، فقال لها: يمكنك أن تأتي بمحلل.وفعلاً قد اتفقا مع رجل طيب يريد لهما الصلاح -كما تقول في رسالتها- على أن يعقد عليها، وثاني يوم يطلقها دون أن يمسسها كزوج وأكملت عدته، ورجعت لزوجها بعد العدة، وعاشت على هذه الحال خمس سنوات أنجبت خلالها طفلين وهي تعيش مع زوجها في عناد وفي مشاكل وفي جحود وهو صابر ومتحمل كما تقول هي في رسالتها.وقد سافرت إلى الخارج منذ سنة، والتقت بأناس طيبين نصحوها بأنه لا يجوز لها أن تعصي زوجها، وبينوا لها حكم الله، وهي الآن نادمة وتائبة، وتريد أن تعرف ما الحكم في بقائها مع زوجها، هل تبقى معه، أم أنه يفرق بينهما، وإذا فرق بينهما فما مصير الطفلين اللذين جاءا بعد الطلقة الأخيرة، هذه خلاصة رسالتها يا سماحة الشيخ؟","title":"نصيحة في طاعة المرأة لزوجها، وحكم المحلل","answer":"أولاً: الواجب على الزوجة طاعة زوجها في المعروف، ومعاشرته بالمعروف؛ لأن حقه عظيم، وقد قال الله جل وعلا: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وقال سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] وأوصى النبي ﷺ المرأة بالسمع والطاعة لزوجها، وقال: إذا باتت المرأة وزوجها ساخط عليها لعنتها الملائكة حتى تصبح وفي لفظ آخر: كان الذي في السماء ساخطاً عليها حتى يرضى عنها زوجها فالأمر عظيم والخطر كبير، وقال أيضاً عليه الصلاة والسلام: أيما امرأة سألت الطلاق من غير ما بأس لم ترح رائحة الجنة هذا وعيد شديد، فسؤال الطلاق من غير علة من غير بأس لا يجوز، وعلى المرأة السمع والطاعة، والكلام الطيب، والمعاشرة الحسنة في المعروف فيما أباح الله وشرعه ، وليس لها عصيان زوجها ولا تكديره وإيذاؤه لا بالكلام ولا بالفعال، متى طلبها لحاجته في نفسها أجابت، ومتى أمرها أطاعت فيما يتعلق بشئونهما، وهكذا ما يتعلق بخدمة البيت وإحضار الطعام، وما جرت به العادة بين الزوجين، هذه أمور يلزمها أن تطيع زوجها في ذلك، وأن تخاطبه بالتي هي أحسن، وأن تسير معه المسيرة الحسنة التي عرفها الأخيار من المسلمين فيما بينهم، وأما الطلاق فقد حدد الله الطلاق وجعله ثلاثاً، فإذا طلقها ثم راجعها، ثم طلقها ثم راجعها، وهو عاقل، طلقها على الوجه الشرعي، ثم طلقها الثالثة فإن الطلقة الثالثة تحرمها، وليس له أن ينكحها إلا بعد زوج شرعي يطؤها ثم يطلقها أو يموت عنها، بعد ذلك تحل له أن يراجعها، أما التحليل: فهو لا يجوز بل هو منكر وهو نكاح باطل، والرسول ﷺ لعن المحلل والمحلل له والعياذ بالله! فكونه ينكحها زوج محلل يتفقان معه على أنه ينكحها ثم يفارقها، هذا منكر ومن كبائر الذنوب وصاحبه ملعون، المحلل والمحلل له جميعاً، ولا يحلها للزوج السابق؛ فالذي فعلوا مع المحلل أمر منكر وطريق فاسد، وصاحبه قد تعاطى كبيرة عظيمة، وهي لا تزال محرمة على زوجها، وعليها أن تفارقه حتى تتزوج زوجاً شرعياً، وحتى يطأها الزوج الشرعي ثم يفارقها بموت أو بطلاق ثم تعتد. أما الأولاد الذين جاءوا بعد ذلك بهذا النكاح الباطل فهم أولاد زوجها بالشبهة لأجل الشبهة؛ لأن هذا وقع عن شبهة وعن جهل فيلحق الأولاد هذا الزوج وينسبون إليه، ولكن عليها وعلى زوجها التوبة إلى الله، والندم، والإقلاع، والعزم الصادق أن لا يعودا إلى مثل هذا المنكر، ومتى تزوجت زوجاً شرعياً لا محللاً ثم وطئها ثم طلقها أو مات عنها فإنها تحل لزوجها هذا. المقدم: يعني إذاً: الخلاصة -فضيلة الشيخ- أنها تفارق زوجها ويفارقها الآن. الشيخ: الخلاصة أنها مقيمة معه على حرام، وعليها أن تفارقه ويفارقها، وعليهما التوبة إلى الله جل وعلا جميعاً، أما أولادهما فلاحقون بأبيهم؛ لأجل الشبهة، لأجل وطء الشبهة، وليس لها أن تعود إليه أبداً إلا بعد زواج شرعي، بعد زوج شرعي يطؤها ثم يفارقها بموت أو طلاق، ثم بعد ذلك يتزوجها زوجها الأول إذا شاء، نعم. نسأل الله السلامة. نعم. المقدم: أحسنتم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6137/نصيحة-في-طاعة-المراة-لزوجها-وحكم-المحلل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20202.mp3","categories":["الطلاق","الحقوق الزوجية"]},{"id":8366,"question":"هنا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أم رامز أيضاً تثير مشكلة عمل المرأة والراتب وما يقع بين الأزواج حول هذا.. سماحة الشيخ فتقول: تعاقد زوجي وسافر للعمل في بلدٍ عربي، وتركني مع الأولاد، وكنت أصرف عليهم مرتبي طوال فترة غيابه، وأنا أعمل معلمة، وعندما حضر اشترى قطعة أرضٍ باسمه، ورفض أن يكون لي نصيب منها، والحمد لله، جاء دوري في الإعارة، وسافرت وبقي هو مع الأولاد، والآن يجبرني على أخذ النصف مما رزقت، وإصراره على ذلك يهدد حياتنا الزوجية، ويقول الله تعالى في سورة النساء: الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَى بَعْضٍ وَبِمَا أَنفَقُوا مِنْ أَمْوَالِهِمْ [النساء:34] صدق الله العظيم، ما رأيكم أفيدونا في هذا أفادكم الله؟","title":"حكم مطالبة الزوج للزوجة بنصف راتبها","answer":"الجواب: المشروع لكما جميعاً التسامح والتعاون على الخير، هذا هو الذي ينبغي، المشروع للأزواج فيما بينهم أن يتعاونوا على البر والتقوى، وأن يجتهدوا في مصالح أولادهم، ولا ينبغي لهم التنازع، أما معاشك فهو لك، ومعاشه له، ليس له أن يعترض عليك وليس لك أن تعترضي عليه في معاشه، والنفقة واجبة عليه على أولاده وعليك، أن ينفق عليك وعلى أولاده، ولكن إذا ساعدتيه في هذا الباب من معاشك، فهو أطيب وأحسن وأقرب إلى الوئام وسماح النفوس، وإذا كان بينك وبينه شرط على أنك تذهبين إلى العمل وله النصف أو له الربع من معاشك فلا بأس، المسلمون على شروطهم، إذا اتفقتما على شيء، فلا بأس أن تعطيه النصف أو الثلث أو الربع، حسب ما اتفقتما عليه؛ لأن ذهابك إلى العمل وتركه مع الأولاد فيه مشقة عليه وتعب عليه، فإذا سمح لك بذلك على شرط أن المعاش يكون بينكما أو على شرط أن المعاش ينفق في حاجات البيت وحاجة الأولاد هذا الشرط لا بأس به؛ لأن في ذهابك وسفرك مشقةً عليه، فإذا شرط شيئاً في ذلك، من ربع المعاش أو نصف المعاش أو أقل أو أكثر، فينبغي لك أن تفي بذلك، فالمسلمون على شروطهم، ولا ينبغي لك أن تتحرجي في هذا.\nوبكل حال، فالمشروع لكما جميعاً التسامح والتعاون على البر والتقوى، ولا تمتنعي من شيءٍ يهدئ الأحوال، ويسبب صلاح الحال بينك وبين زوجك، وأيضاً يحصل به الوئام والإحسان إلى الأولاد والإنفاق على الأولاد. نعم.\nالمقدم: بارك الله فيكم، بالنسبة لإنفاقها على الأولاد لمدة سنة، ماذا تقول للزوج سماحة الشيخ؟\nالشيخ: هذا على الزوج أن يشكرها على ذلك؛ لأنها قامت عنه بواجب، ولها أن تطالب بما يلزم الزوج من النفقة، ولها أن تتسامح، والتسامح أفضل في هذا الأمر. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6215/حكم-مطالبة-الزوج-للزوجة-بنصف-راتبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11406.mp3","categories":["الحقوق الزوجية"]},{"id":8552,"question":"يقول في آخر رسالته هذه: إذا كانت الزوجة تعصي زوجها كثيراً فماذا عليها من الإثم، ونود أن توضحوا لنا حقوق الزوجة على زوجها، وحقوق الزوج على زوجته بارك الله فيكم؟","title":"حقوق الزوجين بعضهما على بعض","answer":"الجواب: الواجب على الزوجة طاعة زوجها في المعروف، وعدم عصيانه إذا طلبها في فرشها، أو في حاجة البيت، فالواجب السمع والطاعة بالمعروف، وأن تخدمه الخدمة المعروفة بين الناس في عرف بلاده، وأن لا تعصي أمره ما لم يأمرها بمعصية الله عز وجل، فإن أمرها بالمعصية فلا سمع ولا طاعة، إذا قال لها مثلاً: لا تصلي في الوقت، أو أمرها بشرب الخمر، أو بالتدخين، هذا منكر ليس لها طاعته فيه، أما إذا أمرها بالمعروف ونهاها عن المنكر أو بأمر مباح له في حاجة هذا عليها طاعته في ذلك ويلزمها، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: إذا دعا الرجل امرأته إلى فراشه فأبت أن تجيء لعنتها الملائكة حتى تصبح وفي لفظ آخر: كان الذي في السماء ساخطاً عليها حتى يرضى عنها.\nفالواجب عليها هو السمع والطاعة في المعروف، وإذا تأخرت عن ذلك بلا عذر شرعي تأثم بذلك، وذلك من أسباب غضب الله، أما إن كانت معذورة، بأن طلبها لحاجة وهي معذورة بأن كانت مريضة لا تستطيع تلبية رغبته، أوكانت معذورة بعذر آخر، فإن الواجب على الزوج أن لا يشدد وأن يعذرها بعذرها الوجيه، وأن يحسن العشرة، وأن لا يكون كثير التشديد، يقول الله : وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ويقول سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] ويقول النبي ﷺ: استوصوا بالنساء خيراً فإنكم أخذتموهن بأمانة الله، واستحللتم فروجهن بكلمة الله.\nفالواجب على المؤمن أن يكون طيب العشرة، حسن السيرة، لا يشدد في غير وجه، وعلى الزوجة أن تسمع وتطيع وأن تحسن العشرة، وأن تكون بعيدة عن المعاكسة والعصيان، وبهذا تصلح الأمور، أما إذا شدد هو في غير وجه التشديد أو عصت الأوامر فإن هذا من أسباب الفرقة وعدم بقاء هذه الصلة الزوجية.\nفالحاصل: أن كلاً منهما عليه المعاشرة بالمعروف والقيام بالحق الذي عليه، فالزوج يقوم بالحق الذي عليه من حسن العشرة، وطيب الكلام، وطلاقة الوجه وعدم التعبيس، وأداء حقها من جهة كسوتها وطعامها وشرابها وسكنها المناسب، وعليها هي السمع والطاعة وأن تجيبه إلى رغبته في حاجته في نفسها، وفيما يتعلق ببيته وملابسه ونحو ذلك حسب العرف المعتاد في بلاده، والتي تخدم في العرف يخدمها حسب الطاقة والإمكان، والله المستعان. نعم.\nالمقدم: جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6630/حقوق-الزوجين-بعضهما-على-بعض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20603.mp3","categories":["الحقوق الزوجية"]},{"id":8555,"question":"يقول في آخر رسالته هذه: إذا كانت الزوجة تعصي زوجها كثيراً فماذا عليها من الإثم، ونود أن توضحوا لنا حقوق الزوجة على زوجها، وحقوق الزوج على زوجته بارك الله فيكم؟","title":"حقوق الزوجين بعضهما على بعض","answer":"الجواب: الواجب على الزوجة طاعة زوجها في المعروف، وعدم عصيانه إذا طلبها في فرشها، أو في حاجة البيت، فالواجب السمع والطاعة بالمعروف، وأن تخدمه الخدمة المعروفة بين الناس في عرف بلاده، وأن لا تعصي أمره ما لم يأمرها بمعصية الله عز وجل، فإن أمرها بالمعصية فلا سمع ولا طاعة، إذا قال لها مثلاً: لا تصلي في الوقت، أو أمرها بشرب الخمر، أو بالتدخين، هذا منكر ليس لها طاعته فيه، أما إذا أمرها بالمعروف ونهاها عن المنكر أو بأمر مباح له في حاجة هذا عليها طاعته في ذلك ويلزمها، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: إذا دعا الرجل امرأته إلى فراشه فأبت أن تجيء لعنتها الملائكة حتى تصبح وفي لفظ آخر: كان الذي في السماء ساخطاً عليها حتى يرضى عنها.\nفالواجب عليها هو السمع والطاعة في المعروف، وإذا تأخرت عن ذلك بلا عذر شرعي تأثم بذلك، وذلك من أسباب غضب الله، أما إن كانت معذورة، بأن طلبها لحاجة وهي معذورة بأن كانت مريضة لا تستطيع تلبية رغبته، أوكانت معذورة بعذر آخر، فإن الواجب على الزوج أن لا يشدد وأن يعذرها بعذرها الوجيه، وأن يحسن العشرة، وأن لا يكون كثير التشديد، يقول الله : وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ويقول سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] ويقول النبي ﷺ: استوصوا بالنساء خيراً فإنكم أخذتموهن بأمانة الله، واستحللتم فروجهن بكلمة الله.\nفالواجب على المؤمن أن يكون طيب العشرة، حسن السيرة، لا يشدد في غير وجه، وعلى الزوجة أن تسمع وتطيع وأن تحسن العشرة، وأن تكون بعيدة عن المعاكسة والعصيان، وبهذا تصلح الأمور، أما إذا شدد هو في غير وجه التشديد أو عصت الأوامر فإن هذا من أسباب الفرقة وعدم بقاء هذه الصلة الزوجية.\nفالحاصل: أن كلاً منهما عليه المعاشرة بالمعروف والقيام بالحق الذي عليه، فالزوج يقوم بالحق الذي عليه من حسن العشرة، وطيب الكلام، وطلاقة الوجه وعدم التعبيس، وأداء حقها من جهة كسوتها وطعامها وشرابها وسكنها المناسب، وعليها هي السمع والطاعة وأن تجيبه إلى رغبته في حاجته في نفسها، وفيما يتعلق ببيته وملابسه ونحو ذلك حسب العرف المعتاد في بلاده، والتي تخدم في العرف يخدمها حسب الطاقة والإمكان، والله المستعان. نعم.\nالمقدم: جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6630/حقوق-الزوجين-بعضهما-على-بعض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20603.mp3","categories":["الحقوق الزوجية"]},{"id":8557,"question":"هذه رسالة من السائل (ع. س) سوري الجنسية مقيم في الرياض، يقول في رسالته: أنا متزوج وبعد زواجي بخمس سنوات علمت من أحد الجيران أن زوجتي تمارس الفاحشة، فراقبت ذلك فوجدته صحيحاً، فما كان مني إلا أن قمت بضربها، فطلبت مني الطلاق أكثر من مرة فلم أطلقها خوفاً من تشتت الأولاد، ولو طلقتها ليس عندي مال أتزوج به، وأنا عامل عادي يوم أعمل وأكثر الأيام بدون عمل أفيدوني ماذا أفعل، بارك الله فيكم؟","title":"ما يجب على من علم عن زوجته أنها تفعل الفاحشة؟","answer":"الجواب: هذه من المصائب العظيمة، والواجب علاجها بالتأديب والنصيحة، وتوجيه اللوم إليها وبيان أن الواجب عليها العفة، والحذر مما حرم الله عليها فإن الزنا من أقبح الجرائم ومن أعظم الكبائر، وقد توعد الله الزاني بالعذاب الشديد، قال جل وعلا: وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا نعوذ بالله، ... توعد الزاني بأنه يضاعف له العذاب، ويخلد فيه مهاناً يوم القيامة في النار نسأل الله العافية. والنبي عليه الصلاة والسلام قال: لا يزني الزاني حين يزني وهو مؤمن هذا من علامة ضعف الإيمان، أو عدم الإيمان نعوذ بالله، فعلى الزوج أن يلاحظها ويعتني بها ويؤدبها فيما إذا فعلت شيئاً من هذا، أو وجد علامات شيء من ذلك، فعليه أن يؤدبها الأدب الرادع مع الوعظ والتذكير بالله، وأن هذا منكر ومعصية لله ، ومن أسباب الفراق، فإن استقامت فالحمد لله، وإن لم تستقم فارقها طلقها؛ لئلا تحمل عليه أولاداً من غيره، ومتى استقامت وتابت ورجعت إلى الله  فالحمد لله، فالتوبة بابها مفتوح ومن تاب تاب الله عليه إذا كان صادقاً، فأما إن لم يحصل منها الرجوع والتوبة واستمرت على حالها السيئة، فإن مثل هذه لا ينبغي بقاؤها، بل ينبغي فراقها وعدم بقائها؛ لأن هذا يجر عليه شراً كثيراً في نفسه وفي أولاده، وفي سمعته، ولا حول ولا قوة إلا بالله! نعم.\nالمقدم: ألا توجهون سماحة الشيخ إلى سد أبواب التي تؤدي لمثل هذا من التساهل باختلاط النساء والرجال ودخول غير المحارم؟\nالشيخ: كذلك هذا حق أيضاً كونه يعني، يعتني بسد الأبواب التي تفضي إلى هذا الشيء مثل منعها من الخروج، ومثل عدم اختلاطها بالنساء الخبيثات من جيران أو غيرهم، إذا تيسر له هذا، هذا من أهم الأمور ألا تخالط الرديئات، وألا تخرج الأسواق، وأن تحرص على الحجاب، ولكن من اعتادت الفاحشة والعياذ بالله تحصلها ولو بالهاتف نسأل الله العافية وهي في بيتها نسأل الله ....، لكن على كل حال تعاطي الأسباب مهما أمكن إذا كان من عادتها الخروج يمنعها من الخروج إلا من ضرورة، وإذا كان يدخل عليها أحد رديء يمنع الداخل الرديء، وإذا كانت تخرج إلى جيران ليسوا بطيبين يمنعها من ذلك، وهكذا، يعني: يتعاطى الأسباب..\nالمقدم: والخروج إلى غير المحارم، مقابلة غير المحارم يتساهل فيه كثير من الناس؟\nالشيخ: كذلك خروجها إلى غير المحارم إلى بني عمها الذين لا يؤمنون، أو إلى غيرهم كل هذا يعني: عليه أن يجتهد في منع أسباب الشر مهما أمكن.\nالمقدم: جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6631/ما-يجب-على-من-علم-عن-زوجته-انها-تفعل-الفاحشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20604.mp3","categories":["الحقوق الزوجية","نصائح وتوجيهات"]},{"id":8649,"question":"يسأل أيضاً ويقول: ما حكم لعن الرجل لزوجته، وهل تحرم عليه بذلك أم لا؟","title":"حكم لعن الرجل لزوجته","answer":"الجواب: لعن الرجل لامرأته أمر منكر ومن كبائر الذنوب، وهكذا لعنه للناس، فاللعن من الكبائر ولا يجوز للمسلم أن يتعاطى ذلك مع إخوانه المسلمين، وقد صح عن رسول الله ﷺ أنه قال: لعن المؤمن كقتله وهذا يدل على عظم الخطر حتى شبهه بالقتل، فدل ذلك على أنه من كبائر الذنوب، وقال عليه الصلاة والسلام: سباب المسلم فسوق وقتاله كفر متفق على صحته، فدل على أن السباب -وهو اللعن والشتم- من الفسوق يعني: من المعاصي، فوجب تركه والحذر منه، وقال عليه الصلاة والسلام: إن اللعانين لا يكونون شهداء ولا شفعاء يوم القيامة وجاء عنه عليه الصلاة والسلام أنه قال: ليس المؤمن بالطعان، ولا اللعان، ولا الفاحش، ولا البذيء فلا يجوز للمسلم أن يلعن زوجته، وليس لها أن تلعن زوجها، وليس له أن يلعن أولاده، وليس لها أن تلعن أولادها، وهكذا غيرهم من المسلمين لا يجوز سبهم ولعنهم، ولا تحرم عليه زوجته بذلك، لو أنه لعنها لم تحرم بذلك فزوجته باقية على حلها له، لكنه قد أساء وعليه التوبة إلى الله وعليه استسماح زوجته مما حصل من لعنها، ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6787/حكم-لعن-الرجل-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_213/21302.mp3","categories":["الأخلاق المذمومة","الحقوق الزوجية"]},{"id":8764,"question":"أخت لنا بعثت برسالة تقول (م. أ. ع) مصرية، تقول في رسالته: زوجي مصري يعمل بالرياض وتزوجته من سنتين صبرت فيهم على الوحدة والغربة فهو ينزل عمله مبكرًا جدًا ويرجع بعد الظهر تقريبًا بنصف ساعة أو أقل ليتغدى ثم ينزل ولا أراه إلا منتصف الليل، وخلال الفترة من العصر إلى الليل يقضيها بين عمل وقراءة مع أصدقاء له، وقد نصحته أن يعطي كل ذي حق حقه، فلربه حق ولنفسه حق ولزوجه حق من الجلوس معها ومؤانستها فهو يأتي متعب لينام ولا يؤانسني حتى بالكلام الطيب الذي تنتظره الزوجة، وهذا بلا شك له أثره السيئ على نفسيتي وهو يكره كثرة الكلام معه في هذا الموضوع، ويكتفي بأنه يجلس بالبيت الخميس فقط وهذا مما لا شك فيه أثر على سلوكي فأصبحت أغضب وأثور وذكرته كثيرًا، ولم يكن جوابه إلا: هذه هي الحياة، فبم تنصحونني؟ وما هو حل هذه المشكلة التي عانيت منها وصبرت عليها سنتين جزاكم الله خيرا؟ً","title":"نصيحة للزوج المقصر في حقوق زوجته","answer":"الجواب: أولًا: ننصحك بالصبر والكلام الطيب وحسن الأسلوب معه، والدعاء له بالهداية والتوفيق، ونقول لك: قد أحسنت وقد ذكرت له الحق، فإن عليه أن ينصف زوجته، وأن يعطيها حقها بالمؤانسة والجلوس معها والتحدث معها كما فعل النبي ﷺ، وكما أوصى أمته عليه الصلاة والسلام، وقال: استوصوا بالنساء خيرًا، وقال لـعبدالله بن عمرو لما أعرض عن زوجته: إن لنفسك عليك حقًا، ولأهلك عليك حقًا، ولضيفك عليك حقًا، فأعط كل ذي حق حقه، ولما زار سلمان  أبا الدرداء ورأى عنده شيئًا من التقشف والتعبد وعدم التفاته إلى أهله نصحه، وكانت اشتكت إليه زوجة أبي الدرداء وأنه لا حاجة له في الدنيا، فعرف من كلامها أنه لا يلتفت إليها كما ينبغي، فنصحه سلمان ، وأمره أن ينام مع أهله إلى آخر الليل ثم يقوم يصلي، وأمره أن يصوم تارة ويفطر تارة، وقال له سلمان: إن لنفسك عليك حقًا، ولأهلك عليك حقًا، ولضيفك عليك حقًا، فأعط كل ذي حق حقه، ثم توجه إلى النبي صلى الله عليه وسلم فأخبره سلمان و أبو الدرداء بما جرى فقال النبي صلى الله عليه وسلم: صدق سلمان، صدق سلمان.\nفالواجب على زوجك أن يتقي الله، وأن ينصفك وأن يعتني بك، وأن يحسن عشرتك، فيعمل في الوقت الذي حدد فيه العمل، ثم يأتي إلى البيت ويعاشر أهله ويتحدث إليهم، هكذا حتى تطمئن زوجته إليه، وحتى يحصل بينهما المؤانسة والراحة فإن الزوجة سكن الزوج، الله جعل الزوجة سكنًا للزوج وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُمْ مِنْ أَنفُسِكُمْ أَزْوَاجًا لِتَسْكُنُوا إِلَيْهَا [الروم:21] فعليك -أيها الزوج- أن تتقي الله، وأن تحسن في أهلك، وأن تفرغ لهم بعض الوقت، وأن تؤانسهم بالكلام الطيب والمداعبة وحسن المقابلة وطلاقة الوجه؛ لأن لها عليك حقًا، وهكذا ضيفك، وهكذا بدنك، فأعط ربك حقه، وأعط العمل حقه، وأعط نفسك حقها، وأعط الزوجة حقها، واجتهد في ذلك واستسمحها وقل لها الكلام الطيب عما تقصر فيه حتى تسمح عنك، وعليك بالرفق والحكمة وطيب الكلام، ولا تكن عنيفًا ولا شديدًا، هذا هو الذي ينبغي لك أيها الأخ، وعليك -أيها الأخت في الله- أن تصبري وتحتسبي، وأن تخاطبيه بالتي هي أحسن وسوف يجعل الله لك فرجًا ومخرجًا وحسن عاقبة. نعم.","link":"https://binbaz.org.sa/fatwas/6914/نصيحة-للزوج-المقصر-في-حقوق-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16211.mp3","categories":["الحقوق الزوجية"]},{"id":8815,"question":"نفس الأخت السائلة (م. أ. ع) بعثت برسالة أخرى ضمنتها الموضوع السابق وأشياء أخرى، تقول: تزوجت شابًا نحسبه ملتزم، واتفق مع أبي أنه سيؤثث بيت الزوجية اعتبارًا أن الأثاث مهر، وجئت إلى الرياض وكل أملي في حياة زوجية صالحة، فإذا به لا يحب الجلوس بالبيت حتى بعد انتهاء دوامه، ويأتي البيت في ساعة متأخرة، ويبحث عن أي شيء يشغله خارج البيت، ونصحته كثيرًا وصبرت عليه ولم يسمع للنصيحة، ومرت سنتان ولي منه بنت وولد الآن، وهو إلى الآن لم يدخر مالًا لا للبيت ولا لتأثيثه الذي هو مهر لي، وكلما ذكرته أيضًا بحقوقي لديه لم يهتم، ويدعي أنه يصرف المال على إصلاح سيارة لديه دائمة التعطيل، ويسرف في ماله كثيرًا، وهنا أتساءل: أليس حق الزوجة من بيت ومهر أولى من أي حقوق أخرى لأنه يعتبر دين عليه؟ثانيًا: أليس من حق الزوجة أن يجلس معها يؤنسها في غربتها بعد انتهاء عمله، ويذكرها بالله أيضًا؟ ماذا تنصحونني، وماذا أفعل وقد ساءت نفسيتي؟ هل يحق لي هنا طلب الطلاق لأنه مصمم ومصر على هذه الحياة بتلكم الصورة؟","title":"نصيحة للزوجة بالصبر على أخطاء الزوج","answer":"الجواب: قد سبق ما نصحتك به أيها الأخت الكريمة، ووصيتي كما تقدم الصبر وحسن النصيحة بالكلام الطيب، ولا تيأسي لا تيأسي، والواجب عليه أن يؤدي الحق الذي عليه، فإن أداء الدين أمر لازم، ولكن يقول الله عز وجل: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280] فإذا كان معسرًا فارفقي به وسامحيه حتى يجعل الله فرجًا ومخرجًا، والسيارة اليوم لا يخفى على أحد أنها ضرورية، ولا سيما صاحب العمل يذهب عليها ويرجع عليها، فهو في أشد الحاجة إليها على أن تكون من السيارات التي تناسب أمثاله، فعليه أن يجتهد في حفظ ما تيسر من المال لحاجة البيت وتأثيث البيت، وعليه أن يتقي الله في إنصافك ومؤانستك والتحدث إليك وإعطائك ما تيسر من الوقت، هذا أمر لازم له، والرسول ﷺ أمر بذلك وقال ﷺ: استوصوا بالنساء خيرًا فعليه أن يتقي الله وأن يقوم بواجب الأهل حسب طاقته وإمكانه.\nوأنت لا تعجلي في طلب الطلاق، واصبري وأحسني العشرة إليه وأبشري بالأجر العظيم والخير الكثير والعاقبة الحميدة، وقد تبتلين بمن هو شر منه فلا تعجلي، فالوقت الآن خطير وهذا آخر الزمان، والشر أكثر والخير أقل، فعليك أن تصبري وتحتسبي، وأن تسألي الله له الهداية والتوفيق، وأن يغير حاله إلى حال خير منها، والله سبحانه هو الفعال لما يريد وهو القادر على كل شيء وهو القائل : وَبَشِّرِ الصَّابِرِينَ [البقرة:155]، وهو القائل سبحانه: إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ [الزمر:10]، ويقول نبيه عليه الصلاة والسلام: ما أعطي أحد عطاءً خيرًا وأوسع من الصبر. نعم.","link":"https://binbaz.org.sa/fatwas/6970/نصيحة-للزوجة-بالصبر-على-اخطاء-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16212.mp3","categories":["الحقوق الزوجية"]},{"id":8862,"question":"أخونا يقول: إنه مبتلى بزوجة غير صالحة إلا أنها ابنة عمه ويتيمة أيضاً، وهي غير طائعة لربها -كما يقول- وبالتالي غير مطيعة له ويرجو من سماحة الشيخ التوجيه، هل يخرجها أو يصبر عليها، وبم توجهونه لو تكرمتم؟","title":"ما واجب الزوج تجاه زوجة مفرطة في طاعة ربها؟","answer":"الجواب: أولاً: ينظر في شأنها من جهة عدم طاعتها لربها إن كانت لا تصلي فترك الصلاة كفر على أرجح قولي العلماء كما تقدم وإن كانت لا تجحد وجوبها، فمثل هذه لا ينبغي له أن يعاشرها ولا يتصل بها حتى تتوب إلى الله وترجع عن كفرها وتقيم الصلاة، أما إن كانت مسائل أخرى تفعلها من بعض المعاصي كالغيبة أو بعض التساهل في الحجاب، أو ما أشبه ذلك من المعاصي فإنه يفعل ما هو الأصلح، فإذا رأى الصبر عليها ونصيحتها وتأديبها ولو بالضرب المناسب الذي لا يجرح ولا يكسر، ضرب يؤدبها ويؤلمها ولكن لا يضرها ضرراً كبيراً فمثلما قال الله جل وعلا: وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ[النساء:34] فالمؤمن يؤدب زوجته إذا لم تستقم بالوعظ والتذكير ولا بالهجر فله تأديبها التأديب المناسب الذي لا يضرها ولكن يؤلمها بعض الألم ويخيفها حتى تستقيم على أمر الله، أو يخبر والدها إن كان لها والد أو أخاها إن كان لها أخ جيد حتى يقوم بنصيحتها أو تأديبها ومساعدة زوجها عليها.\nالمقدم: يقول: إنها يتيمة سماحة الشيخ؟\nالشيخ: ولو أنها يتيمة، اليتم لا يمنع من تأديبها ونصيحتها واليتيم يؤدب إذا أخطأ يؤدب ويضرب إذا ترك الصلاة وهو ابن عشر ضرب وإذا أساء الأدب ضرب حتى يتمرن على الخير وحتى يعتاد الخير ولو أنه يتيم، بعض الناس يحسب أن اليتيم لا يؤدب ولا يضرب، لا، اليتيم يضرب إذا دعت الحاجة إلى ضربه ويؤدب ويسجن حتى يستقيم وحتى يتأدب الآداب الشرعية، وإلا خرج كلاً على الناس وضرراً على الناس فاسداً ضائعاً ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: إذاً يرى سماحة الشيخ أنه يناقش هذه البنت في موضوع الصلاة إن كانت جاحدة لوجوبها أو متساهلة أو متهاونة ومن ثم يبدأ في عشرتها من جديد؟\nالشيخ: ينظر أولاً في مسألة الصلاة، إذا كانت لا تصلي يعلمها أن ترك الصلاة كفر وأنها لا تستقيم له زوجة وهي تترك الصلاة، والواجب فراقها إلا أن تتوب، فإن تابت فالحمد لله وإلا اعتزلها حتى تتوب إلى الله، وإذا كانت فقيرة أنفق عليها إن كان يستطيع أو سعى لها في الإنفاق عليها لفقرها لعل الله يهديها بذلك، ولعلها ترجع إلى الصواب، فإن أصرت رفع أمرها إلى ولاة الأمور تستتاب فإن تابت وإلا قتلت؛ لأن من ترك الصلاة ولم يتب يقتل، نسأل الله السلامة، وإن كانت المسألة معاصي أخرى غير ترك الصلاة دون ذلك فالمعاصي تعالج بالأدب تأديبها يؤدبها الزوج أو أبوها أو أخوها ومع النصيحة مع الوعظ والتذكير حتى تستقيم إن شاء الله، مع الإحسان إليها بالنفقة. نعم.\nالمقدم: بارك الله فيكم. إذاً باب المناقشة مفتوح والحالة هذه؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/7017/ما-واجب-الزوج-تجاه-زوجة-مفرطة-في-طاعة-ربها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_137/13705.mp3","categories":["الحقوق الزوجية"]},{"id":8922,"question":"الرسالة التالية وصلت إلى البرنامج من البحرين، باعثها أحد الإخوة من هناك يقول: أبو إبراهيم، أخونا له مجموعة من الأسئلة من بينها سؤال يقول: أرغب في الزواج من امرأة ثانية وأنا قادر على تكاليف الزواج وعلى الصرف على بيتين، وأجد في نفسي أنني أستطيع أن أعدل بين الزوجتين، لكني سمعت من بعض الإخوة أن زواج الثانية لابد له من شروط، كأن تكون الزوجة الأولى مريضة أو لا تنجب أو غير ذلك من الأسباب، فهل هذا صحيح أو أنه في الإمكان أن أعدد من غير سبب ما دمت قادراً وأجد في نفسي الاستطاعة على العدل بين الزوجتين، وماذا يرى سماحتكم في هذا الموضوع ولاسيما التعدد خاصة، جزاكم الله خيراً؟","title":"هل يتزوج الثانية دون عيب أو نقص في الأولى","answer":"الجواب: لا مانع من التعدد وإن كانت الزوجة الموجودة صالحة وطيبة ليس فيها مرض ولا علة ولو كانت تنجب لا حرج في ذلك إذا كنت بحمد الله قادراً على الزواج وعلى العدل فالحمد لله، الله يقول سبحانه: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3]، والنبي ﷺ تزوج عدة من النساء عليه الصلاة والسلام وليس في أزواجه علة.\nفالمقصود أنه ﷺ تزوج وهكذا الصحابة تزوجوا، منهم من تزوج ثنتين وتزوج ثلاث، ومنهم من تزوج أربع، فالأمر في هذا واسع والحمد لله، إنما المؤمن يحرص أن يعدل ويجتهد في العدل بين الزوجتين أو الثلاث أو الأربع، والزواج فيه مصالح؛ فيه عفة الفرج وعفة النظر وفيه كثرة النسل، وفيه إحسان للنساء أيضًا حتى النساء فيه إحسان إليهن، فإن وجود نساء ليس لهن أزواج هذا من المصائب وفيه خطر، فكون المرأة تعطى نصف زوج، يعني: يحصل لها نصف أو ثلث أو ربع يعفها وينفق عليها ويحصل لها بسببه النسل هذا خير عظيم ومصلحة كبيرة، خير من بقائها في البيت بدون زوج، فكونها يحصل لها ربع الزوج أو ثلثه أو نصفه خير من بقائها في بيتها بدون زوج لوجوه كثيرة ومصالح جمة للزوج والزوجة جميعًا من كثرة النسل وعفة فرجها وعفة فرجه، وغض بصرها وغض بصره، وإيناسها في هذه الدنيا وقضاء وطرها وقضاء وطره، فالمصالح كثيرة، ومن ذلك تكثير الأمة، فإن وجود النسل بين الزوجين من زوجتين أو أكثر أكثر للأمة، والنبي ﷺ قال: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة.\nفالمطلوب تكثير الأمة، تكثير الأولاد الصالحين من الرجال والنساء، فالمؤمن يجتهد ويسأل الله التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا، بالرغم من أن شطر هذه الكلمة موجه للنساء جزاكم الله خيرًا سماحة الشيخ إلا أني أجد في نفسي الرغبة أكثر ولاسيما وقد قرأت كثيراً عن تعدد العوانس في البيوت؟\nالشيخ: من المصائب أن كثيرًا من الناس اليوم يدعو إلى عدم التعدد وربما اغتروا بما يقوله بعض النصارى ومن شابه النصارى في ذلك، وكثير منهم يحبذ أن يكون الزوج باقياً على واحدة ويندد بالأزواج الذين يعددون وهذا كله غلط، وكله تشبه بالنصارى ، أو تأثر بما قالوه أو قاله من التحق بهم أو شاركهم في رأيهم أو اقتدى بهم في أخلاقهم، والشريعة الإسلامية العظيمة جاءت بالتعدد وكان التعدد قبلنا أكثر، كان عند داود مائة امرأة عليه الصلاة والسلام، وتزوج سليمان تسعاً وتسعين، في رواية: سبعين، كان التعدد في شريعة التوراة أكثر أما في شريعة محمد ﷺ فاقتصر العدد على أربع فأقل للأمة ما عدا النبي ﷺ فله تسع عليه الصلاة والسلام، هذا من رحمة الله جل وعلا أن جعل العدد أربعًا فأقل في هذه الأمة لحكمة بالغة، أما مصالح التعدد فشيء لا يحصى، مصالح التعدد فيه شيء واضح، المصالح كثيرة للرجال والنساء، النساء يحصل لهن العفة وقضاء الوطر والإنفاق عليهن، ودخول الزوج عليهن واحترامهن، والدفاع عنهن وهيبة الرجل إذا دخل عليها، وسلامتها في الأغلب من تعلق غيره بها، إلى غير ذلك من المصالح، ثم الإنفاق عليها ثم وجود الولد الذي يهبها الله ولدًا على يديه فيحصل لها بذلك خير عظيم إذا أصلح الله الولد، وقد يكون عدة أولاد من الرجال والنساء، فالمصالح كثيرة، فهو ينتفع وهي تنتفع، والأسرة كلها تنتفع، فإن كثرة النسل فيه نفع للجميع وتكثير للأمة، كما أن في ذلك صيانة لها وحماية لها وعفة لفرجها وإنفاقًا عليها وإحسانًا إليها، وحرصاً على كل ما يصونها من كل بلاء و شر. نعم.\nالمقدم: بارك الله فيكم، بعض النساء سماحة الشيخ تعتقد أن الزواج من أجل النفقة فقط، فإذا كانت موظفة ولها دخل أو لها تجارة أو كذا لا تريد إلا رجلا خاليًا؟\nالشيخ: هذا غلط، هذا من الغلط، الزواج يراد منه مصالح كثيرة:\nيراد منه طيب العشرة بين الزوجين والأنس في هذه الدنيا والتمتع بينهما المتعة الحسنة الصالحة فيما بينهما.\nويراد منه أيضاً إنجاب الأولاد الصالحين حتى تكثر الأمة ويكثر فيها الصلاح والخير.\nويراد منه أيضاً عفة الفرج عما حرم الله وعفة النظر عما حرم الله.\nويراد من ذلك أيضاً تقليل الفساد في الأرض فإن وجود الرجال والنساء بدون زواج من أعظم الأسباب للفساد في الأرض وكثرة الزنا والفواحش، فإذا تزوجت وتزوج الشاب صار هذا من أعظم الأسباب للصيانة والحماية وقلة الفساد في الأرض، فالزواج ينفع هذا وهذا، ولهذا قال ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء .\nفالزواج فيه خير للجميع لا مجرد النفقة فقط، فيه مصالح كثيرة غير النفقة. نعم.\nالمقدم: بارك الله فيكم، بعض الأزواج سماحة الشيخ أساء إلى مبدأ التعدد؟\nالشيخ: لا شك أن الزوج إذا لم يعدل أساء إلى التعدد وأساء إلى الشريعة وأساء إلى المسلمين، فالواجب على الزوج أن يتقي الله وأن يحسن فيما عليه وأن يؤدي الواجب وأن يكون حريصاً على العدل بين الزوجتين فأكثر حتى لا يظلم نفسه وحتى لا يسبب النفرة من التعدد بأسباب عمله، وحتى أيضاً لا تقع المشاكل بين الأسرتين وتكثر الخصومات في المحاكم، هذا كله يسبب المشاكل، أما العدل والإحسان وطيب العشرة فهو يسبب الخير الكثير للأسرتين وللمجتمع كله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7079/هل-يتزوج-الثانية-دون-عيب-او-نقص-في-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_142/14203.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8933,"question":"جزاكم الله خيراً، إلى المسئولين عن برنامج نور على الدرب: السلام عليكم ورحمة الله وبركاته، أحيطكم علماً بأنني من المتابعات لهذا البرنامج الذي هو فعلاً نور لمن أراد أن يسير على درب الإيمان، وفقكم الله وهدانا وإياكم إلى ما فيه خير الإسلام والمسلمين.وبعد: أنا سيدة متزوجة وعندي طفلان والآن مرافقة لزوجي الذي يعمل في إحدى الدول العربية الشقيقة، وكنت أعمل في إحدى الجامعات وحاصلة على إحدى الدرجات العلمية وأوشكت إجازتي أن تنتهي التي وافق العمل عليها لمرافقة الزوج، ولما يتطلبه عملي من حضور ومواصلة دراسة ولحبي لعملي وإحساسي أنني أقدم شيئاً في الحياة يدخر لي للآخرة، وليس لدنيا أو منصب أفكر في العودة إلى بلدي وعملي وبصحبة أطفالي معي، ولكني في نفس الوقت أخاف الله أن يكون في بعد أطفالي عن والدهم وأيضاً بعدي عن زوجي إجحاف وهضم حق لهم علي، أفيدوني أفادكم الله، أأرجع إلى عملي أم أستقيل وأمكث مع زوجي وأولادي وبذلك أنال ثواب الآخرة؟ والسلام عليكم ورحمة الله وبركاته، والمرسلة إحدى الأخوات تقول: (س. م.) من مصر.","title":"ما الواجب على المرأة إذا خيرت بين عملها وبين أبنائها؟","answer":"الجواب: أولاً: لابد من سماح الزوج، فإذا سمح الزوج لك بالرجوع فانظري في الأصلح، فإن رأيت أن الأصلح الرجوع لدينك ودنياك وزوجك سامح فارجعي إلى بلدك أنت وأطفالك، أما إذا لم يسمح فلا ترجعي بل عليك السمع والطاعة، فابقي عند زوجك وعند أولادك واعملي ما يلزم من نصح للزوج وخدمته وخدمة الأولاد واستعيني بالله على طاعته من القراءة والإكثار من قراءة القرآن وذكر الله، ومن الأعمال الصالحات حتى ترجعا جميعاً إن شاء الله.\nأما إذا سمح زوجك وقال: لا بأس، فانظري في الأصلح، إن كان جلوسك عنده أصلح لك ولزوجك ولأولادك فاجلسي عنده ولو سمح لك اجلسي، حتى يتمتع بك وحتى يطمئن إليك وحتى يبتعد عن أسباب الشر، وأنت كذلك تطمئنين إليه وتبتعدي عن أسباب الشر وتقومي بأطفالك في حضرة أبيهم وتحسني إليهم، هذا كله أنفع لكم جميعاً فيما يظهر وأصلح لكم جميعاً فيما يظهر، لكن متى اتفقت مع الزوج على الرجوع واتضح لك أنه أصلح لأمر ديني، في رجوعك ينفع الناس وهو سامح وليس عليه خطر من رجوعك فلا بأس أن ترجعي بأطفالك وتقومي بما يلزم هناك من الإحسان إلى أطفالك وتربيتهم التربية الشرعية الإسلامية، والدعاء لهم بالصلاح والدعاء لزوجك بالتوفيق ولا حرج في ذلك. نعم.\nالمقدم: بارك الله فيكم، لكن يرجح سماحة الشيخ عبد العزيز أن تبقى مع زوجها وبصحبة الأطفال أيضاً ليجتمع شمل الأسرة وليتربى الأطفال تربية صحيحة؟\nالشيخ: نعم، نعم.\nالمقدم: ترجحوا هذا؟\nالشيخ: بدون شك.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7091/ما-الواجب-على-المراة-اذا-خيرت-بين-عملها-وبين-ابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_143/14308.mp3","categories":["قضايا المرأة","الحقوق الزوجية"]},{"id":8979,"question":"أمامي رسالة مطولة سماحة الشيخ وباعثها أحد الإخوة يقول: المرسل عباس عبدالفتاح شحات من جمهورية مصر العربية وجه قبلي، أخونا رسالته مطولة في الواقع ملخصها: أنه تزوج فتاة وكان يعتقد أنها على خلق ودين فاتضح له غير ذلك، واتضح له أيضًا أن أهلها على أسوأ وصف يمكن أن يذكر، ويذكر أشياء وأشياء لعل في عدم ذكرها الأفضلية أرجو من سماحة الشيخ أن يتفضل بتوجيه أخينا ولاسيما أنه يستشيركم في موضوع طلاقها وقد أنجبت له مولودًا؟","title":"موقف الزوج تجاه زوجة ظهر له عدم صلاحها","answer":"الجواب: الذي نرى في هذا هو النصيحة، ينصحها ويجتهد في ذلك، ويوجهها إلى الخير، ويعلمها ما تجهل، ويوصيها بما ينفعها، ويطلب من أوليائها أيضًا إذا كان فيهم أحد طيب أن ينصحها أيضًا، أو من أمه أو أمها أو أخته أو أختها، أو بعض أقاربه الآخرين أو أقاربها أن ينصحوها حتى تدع ما يسوءه منها، وما أنكره عليها من الأخلاق، يجتهد في هذا ولا يعجل في الطلاق. نوصي بأن لا تعجل يا أخي في الطلاق وأن تجتهد في النصيحة، وأن تعمل ما تستطيع من توجيهها إلى الخير أو الاستعانة ببعض أقاربها أو أقاربك على توجيهها إلى الخير ولو كان أهلها في أسوأ حالة قد يهديها الله وتخالف أهلها.\nفعليك أن تنصحها وأن تستكثر من ذلك، وأن لا تعجل ولاسيما معها أن أولاد لك، فلا ينبغي أن تعجل مهما أمكن. نعم.\nالمقدم: بارك الله فيكم، إذا كان يتأذى من الناحية المالية والمصاريف سماحة الشيخ؟\nالشيخ: على كل حال هذا له علاج يحفظ عنها ماله ولا يعطيها إلا قدر حاجتها، ويدعو لها في ظهر الغيب بالتوفيق والهداية في صلاته وفي غير صلاته، دعاء المسلم لأخيه بظهر الغيب مستجاب، يدعو لها يجتهد يدعو لها بالصلاح والتوفيق والهداية، وأن يعافيها الله من شر أخلاقها التي انتقدها عليها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7137/موقف-الزوج-تجاه-زوجة-ظهر-له-عدم-صلاحها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_174/17404.mp3","categories":["الحقوق الزوجية"]},{"id":8983,"question":"نعود في هذه الحلقة سماحة الشيخ إلى رسالة الأخ: بابكر آدم سليمان سوداني أخونا عرضنا جزءًا من أسئلته في حلقة مضت وفي هذه الحلقة يقول: أنا متزوج ومستقر بمنطقة، ولي عمل بمنطقة أخرى تبعد حوالي مسافة يومين بالسيارة، وحصل أن تزوجت بمنطقة عملي وكنت أقيم في مكان عملي زهاء شهرين أو ثلاثة وإذا أتيت إلى مكان استقراري أقيم حوالي أسبوع أو أسبوعين فهل هذا صحيح أم فيه مخالفة للشريعة في العدل بين الزوجات؟","title":"كيف يعدل وله زوجتان في منطقتين متباعدتين","answer":"الجواب: الواجب عليك أن تعدل بينهما حسب الطاقة والإمكان، فتنقل التي في مستقرك إلى محل عملك حتى تعدل بينهما أو تنقل الجديدة إلى محلك الأول حتى تعدل بينهما، أو تستسمحهما، فإذا سمحت الأولى ولم تلحقها حرجًا فلا بأس بذلك الحق لهما، فإذا سمحت الأولى عن بعض حقها فلا بأس.\nالمقصود أن عليك أن تتحرى العدل حسب طاقتك، إما بنقل الأولى إلى محل عملك، أو نقل الثانية إلى محل أصلك إلى محل بلدك الأولى حتى تجمع بينهما هناك وحتى تعدل بينهما، أو تستسمح الأولى عما يحصل عليها من النقص، فإذا سمحت فالحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7141/كيف-يعدل-وله-زوجتان-في-منطقتين-متباعدتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_174/17408.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":9020,"question":"زوجتي كانت تعمل بالمملكة قبل أن أتزوجها وبعد الزواج حضرت معها إلى المملكة بصفة مرافق لها بدلاً من أخيها، والآن تريد زوجتي أن تستقل براتبها على أن أعمل وأتحمل مصروفات البيت في حين أنها تستثمر وقت البيت في العمل وتحصل على راتب، كما أنها ترفض البقاء في البيت بحجة أنها كانت تعمل قبل الزواج، فما هو حكم الإسلام في ذلك؟ وهل هذا الراتب التي تحصل عليه يخصها فقط أم للزوج حق فيه، صاحب هذا السؤال هو الأخ محمد أسامة إسحاق من أبقيط في المنطقة الشرقية؟","title":"حكم عمل الزوجة والراتب الذي تأخذه نظير ذلك","answer":"الجواب: عليكما أن تصطلحا وأن تتركا النزاع، فإذا اصطلحتما فلا بأس، يقول الله جل وعلا أولاً: وَالصُّلْحُ خَيْرٌ [النساء:128]، ويقول النبي ﷺ: الصلح جائز بين المسلمين إلا صلحاً حرم حلالاً أو أحل حراماً، ولاسيما بين الزوجين فالصلح بينهما مطلوب.\nفينبغي للمؤمن أن يحرص على الصلح مع زوجته وعدم النزاع حتى لا يسبب ذلك الطلاق والفراق، والأصل أن راتبها لها، هذا هو الأصل، المرأة راتبها لها وراتب الرجل له، كل له ما كسب لكن إذا سمحت أن تعطي زوجها نصف الراتب أو ربع الراتب أو ثلث الراتب أو جميع الراتب فلا بأس الحق لها، وعلى الزوج أن يقوم بالبيت ونفقات البيت، وإذا كانت شرطت عليه أنها تقوم بالتعليم أو العمل الآخر الذي تعمله قبل الزوج شرطت عليه أنه يمكنها من ذلك فالمسلمون على شروطهم، أما إن كانت لم تشرط ذلك فله المنع، له أن يمنعها من الذهاب للتدريس وغير التدريس وأن تبقى في بيته، وعليه أن ينفق عليها حاجاتها كما قال النبي ﷺ: ولهن عليكم رزقهن وكسوتهن بالمعروف، لكن الصلح بين الزوج والزوجة في أمور النزاع بينهما يكون أمراً مطلوباً، فالصلح بينكما أيها السائل من أحسن ما يكون حتى تبقى المودة وتبقى المحبة وتبقى العشرة، وينبغي لكل واحد منكما أن يتسامح وأن لا يشدد، فأنت ترضى بما تيسر وهي تسمح بما تيسر حتى لا يكون بينكما الفراق، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/7178/حكم-عمل-الزوجة-والراتب-الذي-تاخذه-نظير-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14713.mp3","categories":["الحقوق الزوجية"]},{"id":9094,"question":"أخت لنا من المنطقة الشرقية بعثت برسالة وكتبتها بأسلوبها وعلى طريقتها، ونقرأ الرسالة كما وردت: بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله وبركاته وبعد: أنا السائلة (ن. د. ق) من الشرقية، أنا تزوجت إنساناً أنانياً بمعنى الكلمة، لم يكن يحسب للعواطف ولا الإنسانية أي حساب -أي: أنه جعل يتصرف دون تفكير- إنه جاد في كل شيء وحين يتخذ قراراً لا يرجع فيه، إنني كنت أحبه ولكن عندما اتضحت لي الحقيقة كرهته ولم أفكر فيه، أروي لكم قصتي: حيث أنني يوماً من الأيام قد نسيت أن صلاة الظهر والعصر لم أصلهما فاستغفرت ربي، وقد تكرر هذا الحدث، وفي كل مرة هو الذي يوجهني وليس لأجل أنه يحبني ويريد الخير لي إنما يريد أن يرصد الأخطاء ويحاسبني فيها في المستقبل، وعندما حاسبني بالصلاة التي قد نسيتها أردته أن يسامحني وتظاهر لي بأنه قد سامحني ولكنه بعد مضي فترة على زواجنا وأنجبنا طفلة طلب مني أن ننفصل لعدم كفاية ديني، وإنني أهمل في بعض المرات، والأهم من ذلك كله منذ تزوجنا أنه لا يريد أن يفهمني ولا يتفاهم معي، وأنه يعاملني بأسلوب يصعب علي إظهار عواطفي وحبي له بأنه يتهرب من الكلام معي وعدم مصارحتي بما يجول داخله، وفي ذات مرة فوجئت بأنه عندما ذهب بي إلى أهلي خطب فتاة ولم يوافقوا أهلها لأنه متزوج ولديه طفلة، وعندما رجعت قال: يجب أن ننفصل؛ لأنني أريد امرأة متدينة، وذكر لي الحديث الذي يقول: اظفر بذات الدين تربت يداك فاعذريني، وأخذ يكلمني بأسلوب عرفت منه أنه ناوي أن يتزوج غيري، ولكني عرضت عليه جميع الحلول غير الطلاق، لكنه صمم وطلقني دون ذنب وأنا وابنتي الآن في حيرة، علماً بأنه لم يتزوج متدينة وكان زواجه بتشريع زوجته أو كذا عبارة لم أفهمها سماحة الشيخ العبارات الأخيرة غير واضحة، فأرجو أن يتفضل سماحة الشيخ بالمعالجة على ضوء ما سمعتم؟","title":"الواجب على المرأة تجاه زوجها والعكس","answer":"الجواب: مادام الطلاق حصل فالعلاج الآن ليس له يعني أثر كبير في حصول المطلوب، لكن إن قدر الله رجوعك إليه فالواجب عليك لا من أجله بل من أجل الله سبحانه وتعالى وعظمته وما أوجب عليك من الحق، الواجب عليك أن تهتمي بأمور الدين، وأن تحرصي على أداء الصلاة في وقتها، فمثلها لا ينسى هي عمود الإسلام، وهي الركن الثاني من أركان الإسلام بعد الشهادتين، فالواجب عليك أن تكوني مثالية في الأخلاق الإسلامية وبأداء ما أوجب الله عليك حتى لا يجد طريقاً إلى ذمك وعيبك وإلى التماس امرأة أدين منك، فهذا هو الذي ينبغي منك أن تكوني حريصة؛ لأن الله أوجب عليك أن تستقيمي على دينه، وأن تحافظي على ما أوجب عليك، وأن تحذري ما حرم الله عليك، فأنت إن شاء الله سواءً عند أهلك أو إن رجعت إليه الواجب عليك أن تهتمي بأمر الدين، وأن تحرصي على أداء ما أوجب الله من الصلاة العظيمة في وقتها بالخشوع والطمأنينة، وهكذا جميع ما أوجب الله عليك من بر الوالدين، من صلة الرحم، من حفظ اللسان عن الغيبة والنميمة، من حفظه عن السب والشتم والكذب إلى غير ذلك، عليك أن تحرصي على كل ما أوجب الله، وهكذا صوم رمضان تحرصين على أدائه كما شرع الله مع التحفظ عن كل ما حرم الله من غيبة أو نميمة أو كذب أو سب أو غير ذلك مما يجرح الصيام، وهكذا في الزكاة إذا كان عندك مال تزكين كما أمر الله، وهكذا في جميع الشئون تحرصين على حفظ دينك وعلى ترك ما حرم الله عليك، وإن يسر الله لك الرجوع فكوني مثالاً طيباً للمرأة الصالحة ذات الخلق الكريم، بشوشة في وجه زوجك، تحبين له الخير وتكرهين له الشر، ولو قدر أنه لم يعمل معك ما ينبغي من البشاشة وحسن الخلق فكوني خيراً منه حتى يرجع إلى أن يتحسن خلقه وأن يعاملك بمثل ما تعاملينه، فعليك بتقوى الله في كل الأحوال، وإن قدر الله إليك الرجوع فاحرصي على الأخلاق الفاضلة واللين في وجهه والبشاشة والكلام الطيب والمبادرة إلى فعل أوامره التي لا حرج فيها وترك ما نهاك عنه من الأمور التي يحب أن تتركيها وهي لا تتعلق بحق الله سبحانه وتعالى.\nالمقصود أن تلتمسي أسباب رضاه وأن تبتعدي عن أسباب سخطه إلا في الأمور التي أوجبها الله عليك فهذه أمور يجب عليك أن تفعليها، وهكذا ما حرم الله عليك يجب أن تتركي ما حرم الله عليك، وليس لك أن تطيعيه ولا غيره في معصية الله سبحانه وتعالى، ومتى اجتهدت في الخير وفي الأخلاق الفاضلة وفي معاملته بما ينبغي من الخلق الكريم والعمل الطيب والمسارعة إلى تحضير أوامره وامتثالها فإنه سوف إن شاء الله يرجع إلى العمل الطيب معك والسيرة الحميدة معك وربما يستغني بك عن الزواج، نسأل الله أن يقدر لك وله كل خير، وأن يجمعكما على خير إنه على كل شيء قدير.\nالمقدم: اللهم آمين جزاكم الله خيراً، سماحة الشيخ: إذا أذنتم لي ألحظ على كتابة أختنا أنها كتبت بصدق وموضوعية فهي تقول: إنني نسيت فريضة كذا وكذا ثم تقول: إنه يوجهني لكن الرجل فيما يبدو جاد أكثر مما يجب، نصحتم المرأة جزاكم الله خيراً وهي نصيحة ثمينة ولاشك، لكن ماذا عن الرجال شيخ عبد العزيز ؟\nالشيخ: هو عليه كذلك، عليه إذا قدر الله له الرجوع إليها أو مع الجديدة عليه أن يتقي الله وأن يحسن المعاشرة، فالله سبحانه يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، ويقول : وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228]، فللزوجات حق عظيم وإن كان حق الزوج أكبر وله درجة فوق حقها لكن يجب ألا يستغل درجته في إيذائها وظلمها وعدم إنصافها، فلها حق كبير وله حق، وحقه أكبر لكن عليه أن يؤدي الحق الذي عليه في حسن المعاشرة والتلطف بالمرأة وطيب الكلام معها وإعطائها حقوقها، هذا واجب عليه، وهي واجب عليها أن تبادله المحبة والفعل الطيب والكلام الطيب وأداء الحقوق، وحسن المعاشرة، وأن تزيد فوق ذلك لأن له عليها درجة، هذا هو واجبهما جميعاً.\nأما إذا أراد الزوج أن تكون هي طيبة وهو ليس بطيب هذا ليس من الإنصاف في شيء، بل يجب أن ينصفها وأن يقوم بحقها وأن يحسن معاشرتها حتى ينشرح صدرها للقيام بحقه وحتى تبادله المحبة والمعاشرة الطيبة، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين. هذه الجدية الزائدة أو هذه الصرامة أو الشخصية القوية التي يسميها بعض الرجال كيف تنصحونهم نحوها لو تكرمتم سماحة الشيخ؟\nالشيخ: الواجب على الرجل أن يحرص على التسامح والعفو عن بعض الهفوات التي لا أهمية لها في حقه، وألا يطلب حقه كاملاً بل يتسامح ويعفو عن الكثير، هكذا ينبغي للرجل وهكذا كان النبي صلى الله عليه وسلم مع زوجاته عليه الصلاة والسلام، يكون ليناً معهن طيب الخلق معهن، يعاشرهن بالمعروف ويتسامح عن كثير مما قد تغلط فيه المرأة أو يزل به لسانها، أو تجهله أو ما أشبه ذلك، فالرجل هكذا ينبغي له أن يكون سمح الأخلاق طيب السيرة، كثير العفو والصفح عما يتعلق بحقه، لا يطلب حقه كاملاً بل يتسامح عن بعض الشيء، ثم إذا عاتب يعاتب بلطف وكلام طيب وعبارات حسنة وتوجيه واضح ليس فيه غلظة ولا شدة ولا عنف، اللهم إلا إذا كابرت وعاندت هذا هو محل الشدة عليها بسبب عنادها وتكبرها وعنفها، أما مادامت تلتمس منه التوجيه وكلامها طيب فينبغي له أن يكون أطيب. نعم.\nالمقدم: بارك الله فيك.","link":"https://binbaz.org.sa/fatwas/7254/الواجب-على-المراة-تجاه-زوجها-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_150/15005.mp3","categories":["الحقوق الزوجية"]},{"id":9247,"question":"وهذه رسالة وردت من السائلة (ن. ع. م) من مكة المكرمة تقول في رسالتها: أنا امرأة متزوجة منذ عشر سنوات، تزوجت رجلاً وعشت معه أربع سنوات كلها سعادة، وفي السنوات الأخيرة راح زوجي يختلط بالناس الذين يمشون في طريق سيئ، فراح يشرب المسكر أبعدنا الله وإياكم عن ذلك، ويحضر إلى البيت وهو في حالة غير طبيعية فيضربني ضرباً قوياً بدون أي سبب، وأنا امرأة مسلمة لا أستطيع أن أعيش مع إنسان يفعل شيئاً يخالف الإسلام، لكن المشكلة أن لدي منه أربعة أطفال، وأكبرهم يبلغ من العمر خمس سنين فلا أدري ماذا أفعل أفيدوني أفادكم الله؟","title":"بقاء الزوجة مع زوجها السكران وطلب الطلاق منه","answer":"الجواب: عليك أن تنصحيه وقت صحوه، وتطلبي من أبيه إن كان موجوداً أو جده أو إخوته الكبار أو أمه أو من يعز عليه من أخوال وأعمام، حتى ينصحوه وحتى يوجهوه إلى الخير، لعله يهتدي بأسبابك، فإن هداه الله وتاب فالحمد لله، وإن أصر على حاله السيئة فلك أن تطلبي الطلاق، تتصلي بالمحكمة حتى يحصل الطلاق؛ لأن بقاءه معك وهو بهذه الحالة يضرك، ويضر أولادك، وأنت أحق بأولادك ما دام بهذه الحالة، فعليك أن تفعلي المستطاع من أسباب هدايته مع والده ووالدته، وأقاربه الكبار الذين يحترمهم، ويستفيد من كلامهم ويقدر كلامهم لعل الله يهديه بأسبابهم، وأنت مع هذا تدعين له في ظهر الغيب، في صلاتك وفي الليل وفي آخر الليل، تدعين له أن الله يهديه، وأن الله يرده للتوبة وأن يعيذه من هذا العمل السيئ ومن أصحاب الشر وصحبتهم، لعل الله يستجيب لك، ويرده إلى الخير، لعل الله يستجيب سبحانه وتعالى دعاءك ويرد هذا الرجل إلى الخير والاستقامة، فإن أصر على حالته السيئة، على تعاطيه المسكر فلا مانع من طلب الطلاق؛ لأن بقاءه معك وهو على هذه الحال لاشك أن فيه مضرة عليك وعلى أولادك، نسأل الله لنا وله الهداية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7409/بقاء-الزوجة-مع-زوجها-السكران-وطلب-الطلاق-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23508.mp3","categories":["الطلاق","الحقوق الزوجية"]},{"id":9250,"question":"وهذه رسالة وردتنا من السائل عبد الله العوكي سوداني مقيم في جدة، يقول في رسالته: تزوجت امرأة وأنجبت منها طفلة، ورأيتها مشت إلى الفاحشة يقصد الطفلة، وعندما ضربتها قالت لي: أجبرتني والدتي على هذا الفعل، وطلقتها ماذا أعمل؟ هل يجوز لي ردها أم آخذ طفلتي منها وأتركها أفيدوني أفادكم الله؟","title":"حكم معاشرة الزوجة التي تدعو ابنتها للفاحشة","answer":"الجواب: هذا يحتاج إلى عناية، إذا كانت الأم قد تابت إلى الله عز وجل وظهر منها الخير بشهادة أقاربها وجيرانها، أو ثبت عندك أن البنت كذبت عليها، وأنها ما فعلت شيئاً من الشر، وأن الفساد من البنت لا منها، فراجعها، أما إن كان الظاهر صدق البنت وأن المرأة تدعو إلى الفاحشة وأنها فاسدة العرض فلا تؤمن عليك وعلى أولادك، فينبغي أن لا تراجعها، وليس لك أن تراجعها ما دامت بهذه الحالة السيئة؛ لأن هذا فيه خطر، فيه خطر عليك وعلى أولادك، لكن لا تعجل في الأمور، تثبت في الأمور وانظر واسأل العارفين بها من الجيران والأقارب، فإن ثبت أنها طيبة، وأنها لم تفعل هذا الأمر أو أنها تابت توبة صادقة، فلا مانع من مراجعتها ما دامت في العدة، أو العود إليها بنكاح جديد، أما إن ظهر لك أنها على حالها السيئة، وأنها غير شريفة العرض، فينبغي لك أن لا تعود إليها؛ لئلا تعلق عليك أولاداً من غيرك، نسأل الله السلامة والعافية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7410/حكم-معاشرة-الزوجة-التي-تدعو-ابنتها-للفاحشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23509.mp3","categories":["الحقوق الزوجية"]},{"id":9274,"question":"الرسالة التالية من مكة المكرمة وبعثت بها إحدى الأخوات المستمعات تقول ( س . س . ع ) أختنا تقول في سؤال لها: إذا المرأة طلبت من زوجها نقودًا لكي تذهب مثلًا للدكتور أو تشتري شيئًا معينًا وأعطاها برغبته ولم تذهب مثلًا للدكتور أولم تشتر هذا الشيء الذي طلبت النقود من أجله واشترت شيئًا آخر لأولادها وأولاده أيضًا أو ادخرت تلكم الفلوس ليوم ما، فهل تعتبر في هذا عاصية ومخالفة وترجو التوجيه، وأيضًا سمعت أن خروج المرأة بدون إذن من زوجها حرام، ولكني أنا -تتحدث عن نفسها- ولكني أنا أخذت منه الإذن وقلت له: إذا لم تكن موجودًا فسوف أخرج إذا أردت الخروج؟ فقال: أنت مسامحة على ذلك، وترجو التوجيه حيال هذه الأمور، جزاكم الله خيرًا؟","title":"حكم أخذ المرأة شيئًا من مال زوجها تدخره للزمن","answer":"الجواب: إذا أخذت المرأة من زوجها النقود لبعض الحاجات أو للطبيب ثم بدا لها أن لا تذهب وأن لا تشتري هذه الحاجة وأن تحفظ الفلوس لحاجة أخرى أهم أو لحاجات الأولاد أو لحاجات البيت، أو تحفظها ليوم ما فلا بأس عليها في هذا، وهي محسنة وعليها أن تنظر في الأصلح ولا يضرها هذا، بل هذا يدل على كمال العقل وقوة الدين، وقوة البصيرة فلا حرج في هذا.\nإنما الواجب أن تكون هذه الفلوس مصروفة في شيء ينفع لا في إسراف ولا في تبذير ولا في شيء محرم، تحفظها لحاجتها وتصرفها في المصلحة، ولو كانت غير ما أذن فيها الزوج كأن تأخذها للطبيب ثم تقول: أنا طيبة ولا حاجة إلى الطبيب أو تأخذها لشراء حاجة ثم ترى أن غيرها أولى منها، أو ترى أن حفظها لحاجة الأولاد أو لحاجة البيت التي هي أهم، كل هذا لا بأس به والحمد لله.\nأما الخروج فليس لها الخروج إلا بإذنه، فإذا أذن إذنًا عامًا فلا بأس، ومع الإذن العام تتحرى لا تخرج لكل شيء، تخرج للأمور المهمة، ولا تخرج إلى جهات فيها خطر أو فيها تهمة تخرج إلى محلات لا تهمة فيها، ولا خطر فيها، وإذا تيسر أن يكون معها صاحبة فهذا يكون أكمل وأحسن في هذا العصر؛ لأنه أبعد عن الشر والخطر، ولا تخرج إلا عند الحاجات المهمة جدًا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7436/حكم-اخذ-المراة-شيىا-من-مال-زوجها-تدخره-للزمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_183/18304.mp3","categories":["الحقوق الزوجية","النفقات"]},{"id":9304,"question":"هذه رسالة وردت إلى البرنامج من العراق من محافظة كركوك من المستمعة زهراء ، تقول في رسالتها: تقدم لي شاب وطلبني من أهلي، وتم عقد قراني عليه، واشترى لي الحلي الذهبية وأثث لي بيتاً كاملاً، وفي ليلة الزفاف رفضته لا أعلم لماذا فطلقني، ثم تقدم لي شاب آخر وعقدنا القران وفي ليلة الزفاف رفضته أيضا، وأردت الطلاق منه فطلقني وأنا الآن حائرة لا أعرف ماذا أفعل، ولا أعرف لماذا أخاف من الزواج، وأنا أكره الرجال جميعاً، وقد يكون كرهي لهم هو أنني أثناء خروجي من بيتنا لقضاء بعض الحاجات أتعرض للسب والشتم من الرجال، فأصبحوا الرجال جميعاً في نظري لا شيء، بل هم صنف واحد مع احترامي لأهل الخير منهم، فماذا عساي أن أفعل، وهل علي إثم في رفض الرجلين السابقين اللذين عقد نكاحي عليهما أم لا، وما هي الأدعية التي يمكن أن تقال في ليلة الزفاف، أفيدوني أفادكم الله؟","title":"حكم رفض المرأة زوجها بعد العقد","answer":"الجواب: إذا كان الرفض لهما بسبب بغضاء حدثت في القلب وكره وقع في القلب لم تستطيعي دفعه فلا شيء عليك، الله الذي يجمع القلوب ، أما إذا كان مجرد تساهل وهوى فعليك التوبة إلى الله من ذلك؛ لأن طلب الطلاق من دون عذر أمر لا يجوز، فالواجب على المرأة أن لا تطلب الطلاق إذا كان ما هناك موجباً لطلب الطلاق، فإن كان نزل بك كره لهما وبغضاء لهما لم تستطيعي أن تجيبي إلى الدخول على الأول والثاني لما وقع في قلبك من الكراهة الشديدة حتى لم تستطيعي فهذا شيء غلبك والأمر إلى الله وليس عليك فيه شيء، أما إذا كان مجرد تساهل، ومجرد طاعة للشيطان هذا لا يجوز، بل الواجب على المرأة إذا تم عقد القران أن تجيب إلى الدخول وأن تمكن الزوج منها كما شرع الله .\nوالآن عليك أن تسألي الله جل وعلا أن يزيل ما في قلبك من كراهة الرجال الطيبين، وأن يشرح صدرك للزواج الشرعي، وتلحي على الله، والله يحب الإلحاح بالدعاء ، يقول: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]، فعليك أن تلحي في الدعاء، وتكرري الدعاء في مثل السجود... في آخر التحيات.. في آخر الليل، في كل وقت، عليك أن تسألي الله  أن يشرح صدرك للزواج، وأن يزيل ما في قلبك من كراهة الرجال الطيبين، وأن يسهل لك الزوج الصالح، وإذا حصل ذلك فعليك أن تجيبي إلى الدخول، ولا تطاوعي الشيطان في طلب الطلاق، نسأل الله لنا ولك الهداية والتوفيق.","link":"https://binbaz.org.sa/fatwas/7472/حكم-رفض-المراة-زوجها-بعد-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23613.mp3","categories":["الحقوق الزوجية","الطلاق"]},{"id":9341,"question":"لها سؤال ثانٍ في هذه الرسالة وهو سؤال طويل في الحقيقة يتعلق بخلاف بينها وبين زوجها لكن خلاصة ما في هذا السؤال تقول: أنا حرمت زوجي بأن لا أنجب منه أطفال بسبب كلام حصل بيني وبين أهلي، فهو مهمل بالنسبة لي وقد أنجبت منه أربع بنات لم أنجب عنده سوى واحدة أما الباقي فقد أنجبتهن عند أهلي، وهو مع ذلك لا يقدر ظروفي وأنا الآن عند أهلي منذ ثمان سنوات، وأنا الآن راضية عنه لكنه يضايقني بكلام ليس له دليل، وأنا الآن لا أريد منه إلا السلامة وأريد أن أجلس على بناتي وأنا خائفة فهو يقول: أريدك أن تذهبي معي، لكن أنا لا أطمئن إليه، أخشى أن يسبب لي بعض المشاكل وأنا مصرة على الجلوس عند أهلي، فهل علي إثم مع أنني مريضة، هكذا تقول؟","title":"تريد العيش عند أهلها لخصومة مع زوجها","answer":"الجواب: هذه المسألة نزاع خصومة مرجعها المحكمة، إن سمح عنك فلا بأس، وإن لم يسمح عنك فالمحكمة تنظر في الأمر، وإن توسط بينكما من يصلح بينكما ويزيل ما بينكما من الإشكال فالصلح خير، أما إن لم يتيسر الصلح ولم يسمح فالمرجع المحكمة.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7503/تريد-العيش-عند-اهلها-لخصومة-مع-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23802.mp3","categories":["الحقوق الزوجية"]},{"id":9344,"question":"تسأل أيضاً وتقول: أنا أخشى من الله عز وجل ولا أريد أن يلحقني شيء وهو يمنعني أن لا أخرج من البيت، وأنا لا أخرج سوى لعماتي وإذا خرجت أكون مستترة جداً حتى الذهاب إلى السوق لا أذهب إليه، بل أوصي والدتي بما أحتاج إليه، فما الحكم في ذلك؟","title":"حكم طاعة الزوج في عدم الذهاب إلى أحد الأقارب","answer":"الجواب: إذا منع الزوج زوجته من الخروج لعماتها أو خالاتها أو للسوق أو نحو ذلك فعليها أن تمتثل وعليها السمع والطاعة في ذلك، إلا إذا قصر بأن لم يشتر لها حاجتها اللازمة في البيت، أو لم ينفق عليها فلها الخروج لأنه قصر في حقها، أما ما دام أنه يقضي حاجتها ويعطيها مطالب البيت فليس لها الخروج إلا بإذنه، وإذا منعها من الخروج لعمة أو خالة أو لجيران أو غير ذلك فعليها أن تمتنع وعليها أن تحل المشكل بالكلام الطيب معه، والمذاكرة معه فيما يضرها في هذا الشيء، والأسلوب الحسن الذي يلين قلبه حتى يأذن لها، أما المكابرة والعصيان فلا تجوز، الواجب عليك أيها السائلة! أن تسمعي وتطيعي وأن تخاطبيه بالتي هي أحسن، حتى يرضى ويأذن. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7505/حكم-طاعة-الزوج-في-عدم-الذهاب-الى-احد-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23803.mp3","categories":["الحقوق الزوجية","قضايا المرأة"]},{"id":9353,"question":"هل من واجب الزوجة أن تقبل يد ورأس زوجها في صباح ومساء كل يوم؟","title":"حكم القول بوجوب تقبيل المرأة يد زوجها ورأسه","answer":"الجواب: لا نعلم لهذا أصلاً ولو فعلت فلا حرج، لكن لا نعلم......، ليس بواجب ولا مشروع، وإنما تسلم عليه السلام المعتاد سلام الرجل على أهله والمرأة على زوجها وهذا شيء معروف بين الزوجين، تفعل مع زوجها ما يفعله الناس من تقبيل ومن مؤانسة ومن مداعبة، أما يجب عليها أن تقبل يده أو رأسه أو رجله فهذا لا أصل له، وإنما تفعل معه ما جرت به العادة وما يحبه منها مما ليس فيه محذور شرعاً، وإذا رأى أنها تقبل يده أو تقبل ركبته أو تقبل رأسه وفعلت ذلك فلا بأس. نعم.\nالمقدم: إذا قدم من سفر أو كان ذلك في الأعياد؟\nالشيخ: كل هذا لا بأس به لكن لا يجب إنما تستعمل ما ترى فيه شيئاً يعني: يحبه منها، أو يطيب نفسه، أو يسبب تمام الألفة بينهما والعشرة بينهما لا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/7516/حكم-القول-بوجوب-تقبيل-المراة-يد-زوجها-وراسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_156/15603.mp3","categories":["الحقوق الزوجية"]},{"id":9463,"question":"هذه رسالة وردت من السائلة: (م. ن. ر) من الخبر في المملكة، تقول هذه السائلة في رسالتها: أنا امرأة متزوجة ولي أولاد حصل بيني وبين زوجي مشاكل، فهو متزوج من امرأة أخرى، ويؤدي إليها كل الحقوق وأنا لا يعرف من حقوقي شيئاً، ولا يريد أن أذهب إلى أهله منذ سنتين، فهل يجوز لي أن أقاطع أهله بسبب ابنهم، أفيدوني أفادكم الله؟","title":"ما يعدل مع زوجته ومنعها من زيارة أهله","answer":"الجواب: هذا شيء بينك وبينه إن صلحت أنت وإياه فالحمد لله، وإلا فالمحكمة تنظر بينكما، ....... خصومة، هذه مسألة خصومة، فإذا سمحت وصلحت وصبرت على ما قال لك فلا بأس وهذا إليك، فإن لم تصبري فالأمر يرجع فيه إلى المحكمة، والمحكمة تنظر في الأمر بينك وبين زوجك، أصلح الله حال الجميع.\nالمقدم: هذا بالنسبة لما لها من حقوق؟\nالشيخ: نعم.\nالمقدم: لكن هل يجوز له أن يمنعها من زيارة أهله؟\nالشيخ: عليها السمع والطاعة، عليها السمع والطاعة لزوجها فيما أمرها به بالمعروف، وقد يكون زيارتها لأهله تضره، وقد يكون منعها؛ لأنها إذا زارت أهله قالت: فيه كذا، وقالت: فيه كذا، وقالت: فيه كذا. المقصود إذا منعها من أهله تمتنع.\nالمقدم: ولا إثم عليها؟\nالشيخ: ما عليها إثم، ما هو بضروري تزور أهله، المقصود إذا منعها من أهله أو من جيرانه أو من فلان أو فلان لا تزوره تمتنع تصبر، وأما حقوقها فهذا بينها وبينه عند القاضي إلا أن تسمح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7620/ما-يعدل-مع-زوجته-ومنعها-من-زيارة-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25509.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":9464,"question":"لها سؤال آخر تقول: إن زوجي قال لي: عليك الحرج إذا اشتريت لأولادي شيئاً من مالك أو مال أهلك، وهو لا يحافظ على الصلاة جيداً، ويأكل المحرمات التي حرم الله كالحبوب والخمر إلى آخرها، فهل هذا الحرج يلزمني، يعني: هل تحريجه هذا يلزمني أفيدوني أفادكم الله؟","title":"حكم منع الزوجة من الإنفاق على أبنائه من مالها","answer":"الجواب: إذا كان يقوم بحقهم ويعطيك حاجتهم فلا تأخذي لهم من أحد شيئًا، أما إذا كان قصر أو تركهم بدون كسوة، ومن دون حاجاتهم فلا بأس، ولكن ما دام يقوم بحاجاتهم فامتثلي أمره، وإن كان في نفسه عنده معاصي، لكن إذا كان لا يصلي لا تبقين معه؛ لأن من لا يصلي كافر، إذا كان لا يصلي فالذي لا يصلي كافر نسأل الله العافية، أما إذا كان يصلي ولكن قد يفعل بعض المحرمات فهذا عاصي وأنت بالخيار، إن صبرت عليه فلا بأس، وإن طلبت الفراق فهذا إلى المحكمة تتصلين بالمحكمة أنت وإياه والمحكمة تنظر في أمركما. نسأل الله للجميع الهداية.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7621/حكم-منع-الزوجة-من-الانفاق-على-ابناىه-من-مالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25510.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":9595,"question":"هذه رسالة وردتنا من سائلةٍ رمزت لنفسها بالحائرة (س. ش) من الرياض، هذه السائلة في الحقيقة تعرض مشكلةً طويلة تتلخص في أنها تزوجت من مدة لا تتجاوز سبعة أشهر من إنسانٍ لم تكن مقتنعة به في الأول، ولكن بعد الزواج أحبته وحملت منه، لكنها أجهضت بسبب سوء حالتها الصحية والنفسية، وتقول: إن سبب سوء الحالة: هو أنها سكنت مع عائلته الكبيرة وهي موظفة، وتخرج من عملها متعبة فتجد المشاكل في المنزل من أهل زوجها، وتقول: إنهم يجبرونها على أشياء لا ترغب فيها وهي محرمة؛ كالخروج أمام إخوة زوجها الكبار، والجلوس معهم والأكل معهم، مع أنه لا يجوز شرعاً، والرسول ﷺ قال: الحمو الموت تقول: قد لاقيت أنواعاً من العذاب عند هؤلاء، وصبرت واستسلمت، ولكن زادت الأمور عن حدها المعقول، ووصل الأمر بهم أن اتهموني في عرضي وشرفي، وقلت لزوجي: ما الحل؟ قال: تحملي واصبري، ولكن عجزت وكان سلبياً زوجي معي، فهو يخرج من البيت ويتركني، ولا يعود إلا بعد منتصف الليل، فقررت أن أخرج أنا وهو في بيت مستقل فاعترض والده ووالدته، وهدداه بأن يحرماه من الميراث إن خرج في بيت مستقل، فطلب منه أبوه أن يعيدني إلى أهلي، وأنا الآن عند أهلي منذ ثلاثة أشهر، وقد تدهورت حالتي الصحية وحالة زوجي أيضاً، ولم يقم بإرجاعي ولم يسأل عني بالرغم أن كلاً منا يحب الآخر، بسبب خوفه من والديه ومن أخيه الأكبر، فتسأل، تقول: ما الحل في هذا؟ هل أطلب الطلاق منه، رغم أنني أريده وهو يريدني، أم ماذا أفعل؟ ولكن لا تقولوا جزاكم الله خيراً: عودي وعيشي مع أهله، فليس من المعقول أن أعيش معهم بعد أن اتهموني في عرضي، وأنا لا أوافق على الخروج أمام إخوته الرجال أبداً مهما كانت الظروف، أفيدوني أفادكم الله؟","title":"أساء أهله معاملتها ويرفضون انتقالها مع زوجها في بيت مستقل","answer":"الجواب: إذا كان الواقع هو ما ذكرته السائلة، فلا مانع من خروجه في بيت مستقل، ولا يلزمه طاعة والديه في هذا، لأن والديه لم ينظرا إلى حاله، ولم يرحما حاله، ولم يقدرا ظروفه التي أشارت إليها السائلة، فلا حرج عليه أن يخرج في بيتٍ مستقل، ويستسمح والديه، وإن أبيا أن يسمحا فلا حرج عليه، ولكن يجاهد في استرضائهما، والحرص على مخاطبتهما بالتي هي أحسن، وأما الميراث فالله أعلم من يموت الأول، وليس لهما أن يحرمانه، ليس لهما أن يحرماه الميراث، حتى لو أوصيا بحرمانه، لا حق لهما في ذلك، والوصية بحرمانه باطلة، ليس الأمر إليهما، متى ماتا قبله ورثهما وإن أبيا، فلا ينبغي أن يخاف من هذا، ولكن المهم عدم العقوق، وإذا كانا لم يقدرا حاله فخروجه حينئذٍ ليس بعقوق، لأن الرسول ﷺ يقول: إنما الطاعة في المعروف فعليه أن يخرج إن شاء، ويكون في بيتٍ مستقل، ويعيدك إلى المسكن المناسب، ويسترضي والديه حسب الطاقة والإمكان في المستقبل، وعلى والديه أن يرضيا، وأن يساعداه على ما يجمع شمله بأهله وألا يشددا عليه في هذا.\nوأما خروجك بين إخوته، وبين غير محارمك كاشفةً، وإلزامهم لك بذلك، فهذا منكر لا يجوز، وهذا يدل على ضعف إيمانهما، إن كنت صادقة فيما قلت، نسأل الله للجميع الهداية والتوفيق.\nالمقدم: بارك الله فيكم، ولكن على فرض أنه لم يستجب ولم يخرج، وهي باقية عند أهلها، يجوز لها طلب الطلاق؟\nالشيخ: إذا كان الحال كما ذكرت لها طلب الطلاق. نعم، لأنها معذورة.\nالمقدم: ولا تدخل في الوعيد؟\nالشيخ: لا ما تدخل.. لها طلب الطلاق؛ لأنها معذورة، بسبب ما ذكرت. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7761/اساء-اهله-معاملتها-ويرفضون-انتقالها-مع-زوجها-في-بيت-مستقل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_271/27102.mp3","categories":["الطلاق","الحقوق الزوجية"]},{"id":9650,"question":"تسأل الأخت من مكة أيضاً وتقول: أنا متزوجة من مدة عشر سنوات، وقد حصل بيني في يوم من الأيام وبين زوجي خصام، حيث قال لي: أحضري طعام العشاء فرفضت طاعته، وقلت له: لن أحضر لك الطعام حتى توصلني إلى أهلي، فوقف معي ساعتين ثم اتجه إلى منطقة أخرى ولم يقل لي أي شيء، فهل هو آثم وأنا آثمة في عدم طاعته، أم لا، أفيدوني وماذا أفعل حتى أرضي زوجي وفقكم الله؟","title":"رفضت طاعة زوجها وتخاف من الإثم","answer":"الجواب: الواجب على المرأة السمع والطاعة لزوجها في المعروف، وإحسان الخلق، وطيب الكلام، وتنفيذ الأوامر من إحضار الطعام أو غيره من الشاي أو القهوة أو حاجات أخرى مما أباح الله، هذا هو الواجب على الزوجة، والواجب على الزوج كذلك أن يعاشرها بالمعروف بالكلام الطيب، بالسيرة الحميدة، كما قال الله سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وقال الله : وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] فحق الزوج أكبر وهي لها حق عليه أن يعاشرها بالمعروف بالكلام الطيب، بالسيرة الحميدة، بالإنفاق عليها نفقة أمثالها، كسوتها كسوة أمثالها، يخاطبها بالكلام الطيب لا بالسب واللعن، بل بالكلام الطيب والأسلوب الحسن، وهي كذلك تخاطبه بالكلام الطيب والأسلوب الحسن، وتسمع وتطيع في أوامره، لا تعصيه في الأوامر التي ليس فيها حرج شرعاً، ليس فيها منكر، كإحضار الطعام، إحضار الشاي، عمل شيء آخر مما أباح الله مما جرت به العادة، أن تفعله الزوجة مع زوجها، هذا هو الواجب على المرأة حتى تستقيم الأحوال، وحتى تستمر العشرة الطيبة.\nأما إذا أمرها بما لا يجوز كأن يقول لها: تحضر له الخمر أو الدخان أو ما أشبهه مما حرم الله، أو تسمع معه الأغاني والملاهي لا يلزمها ذلك؛ لأن الله يقول جل وعلا: وَلا يَعْصِينَكَ فِي مَعْرُوفٍ [الممتحنة:12] ويقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فإذا أمرها بالمعصية ليس لها أن تطيعه، ولكن ترد عليه بالرد الطيب: يا فلان! هذا لا يجوز، هداك الله، أعاذك الله من الشيطان، هذا أمر لا يجوز لي ولا لك، وليس لي أن أعينك على ما حرم الله، يكون عندها أسلوب حسن تعضه وتذكره بالله عز وجل، ولكن لا تطيعه في المعاصي، وعليها أن تخدمه الخدمة المعروفة المعتادة بين أمثالهم؛ لأن الأسر تختلف فإذا كان مثلها يخدم مثله والعادة أنها تخدمه في الأسر المماثلة لهم في بلادهم فإنها تخدمه.\nأما إذا كانت من أسرة تخدم فإن عليه أن يخدمها إذا استطاع ذلك عليه أن يخدمها عملاً بالعادة المعروفة؛ لأن الشرط العرفي كالنطقي ولكن إذا تسامحت وخدمت كما خدمت فاطمة رضي الله عنها بنت النبي ﷺ زوجها علي ، كانت تطحن وتخدم وتصلح الطعام رضي الله عنها وأرضاها، فهكذا ينبغي للزوجة أن تتسامح وأن تخدم حتى ولو كان مثلها يخدم إذا تنازلت وتسامحت كان هذا من طيب الأخلاق ومن حسن السيرة، ومن أسباب استمرار العشرة، لكن إذا كان مثلها يخدم وأسرة تخدم وتيسر للزوج أن يخدمها فذلك حق. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7821/رفضت-طاعة-زوجها-وتخاف-من-الاثم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25106.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":9744,"question":"هذه رسالة من الأخ رمز لاسمه بـ (ك. ح. ص. خ) مصري يعمل بالمملكة العربية السعودية وفي رسالته ستة أسئلة سوف نعرض بإذن الله سؤالين منها ونؤجل الباقي لحلقات أخرى حتى نتيح المجال لأكثر من رسالة، سؤاله الأول يقول: زوجتي تصر على العمل موظفة بأحد المصالح مع العلم بأن مكان العمل ذاته ليس فيه اختلاط ولكن الطريق إليه لا يخلو من الاختلاط، فما الحكم إذا منعتها أو وما حكم عملها إذا كانت لا تحتاج لعملها هذا أبدًا، وهي ليست في حاجة مادية إليه وتتكلف في الذهاب والعودة مع العلم أنها محتشمة، وماذا علي من الناحية الشرعية إذا أذنت لها وهل يحق لي منعها؟","title":"موقف الرجل إذا أصرت الزوجة على العمل","answer":"الجواب: إذا كان محلها ليس فيه اختلاط وإنما هو محل نساء وليس فيه خطر عليها من جهة عرضها فلا بأس أن تعمل، وعليك أن توصلها إلى المحل بالطريقة السليمة إذا كان الطريق فيه خطر عليك أن توصلها إليه بالطريقة السليمة، ولك أن تمنعها من ذلك إذا كنت ترى أن في ذلك مشقة عليك أو عليها أو خطرًا عليك أو عليها، لك أن تمنعها إلا أن تكون شرطت هذا عليك في النكاح وأنها تبقى في عملها شرطًا بينك وبينها فإذا كان هناك شرط في النكاح أنك تبقيها في العمل المذكور فالمسلمون على شروطهم، يقول النبي ﷺ: إن أحق الشروط أن يوفى بها ما استحللتم به الفروج، لكن عليك أن تلاحظ في الذهاب بها أو يذهب بها بعض أولادها الكبار أو إخوتها حتى تصل إلى المحل بأمان وبطريقة سليمة ما دام المحل ليس فيه خلطة وليس فيه خطر فلا حرج في ذلك إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/7909/موقف-الرجل-اذا-اصرت-الزوجة-على-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19604.mp3","categories":["الحقوق الزوجية"]},{"id":9809,"question":"وأولى رسائل هذه الحلقة وردتنا من المستمع (ن . م) من العراق محافظة نينوى مدينة الموصل، يقول المستمع (ن. م) في رسالته: هل إراقة المني خارج فرج المرأة بالنسبة للرجل المتزوج حرام، وخاصة في حالة الحيض أو الولادة، أفيدونا أفادكم الله؟","title":"هل الإنزال خارج فرج الزوجة حرام؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، وخيرته من خلقه، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فإراقة المني خارج الفرج إذا كان لمصلحة فلا بأس بذلك، وهذا يسمى العزل، وقد ثبت عن الصحابة رضي الله عنهم وأرضاهم أنهم كانوا يعزلون، وقد أقرهم النبي عليه الصلاة والسلام، فإذا دعت الحاجة إلى العزل بأن يريق منيه خارج الفرج، إما لكونه لا يرغب في الحمل ذلك الوقت، أو لما ذكره السائل من كونه محرم عليه الجماع، فيضع ذكره حول فرجها ويريق المني خارج ولا يجامع، فلا بأس بذلك؛ لأن المحرم هو الجماع، قال النبي ﷺ في حق الحائض: اصنعوا كل شيء إلا النكاح يعني: إلا الجماع، فله أن يباشرها بالتقبيل والضم إلى نفسه والاستمتاع بفرجها وبطنها وغير ذلك، لكن الأفضل أن يكون عليها إزار أو سراويل إبعادًا عن الخطر، فإنه متى باشر حول الفرج فقد ينزغ الشيطان ويدعوه إلى الجماع المحرم، فالأفضل هو أنه يباشرها من وراء الإزار أو السراويل أو القميص، قالت عائشة رضي الله عنها: كان النبي ﷺ يأمر إحدانا إذا رغب أن يباشرها وهي حائض يأمرها أن تتزر، فيباشرها وهي حائض هكذا قالت عائشة رضي الله عنها.\nفالمقصود أن السنة في حق الزوج إذا كانت المرأة حائض أو نفساء أن يباشرها من وراء الإزار أو من وراء السراويل ونحو ذلك، لكن لو باشرها من داخل الإزار ومن داخل السراويل فلا حرج في هذا، فقد جاء في السنة ما يدل على ذلك، لقوله ﷺ: اصنعوا كل شيء إلا النكاح لما قيل له: إن اليهود إذا حاضت المرأة فيهم لم يؤاكلوها ولم يشاربوها ولم يساكنوها في البيت، قال عليه الصلاة والسلام: اصنعوا كل شيء إلا النكاح يعني: خالفوا اليهود، معنى (إلا النكاح) يعني: إلا الجماع، فإذا وضع فرجه على فخذها وأمنى خارج الفرج فلا حرج، لكن ليس له أن يجامع بل يحرم عليه الجماع، سواء أنزل أم لم ينزل يجب أن يبتعد عن الجماع، أما كونه يضع ذكره على فخذها أو قرب فرجها ولكن لا يولجه حتى ينزل فلا حرج في ذلك، ولكن الأفضل له والأولى والأحوط أن يبتعد عن هذا؛ لئلا يدفعه الشيطان إلى الجماع المحرم، ولهذا أمر النبي ﷺ النساء أن يأتزرن عند إرادته المباشرة عليه الصلاة والسلام، هذا هو الأفضل وهذا هو الأحوط. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7976/هل-الانزال-خارج-فرج-الزوجة-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_197/19708.mp3","categories":["الحقوق الزوجية"]},{"id":9847,"question":"هذه رسالة وردت إلينا من (م. م. ح) مقيم بنجران وهو مصري الجنسية، الأخ السائل في رسالته يقول: أنا متزوج من بنت عمي شقيق أبي، وعلى إثر خلاف كبير بيني وبين عمي وزوجته، أدى إلى تحطيم مستقبلي ومستقبل أولادي فمنعت زوجتي من الذهاب إلى أبيها وأمها، ومنعت أيضاً والد زوجتي ووالدتها من الحضور إلى بيتي و لم يزل الخلاف قائماً، وقبل حضوري إلى المملكة طلبت مني زوجتي أن ترى والدها ووالدتها وإخوتها، فأثار ذلك جنوني وغضبي الشديد ورفضت هذا المطلب وضربتها، وحلفت عليها يميناً هذا نصه: علي الطلاق بالثلاث لو ذهبت إلى بيت أبيك في غيابي لن أخليك في البيت عند عودتي، وكررت ذلك مرة ثانية، في أقل من ربع ساعة، فهل إذا ذهبت إلى بيت أبيها في غيابي تكون طالقاً مرتين، أم يعتبر يميناً معلقاً له كفارة، وإذا كان كذلك فما كفارته أفيدوني بارك الله فيكم؟","title":"حكم منع الزوجة من زيارة والديها والحلف على ذلك بالطلاق","answer":"الجواب: هذا فيه تفصيل على حسب نيتك: إن كنت نويت منعها من هذا الذهاب وتخويفها وتحريجها وليس القصد من ذلك أنها طالق، وإنما أردت تخويفها وتحذيرها ومنعها فهذا فيه كفارة اليمين يمين واحدة، أما إذا كنت أردت بذلك إيقاع الطلاق، وأنها متى خرجت متى راحت إلى أهلها وقع الطلاق، فإنه يقع عليها طلقة واحدة، وإذا كنت أردت بالتكرار طلقة ثانية، فإنه يقع طلقة ثانية، أما إذا أردت بالتكرار تأكيد الكلام وتأكيد المقام لا طلاقاً آخر، فإنه لا يقع إلا طلقة واحدة، ولك العود إليها بنكاح جديد، بشروطه المعتبرة شرعاً، هذا هو التفصيل في هذا الأمر، أما كونها تذهب إلى والديها، فهذا فيه تفصيل:\nإن كان ذهابها إليهم يضرك ويضرها لسوء أخلاقهم وسوء أعمالهم، ويفسدونها عليك فلا حرج في منعها، أما إذا كان ذهابها إليهم لا يضرك ولا يضرها، فينبغي أن تسمح بذلك، وعلى كل حال ينبغي علاج هذا الأمر بالطرق الطيبة بينك وبين والدي زوجتك؛ لأن هذا يشق عليها كثيراً إذا طال، فينبغي أن تعالج هذا الأمر بواسطة أهل الخير والإصلاح بينكم حتى يتيسر ذهابها إليهم عن رضا منك، نسأل الله للجميع الهداية.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8024/حكم-منع-الزوجة-من-زيارة-والديها-والحلف-على-ذلك-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26212.mp3","categories":["الطلاق","الأيمان والنذور","الحقوق الزوجية"]},{"id":9886,"question":"يسأل أيضاً ويقول: هل على الزوجة خدمة أم زوجها أم لا؟ وما الحكم في ذلك؛ لأن هذا سبب مشكلة عندنا في البيت، ويجعلني أحياناً ألجأ إلى التفكير في الطلاق، وقد سألت في بلدتي مصر أحد المشايخ فقال: حاول أن توفق بين أمك وزوجتك، علماً بأن الزوجة يتيمة وليس لها أحد سواي، ولي منها أبناء ووالدتي ليست كبيرة السن ولله الحمد وعندها بنات في المنزل، والتوفيق بينهما أصبح مستحيلاً، فهل يجوز لي أن أعمل لي بيتاً مستقلاً لي وزوجتي وأترك والدتي وإخوتي، ما الحكم في ذلك؟ بارك الله فيكم.","title":"هل على الزوجة خدمة أم زوجها؟","answer":"الجواب: خدمة المرأة لزوجها وأهل زوجها أمر يختلف بحسب العرف في البلاد، وكان أزواج النبي ﷺ يخدمن بيوتهن، وكانت فاطمة رضي الله عنها تخدم بيتها، في الطحن والعجن والخبز وغير ذلك؛ وكنس البيت ونحو ذلك. فالذي ينبغي للمرأة أن تخدم زوجها وتخدم البيت، وإذا كان في البيت أمه أو أخته أو بناته، فالمشروع لها أن تخدمهن إذا كان العرف في بلادها كذلك.\nأما إذا كان العرف في الأسرة أو في البلد أو في القبيلة التي هي فيها، أنها تخدم وأنها لا تقوم بالخدمة هي، بل يستجلب لها خادمة، فإنه لا يلزمها وعلى الزوج إذا استطاع أن يأتي بالخادمة إلا أن تسمح بالخدمة، وتقوم بها من غير جبر لها فقد أحسنت في ذلك.\nفالحاصل: أن هذا الأمر يختلف ويتنوع بحسب عرف البلاد، إذا حصلت المشاحة والمشاقة، والأفضل للزوج أن يتحرى في هذا الأسلوب الحسن، وأن يرضي المرأة بما يستطيع من المال عند وجود النزاع حتى تخدم بنفس طيبة، حتى تخدم أمه، تخدم بناته أخواته الصغار، ونحو ذلك يكون بالأسلوب الحسن والكلام الطيب، والمساعدة المالية إذا حصلت المشاقة ولم يتضح العرف الذي يقنعها بأن تقوم بالخدمة في بيتها، والله ولي التوفيق. نعم.\nالمقدم: أثابكم الله وبارك الله فيكم، ولكن إذا استطاع أن يرضي والدته وينتقل في بيت مستقل لا حرج عليه؟\nالشيخ: لا حرج عليه، إلا أن تأبى والدته، إذا كانت الوالدة تأبى أن يخرج؛ لأنها محتاجة إليه أو لأسباب أخرى فلا ينبغي الخروج؛ لأن برها واجب، طاعتها مهمة، وقد يكون إخوته الذين في البيت لا يقومون مقامه، ولا يسدون مسده.\nفالحاصل: أنه ينبغي له أن يلاحظ أمه، ويستشيرها، فإذا سمحت فلا مانع من خروجه في بيت مستقل.\nأما إن كانت محتاجة إليه، أو كان هناك أسباب تدعو إلى عدم سماحها بخروجه فلا يخرج، بل يصبر ويحاول التوفيق بينها وبين زوجته ويرضي الزوجة بما يستطيع ولو بالمال حتى تمشي الأمور على الوجه المطلوب وحتى لا يخسر أمه بسبب زعلها عليه وغضبها عليه، والله المستعان.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8045/هل-على-الزوجة-خدمة-ام-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26402.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":9953,"question":"يسأل أيضاً ويقول: يحصل أحيانًا بعض الخلافات والمناقشة الحارة بين الزوجين فتغضب الزوجةُ زوجها، وهذه المناقشة غالباً ما تكون في أمور دنيوية، فهل تأثم المرأة بإغضاب زوجها؟ أفيدونا أفادكم الله.","title":"هل تأثم المرأة بإغضاب زوجها أثناء النقاش بينهما","answer":"الجواب: إذا كان إغضابها له بغير حق تأثم ولا يجوز لها أن تنازع ولا أن تؤذيه بالكلام، أما إن كان بحق بأن أنكرت عليه منكر، يتساهل في الصلاة فأنكرت عليه، يشرب المسكر فأنكرت عليه وناصحته فغضب فهي مأجورة غير مأزورة بل مشكورة.\nفالمقصود إن كان إغضابها له بحق فهي مأجورة وإن كان بغير حق فهي آثمة ولا يجوز لها إغضابه بدون حق، وعليها الكلام الطيب والسمع والطاعة في المعروف، لكن إذا كان هو يتعاطى المعاصي فأنكرت عليه ونصحته ووجهته إلى الخير فالواجب عليه أن يقبل منها وأن يشكرها وأن لا يغضب لأنها محسنة ومأجورة وناصحة فجزاؤها أن يزداد حبها وأن يشكرها على ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8121/هل-تاثم-المراة-باغضاب-زوجها-اثناء-النقاش-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27407.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":10003,"question":"تقول عندما تتصل امرأة بالهاتف على إحدى صديقاتها، ويجيب عليها أخو أو أبو هذه الصديقة، هل تقول هذه المرأة: السلام عليكم؟ أم تقول له: فلانة موجودة من غير تحية الإسلام أفيدونا جزاكم الله خيرًا؟","title":"حكم إلقاء المرأة السلام على الرجل الأجنبي","answer":"الجواب: السنة السلام؛ لأن المكالمة كالمقابلة، والمشروع للمؤمن عند لقاء أخيه أو أخته في الله أن يقول: السلام عليكم، أو السلام عليكم ورحمة الله، أو السلام عليكم ورحمة الله وبركاته، فإذا كلمه بالتلفون يبدأ يقول: السلام عليكم، وإن زاد ورحمة الله وبركاته كان أكمل، وذاك يرد عليه ويقول: وعليكم السلام ورحمة الله وبركاته، على ما قال له أخوه، ثم يسأل عن مراده. نعم.\nالمقدم: جزاكم الله خيرًا، هذا إن كان من المرأة للرجل ... ؟\nالشيخ: ولو بين الرجال والنساء، ولو كانت مع أجنبي؛ لأن هذا شرع الله، تقول: السلام عليكم، كان النبي ﷺ يسلم على النساء وهن أجنبيات، هي تقول له: السلام عليكم، ثم تقول: أين فلانة؟ زوجته أو أخته أو أمه، تسأل عنها عن لازمها، وإن كان تستفتي تسأل تقول: السلام عليكم، وتسأل عن حاجتها إن كانت تسأل عالمًا، تستفتي تقول: السلام عليكم أولًا ثم تسأل.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8169/حكم-القاء-المراة-السلام-على-الرجل-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33108.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة","قضايا المرأة"]},{"id":10037,"question":"أخيراً يسأل ويقول: ماذا نفعل مع امرأة هجرت زوجها في الفراش منذ حوالي سبع سنوات، ولا ترضى أن تكلمه أو تسأل عنه إذا كان مريضاً؟","title":"نصيحة امرأة هجرت زوجها في الفراش","answer":"الجواب: لا حول ولا قوة إلا بالله، هذه حالة سيئة نسأل الله العافية، ولكن هو إذا كان راضياً عنها سامحاً عنها فلا بأس، وإلا فالواجب عليها طاعة زوجها وعدم هجره إلا بعلة شرعية، فإذا كانت هجرته لأنه ترك الصلاة، هجرته لأنه أتى بأمر يوجب كفره وردته عن الإسلام لسب الدين والاستهزاء بالدين، أو هجرته لأنه ما قام بنفقتها ولا يعطيها حقها هذه لها حق في ذلك، أما إذا كانت هجرته بدون أسباب فهذا لا يجوز لها، بل يجب عليها أن تؤدي حقه وأن تسمع وتطيع له في الفراش وغيره، وله أن يطالبها بذلك وله أن يرفع أمرها إلى الحاكم الشرعي أو إلى أبيها أو إخوتها حتى يقوموا عليها بما يجب إن لم يصلح معها على شيء من المال ونحوه، أما إذا أرضاها بشيء من المال واستقامت الأحوال فالحمد لله.\nالحاصل أن هذا يختلف فإن كانت هجرته لكفره وضلاله أو سبه الدين أو تركه الصلاة أو كونه لم يعطها حقها ولم ينفق عليها فهي معذورة، أما إذا كانت هجرته لغير عذر شرعي فهذا يعالج الموضوع إما بالمال وإرضائها بالمال، وإما بواسطة أبيها وإخوتها أو بواسطة المحكمة أو يطلقها ويعطيه الله أبرك منها، هذه أمور تعالج إذا كان الهجر بغير حق تعالج إما بالطلاق وإما بغير الطلاق بما يستطيع، وتأثم هي إذا كان هجرها بغير حق، عليها أن تتقي الله وعليها أن ترجع إلى طاعة زوجها بالمعروف وأن تؤدي حقه، إذا كان قد أدى حقها وليس هناك موجب لهجرها له نسأل الله للجميع الهداية. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8200/نصيحة-امراة-هجرت-زوجها-في-الفراش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30104.mp3","categories":["الحقوق الزوجية"]},{"id":10124,"question":"من الإمارات العربية المتحدة رسالة بعث بها أحد الإخوة المستمعين من هناك رمز إلى اسمه بالحروف (ر. ط. ع) رسالته مطولة بعض الشيء يقول: إنني متزوج من زوجة ولي منها ثلاث بنات وولدان، ومشكلتي مع هذه الزوجة أنها من ثمان سنوات وأنا أحاول هدايتها وبالمعروف وبالكلام الطيب ولكن دون جدوى، رأسها قاسٍ كالصخر لا تسمع الكلام وتعصي أوامري ولا تسمع لي، وتحرجني أمام الأهل والأصحاب وتنكر المعروف والجميل دائماً، وتحب السيطرة وتحب أن تكون الكلمة لها، ولا تحب أن أزور أهلي وبالأخص والدتي، وكل هذا الصبر لأنها من الرحم ومن أجل أمها وهي عمتي أخت أبي ولكن دون فائدة، وباختصار إنني لست مرتاح معها ونفسي تطلب الزواج كما لو كنت لم أتزوج من قبل، هل لو تزوجت أكون قد ظلمتها؟ وهل لو لم أتزوج أكون أحاسب على طلب نفسي للزواج جزاكم الله خيراً؟","title":"نصيحة لزوج ابتلي بزوجة لا تحسن عشرته","answer":"الجواب: مثل هذه المرأة التي ذكرت أوصافها ينبغي طلاقها وعدم بقائها، فإذا استطعت أن تبقيها وتزوجت غيرها حتى تعف نفسك فهذا طيب، تزوج إذا قدرت وتبقيها من أجل أولادها أو من أجل أمها وترحمها بالكلام الطيب معها والتوجيه لها دائماً إلى الخير وأمها تعينك على ذلك بالتوجيه لها إلى الخير فلا حرج عليك، إذا كانت تصلي أما إذا كانت لا تصلي فلا تبقى معك أبداً، يجب أن تفارقها؛ لأن من ترك الصلاة كفر نسأل الله العافية.\nوينبغي لك أن تبادر بالزواج حتى تعف نفسك إذا كنت تستطيع بادر بالزواج ولعلها تهتدي بعد ذلك أو تطلقها وتستريح منها والحمد لله، لأن هذه بقاؤها معك تعب عليك وضرر عليك، لكن إذا هداها الله بعد زواجك فهذا لا بأس، أو رحمتها من أجل ضعف عقلها ومن أجل أمها وصبرت عليها وأحسنت إليها فأنت مأجور على إحسانك وصبرك، ولكن أنت معذور في فراقها وطلاقها بسبب أخلاقها الذميمة التي ذكرت عنها.\nفينبغي لك أن تبادر بالزواج وتحرص على الزواج والله يعينك حتى تعف نفسك وتستريح من هذا البلاء، فإن هداها الله وإلا فارقها، الله جل وعلا يقول: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ [النساء:130]. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8297/نصيحة-لزوج-ابتلي-بزوجة-لا-تحسن-عشرته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30503.mp3","categories":["الحقوق الزوجية"]},{"id":10136,"question":"من الإمارات العربية المتحدة رسالة بعث بها أحد الإخوة المستمعين من هناك رمز إلى اسمه بالحروف (ر. ط. ع) رسالته مطولة بعض الشيء يقول: إنني متزوج من زوجة ولي منها ثلاث بنات وولدان، ومشكلتي مع هذه الزوجة أنها من ثمان سنوات وأنا أحاول هدايتها وبالمعروف وبالكلام الطيب ولكن دون جدوى، رأسها قاسٍ كالصخر لا تسمع الكلام وتعصي أوامري ولا تسمع لي، وتحرجني أمام الأهل والأصحاب وتنكر المعروف والجميل دائماً، وتحب السيطرة وتحب أن تكون الكلمة لها، ولا تحب أن أزور أهلي وبالأخص والدتي، وكل هذا الصبر لأنها من الرحم ومن أجل أمها وهي عمتي أخت أبي ولكن دون فائدة، وباختصار إنني لست مرتاح معها ونفسي تطلب الزواج كما لو كنت لم أتزوج من قبل، هل لو تزوجت أكون قد ظلمتها؟ وهل لو لم أتزوج أكون أحاسب على طلب نفسي للزواج جزاكم الله خيراً؟","title":"نصيحة لزوج ابتلي بزوجة لا تحسن عشرته","answer":"الجواب: مثل هذه المرأة التي ذكرت أوصافها ينبغي طلاقها وعدم بقائها، فإذا استطعت أن تبقيها وتزوجت غيرها حتى تعف نفسك فهذا طيب، تزوج إذا قدرت وتبقيها من أجل أولادها أو من أجل أمها وترحمها بالكلام الطيب معها والتوجيه لها دائماً إلى الخير وأمها تعينك على ذلك بالتوجيه لها إلى الخير فلا حرج عليك، إذا كانت تصلي أما إذا كانت لا تصلي فلا تبقى معك أبداً، يجب أن تفارقها؛ لأن من ترك الصلاة كفر نسأل الله العافية.\nوينبغي لك أن تبادر بالزواج حتى تعف نفسك إذا كنت تستطيع بادر بالزواج ولعلها تهتدي بعد ذلك أو تطلقها وتستريح منها والحمد لله، لأن هذه بقاؤها معك تعب عليك وضرر عليك، لكن إذا هداها الله بعد زواجك فهذا لا بأس، أو رحمتها من أجل ضعف عقلها ومن أجل أمها وصبرت عليها وأحسنت إليها فأنت مأجور على إحسانك وصبرك، ولكن أنت معذور في فراقها وطلاقها بسبب أخلاقها الذميمة التي ذكرت عنها.\nفينبغي لك أن تبادر بالزواج وتحرص على الزواج والله يعينك حتى تعف نفسك وتستريح من هذا البلاء، فإن هداها الله وإلا فارقها، الله جل وعلا يقول: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ [النساء:130]. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8297/نصيحة-لزوج-ابتلي-بزوجة-لا-تحسن-عشرته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30503.mp3","categories":["الحقوق الزوجية"]},{"id":10258,"question":"رسالة من المنطقة الشرقية في المملكة بعث بها أحد الإخوة يقول: المتعاقد طبيب (أ. ل. ح. د): أخونا له قضية مع زوجته يذكر أولاً: أنه على خلاف دائم معها، لأسباب يصفها بأنها تافهة في كثير من الأحيان؟","title":"الخلافات الدائمة بين الزوجين ووسائل تلافيها","answer":"الجواب: ننصحهما بالحلم والرفق والتواصي بالحق والصبر وعدم النزاع وعدم الطلاق، نوصي الجميع بالتعاون على الخير والتواصي بالخير، وعدم المنازعة، نوصي المرأة بالسمع والطاعة لزوجها في المعروف، نوصي الزوج بالصبر والحلم وعدم العجلة في الطلاق أو الضرب أو السب، كل واحد منهما عليه أن يتحمل ويستعمل الرفق في كل الأمور، لقوله ﷺ: إن الرفق لا يكون في شيء إلا زانه، ولا ينزع من شيء إلا شان ، ولأن هذا العمل داخل في وقوله تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228].\nفالمشاجرة الدائمة والنزاع من أسباب الطلاق، وهكذا السب والشتم، فالواجب على كل منهما حفظ اللسان عما لا ينبغي، وحفظ الجوارح عما لاينبغي، والرفق بالأمور والحلم والصبر. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8428/الخلافات-الداىمة-بين-الزوجين-ووساىل-تلافيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27908.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":10356,"question":"المستمعة (ع. م. الخطيب ) من الضفة الغربية بفلسطين، بعثت برسالة ضمنتها مجموعة كبيرة من الأسئلة، عرضنا بعضًأ منها في حلقة مضت، وفي هذه الحلقة لها عدد من الأسئلة أيضًأ تقول في أحدها: إذا كان للمرأة مال كالحلي أو كأي شيء آخر وأحبت أن تزكيه، فهل لزوجها أن يمنعها من ذلك؟ نرجو التوجيه جزاكم الله خيرا، علمًأ بأن ذلك المال من مهرها؟","title":"حكم منع الزوج زوجته من إخراج زكاة حليها","answer":"الجواب: ليس لزوجها أن يمنعها من الزكاة ولا أن يمنعها من الصدقة، بل ينبغي له أن يعينها على ذلك وأن يشجعها على ما ينفعها في الآخرة، فإذا أرادت أن تزكي حليها فالواجب عليه أن يعينها على ذلك وليس له أن يمنعها.     \nوالصواب: أن الحلي فيه الزكاة إذا بلغ النصاب، هذا هو الصواب من قولي العلماء، لأدلة في ذلك واضحة تدل على وجوب الزكاة في الحلي إذا بلغت النصاب من الذهب أو الفضة، فإن على المرأة أن تزكيها كل سنة، والزكاة ربع العشر، والنصاب عشرون مثقالًأ من الذهب قدره اثنان وتسعون غرام ومن الجنيهات إحدى عشر جنيه وثلاثة أسباع جنيه، يعني: إحدى عشر ونص جنيه سعودي.\nفإذا بلغت الحلي هذا المقدار وجبت الزكاة فيها إذا حال الحول عليها كل سنة ربع العشر، من كل مائة اثنان ونص من ألف خمسًأ وعشرين، وهكذا يعني: ربع العشر.\nوهكذا الفضة إذا بلغت النصاب مائة وأربعين مثقالًأ، ومقدار ذلك ستة وخمسون ريالًأ سعوديًأ من الفضة وما يعادلها من العمل، فإن الواجب زكاة ذلك ربع العشر، ففي المائتين خمسة، وفي الأربعمائة عشرة وفي الألف خمسًأ وعشرون وهكذا.\nوإذا أرادت الصدقة من مالها من مهرها أو غيره من ورثها من أبيها أو من تجارتها ليس له أن يمنعها حتى التطوع، بل المشروع له أن يشجعها على الخير ويعينها على الخير، والله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول النبي ﷺ: والله في عون العبد ما كان العبد في عون أخيه.\nفالمشروع لها أن تعينه على الخير، والمشروع له أن يعينها، كل منهما يعين الآخر، هي تعينه على طاعة الله ورسوله وعلى الصدقة وعلى صلة الرحم وعلى جميع أنواع الخير، وهو كذلك يشرع له أن يعينها على الصدقة، وعلى صلة الرحم وعلى غير هذا من أنواع الخير، رزق الله الجميع الهداية والتوفيق.","link":"https://binbaz.org.sa/fatwas/8518/حكم-منع-الزوج-زوجته-من-اخراج-زكاة-حليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33807.mp3","categories":["الحقوق الزوجية"]},{"id":10394,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من رأس تنورة تقول: أرجو عرض سؤالي الآتي على سماحة الشيخ: عبد العزيز بن عبد الله بن باز حفظه الله، تقول في رسالتها -وهي مطولة بعض الشيء-: لقد تزوجت برجل من مدة ست وعشرين سنة وأنجبت منه ابنين وأربع بنات، وقد مكثنا عشر سنوات على خير ما يرام، وبعدها بدأت ألاحظ على زوجي تغيرًا في عينه، مما جعلني أخاف من ذلك وأكره هذا المنظر ولا أطيقه، وإذا دخل علي في البيت أرى كأن في عينيه نارًا، مما يجعلني لا أطيق الاجتماع به ولا السير معه ولا أجلس معه من أجل الخوف الذي يساورني إذا رأيته؛ لأنه في حالة غير طبيعية مما أشاهده في عيونه، وقد أخذني أخي إلى جدة ليعالجني هناك، خشية أن يكون بي مرض وأنا ليس بي مرض، وقد ذهبت إلى أهلي أربع مرات من أجل ذلك ويردونني عليه، وبعد ذلك أخذت إحدى البنات وذهبت إلى الرياض واستأجرت بيتًا وسكنت فيه، ثم جاء أهلي وأخذوني وردوني إلى بيت زوجي في المنطقة الشرقية، وقد اتهمت أيضًا بفقدان الذاكرة وأنا ليس بي شيء بحمد الله، وقال أخي: إن عندي انفصامًا في الشخصية وإني مجنونة، فأرجو من مكارم أخلاقكم أن تتفضلوا بتوجيهي كيف أتصرف حتى أعود إلى حياتي الزوجية كما كنت؟ جزاكم الله خيرًا.","title":"تغير منظر زوجها في نظرها وكادت أن تهجر بيتها خوفا منه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالذي أراه في مثل هذا عرض الحالة على من تظنين أن عنده خبرة بهذا المرض النفسي الذي حدث لك لعله يجد علاجًا لهذا، هذا مرض نفسي يعرض على أطباء من علاج النفس، علاج الأمراض النفسية لعله يجد لك علاجا.\nومما يعالج به مثل هذا: العناية بالقرآن الكريم من نفث يديك عند النوم، تنفثي في يديك عند النوم تقرأين (قل هو الله أحد) والمعوذتين ثلاث مرات عند النوم، وتمسحين بذلك على ما أقبل من جسدك على الرأس والوجه وما أقبل من الجسد ثلاث مرات عند النوم.\nكان النبي ﷺ يستعمل هذا إذا اشتكى شيئًا عليه الصلاة والسلام، مع التعوذ بكلمات الله التامات من شر ما خلق، صباحًا ومساء ثلاث مرات. وكذلك باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم، ثلاث مرات، صباحًا ومساء. وقراءة آية الكرسي عند النوم، كل ذلك من أسباب العافية والسلامة. وهكذا قراءة آية الكرسي بعد كل صلاة. وقراءة قل هو الله أحد والمعوذتين بعد كل صلاة، مع تكرار السور الثلاث بعد المغرب والفجر ثلاث مرات. كل هذا من العلاج لهذا المرض إن شاء الله؛ لأنه قد يكون هناك شيء إما عين وإما غير ذلك من أعمال سيئة من بعض خصومك أنت وزوجك. فالمقصود: أن هذا قد يكون هناك عمل غير صورة زوجك في نظرك وفي مقابلتك له من عمل بعض المفسدين أو عين، وهي النظرة يسمونها النظرة قد هذا وقد يكون هذا، فإذا فعلت ما ذكر من القراءة والتعوذات فلا بأس ونرجو لك الشفاء، وإن عرضت نفسك بعض أطباء النفس من رجال أو نساء أخبرتيهم بالواقع فربما يكون عندهم شيء من العلاج، نسأل الله لك الشفاء والعافية.\nأما ما يتعلق بالنزاع والخصومة هذا لدى المحكمة إذا كان هناك نزاع غير هذا المرض فهذا عند المحكمة. نعم.\nالمقدم: جزاكم الله خيرًا، يبدو أن النزاع أو الخلاف بسبب هذه الحالة؟\nالشيخ: هذا الظاهر وما حصل لها من التغير في نظرها بالنسبة إلى زوجها، قد يكون هذا شيئًا واقعا، وقد يكون شيء في عينها فقط، والله أعلم سبحانه وتعالى. نعم.\nالمقدم: سماحة الشيخ! نفترض أن الزوج يستمع إلينا الآن هل من كلمة للزوج والمرأة في هذه الحالة الحديثة عليه؟\nالشيخ: نوصي الزوج بالعناية بها بالأساليب الحسنة والكلام الطيب والخطاب المناسب، والدعاء كل منهم يدعو الله أن يزيل ما حصل، هي تدعو ربها أن الله يشفيها مما أصابها والزوج كذلك يدعو الله أن يشفيه مما وقع ويشفيها مما وقع، يسأل ربه أن الله يشفيه مما وقع إن كان هناك شيء.. ، ويسأل ربه لها أيضًا أن الله يشفيها ويعافيها مما أصابها.\nالدعاء سلاح المؤمن، والله يقول سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] فنوصي كل منهما بسؤال الله العافية والشفاء مما حصل، وأن الله يعيد الحالة إلى حالتها الأولى الحسنة، هو القادر على كل شيء . نعم.\nالمقدم: سماحة الشيخ! المريض قد لا يحسن معالجة نفسه، هل تنصحونها بأن يقرأ عليها بعض الناس أو يصف لها بعض الوصفات المناسبة؟\nالشيخ: لا، هي تقرأ إذا كانت تقرأ أو يقرأ لها زوجها أو يقرأ لها أخوها أو أبوها أو امرأة صالحة تقرأ تنفث عليها، طيب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8566/تغير-منظر-زوجها-في-نظرها-وكادت-ان-تهجر-بيتها-خوفا-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34001.mp3","categories":["الحقوق الزوجية"]},{"id":10417,"question":"في سؤال لها آخر تقول فيه: هل يجوز للمرأة أن تصوم من غير إذن من زوجها لقضاء فرض أو تطوع؟ وهل يجوز له إذا علم أنها صائمة في وسط صيامها أي: في النهار أن يأمرها بأن تفطر أو يدعها تكمل؟ وهل يجوز صيامها وهو غير راضٍ وغاضب عليها إذا أصرت أن تصوم؟","title":"حكم صيام المرأة بدون إذن زوجها","answer":"الجواب: أما صوم الفرض كقضاء رمضان فهذا ليس له منعها ويجب عليه تمكينها، وليس لها طاعته في ذلك لو منعها، عليها القضاء؛ لأن الله جل وعلا أمرها بالقضاء وهكذا الرسول ﷺ، وقد أجمع المسلمون على: أنه يجب على المرأة إذا أفطرت في رمضان بسبب الحيض أو النفاس أن تقضي، وليس لزوجها أن يمنعها من ذلك.\nوأما التطوع: فإن كان غائبًا لا بأس، وإن كان شاهدًا فلا تصم إلا بإذنه، لقول النبي ﷺ: لا تصومن امرأة وزوجها حاضر إلا بإذنه، فإذا كان زوجك حاضرًا فليس لك الصوم إلا بإذنه، أعني: صوم التطوع كالخميس أو الإثنين أو ست من شوال أو صيام ثلاثة أيام من كل شهر ونحو ذلك، لابد من إذنه فإن أذن لك وإلا فلا تصومي.\nأما إن كان غائبًا مسافرا فلا بأس أن تصومي حال غيبته ولو بغير إذنه؛ لأنه حينئذ لا يتضرر بذلك وليس عليه حرج من ذلك، بخلاف حضوره فإنه قد يمنعه من بعض حاجاته.\nوالخلاصة: أنه لا يجوز لك الصوم بحضوره إذا كان الصوم تطوع إلا بإذنه، أما في حال الغيبة فلا بأس، وأما قضاء رمضان فالواجب عليك صومه وإن لم يأذن، لكن الكلام معه في ذلك واستسماحه حتى يأذن لك في تعجيل الصوم كلام حسن كلام طيب؛ لأن الإنسان لا يدري هل تطول حياته أم لا فإذا بادرت بالصوم وسارعت بالصوم فهو أحوط لك وليس له منعك من ذلك، يعني: قضاء ما عليك من رمضان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8590/حكم-صيام-المراة-بدون-اذن-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34103.mp3","categories":["صيام التطوع","الحقوق الزوجية"]},{"id":10518,"question":"لها ملاحظة أخرى على ذلكم الزوج تقول سماحة الشيخ: زوجي لا يأتي بطلباتي كاملة، ولا ينزلني للسوق، فإذا نزلت مع ابن زوجي أو أخي بدون استئذان هل علي إثم؟ أو هل أكون عاصية لزوجي علمًا بأنه يقول: لا تنزلي مع أحد؟","title":"حكم خروج المرأة إلى السوق دون إذن زوجها","answer":"الجواب: لا تنزلي، ما دام يقول: لا تنزلي، لا تنزلي وإذا كانت هناك حاجات لم يشترها، ليشتريها أخوك أو غيره والحمد لله، استنيبي من يشتريها بدل من خروجك إلا بإذنه، المرأة لا تخرج إلا بإذن زوجها إلا عند الضرورة، وهذه ما هي بضرورة، والحمد لله يكفيك أخوك أو غيره. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8693/حكم-خروج-المراة-الى-السوق-دون-اذن-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28307.mp3","categories":["الحقوق الزوجية"]},{"id":10519,"question":"أيضًا ملاحظتها الثالثة تقول: بجواري نساء يزرنني وإذا أردت زيارتهن رفض زوجي، علماً بأنهم من جماعته، فهل أزورهم بدون استئذان وجهوني جزاكم الله خيرًا؟","title":"حكم منع الزوج لزوجته من زيارة جاراتها","answer":"الجواب: لا تزورنهن إلا بإذنه، وهم قد أحسنوا إذا زاروك جزاهم الله خيرًا، أما أنت فاعتذري إليهم أن زوجك منعك، فهذا عذر شرعي، وقد يكون له مقاصد طيبة، وقد يكون غير ذلك، فعلى كل حال الذي نوصيك به أن لا تعصيه في هذا، الزوج يطاع في المعروف، وهذا من المعروف فلا تعصيه فيه. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8694/حكم-منع-الزوج-لزوجته-من-زيارة-جاراتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28308.mp3","categories":["الحقوق الزوجية"]},{"id":10540,"question":"السائلة أم عبد الله من الرياض تقول: امرأة تشتكي من زوجها حيث إنه متزوج من امرأة أخرى، وتقول: بأنه لا يعدل مع أنه شخص ملتزم ويؤدي الفروض بأوقاتها ومستقيم وتحمد الله على ذلك، ويطلب منها ألا تستخدم موانع الحمل، أما الثانية فقد ترك لها حرية الاختيار، ما هي نصيحتكم سماحة الشيخ لهم؟","title":"حكم التفريق بين الزوجتين في استخدام موانع الحمل","answer":"الجواب: نصيحتي للجميع الأول أن يعدل الزوج ويتقي الله في ذلك؛ لأن الله أوجب عليه العدل بين الزوجتين في القسم والنفقة، فلا يجر على واحدة منهن، بل يجب أن يعدل بينهما، وأما كونه يمنع هذه من الحمل من تعاطي الحبوب ولا يمنع الأخرى، هذا قد يكون له نظر في ذلك لأسباب تقتضي ذلك، وهذا محل نظر، إذا كان ما هناك أسباب تقتضي ذلك فالواجب أن يسمح لهما جميعًا؛ لأن كل واحدة تريد الولد، أما إذا كانت الممنوعة من الولد يضرها الولد مع المرض يضرها.... لها أسباب معقولة هو معذور، أما أن يمنعها من الولد بغير أسباب ويأذن للأخرى فهذا فيه نوع من الجور.\nفالواجب أن يسمح لهما جميعاً ولا يجوز لهما منع الحمل كلاهما، لا يجوز له ولا لها، بل يجب عليهما أن يجتهدا في أسباب الحمل؛ لأن الرسول ﷺ، أمر بتزوج الولود الودود وقال: إني مكاثر بكم الأمم يوم القيامة فالمطلوب تكثير النسل، يشرع للزوج والزوجة أن يجتهدا في تكثير النسل، ولعل الله ينفعهما بذلك، فإن من النعمة العظيمة أن يرزقا ذرية طيبة، فلا وجه للمنع، ولا وجه للاتفاق على المنع أيضاً إلا لعلة شرعية، لأسباب شرعية تقتضي المنع الموقت، كأن تكون مريضة يضرها الحمل كأن يكون معها رضيع يضره الحمل، أو يضرها هي أيضاً الحمل، المقصود إذا كان لأسباب شرعية فلا بأس، أما منع هذه بدون سبب شرعي، أو هذه بدون سبب شرعي، أو منعهما بدون سبب شرعي كل هذا لا يجوز، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8715/حكم-التفريق-بين-الزوجتين-في-استخدام-موانع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28412.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":10556,"question":"يقول أيضاً ويبدو أنه يعني نفس الزوجة، أمرت زوجتي بأن تصلي وكل هذا بدون فائدة، ماذا أعمل رغم أنها متعلمة جيداً؟ المرجو الإفادة جزاكم الله خيراً.","title":"ما يجب على من ابتُلي بزوجة لا تصلي؟","answer":"الجواب: الواجب أمرها بالصلاة وتأديبها على ذلك، ولو بالضرب المناسب؛ لأن ترك الصلاة جريمة عظيمة بل كفر في أصح قولي العلماء، فالواجب عليك أن تأمرها بالصلاة وأن تؤدبها على ذلك، فإن أصرت وجب فراقها على الصحيح، بطلقة واحدة تمنع تعلقك بها، وتكون وثيقة... تعطى بها وثيقة حتى تتمكن من الزواج بعد ذلك.\nالمقصود: أنه إذا كانت ممتنعة من الصلاة، فالصحيح: أنه ليس لك أن تبقيها في عصمتك، بل يجب أن تفارقها، في أصح قولي العلماء، لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وسوف يعطيك ربك خيراً منها، ربنا يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فأنت بحمدا لله على خير من أجل غيرتك لله وكراهتك لعملها، وعليك أن تكمل ذلك بإعطائها الطلاق، حتى لا تبقى لك علقة بها، طلقة واحدة فقط، حسماً لمادة التعلق بها وخروجاً من خلاف من قال من العلماء: إن تركها الصلاة لا يوجب كفرها، فالطلقة يحصل بها راحتك منها ويحصل بها حسم لمادة الخلاف ويحصل بها وثيقة لها تعتمد عليها في التزوج بغيرك.\nونسأل الله أن يهديها ويردها للصواب وأن يعطيك خيراً منها إن لم تهتد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8736/ما-يجب-على-من-ابتلي-بزوجة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32206.mp3","categories":["الحقوق الزوجية"]},{"id":10563,"question":"من المستمعة (ع. هـ. م) سوداني مقيمة في المملكة، بعثت تسأل عن قضية هامة جداً نرجو أن يتفهمها الناس فهماً صحيحاً، تقول: أسأل عن خدمة المرأة لزوجها، من ترتيب المنزل وإعداد الطعام ونظافة المنزل وغسل وكوي الثياب له، وأيضاً نظافة الأطفال، وتناولهم الطعام، هل يكون عليها واجب أو فرض من الله، أو يعتبر خدمة إنسانية بينهما، وإذا لم تخدمه في الأشياء المذكورة ماذا يكون حكمها في الدين؟ هل عليها إثم أم لا؟","title":"حكم خدمة المرأة لزوجها","answer":"الجواب: هذه المسألة مهمة والصواب فيها: أنها واجبة عليها لزوجها، وهكذا كان أصحاب النبي صلى الله عليه وسلم تخدمهم نساؤهم، حتى فاطمة رضي الله عنها كانت تخدم زوجها وتقوم بحاجة البيت، من طحن وكنس وطبخ وغير ذلك، فهذا من المعاشرة بالمعروف، أو هذا هو الأصل.\nإلا إذا كانت المرأة من بيئة قد عرفوا بأنهم يخدمون في أي قطر أو في أي زمان، فالناس لهم عرفهم؛ لأن الله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] فإذا كانت المرأة من بيئة تخدم ولم يكن من عادتهم أنهم يخدمون البيت، فإن الزوج يأتي لها بخادمة إن لم تسمح بأن تخدم بيتها، أما إن سمحت فالحمد لله، وأما الأصل فالأصل أنها تخدم زوجها في كل شيء مما ذكرت السائلة، كنس البيت طبخ الطعام تغسيل الثياب كيها ونحو ذلك، هذا هو العرف السائد في عهد النبي ﷺ وعهد من بعده، لكن إذا وجدت بيئة وأسرة لها عرف آخر في بلادهم واشتهر ذلك بينهم وعرف بينهم وعرفه الزوج. فإنهم يعملوا بعرفهم لأنه كالمشروط، الشيء الذي استمر عليه العرف والزوج يعرفه كالمشروط، إلا أن تسمح الزوجة بترك هذا الشيء وأن تخدمه وأن تترك ما عليه عرف أسرتها وبلادها فهي بهذا قد فعلت معروفاً ولا حرج.\nفالمقصود: أنها تعامل بمقتضى العرف في بلاده وأسرته، وإلا فالأصل أن تخدم زوجها هذا هو الأصل في حاجات البيت وحاجات ثيابه ونحو ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8738/حكم-خدمة-المراة-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32208.mp3","categories":["الحقوق الزوجية"]},{"id":10577,"question":"تقول أختنا الجزائرية: لي أخت متزوجة ولها مشاكل مع زوجها وأهله، وحينما تأتي لزيارتنا تقص علينا ما يحدث لها ولأولادها وتبكي كثيراً؛ إذ أنها تظلم كثيراً، فنحن نوصيها بالصبر، لكني أسأل: هل لها أن تفعل ذلك عندنا جزاكم الله خيرا، وبم توصونها؟","title":"حث المرأة على الصبر وعدم شكوى زوجها إلى أحد","answer":"الجواب: نوصيها بالصبر إذا كان الزوج جيداً طيباً نوصيها بالصبر وعدم الشكوى إليكم وعدم إخباركم بشيء، بل يكون ذلك بينها وبين زوجها، وإذا استطاعت أن تطلب من أبيه أو أخيه الكبير أو خاله أو عمه الجيد أن ينصحه وأن يشير عليه إذا دعت الحاجة إلى ذلك فلا بأس، لكن مهما أمكن أن تحل مشاكلها بنفسها فيما بينها وبينه فهو أولى.\nوعليها أن تستعمل الخلق الطيب والكلام الطيب والأسلوب الحسن حتى يهدأ غضبه، وحتى يجيبها إلى طلبها لا بالعنف والشدة والهجر ونحو ذلك، بل تعالج الأمور بالحكمة والكلام الطيب والأسلوب الحسن.\nوعلى زوجها أن يتقي الله، وأن يعامل زوجته بالمعروف والكلام الطيب والأسلوب الحسن، كل منهما عليه أن يجتهد في المعاملة باللطف والخير، كما قال الله : وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وقال سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] فحقه أكبر، لكن ليس له أن يستعمل حقه في ظلمها والعدوان عليها والاكفهرار في وجهها وسوء المعاشرة كل هذا ما يجوز، بل عليه أن يعرف لها قدرها، وأن يحسن عشرتها، وأن يتبسم في وجهها، وأن يعاملها باللطف والكلام الطيب حسب الإمكان حتى تستقيم العشرة، وحتى تدوم المودة، وحتى يقوم كل واحد بما ينبغي لصاحبه.\nوعليها هي كذلك أن تستقيم وأن تعامله باللطف والكلام الطيب والأسلوب الحسن وأن تؤدي حقه بكل بشاشة وكل كلام طيب حتى تكون العشرة طيبة، كل واحد منهما يحرص على أن يكون على علاقة حسنة مع صاحبه، وعلى كلام طيب، وعلى أسلوب حسن في جميع الأحوال عند الجماع وغير الجماع، وفي حاجات البيت، وفي الزيارة لأهلها وفي غير ذلك من الشئون، كل منهما عليه أن يستعمل الأساليب الحسنة واللطف في حل المشاكل. نسأل الله للجميع الهداية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/8743/حث-المراة-على-الصبر-وعدم-شكوى-زوجها-الى-احد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32303.mp3","categories":["الحقوق الزوجية"]},{"id":10918,"question":"سؤال آخر على النقيض من السؤال الأول يقول فيه: هناك زوج عند أتفه الأسباب يضرب زوجته، ويبخل كثيرًا عليها وعلى أولادها، بينما هو كريم مع الآخرين، كيف توجهون مثل هذا؟ جزاكم الله خيرًا ... سماحة الشيخ.","title":"حكم ضرب الزوجة عند أتفه الأسباب والبخل عليها بالنفقة","answer":"الجواب:  هذا قد أتى منكرًا، ولا ينبغي له ذلك، بل الواجب عليه أن يحسن العشرة لأهله، ويكف يده عن الضرب، اشتكى بعض الناس إلى النبي ﷺ أنهم يضربون نساءهم فقال: إنهم ليسوا بخياركم، ليس الضرابون لنسائهم بخيارهم، وإنما أهل العفة والصبر والتحمل أولى، ولهذا قال الله سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وليس من المعروف الضرب بغير سبب، أو إسراف في الضرب، حتى ولو كان وقع منها بعض الشيء فليعالج بالكلام الطيب، والأسلوب الحسن والهجر، أو الوعظ والتذكير، ويجعل الضرب آخر الطب، يكون الضرب آخر الطب عند العجز عن العلاج بغيره، وإذا ضرب يكون ضربًا خفيفًا، لا يجرح، ولا يكسر، ولا يترتب عليه خطر عند الضرورة إليه عند الحاجة الشديدة إليه، إذا كان الوعظ والهجر لم يكفيا كما قال سبحانه في كتابه العظيم: وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ فَإِنْ أَطَعْنَكُمْ فَلا تَبْغُوا عَلَيْهِنَّ سَبِيلًا إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا [النساء:34] . فالمقصود أنه يعالج الأمور بغير الضرب مهما أمكن، بالكلام الطيب، والأسلوب الحسن، فإن دعت الحاجة إلى الهجر هجرها يومين ثلاثًا أكثر من ذلك في الفراش، يعطيها ظهره لا يكلمها، لكن الهجر بالكلام يكون ثلاثة أيام فأقل، إذا كان بالكلام. أما بالفعال .... يعطيها ظهره، أو يعالجها بأشياء أخرى تعرف منها أنه زعلان عليها، وأنه غضبان عليها؛ فلا بأس حتى تعتدل، والله يقول سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228]، فالرجل له درجة عليها، فلا مانع أن يستعمل الدرجة على الوجه الشرعي، بالوعظ والتذكير والهجر والضرب الخفيف عند الحاجة إليه، أما استعمال الضرب عند أتفه الأسباب هذا منكر ولا يجوز. وهكذا التقتير عليها وعلى أولادها لا يجوز، عليه أن ينفق عليها النفقة الشرعية ويحسن إليها ولا يقتر عليها، هذا هو الواجب عليه أن ينفق بالمعروف، فإن قصر فلها أن تأخذ من ماله ما يكفيها ولو من غير علمه، إذا قصر عليها ولم يعطها حقها ساغ لها أن تأخذ من ماله ما يكفيها ويكفي أولادها بالمعروف، كما ثبت في الصحيح عن عائشة -رضي الله عنها-: أن هند بنت عتبة اشتكت إلى النبي ﷺ أن أبا سفيان لا يعطيها ما يكفيها ويكفي بنيها، فقال لها: خذي من ماله بالمعروف ما يكفيك ويكفي بنيك وأفتاها بهذا -عليه الصلاة والسلام-. نعم.","link":"https://binbaz.org.sa/fatwas/9103/حكم-ضرب-الزوجة-عند-اتفه-الاسباب-والبخل-عليها-بالنفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36113.mp3","categories":["الحقوق الزوجية"]},{"id":10976,"question":"وصلتنا رسالة من المغرب من الهاشم بولا، يقول في هذا  ماذا تقولون -يا سماحة الشيخ- على الشخص الذي يفضل زوجته على والدته، وهل هذا يجوز؟ نرجو التوجيه في ذلك.","title":"حكم تفضيل الزوجة على الأم","answer":"الجواب: هذا يختلف إذا كان قد قام بحق أمه، في ملابسها المعتادة، وطعامها وشرابها، ولكن يخص الزوجة بأشياء تناسبها، تناسب أمثالها فلا بأس، للزوجة ملابس تناسبها، وللأم ملابس تناسبها، فإذا أعطى كل واحدة ما يناسبها فلا حرج في ذلك، ولو كان الذي أعطى الزوجة أكثر، أو أعلى؛ لأنه الذي يناسبها، والمرأة التي هي أمه يناسبها شيء آخر، فلا حرج في ذلك، كل واحدة تعطى ما يناسبها من الشخص، فيعطي الزوجة من الملابس وغيرها ما يناسبها، ويعطي الوالدة من الملابس ما يناسبها. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9154/حكم-تفضيل-الزوجة-على-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28620.mp3","categories":["الحقوق الزوجية"]},{"id":11174,"question":"هذا السائل أرسل بهذا السؤال من الزلفي (ع. م. م) يقول: سماحة الشيخ: والدي متزوج ثلاث نساء مع والدتي ولكن أبي لا يأتي والدتي علمًا بأنها هي أم الأولاد، من مدة تزيد ما يقارب على ست سنوات تقريبًا، وكان السبب في ذلك هو: أن والدي كان يأتي متأخرًا من الليل إذا كان يومها، وبعكسه مع نسائه الأخريات، ووالدتي لم تصبر على هذه الحالة وعلى هذا الظلم وغيرها، فقالت له: إذا كان هذا حضورك لي وهذه حالك معي فلا تحضر،  هل الإثم على والدي الذي ترك والدتي مدة ست سنوات أم على والدتي التي قالت: لا تحضر، عليها شيء، وهي تقصد بالحضور المتأخر من هذا الزوج، وإحضاره الطفل يجعله ينام في فراش والدتي، أرجو منكم الإجابة يا سماحة الشيخ؟","title":"العدل بين الزوجات مطلب شرعي","answer":"الجواب: لاشك أنه أخطأ لأن الواجب عليه العدل، إلا إذا كان بلغها قال: إن كانت ... وإلا طلقت هذا قد اعتذر إليها، أما كونه يقسم للثلاث ويتساهل في حق الوالدة ولا يأتي إلا في آخر الليل أو يضيعها هذا منكر ما يجوز، هذا ظلم، بل الواجب عليه إما أن يعدل وإما أن يطلق، إلا إذا رضيت قالت: أنا سامحة ولو ما جئت، إن جئت فلا بأس وإن ما جئت فلا بأس فلا بأس إذا سمحت لا بأس. سودة رضي الله عنها أم المؤمنين بنت زمعة أراد النبي ﷺ طلاقها فقالت: يا رسول الله دعني في حبالك وأنا سامحة عن حقي لعائشة فأقرها في حباله وبقيت زوجة له ولم يطلقها برضاها، فإذا سمحت والدتك فلا بأس، وإلا فلها طلب الطلاق إما أن يعدل وإما أن يطلق، والإثم عليه إذا كانت لم تسمح. نعم. المقدم: سماحة الشيخ: العدل بين الزوجات أمر مطلوب هل من كلمة توجيهية لأولئك الذين يعددون؟ الشيخ: نعم. الواجب عليهم جميعًا تقوى الله سبحانه وأن يعدلوا، فالذي عنده زوجتان أو ثلاث أو أربع الواجب عليه تقوى الله، وأن يعدل أو يخير المرغوب عنها يقول: إن شئت صبرت وإن شئت طلقت، أما أن يظلمها ويؤذيها، لا. بل يجوز له أن يقول لها: أنتِ سامحة فلا بأس وإلا طلقتكِ، فإن سمحت فالحمد لله وإلا طلقها.  أما أن يظلمها ولا يطلق لا يجوز، بل يجب العدل في المبيت وغيره؛ لأن الله جل وعلا أوجب العدل والله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، فالواجب العدل بين الزوجات، ويقول ﷺ: من كانت له زوجتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فعلى الزوج أن يعدل بين الزوجتين أو أكثر، وإذا رغب عن إحداهن يقول لها: أنا راغب أنت تصبرين متى شئت جئت وإلا فلا، وإلا طلقتكِ، لا بأس قد برئ إذا سمحت لا يضره ذلك ولا حرج عليه، وإذا لم تسمح يطلقها. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9354/العدل-بين-الزوجات-مطلب-شرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29021.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":11180,"question":"من جدة رسالة بتوقيع أحد الإخوة يقول: أخوكم في الله سعد، الأخ سعد يقول: الزوجة التي لا تصلي ليس بإرادتها؛ بل بسبب الوساوس، هل يجوز لزوجها معاشرتها وأن تبقى معه، فهي لا تستطيع الوضوء ولا حتى التيمم لمرضها كما قلت: بالوسواس، هل تصلي بدون وضوء؟","title":"كيفية العمل مع الزوجة التي لا تصلي بسبب الوساوس","answer":"الجواب: الواجب تعليمها وتوجيهها، وأن الوساوس التي تعتريها لا يجوز لها أن تميل إليها وأن تستعملها حتى تضيع الصلاة، بل يجب أن تدعها وأن تصلي، وعليك أن توضح لها ذلك وأن تأمرها بذلك، ولو بالتأديب ولو بالضرب المناسب غير المبرح؛ لأن ترك الصلاة كفر أكبر، فلابد أن تعتني بهذا الأمر وأن تلزمها بالصلاة وأن توجهها إلى الخير؛ حتى تدع الوساوس وحتى تصلي الصلاة التي فرض الله عليها، هذا يحتاج إلى جهاد وصبر لابد؛ لأن الجهل داء عضال. فلابد من التعليم والتوجيه والإرشاد منك ومن أمها وأبيها إن كان لها أبوان من أقاربها، لابد من التعاون على البر والتقوى حتى تفهم الأمر الشرعي. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9369/كيفية-العمل-مع-الزوجة-التي-لا-تصلي-بسبب-الوساوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37214.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":11292,"question":"بعد هذا رسالة بعث بها المستمع إبراهيم المرزوق رسالته مطولة يصف فيه حالته الزوجية بأنها ممتازة، وله زوجة مستقيمة وهو كذلك، إلا أنها لا تقوم بالحقوق الزوجية كاملة، فما هو توجيهكم، جزاكم الله خيرًا؟","title":"ما موقف الزوج من امرأة مستقيمة تقصر في بعض حقوقه؟","answer":"الجواب:  عليك أن تناصحها، وتتكلم معها بالكلام الطيب وإن شاء الله يهديها الرب جل وعلا ما دامها طيبة إن شاء الله مع المناصحة ومع المذاكرة ومع الكلام الطيب يحصل المطلوب إن شاء الله ولا تعجل. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9489/ما-موقف-الزوج-من-امراة-مستقيمة-تقصر-في-بعض-حقوقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37621.mp3","categories":["الحقوق الزوجية"]},{"id":11500,"question":"سوداني مقيم في المملكة اسمه (جعفر . س) يقول: أنا رجل متزوج، ونويت الزواج من امرأة أخرى، لكن أخفيت ذلك عن زوجتي، فهي إن أخبرتها ستعارض بطبيعة الحال، فما حكم الإسلام في إخفائي لذلك الأمر عنها؟ جزاكم الله خيرًا.","title":"حكم إخفاء الرجل زواجه بالثانية عن زوجته الأولى","answer":"الجواب:  لا حرج في ذلك أن تخفي عنها؛ لكن متى تزوجت لابد من العدل، لابد من العدل بينهما إلا أن ترضى الأخيرة بعدم القسم لها فلا بأس، وإلا فلابد من العدل، تقسم لهذه ولهذه، سواء سواء، نعم. المقدم: بارك الله فيكم، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9678/حكم-اخفاء-الرجل-زواجه-بالثانية-عن-زوجته-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38311.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":11559,"question":"آخر سؤال لها تقول: رجل هجر زوجته منذ أكثر من عشر سنين، وبقيت هي في بلد وهو في بلد، وتزوج من امرأة أخرى، وأنجب منها أطفالًا، والمرأة التي هجرها لديها منه أولاد، أكبرهم الآن يبلغ ثلاثين عامًا، فهل يجوز لهذا الرجل أن يهجرها طوال هذه المدة، علمًا بأنه يستطيع السفر لتلك البلد؟ ثم هل حرمت عليه بسبب هجره لها بحجة أنه لا يحبها؟","title":"حكم هجر إحدى الزوجات لعدم حبه لها","answer":"الجواب:  إذا كانت لم تسمح عنه، ولم ترض بذلك فليس له هجرها، بل يجب عليه أن يعدل، أو يطلق، أما إذا كانت قد سامحته، قالت: إن شئت فأت، وإن شئت فلا حرج، فلا شيء عليه، فقد تركت سودة -رضي الله عنها- لقد طلبت سودة -رضي الله عنها- من النبي ﷺ أن يبقيها في عصمته، وجعلت يومها لعائشة لما هم بطلاقها، فوافق -عليه الصلاة والسلام- على ذلك، وجعل يومها لعائشة. فلا حرج في ذلك، أما إذا كانت لا، لا ترض بهذا؛ فإن عليه أن يعدل، أو يطلق، إما أن يقول لها: اسمحي عما فعلت، وإلا طلقتك، فإذا قالت: لا، لا أسمح، إما أن تعدل، وإما أن تطلق؛ يلزمه هذا أو هذا، إما أن يعدل، وإما أن يطلق، أما إذا قالت: لا، أنا سامحة، إن جئت حياك الله، وإن رحت ما عندي مانع؛ لا بأس، لا تطلقني؛ فلا حرج عليه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9742/حكم-هجر-احدى-الزوجات-لعدم-حبه-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29708.mp3","categories":["الحقوق الزوجية"]},{"id":11806,"question":"من مشاكل مجتمعنا سماحة الشيخ مشكلة بعثت بها إحدى الأخوات المستمعات (م. ع. س) من الطائف، المشكلة في صفحتين، هل أقرأ هاتين الصفحتين، أم ألخصهما؟ جزاكم الله خيرًا. الشيخ: التلخيص. المقدم: التلخيص: أن زوجها لا يستجيب لمطالبها أحيانًا، وتشكو من أمه، وأخواته حتى أن الزوج استجاب للنميمة التي تقع من أخواته، ومن أمه، ولا يذهب بها لزيارة أهلها حتى في الأعياد، وترجو من سماحتكم التوجيه لكل الأطراف، جزاكم الله خيرًا.","title":"حكم من يمنع زوجته من زيارة أقاربها","answer":"الجواب:  ننصح الجميع بتقوى الله، والتعاون على البر والتقوى، ننصحها هي، ننصح المرأة بأن تستقيم، وأن تتسامح في هذا الأمر، وتدعو الله للجميع بالهداية، ونوصي الأخوات، وغيرهم بترك ما حرم الله عليهن من الغيبة والنميمة، وننصح الزوج بتقوى الله، وأن يؤدي الواجب، وأن يعدل، ولا يضر المرأة، نوصي الجميع بتقوى الله، وأن يقوم كل واحد بما يجب عليه، وأن يحذر الزوج من ظلمها. وهكذا أخواته وأقاربه عليهم أن يتقوا الله، ويحذروا ظلمها، وعليها أيضًا، عليك أنت أيها الزوجة أن تتقي الله، وألا تكذبي عليهم، وألا تؤذيهم بشيء، أما إذا استمر الأمر، ولم يستقم لك زوجك؛ فلك الشكوى إلى المحكمة بما ظلمك فيه، وفيما تراه المحكمة الكفاية، إن شاء الله. وإن وسطت أنت، أو أولياؤك، جماعة من أهل الخير، أو شخص من أهل الخير، أو امرأة من أهل الخير؛ حتى تصلح بين الجميع، وحتى يزول المحذور؛ فالصلح خير. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9990/حكم-من-يمنع-زوجته-من-زيارة-اقاربها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42308.mp3","categories":["الحقوق الزوجية"]},{"id":11983,"question":"ما هي النصيحة التي يتوجه بها سماحتكم للنساء حديثات العهد بالزواج؟","title":"وصايا للمرأة حديثة العهد بالزواج تجاه زوجها","answer":"الجواب:  نوصيهن النساء نوصي الحديثات العهد بالزواج، نوصيهن بحسن الخلق، وطيب العشرة مع الزوج، والتحمل لما قد يقع من تقصير من الزوج؛ حتى تستقيم الأحوال، تكون طيبة الأخلاق، حديثها مع زوجها طيب، تقوم بواجبها في منزلها، تعتني بنفسها من جهة النظافة والطيب، والحديث الطيب مع زوجها؛ لأن هذا من أسباب ثبات الزواج وبقائه واستمراره، ونحذرها من العنف والشدة، أو عدم تنفيذ أوامره التي لا محذور فيها، بل المشروع لها أن تعتني بأوامره وتنفذها إذا كان ليس فيها محذور شرعًا، أن تكون طيبة في الكلام معه، والحديث بالابتسام، والضحك المناسب، وتنفيذ الأوامر، وطيب المعاشرة، وطيب المخالقة، مع التطيب مع النظافة، مع إكرام أهله كأمه وأخواته وأبيه ونحو ذلك، كل هذا نوصي به الزوجات الجديدات وغيرهن. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10168/وصايا-للمراة-حديثة-العهد-بالزواج-تجاه-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_430/43006.mp3","categories":["الحقوق الزوجية"]},{"id":11984,"question":"سماحة الشيخ! بعض الأزواج في أول الحياة الزوجية يريد كل منهما أن يبرز شخصيته أمام الآخر، ما هو التوجيه سماحة الشيخ؟","title":"أسلوب التعامل بين الزوجين","answer":"الجواب:  الواجب العناية بهذا الأمر بدون تكلف، يحسن خلقه، وتحسن خلقها، هو يحسن خلقه، ويطمئن إليها ويعاشرها المعاشرة الطيبة بالكلام الطيب، والأسلوب الحسن، والجماع حسب التيسير، وكذلك في الفراش، طيب الخلق، وعدم التعبيس، وعدم الاكفهرار ...... وجه منبسط، وكلام طيب، وإذا دخل على البيت كذلك، وإذا جلس معهم كذلك وفي الفراش من باب أولى، ويؤمن حاجات البيت من غير إسراف، ولا بخل، بحسب أعراف أمثالها، وأمثال أهلها، هكذا ينبغي، يكون صبورًا، يتحرى الأمور المناسبة في المعيشة، وفي الخلق معها، ومع أهلها؛ لأن ذلك أقرب إلى يؤدم بينهما. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10169/اسلوب-التعامل-بين-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_430/43007.mp3","categories":["الحقوق الزوجية"]},{"id":12008,"question":"تزوجت منذ خمس سنوات، وكانت العروسة ذات خلق ودين، والحمد لله، لكن فوجئت بأن قام عداء بينها وبين أختي، وأختي كثيرًا ما تحرض عليها أهلي، وحينئذ أسأل سماحتكم بماذا توجهونني، وحالي ما ذكرت؟ جزاكم الله خيرًا.","title":"موقف الرجل من خصام أخته مع زوجته","answer":"الجواب:  نوصيك بعدم العجلة، مادامت الزوجة طيبة، نوصيك بالبقاء عليها، وإمساكها، ونصيحة أختك، وتحذيرها من التدخل فيما لا يعنيها، لا تعجل أمسك الزوجة، والحمد لله، وانصح الجميع وارفق، واستعن بالله على ذلك كله، وإذا رأيت أن توصي بعض أهلك حتى يوصوا أختك حتى ينصحوها تكف شرها طيب. المقصود: لا تطاوع في الزوجة الطيبة لا أختك ولا غيرها، لكن تنصح أختك، تقول: اتركي الشر، اتركي الشغب، وتوصي أمك تنصحها، أو أباك، أو إخوانك حتى تسلم من شرها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10193/موقف-الرجل-من-خصام-اخته-مع-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43122.mp3","categories":["الحقوق الزوجية"]},{"id":12627,"question":"من جمهورية مصر العربية رسالة وصلت إلى البرنامج من إحدى المستمعات من هناك تقول أم عبدالله: أم عبدالله في سؤال طويل لها تقول: هل يجوز لزوجي أن يمنعني من زيارة أهلي -أبي وأمي وإخواني- وأن يقول لي: أنت مخيرة في البقاء معي، أو تزوري بيت أهلك إذا خرجت لزيارة أهلك لا تدخلي بيتي مرة ثانية، علمًا بأن أهلي غير ملتزمين، ولما علم زوجي بأنني حزنت بسبب هذا الكلام قال لي: إذًا في كل شهر مرة، سافر زوجي بعد ذلك، وغاب لمدة أربعة أشهر، ومنعني من الذهاب إلى أهلي وامتثلت، سؤالي هو: هل يحق لزوجي أن يمنعني من زيارة أهلي لكونهم غير ملتزمين، وهل أكون آثمة والحالة هذه؟ وجهونا جزاكم الله خيرًا.","title":"حكم منع الرجل زوجته من زيارة أهلها غير الملتزمين","answer":"الجواب:  نعم، له أن يمنعك من زيارة أهلك إذا كانت الزيارة تضرك وتضره؛ لأنهم غير ملتزمين، أما إذا كانت الزيارة لا تضرك، ولا تضره، كأن تزوريهم لصلة الرحم والبر وتنصحيهم وتوجهيهم إلى الخير؛ هذا أمر طيب، وينبغي ألا يمنعك، أما إن كانت الزيارة تضرك وتضره، وتسبب مشاكل بينكم، بينكما وبين الأهل؛ فله أن يمنعك من ذلك؛ لما في هذا من المضرة عليه وعليك. وإذا طلق ألا تزوريهم؛ لا تذهبي إليهم، وإن ذهبت إليهم؛ وقع الطلاق إن كان أراد وقوعه، أما إن كان أراد منعك، لا وقوع الطلاق، ولكن أراد أن يمنعك، وأراد تخويفك، وتهديدك، ولم يرد إيقاع الطلاق؛ فإن هذا له حكم اليمين، وعليه كفارتها. وبكل حال، فالواجب عليك السمع والطاعة فيما يقول لك إذا كان معروفًا، وليس فيه ما يخالف شرع الله، أما إذا كان شيئًا يخالف شرع الله، إذا كان منعه لك لا سبب له، ولا وجه له شرعي، فهذا يرجع إلى المحكمة إن لم تصلحي أنت وإياه، فالمرجع في هذا إلى المحكمة، والمحكمة تنظر في الأمر، وفي حل المشكلة، إلا إذا صلحتما فالصلح بينكما جائز وماضي، لكن بشرط ألا يكون ذلك في معصية الله، لابد أن يكون الصلح على وجه شرعي، ليس فيه معصية لله  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10843/حكم-منع-الرجل-زوجته-من-زيارة-اهلها-غير-الملتزمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41507.mp3","categories":["الطلاق","الحقوق الزوجية","الأيمان والنذور"]},{"id":12687,"question":"المستمع: (أ. ن. ع) بعث يسأل ويقول: أنا شاب متزوج، وعندي ثلاثة أبناء، ولله الحمد، عرضت على زوجتي الحجاب الشرعي، وطلبت منها عدم مصافحة الأجانب، ولكنها لم تستجب حتى الآن، فكيف يكون توجيهكم؟ جزاكم الله خيرًا.","title":"حكم الزوجة إذا لم تطع زوجها في المعروف","answer":"الجواب:  ننصحها بأن تستجيب لك، فعليها أن تحتجب عن الرجال، وعليها أن لا تصافح الرجال الأجانب، وعليها أن تتقي الله، فإن هذا من أسباب الفتنة، والله -جل وعلا- يقول: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] الآية من سورة الأحزاب. ويقول سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ [النور:31] إلى آخره، والوجه والشعر واليد والقدم، كلها من الزينة، والنبي  يقول: إني لا أصافح النساء وقالت عائشة -رضي الله عنها-: والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام -عليه الصلاة والسلام- ولما مدت إليه امرأة يوم البيعة يدها قال: إني لا أصافح النساء عليه الصلاة والسلام. المقصود: أن المرأة عليها أن تستمع، وتطيع لأوامر الله ورسوله، وعليها أن تجيب زوجها، وأن تسمع له في طاعة الله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10897/حكم-الزوجة-اذا-لم-تطع-زوجها-في-المعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41715.mp3","categories":["الحقوق الزوجية"]},{"id":13061,"question":"السائلة أم محمد تقول: أسأل عن الحكم الشرعي في المرأة التي تسب زوجها إذا كان عنيدًا نوعًا ما مع الآخرين؟","title":"حكم سب المرأة زوجها","answer":"الجواب:  لا ينبغي السب، لا يجوز السب، لكن تدعو له بالهداية، وتعامله باللطف والعبارات الحسنة، والألفاظ الطيبة .. تدعو له بالهداية، أما السب لا يجوز، لا تقول: لعنك الله، ولا قاتلك الله؛ لأن هذا يسبب شرًا كثيرًا، والنبي ﷺ يقول: سباب المسلم فسوق ويقول: ليس المؤمن بالطعان، ولا اللعان، ولا الفاحش، ولا البذيء ويقول ﷺ: لعن المؤمن كقتله فلا يجوز السب، ولكن تدعو له بالهداية، تخاطبه بالتي هي أحسن، يا فلان! يا أبا فلان! هداك الله، ينبغي كذا، أنصحك بكذا، أشير عليك بكذا، عليه بالعبارات الحسنة، بالأساليب الحسنة .. بالنصيحة، والتوجيه الطيب، أما السب والكلام السيئ والجفاء فلا يجوز.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11278/حكم-سب-المراة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50521.mp3","categories":["الحقوق الزوجية"]},{"id":13261,"question":"السائلة أم عمر لها سؤالان:  الأول تقول هذه السائلة: سماحة الشيخ! ما حكم مصارحة المرأة لزوجها في جميع أمورها التي تخصها، وتخص العائلة، وهل يجوز لها الكذب عليه في أمور تجلب المشاكل لها، علمًا بأنني سمعت عن الرسول ﷺ حديثًا فيما معناه بأن المرأة تكذب على الرجل، وكذلك الرجل يكذب على زوجته، وأيضًا هناك نوع من الكذب الحلال، وهو لدرء المفاسد؟ أفتونا في ضوء ذلك مأجورين.","title":"حكم الكذب على الزوجة وكذب الزوجة على زوجها","answer":"الجواب:  هذا موضوع عظيم، أما ما يتعلق بالمصارحات في مصالح البيت، وشؤون البيت هذا لابد منه، تصارحه، وتعطيه المعلومات الكافية عن حاجات البيت، وشؤون البيت، إلا الشيء الذي تستطيع أن تسده بنفسها، وتقوم به من مالها، هذا لا بأس، وإلا تصارحه بشؤون البيت؛ حتى لا يكون في خلل مع ضيوفه، أو مع أولاده، أو مع من تحت يده من أيتام وغيرهم، لابد تصارحه بجميع حاجات البيت حتى يقوم بالواجب؛ لأنها مؤتمنة مثلما قال ﷺ: المرأة راعية في بيت زوجها، ومسؤولة عن رعيتها، كلكم راع، وكلكم مسؤول عن رعيته. فلابد أن تعطيه الحقيقة، ولابد أن تجتهد في أداء الواجب؛ لأنها مأمونة على هذا البيت، ولابد من تحري الصواب، وتحري الحق؛ حتى لا تخفي شيئًا يضر أهل البيت. أما الكذب فلا بأس، قد تكذب عليه، أو يكذب عليها فيما لا يضر الناس فيما يخصهما؛ لقوله ﷺ في حديث أم كلثوم بنت عقبة بن أبي معيط قالت -رضي الله عنها-: «لم أسمعه يرخص في شيء فيما يقولون أنه كذب إلا في ثلاث: الخدعة للحرب -الخدعة في الحرب- والإصلاح بين الناس، وحديث الرجل امرأته، والمرأة زوجها» فيما يتعلق بشؤونهما لا بأس؛ لأن هذا قد يحصل به خير كثير، والتئام، وبقاء العقد، ودرء المفاسد، فإذا صرحت له، وصرح لها بأشياء كذب، لكن تنفعهم مثلًا: قالت له: إنك رحت بيت آل فلان، أو زرت آل فلان، أو بيزور آل فلان، أو يقول: لا ما هذا ما صح، وهو يكذب، ولا يترتب عليه شيء يضر الناس، أو يقول: ........ بيتزوج وإلا ما أنا ما اتزوج ........ ما أنا ما اتزوج، أو قالت له: إني أبغى أروح لأهلي؛ لأجل أعود مريضًا، والدتي، وإلا أبي، وهي لها حاجة مهمة لو أخبرته ما راح لها، ولا فيها محذور؛ لا بأس. المقصود: الكذب الذي ينفعهما، ولا يضر أحدًا، ينفعهما فيما بينهما، ولا يضر أحدًا من الناس؛ فلا بأس. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11546/حكم-الكذب-على-الزوجة-وكذب-الزوجة-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51403.mp3","categories":["الحقوق الزوجية"]},{"id":13272,"question":"السائل من جمهورية مصر العربية، ويعمل بالأردن، له مجموعة من الأسئلة، يقول في السؤال هذا سماحة الشيخ: ما حكم المرأة التي لا تطيع زوجها في الأمور الدينية والدنيوية، هل يقوم بتطليقها؟","title":"كيفية التعامل مع الزوجة التي لا تطيع زوجها","answer":"الجواب:  الواجب عليه نصيحتها، توجيهها إلى الخير، وتأديبها التأديب المناسب الخفيف، الذي ما فيه جرح ولا خطر، يعني غير مبرح حتى تستقيم، ولكن إذا كان التأديب والتوجيه ما ينفع؛ فلا مانع من الطلاق، لكن يحرص على تأديبها أولًا بالكلام والنصيحة والتوجيه، أو الهجر يهجرها في المضجع والكلام ثلاثة أيام، وفي المضجع ما شاء حتى تستقيم، فإذا لم تنفع النصيحة والهجر لا بأس أن يؤدِب، كما قال -جل وعلا-: وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ فَإِنْ أَطَعْنَكُمْ فَلا تَبْغُوا عَلَيْهِنَّ سَبِيلًا [النساء:34] لكن ضربًا غير مبرح، ضربًا خفيفًا، لعلها تستقيم، فإن لم تستقم فطلاقها أفضل إذا كان لم تستقم، ولم تقم بالواجب؛ فطلاقها أفضل، طلقة واحدة، وعسى الله أن يبدله بخير منها. أما إن كانت لا تصلي يجب فراقها، إذا أبت أن تصلي؛ فهذا يجب فراقها؛ لأن ترك الصلاة كفر، نسأل الله العافية. أما إذا كان عصيانها فيما يتعلق بحقوقه في الجماع، أو في صنع الطعام، أو في كنس البيت، أو ما أشبه ذلك، أو في خروجها إلى أهلها بغير إذنه، هذه أمور بينهما لا بأس إذا أدبها ونصحها ووجهها إلى الخير، وصبر عليها. أما إذا كانت ضعيفة في الدين ففراقها أفضل، والتي لا تصلي لا يجوز بقاؤها إذا كانت لا تصلي، يجب فراقها؛ لقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وهكذا المرأة، الأحكام تعم الجميع، ولهذا في الحديث الآخر يقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر، أمر الصلاة عظيم؛ لأنها عمود الإسلام، فمن تركها من الرجال، أو النساء؛ كفر، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11559/كيفية-التعامل-مع-الزوجة-التي-لا-تطيع-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51408.mp3","categories":["الحقوق الزوجية"]},{"id":13314,"question":"سماحة الشيخ! الحياة الزوجية الصالحة بين الزوجين كيف تكون، وأسأل: تساهل الناس الحقيقة في قضية الطلاق، وتهاونهم بذلك سماحة الشيخ، لعل لكم توجيه؟","title":"كيفية المعاشرة بالمعروف بين الزوجين","answer":"الجواب: لا شك أن الواجب على كل من الزوجين المعاشرة بالمعروف؛ لأن الله قال -جل وعلا-: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] فالواجب على الزوج أن يعاشر بالمعروف، وعلى الزوجة كذلك، على كل منهما المعاشرة بالمعروف، فالزوج يجتهد في معاشرتها بالمعروف، وهي كذلك وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] فهو يجتهد، وهي تجتهد بالكلام الطيب، والأسلوب الحسن، وحفظ اللسان عما لا ينبغي، وحفظ اليد عما لا ينبغي، فهو يعاشر بالمعروف، وهي كذلك في جميع الأحوال، ويحرص كل منهما على الكلام الطيب، والأسلوب الحسن، وأداء الواجب، الرجل يأتي بما أوجب الله عليه من النفقة، مع الكلام الطيب، والأسلوب الحسن، وهي كذلك عليها أن تسلم نفسها له، تسمع وتطيع له في المعروف، وتخاطبه بالتي هي أحسن، ولا تمنعه من حاجته التي شرع الله له أداءها، هكذا الواجب عليهم أن يتعاونا جميعًا على الخير، وأن يكون كل واحد حريصًا على المعاشرة الطيبة، وعدم النزاع، وعدم الظلم، وبهذا تصلح الأمور، وتستقيم الأحوال، أما مع الظلم، ومع سوء العشرة ما تستقيم الأحوال، نسأل الله السلامة. نعم.  المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11600/كيفية-المعاشرة-بالمعروف-بين-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52104.mp3","categories":["الحقوق الزوجية"]},{"id":13347,"question":"السائلة (ع) من جازان من صبيا تقول: ما حكم خروج الفتاة بدون إذن زوجها، وذلك قبل الدخول بها، أي: ما تزال عند أهلها، هل تستأذن من والدها، أم من زوجها؟","title":"حكم خروج المعقود عليها بغير إذن زوجها","answer":"الجواب: خروجها لا بأس به إذا كان لمصلحة مع التحفظ، ومع الستر، لا بأس، إلا إذا منعها والدها، أو منعها زوجها؛ فلا تخرج إلا بإذن أبيها، أو إذن زوجها، ومادامت عند أهلها لم يدخل بها؛ فليس له إذن عليها؛ لأنها حتى الآن لم تكن تحت أمره، وفي بيته، لكن إذا خرجت لجيرانها، أو للصلاة في المسجد، أو لأسباب أخرى مع التحفظ، ومع الصيانة، والبعد عن أسباب الفتنة؛ فلا حرج في ذلك. أما إذا منعها والدها؛ فعليها السمع والطاعة، وهكذا عند الزوج إذا منعها الزوج، وقال: لا تخرجي إلا بإذني، لا تخرج إلا بإذنه، لا لأهلها، ولا لغير أهلها، لكن إذا كان لم يمنعها الزوج، بل أذن لها، ولم يمنعها أبوها؛ فلا حرج أن تخرج خروجًا سليمًا، ليس فيه محذور شرعًا، كخروجها إلى زيارة بعض جيرانها للراحة، والتحدث معهم على وجه لا محذور فيه، أو لزيارة أخيها، أو زيارة أختها، أو زيارة بعض أقاربها، على وجه لا محذور فيه شرعًا، أو لتعزية مصابين.. أو ما أشبه ذلك، مع التحفظ، وعدم التبرج، وعدم الطيب، هذا كله لا حرج فيه. فالمقصود: إذا خرجت خروجًا شرعيًا، ليس فيه محذور؛ فلا بأس في ذلك، وليس لها أن تخرج إلا بإذن زوجها إذا كانت في بيته وعصمته، وإذا كانت عند أبيها كذلك، إذا أذن لها؛ فلا بأس وإذا منعها؛ فلا تخرج؛ لأنه أعلم بمصالحها. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11633/حكم-خروج-المعقود-عليها-بغير-اذن-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54208.mp3","categories":["الحقوق الزوجية","قضايا المرأة"]},{"id":13363,"question":"بعد ذلك ننتقل إلى حائل ورسالة السائل (هـ. خ) يقول في هذا  متزوج من زوجتين الأولى تزوجتها دون أن أراها الرؤية الشرعية، وفوجئت بأنها غير جميلة، ومريضة مرضًا لا يرجى برؤه، ويقول: مضى على زواجي منها تسعة أعوام، وأنا أعاني نشوزًا، وإعراضًا منها، وبالإضافة إلى أنها غير طبيعية، ولا تفهم الأمور، أمور الحياة، وأبقيتها على ذمتي؛ رحمة بحالها المريضة، وعقلها المتخلف، وكذلك عطفًا على أولادي منها، وهم أربعة أبناء، وزوجتي الأخرى عكس ذلك، ولم أستطع العدل بينهما لكراهيتي لزوجتي الأولى، وحالتي النفسية تزداد سوءًا كل يوم، وتردد في كثير من الأحوال، وأيضًا فقد ترددت في طلاقها، وهي تعلم بذلك، والآن اشتدت حالتي النفسية سوءًا، فهل أطلقها؟ ماذا أعمل سماحة الشيخ؟","title":"توجيه لمن يكره أحد زوجتيه ومتردد في طلاقها","answer":"الجواب: الواجب عليك أن تعمل الأصلح، إن كنت تستطيع العدل، والقيام بالواجب في حق الزوجتين؛ فالحمد لله، اجتهد، واصبر، وصابر، واتقي الله، أما إن كنت لا تستطيع؛ فعليك أن تطلقها طلقة واحدة، وصبرت عليها كثيرًا. فالمقصود: أنك تنظر الأصلح في موضوعها، وموضوع الأخرى، فإن استطعت الصبر عليها كما صبرت هذه المدة الطويلة؛ فاصبر، ولعل الله أن يهديها، ويصلح حالها، وإن طلقتها؛ فطلقها طلقة واحدة، ولا حرج، والحمد لله، قد صبرت كثيرًا، وإن رأيت الأصلح أن تبقيها، وتصبر على أذاها، وعلى نقصها؛ فهذا لا حرج عليك فيه. نعم.","link":"https://binbaz.org.sa/fatwas/11651/توجيه-لمن-يكره-احد-زوجتيه-ومتردد-في-طلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51502.mp3","categories":["الحقوق الزوجية"]},{"id":13374,"question":"هذا السائل سلطان العمر من المدينة النبوية يقول: زوجة صالحة ذات صلاة وعبادة، ولكنها ذات خلق سيئ، حيث ترفع كثيرًا من صوتها على زوجها وأبنائها، تنظر إلى الأمور نظرة سوداوية متشائمة، وتحمل الأمور ما لم تتحمل، هل من كلمة توجهونها إلى مثل ذلك عبر الأثير، فلعلها تستمع إلى ما تقولون يا سماحة الشيخ، وحيث أنها أيضًا تستمع إلى برامج إذاعة القرآن الكريم؟","title":"توجيه لمن تسيء الخلق مع زوجها وأولادها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فنوصي المرأة المذكورة وأشباهها بتقوى الله -جل وعلا- والعناية بحسن الظن، ومراعاة الأساليب الحسنة، والبعد عن سوء الظن لا بأولادها، ولا بغيرهم، يقول الله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ [الحجرات:12] ويقول النبي ﷺ: إياكم والظن، فإن الظن أكذب الحديث. فالواجب على كل مسلم -رجل أو امرأة- الواجب الحذر من سوء الظن، إلا بأسباب واضحة، وإلا فالواجب ترك الظن السيئ، لا بالمرأة، ولا بالزوج، ولا بالأولاد، ولا بأخي الزوج، ولا بأبيه.. ولا بغير ذلك. الواجب حسن الظن بالله، وحسن الظن بأخيك المسلم، أو بأختك المسلمة، وألا تسيء الظن إلا بأسباب واضحة توجب التهمة، وإلا فالأصل البراءة والسلامة، وسوء الظن يسبب الفرقة، والاختلاف، والشحناء، والعداوة، حتى الرجل مع أولاده إذا ساء ظنه بهم، والمرأة مع أولادها إذا ساء ظنها بهم، ساءت الحال بينهم. فالواجب الحذر من ذلك، والواجب العناية بحسن الظن، مادام هناك مجال لحسن الظن، أما إذا وجد، وجدت أسباب تقتضي سوء الظن؛ فلا بأس، كاجتماعه بمن يساء بهم الظن، وكوقوفه مواقف التهم. المقصود: متى وجدت أمور واضحة تقتضي سوء الظن؛ فلا بأس، ولهذا إذا قامت البينة؛ عمل بها، وأسيء الظن بمن قامت عليه البينة بأنه سرق، أو بأنه زنى، أو بأنه شرب الخمر، فإذا قامت البينة الشرعية؛ أقيم عليه الحد، وأسيء به الظن بسبب البينة. أما عند عدم البينات؛ فالواجب ترك سوء الظن، والاعتماد على البراءة الأصلية، والسلامة الأصلية، والحذر من سوء الظن بالمسلم بغير حق، نسأل الله للجميع الهداية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11663/توجيه-لمن-تسيء-الخلق-مع-زوجها-واولادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52501.mp3","categories":["الحقوق الزوجية","قضايا المرأة"]},{"id":13378,"question":"السائل أبو هشام من جدة يقول: هل يجوز للخاطب بعد عقد زواجه أن يذهب مع خطيبته لتأثيث المنزل، وشراء بعض الحاجيات؟","title":"حكم خروج المرأة مع زوجها بعد العقد","answer":"الجواب: هي زوجة له، لكن يخشى أن يقع بها، وأن تحمل، ثم يحصل فرقة، وشكوك، وأوهام في هذا الشيء، فالأحوط ألا يخلو بها حتى يدخل الدخول الشرعي، حتى تزف إليه، هذا أبعد عن الخطر، وإلا فهي زوجة له، لا حرج هي زوجته، له أن يخلو بها، وله أن يجامعها، لكن يخشى إذا وقع هذا قبل الزفاف أن يحصل فرقة، ثم يتبرأ من الولد، ويقول: ما فعلت؛ فيحصل فساد وشر. فالأحوط اجتنابها حتى يحصل الزفاف الشرعي، والدخول الشرعي المعلوم عند الجميع، هذا هو الأحوط والأولى، وإلا فهي زوجته، لا شك إذا خلا بها، لا حرج عليه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11668/حكم-خروج-المراة-مع-زوجها-بعد-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52504.mp3","categories":["الحقوق الزوجية","قضايا المرأة"]},{"id":13549,"question":"السائل الذي أرسل بهذا السؤال يقول: ما حكم الزوجة الذي تسب زوجها؟","title":"حكم سب المرأة زوجها والعكس","answer":"الجواب: ليس لها سب زوجها، ولا يجوز لها ذلك، حكمها أنها عاصية ليس لها سبه، وهو كذلك ليس له سبها، كلاهما لا يجوز له سب الآخر، بل عليهما المعاشرة الطيبة، وحفظ اللسان عما لا ينبغي، يقول الله -جل وعلا-: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ويقول ﷺ: استوصوا بالنساء خيرًا. فالواجب على الزوج المعاشرة الطيبة، وحفظ اللسان عما لا ينبغي، والواجب على الزوجة كذلك المعاشرة الطيبة، والسمع والطاعة في المعروف لزوجها، والحذر من سوء الخلق من سب، أو غيره مما يؤذي الزوج. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11881/حكم-سب-المراة-زوجها-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53212.mp3","categories":["الحقوق الزوجية"]},{"id":13572,"question":"هذا سائل من السودان أرسل بهذه الرسالة كتب بأسلوبه الخاص، يقول في هذا  سماحة الشيخ! السلام عليكم ورحمة الله وبركاته،  لدينا أخت في الله وهي من الداعيات إلى الله  بقدر ما عندها من العلم الشرعي البسيط، وهي خريجة جامعية، وقد تزوجت من أحد الإخوان، وبعد زواجها بفترة جاءت الأخت المشار إليها بفكرة أن طاعة الزوجة في خدمة زوجها في البيت غير واجبة على المرأة، وإنما الواجب عليها فقط الفراش، فهي لا تطبخ، ولا تكنس البيت، ولا تقوم بأي عمل من الأعمال، وأصرت على رأيها، وقد قام الإخوة بنصحها كثيرًا، ولكن دون جدوى، وهي تقول: بأنها تريد فتوى من سماحة الشيخ عبدالعزيز بن باز بهذا، وقد كان الاتصال بها مباشرة في نصحها وإرشادها، فطلبت منكم التوجيه، جزاكم الله خيرًا.","title":"حكم خدمة الزوجة لزوجها","answer":"الجواب: الواجب على الزوجة السمع والطاعة لزوجها، وأن تعاشره بالمعروف كما يعاشرها بالمعروف، قال تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وقال تعالى: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228]. فالواجب عليها السمع والطاعة في الفراش، وحاجته إلى نفسها، والواجب عليها أيضًا خدمته الخدمة المعتادة التي يخدم مثلها مثله، فإذا كانت يخدم مثلها؛ فعليه أن يخدمها، وإذا كان مثلها لا يخدم في عرف بلادهم أنهم يخدمون أزواجهم؛ وجب عليها أن تخدمه؛ لأن هذه مسائل عرفية الرسول ﷺ أطلقها والقرآن أطلقها وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228].  فإذا كانت من بيت يخدم نساؤه، ولا يخدمون؛ أخدمها مع القدرة، وإذا كانت في عرفهم أنها تخدم زوجها، وتقوم بحاجة البيت من الطبخ وغيره؛ فعليها أن تقوم بذلك، وكان أزواج النبي ﷺ يخدمونه في البيت، يخدمونه ﷺ في بيته، ويقدمون له الطعام، والحاجات، وهن أشرف النساء، رضي الله عنهن وأرضاهن. فالواجب على المرأة أن تقوم بالواجب، وأن تخدمه في بيته وأن تقدم له المعتاد من طعام وشراب ولباس، وغير ذلك إلا إذا كان قد استقر في البلد، وعرف في البلد أن مثلها لا يخدم، وإنما يخدم فيما يتعلق بالطبخ، ونحوه؛ فإنه يأتي لها بخادمة إذا تيسر، إذا استطاع ذلك. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11910/حكم-خدمة-الزوجة-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52302.mp3","categories":["الحقوق الزوجية"]},{"id":13725,"question":"في ثاني أسئلتها تقول سماحة الشيخ عبدالعزيز: ما حكم رد سلام المرأة على الرجال الأجانب؟","title":"حكم سلام المرأة وردها على الأجنبي","answer":"الجواب: لا بأس أن ترد السلام وأن تسلم، كان النساء يسلمن على النبي ﷺ ويرد عليهن السلام، من دون أسباب فتنة بالسلام العادي، لا فيه تكسر، ولا تغنج، تسلم سلامًا عاديًا، ويرد عليها لا بأس، كان النساء يسلمن على النبي ﷺ وعلى الصحابة، وكان النبي ﷺ يرد عليهن، لكن مع التستر، والحجاب وعدم الخلوة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12096/حكم-سلام-المراة-وردها-على-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54513.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة","قضايا المرأة"]},{"id":13797,"question":"بعد ذلك ننتقل إلى رسالة بعث بها السائل أخوكم عوض محمود من جمهورية مصر العربية ومقيم في السعودية جدة، يقول: أنا متزوج زوجة وقد أنجبت أربع بنات، وأريد الزواج من امرأة أخرى لكي تنجب لي أولاد ذكور، فماذا تنصحونني؟ جزاكم الله خيرًا.","title":"توجيه لمن يرغب بالزواج بالثانية لإنجاب البنين","answer":"الجواب: هذا طيب، هذا من الأسباب، والتوفيق بيد الله قد تحمل هذه ذكرًا بعد حين، وقد تتزوج امرأة تأتي بذكر وقد تأتي بإناث الأمر بيد الله، إذا تزوجت من باب الأسباب وتسأل ربك أن الله يمنحك ذرية من الذكور طيبة، لا بأس، وهذه التي أتت بأربع قد تأتي بذكور بعد ذلك، ربك على كل شيء قدير، والأمر بيده  ليس بيدها ولا بيدك، تسأل ربك أن الله يسر لك الذرية الطيبة من الذكور والإناث من هذه ومن غيرها. نعم.","link":"https://binbaz.org.sa/fatwas/12168/توجيه-لمن-يرغب-بالزواج-بالثانية-لانجاب-البنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53617.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":13829,"question":"يقول السائل: هل يجوز لي أن أسلم على زوجة عمي أو خالي أو غيرهما من العجائز اللاتي بلغن سن اليأس؟","title":"حكم السلام على النساء","answer":"الجواب: السلام بالكلام لا بأس حتى مع غير العجائز، لك أن تسلم على النساء شبابًا أو عجائز من دون خلوة ومن دون نظر، بل مع غض البصر ومع عدم الخلوة ترد السلام أو تبدأ بالسلام على قريباتك من بنات العم أو بنات الخال أو نحوهن أو زوجة أخيك أو زوجة عمك لا بأس بهذا ولو كانت شابة، ترد السلام أو تبدأ بالسلام، أو تقول: كيف أولادك؟ كيف حال والديك؟ وما أشبه ذلك، لكن لا يجوز مع الخلوة، ولا يجوز مع وجود التكشف والتعري وعدم التستر، بل يجب إذا وجدت شيئًا من هذا أن تنصح، إذا كانت غير متسترة تنصحها وتقول تحجبي، ولا بأس أن تسلم ولا بأس أن تسأل عن حالها لكن تنصحها إذا قصرت في شيء، تأمرها بالحجاب تأمرها بعدم الخلوة بالأجنبي تبين لها الحكم الشرعي. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12195/حكم-السلام-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53006.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق المحمودة","قضايا المرأة"]},{"id":14130,"question":"رسالة وصلت إلى البرنامج من قطر - الدوحة باعثها مستمع من هناك يقول (م. م. ع) مقيم في الدوحة، أخونا له جمع من الأسئلة في أحد أسئلته يقول: هل يجوز للرجل أن يتزوج بامرأتين بدون علم إحداهما، مع إيهامه الثانية أنه غير متزوج؟","title":"حكم الزواج بالثانية دون علم الأولى","answer":"الجواب: هذا فيه تفصيل: يجوز أن يتزوج ثانية وثالثة بدون علم السابقات لا بأس بذلك، إذا كان مثلاً سافر إلى بلد من البلدان وتزوج فيها ويأتي إليها وقت سفره إلى هناك لا بأس بذلك. أما في البلد الواحدة فلا بد من العلم حتى يقسم بينهما وحتى يعدل بينهما، وليس له أن يوهمها أنه لا زوجة له، بل يعلم ويخبرها بأن عنده زوجة؛ لأن هذا من الخداع، فلا بد أن يعلمها أن له زوجة إذا كان في بلد واحد، يقول: نعم. ويقسم لهما جميعًا وينصفهما ويعطيهما حقهما، وليس له الخداع والمكر. أما في بلاد أخرى مثل سافر للدراسة فله أن يتزوج في البلد حتى يعف نفسه ولو ما شاور المرأة ولو ما علم المرأة، لا يضره ذلك ما دام ليس عنده العدد المسموح به وهو أربع بل عنده فرصة، فإذا كان ما عنده إلا واحدة يأخذ ثانية، ما عنده الاثنتين يأخذ ثالثة، عنده ثلاث يأخذ رابعة لا بأس لا يزيد على الأربع.\nالمقصود أنه إذا احتاج إلى ذلك وأراد أن يتزوج ليس من شرط ذلك أن يعلم زوجته إذا كانت في بلد أخرى، لكن مع مراعاة قسم الواجب والعدل في النفقة وغير هذا مما يجب على الزوج من جهة العدالة. نعم، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12569/حكم-الزواج-بالثانية-دون-علم-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61506.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":14159,"question":"السؤال الأخير لأختنا نوارة يقول: هل يجوز للمرأة قصر الصلاة إذا أرادت زيارة بيت والدها الذي يبعد عن بيت زوجها مسافة قصر أم لا؟ وفقكم الله لما يحبه ويرضاه.","title":"حكم القصر للمرأة عند سفرها إلى بيت أبيها","answer":"الجواب: نعم إذا أرادت السفر إلى زيارة أبيها أو غيره في مسافة قصر فإنها تقصر الصلاة، سواء عند أبيها أو عند غير أبيها ما دامت ساكنة في محل آخر عند زوجها، فإذا رجعت إلى أبيها تزوره أو إلى أمها أو إخوتها فإنها تقصر إذا كانت المسافة مسافة قصر، وهي يوم وليلة يعني: بدبيب الأقدام والإبل ونحوها، أما اليوم فهي بمقدار ثمانين كيلو...","link":"https://binbaz.org.sa/fatwas/12600/حكم-القصر-للمراة-عند-سفرها-الى-بيت-ابيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_485/48507.mp3","categories":["الحقوق الزوجية","صلاة المسافر","قضايا المرأة"]},{"id":14388,"question":"هل للرجل الحق في التصرف بمال زوجته مثل الذهب والمجوهرات برغبتها أو بغير رغبتها؟","title":"هل للزوج التصرف في مال زوجته؟","answer":"الجواب: ليس له التصرف في مالها إلا بإذنها، ليس للزوج التصرف في مالها إلا بإذنها؛ لأنها رشيدة، فإذا كانت غير رشيدة فوليها الذي يتصرف؛ أبوها، أو وكيل أبيها، أما الزوج لا، ليس له أن يتصرف، مالها لها. أما حديث: ليس للمرأة عطية إلا من زوجها حديث ضعيف، أو المراد: ليس لها التصرف في ماله هو، أما مالها فلا يتصرف في مالها؛ ولهذا كان النبي ﷺ إذا فرغ من خطبة العيد أتى النساء ووعظهن وذكرهن وأمرهن بالصدقة، وكن يعطين الصدقات، ولم يأمرهن بمشاورة أزواجهن، كان يأخذ منهن الصدقات، ويتقبلها بلال، فدل على أن لهن التصرف في أموالهن إذا كن رشيدات، وليس له منعها من ذلك، وليس له التصرف في مالها بغير إذنها. وفي الصحيح: أن ميمونة قالت: «يا رسول الله، أشعرت أني أعتقت فلانة، قال: أما إنك لو أعطيتها أخوالك لكان أعظم لأجرك ولم يقل لها: ليش تصدقت بها ما شاورتيني؟ قال: إني أعتقتها، فلم يقل: ليش ما شاورتيني؟ دل على أن لها التصرف في مالها، إلا أنه قال: لو أنك وهبتها لأخوالك لكان أعظم لأجرك نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12870/هل-للزوج-التصرف-في-مال-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55211.mp3","categories":["الحقوق الزوجية"]},{"id":14400,"question":"السائل الذي رمز لاسمه بـ (ع. ع) من جمهورية مصر العربية، له مجموعة من الأسئلة، يقول في هذا  هل منع زوجتي عن زيارة بيت والدها يعتبر قطعًا لصلة الرحم؟","title":"حكم منع الرجل زوجته من زيارة أهلها","answer":"الجواب: منعها لا يجوز، لا بد من تنظيم لزيارة، لا تضرك، ولا يحصل بها قطيعة، الواجب تمكينها من زيارة أبيها وإخوتها لصلة الرحم، إلا إذا كانت الزيارة يترتب عليها فساد، إذا كان في بيت أبيها شر، أو أبوها ليس بطيب، زيارتها له تضرها، أو يدعوها إلى منكر فلا بأس أن تمنعها، أما إذا كان أبوها طيبًا وسليمًا، ولا يترتب على زيارتها ما يضرك ولا يضرها فلا تمنعها؛ لأن منعها من قطيعة الرحم، ومن العقوق، فلا ينبغي منك منعها. والمرأة عليها أن تصل أرحامها، وعليك أنت أن تمكنها من ذلك، فبقاؤها لديك وخدمتها لك حسب العرف، ومن عرف المسلمين أن المرأة تزور أباها، وتزور أمها، وتزور أقاربها، فليس لك أن تمنعها إلا إذا كانت الزيارة فيها شر، تضرها في دينها، أو تضرك فلا بأس أن تمنعها إذا كان أبوها فاسقًا تضرها زيارته، أو تضرك زيارته أو أخوها أو عمها، فإذا كان في الزيارة شر عليك أو شر عليها لا بأس أن تمنع، نعم.","link":"https://binbaz.org.sa/fatwas/12882/حكم-منع-الرجل-زوجته-من-زيارة-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55219.mp3","categories":["الحقوق الزوجية","نصائح وتوجيهات"]},{"id":14443,"question":"هذا السائل (ع. ع. م) معهد البريد يقول في هذا  سماحة الشيخ، أنا شخص متزوج وحدث أن ارتكب أحد الأبناء خطأ أثناء تكليفه من قبل والدته بحمل بعض الأغراض للمنزل، وحين تدخلي لمعالجة الموقف حدث بيني وبين والدته شجار، مما جعلني أغضب من تصرفها، فقلت أثناء غضبي ما نصه: لعن الله من أعطاكِ، أو لعن الله من أعطاكْ، وقد ندمت على ذلك ندمًا شديدًا، وأنا لست ممن يستعمل هذه الكلمة الخاطئة والخاصة بالشيطان، ولا حتى مع أولادي ولا مع زوجتي، ولكن لحظة أفقدتني فيها غضبي، فقلت هذا الكلام، فهل علي إثم في علاقتي الزوجية بزوجتي من الناحية الشرعية؟جزاكم الله خيرًا.","title":"حكم نكاح من قال لزوجته: لعن الله من أعطاك","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أن هذا الكلام منكر من القول ومعصية كبيرة، فالواجب عليك التوبة إلى الله منها؛ لأنها سب وشتم لا يليق منك، وقولك: لعن الله من أعطاك هذا خطره عظيم؛ لأن هذا قد يعود إلى الله الذي أعطى، هذا منكر شنيع، وإذا قصدت بذلك الرب فهذه ردة عن الإسلام، فالواجب عليك التوبة إلى الله، ومن تاب تاب الله عليه، عليك التوبة والندم والإقلاع والعزم ألا تعود في ذلك، وعليك الاستكثار من العمل الصالح وأبشر بالخير -إن شاء الله- من تاب تاب الله عليه، يقول الله سبحانه: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53] ويقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] فمن تاب أفلح، فعليك التوبة إلى الله والندم والإقلاع والاستكثار من العمل الصالح وأبشر بالخير -إن شاء الله-. وزوجتك معك ولا يضر ذلك من جهة النكاح، فقد قال الله سبحانه فيمن أشرك وفيمن قتل ولده أو زنى، قال -جل وعلا-: وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:68-69] يعني: المشرك والقاتل والزاني، ثم قال: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا [الفرقان:70] فنسأل الله أن يمن عليك وعلى كل مسلم بالتوبة، ونسأل الله أن يعيذك من العود إلى مثله، نعم.\nالمقدم: سماحة الشيخ، هذا السائل يقول: عندما قلت: لعن الله من أعطاك، يعني: ابنه، يعني الزوجة؟\nالشيخ: على كل حال هو منكر سواء قصد الزوجة أو ما قصد الزوجة، هو منكر، فعليه التوبة إلى الله من ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12907/حكم-نكاح-من-قال-لزوجته-لعن-الله-من-اعطاك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55401.mp3","categories":["الأخلاق المذمومة","الحقوق الزوجية"]},{"id":14504,"question":"هذا سؤال من السائلة مسلمة من العراق، محافظة ديالي، تقول: أنا امرأة متزوجة، ولي أربعة أطفال، وقد تزوج زوجي امرأة ثانية، ولها أطفال أيضًا، والمشكلة أنه لا يعدل في معاملته بيننا، فقد انصرف عني كليًا حتى كأنه لا وجود لي في البيت، وأطفالي يدرسون ويحتاجون إلى مصاريف الدراسة، ولكنه لا يعطيهم، وأنا لا أستطيع أن أطلب منه، وللعلم فنحن نسكن والزوجة الثانية في نفس المسكن، وأخشى على أطفالي من الضياع من هجره للجميع وعدم اهتمامه، فما رأيكم في هذا؟","title":"حكم هجر الزوجة الأولى وترك النفقة عليها وعلى أبنائها","answer":"الجواب: الواجب عليه تقوى الله، الواجب على الزوج أن يتقي الله، وأن يعدل، وقد قال النبي ﷺ: من كان له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالعدل واجب في النفقة بينهما والمساواة بينهما في القسمة، فإذا جار على السائلة هذا عليه إثم في ذلك، إلا إذا كان خيّرها بين الطلاق وبين الصبر فلا حرج عليه، إذا خيّرها واختارت البقاء معه على ظلمه، وعدم عدله فلا بأس عليه إذا خيّرها، أما أنه يمنع الطلاق، ويمنع العدل، فهذا لا يجوز له. أما أولاده فعليه نفقتهم، والواجب عليه مطلقًا طلق أو لم يطلق، عليه أن يعدل في أولاده، ويحسن إليهم، ويقوم بحاجاتهم حسب طاقته، وإذا استطاعت أن تأخذ من ماله شيئًا لحاجتها فلا بأس، إذا كان لديه مال واستطاعت السائلة أن تأخذ من ماله شيئًا بغير علمه قدر حاجتها بالمعروف لأولادها ولها فلا حرج، فقد ثبت عن النبي ﷺ أنه رخص لامرأة أبي سفيان أن تأخذ من ماله بالمعروف ما يكفيها ويكفي بنيها، فإذا وجدت له مالًا تستطيع أن تأخذ منه شيئًا لها ولأولادها بغير علمه بالمعروف، من غير تبذير، ومن غير إسراف فلا حرج في ذلك -إن شاء الله-، وإن لم تستطع فينبغي لها أن تتصل بأقاربه وإخوانه والذين يعزهم ويقدرهم حتى ينصحوه، وحتى يشيروا عليه؛ لعله يهتدي، ولعله يقوم بالواجب.  وينبغي لها أن تكثر من سؤال الله له الهداية، حتى يوفق للعدل، وإن كان هناك حاكم شرعي في الأحوال الشخصية يمكن أن ترفع الأمر إليه، فلا مانع من أن ترفع إليه حتى يلزمه بالعدل.\nولكن مهما أمكن أن يكون ذلك من طريق المصلحين، من أقاربه وجيرانه والناس الذين يعزهم فهو أولى، الإصلاح بينهم، بينها وبينه من طريق الإخوان الطيبين حتى ينفق وحتى يعدل، هذا أولى من الشكوى وأحوط وأقرب إلى السلامة، نسأل الله للجميع الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12999/حكم-هجر-الزوجة-الاولى-وترك-النفقة-عليها-وعلى-ابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_633/nour_63304.mp3","categories":["قضايا المرأة","النفقات","الحقوق الزوجية"]},{"id":14511,"question":"هذا سؤال من السائلة مسلمة من العراق، محافظة ديالي، تقول: أنا امرأة متزوجة، ولي أربعة أطفال، وقد تزوج زوجي امرأة ثانية، ولها أطفال أيضًا، والمشكلة أنه لا يعدل في معاملته بيننا، فقد انصرف عني كليًا حتى كأنه لا وجود لي في البيت، وأطفالي يدرسون ويحتاجون إلى مصاريف الدراسة، ولكنه لا يعطيهم، وأنا لا أستطيع أن أطلب منه، وللعلم فنحن نسكن والزوجة الثانية في نفس المسكن، وأخشى على أطفالي من الضياع من هجره للجميع وعدم اهتمامه، فما رأيكم في هذا؟","title":"حكم هجر الزوجة الأولى وترك النفقة عليها وعلى أبنائها","answer":"الجواب: الواجب عليه تقوى الله، الواجب على الزوج أن يتقي الله، وأن يعدل، وقد قال النبي ﷺ: من كان له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالعدل واجب في النفقة بينهما والمساواة بينهما في القسمة، فإذا جار على السائلة هذا عليه إثم في ذلك، إلا إذا كان خيّرها بين الطلاق وبين الصبر فلا حرج عليه، إذا خيّرها واختارت البقاء معه على ظلمه، وعدم عدله فلا بأس عليه إذا خيّرها، أما أنه يمنع الطلاق، ويمنع العدل، فهذا لا يجوز له. أما أولاده فعليه نفقتهم، والواجب عليه مطلقًا طلق أو لم يطلق، عليه أن يعدل في أولاده، ويحسن إليهم، ويقوم بحاجاتهم حسب طاقته، وإذا استطاعت أن تأخذ من ماله شيئًا لحاجتها فلا بأس، إذا كان لديه مال واستطاعت السائلة أن تأخذ من ماله شيئًا بغير علمه قدر حاجتها بالمعروف لأولادها ولها فلا حرج، فقد ثبت عن النبي ﷺ أنه رخص لامرأة أبي سفيان أن تأخذ من ماله بالمعروف ما يكفيها ويكفي بنيها، فإذا وجدت له مالًا تستطيع أن تأخذ منه شيئًا لها ولأولادها بغير علمه بالمعروف، من غير تبذير، ومن غير إسراف فلا حرج في ذلك -إن شاء الله-، وإن لم تستطع فينبغي لها أن تتصل بأقاربه وإخوانه والذين يعزهم ويقدرهم حتى ينصحوه، وحتى يشيروا عليه؛ لعله يهتدي، ولعله يقوم بالواجب.  وينبغي لها أن تكثر من سؤال الله له الهداية، حتى يوفق للعدل، وإن كان هناك حاكم شرعي في الأحوال الشخصية يمكن أن ترفع الأمر إليه، فلا مانع من أن ترفع إليه حتى يلزمه بالعدل.\nولكن مهما أمكن أن يكون ذلك من طريق المصلحين، من أقاربه وجيرانه والناس الذين يعزهم فهو أولى، الإصلاح بينهم، بينها وبينه من طريق الإخوان الطيبين حتى ينفق وحتى يعدل، هذا أولى من الشكوى وأحوط وأقرب إلى السلامة، نسأل الله للجميع الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12999/حكم-هجر-الزوجة-الاولى-وترك-النفقة-عليها-وعلى-ابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_633/nour_63304.mp3","categories":["قضايا المرأة","النفقات","الحقوق الزوجية"]},{"id":14557,"question":"هذه أختكم في الله (ح. م. ح) كتبت مجموعة من الأسئلة بأسلوبها الخاص تقول سماحة الشيخ: امرأة متزوجة برجل لا يوفر لها، ولا لأولادها أبسط أسباب المعيشة، فهو يعمل يومًا، ويستريح أسبوعًا، وأصبح الأولاد كأنهم أيتام، يتصدق عليهم الجيران، ومن يرى من حالتهم يعطف عليهم، ويقدم لهم الصدقة، تقول: هي تنصحه وتطالبه بسد حاجات البيت والأولاد، ولكن لا حياة لمن تنادي، فأصبحت هي وهو في شجار دائم، فتذكر أيضًا يا سماحة الشيخ بأنها تقول: بأنني لا أقوم بخدمته هل أأثم في ذلك؟ وهل أسأل عن تعاملي معه أمام الله ؟","title":"حكم ترك خدمة الزوج المقصر في النفقة","answer":"الجواب: أيها السائلة أنت بالخيار إن صبرت فلا بأس، وإن لم تصبري فارفعي الأمر للمحكمة، لك أن تطلبي الطلاق؛ لأنه لا يقوم بالواجب، وإن صبرت وتعاونت معه فلا بأس عليك، ولا يلزمك طاعته فيما لا تستطيعين، كأوقات طلب الرزق لأولادك، وأما في الأوقات التي تستطيعين فاستجيبي له في حاجاته، وإذا طلبك في وقت لا تستطيعين الإجابة فأنت معذورة، والله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فعليك طاعته فيما تستطيعين، ولا حرج عليك فيما لا تستطيعين، كوقت طلب الرزق لأولادك ولنفسك؛ لأنه لا يقوم بالنفقة، والأوقات الأخرى التي يمنعك مرض أو عذر شرعي كالحيض، أو ما أشبه ذلك. المقصود: عليك طاعته حسب الطاقة، فيما أباح الله وشرع الله، ولك طلب الفرقة، وطلب الطلاق عند المحكمة؛ لأنه لم يقم بالواجب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13053/حكم-ترك-خدمة-الزوج-المقصر-في-النفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55516.mp3","categories":["الحقوق الزوجية","النفقات"]},{"id":14718,"question":"السائلة (م. ش) من الزبداني، تقول سماحة الشيخ: إذا طلبت من زوجي أن أذهب إلى أختي، أو إلى خالتي يقول لي: ليس لك صلة رحم، هل هذا صحيح؟ وهل للزوج أن يمنع زوجته من زيارة أقاربها؟","title":"هل للزوج منع زوجته من زيارة أقارها؟","answer":"الجواب: هذا غلط، صلة الرحم واجبة بالكلام الطيب، وبالنفقة إذا كان القريب فقيرًا، وأنت غني تساعده، وتحسن إليه، هذا واجب، صلة الرحم واجبة، وقطيعتها محرمة، ولا يجوز للزوج أن يعين على قطيعة الرحم، ولا أن يأمر بقطيعة الرحم، بل يجب عليه أن يساعد على الخير، ولكن لا تخرجي إلا بإذنه، بالكلام الطيب، والأسلوب الحسن، حتى يأذن، وليس له أن يمنعك من صلة الرحم، لا بالمال، ولا بالزيارة إلا إذا كانت الزيارة فيها شرًا، إذا كانت الرحم رحمًا فيها خبث، عندهم المعاصي، له أن يمنعك من زيارتهم، إذا كان عندهم الشر والمعاصي، ويخشى أن تضرك الزيارة.  أما إذا كانوا أهل خير واستقامة فليس له منعك على الوجه المعتاد المعروف الذي ما فيه مضرة عليه، كأن تزوري أختك أو خالتك أو عمتك أو جدتك أو ما أشبه ذلك من أرحامك أو خالك أو أخاك أو ما أشبه ذلك، لكن على الوجه الذي لا يضر الزوج، وإذا منعك فلا تخرجي إلا بإذنه بالأسلوب الحسن، والكلام الطيب، ولا تعجلي، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13198/هل-للزوج-منع-زوجته-من-زيارة-اقارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56023.mp3","categories":["الحقوق الزوجية","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":14752,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (م. ح. أ) من أبها، أخونا رسالته مطولة بعض الشيء، سأقرأها كما وردت يقول:تحية طيبة، وبعد:أبعث إليكم بمشكلتي طالبًا الإفتاء فيها، وجزاكم الله خيرًا، أنا مصري أعمل في المملكة العربية السعودية منذ عام تقريبًا، وكنت قبل أن أحضر عقدت قراني على زوجتي بمصر، وبعد وصولي أرسلت إليها لتحضر إلى هنا، لنعيش هنا، ونبدأ حياتنا الزوجية هنا، فوافقت هي وأسرتها، وأرسلت إليها مهرها كاملًا، كما هو في العقد، وقمت بإعداد شقتي الزوجية، وحضرت إلى هنا وتزوجنا، وبعد شهر ونصف من الزواج بدأت أعراض الحمل، فأصرت على أن ترجع إلى أهلها لتقضي فترة الحمل فرفضت ذلك، وقلت لها: إنني مستعد بخدمتك بكافة ما أملك، وعرضتها بالفعل على طبيبة مختصة كانت تعالجها، وتتابع حالتها، ولكنها رفضت إلا العودة إلى أهلها، وليكن ما يكن، كانت تقول: إذا أردت تطلقني طلقني، وإن أردت أن ألا ترسل لي فلوسًا فلا ترسل، وثمن تذكرة العودة سأرسله من مهري، ولكن لازم أسافر، واستعملت معها أسلوب الترغيب والترهيب، ولكنها أصرت على ذلك، حتى انقلب البيت جحيمًا، وفي النهاية حجزت لها تذكرة وسافرت إلى أهلها، والآن أريد أن أسأل عدة أسئلة -عرض عشرة أسئلة سماحة الشيخ- يقول في سؤاله الأول: هل تعتبر هذه الزوجة ناشزًا؟ وهل يحق لها النفقة -نظرًا لأنها حامل-؛ لأنني غير راض عن سفرها، وحاولت منعها، ولم أستطع؟هذا سؤاله الأول.","title":"حكم النفقة على الناشز وما لها من حقوق إذا طلقت؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذه المرأة إذا كان الواقع كما ذكره السائل تعتبر ناشزًا، وليس لها نفقة؛ لكونها إنما سافرت عن غير رضاك، وعن غير اختيارك، بل بأسباب إلحاحها وإيذائها لك كما ذكرت في السؤال، وليس لها نفقة، بعض أهل العلم يرى أن لها نفقة من جهة الحمل، ولكن الصواب أنها ما دامت بهذه الحال فلا نفقة لها أيضًا، حتى ولو كانت حاملًا، نعم. المقدم: جزاكم الله خيراً.\nالمقدم: هل إذا طلقتها أكون قد ظلمتها؟\nالشيخ: ليس في طلاقها بأس، ولكن نوصيك بعدم الطلاق، ولا تعجل في الطلاق إذا كانت طيبة في دينها؛ لأنها قد تكون ساءت أخلاقها بسبب الحمل والتوحم الذي يصيب الحامل، فلا تعجل في الطلاق إذا كانت طيبة في دينها في صلاتها في أخلاقها في سرها لا تعجل بالطلاق، ولعل الله أن يهديها، ويصلح حالها بعد ذلك، فإن طلقتها طلقة واحدة فلا بأس.  أما الطلاق بالثلاث فلا يجوز، إنما إذا أردت الطلاق تكون طلقة واحدة فقط، ونوصيك بعدم العجلة، وعدم الطلاق مطلقًا. المقدم: جزاكم الله خيرًا. إذا طلقتها ما هي حقوقها المالية التي تجب لها علي؟\nالشيخ: إذا طلقتها فعليك نفقة العدة إذا وافقت على المجيء، ولكن أنت لا تريدها، أما إذا كانت على إصرارها وعدم رضاها بالعودة واستمرارها في النشوز، فليس عليك نفقة حتى ولو بعد الطلقة، لكن إذا طلقتها وأرادت العودة إليك، ورجعت عن رأيها الأول فعليك نفقة العدة إلى أن تضع حملها، ثم عليك نفقة الحمل بعد الوضع، نعم. المقدم: هل يحق لي أن أعتبر ثمن تذكرة العودة نفقة لها لعدة أشهر، وتكاليف السفر تصل إلى ألف ريال تقريبًا؟\nالشيخ: ما دمت تبرعت لها بالتذكرة فليس لك العودة في ذلك، نعم. المقدم: إذا أرسلت لها خطاب أبلغتها فيه طلاقها يكون الطلاق صحيحًا؟ الشيخ: ينبغي لك أن تثبته عند المحكمة، أو كاتب بالعدل، أو مأذون شرعي يصدق عليه من جهة المحكمة حتى يعتبر، حتى يعتمد عليه هناك، نعم.","link":"https://binbaz.org.sa/fatwas/13239/حكم-النفقة-على-الناشز-وما-لها-من-حقوق-اذا-طلقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63001.mp3","categories":["الحقوق الزوجية"]},{"id":14793,"question":"هل من كلمة للأزواج في معاملة الزوجات يا سماحة الشيخ؟","title":"نصيحة في حسن تعامل الزوج مع زوجته","answer":"الجواب: نعم، نصيحتي للأزواج أن يتقوا الله، نصيحتي لجميع الأزواج أن يتقوا الله في نسائهم، وأن يعاملوهن باللطف، والمعاملة الطيبة، كما قال الله -جل وعلا-: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] بالكلام الطيب، بالأسلوب الحسن، بالحلم، بالخلق الكريم، بأداء حقوقهن كاملة، هذا الواجب على جميع الأزواج، الله يقول: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] مثل ما أنك تحب أن تعاشر بالمعروف، وأن تكون طيبة معك في أخلاقها وسيرتها أنت كذلك، الله يقول: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] كون حقك أكبر لك درجة زيادة لا يقتضي، هذه الدرجة ما تقتضي أنك تسيء إليها، وأنك تظلمها لا، يجب عليك أن تحسن الخلق، وأن تعاشر بالمعروف، وأن تقوم بالواجب، من جهة النفقة اللازمة بالمعروف، ومن جهة طيب الكلام، وحسن المخاطبة، هذا هو الواجب على الأزواج جميعًا أن يتقوا الله، وأن يحسنوا إلى أزواجهم بالكلام الطيب، والأسلوب الحسن، والسيرة الحميدة، وعدم السهر، وعدم التقتير في النفقة، كل هذا واجب. عليك أن تنفق بالمعروف، وعليك أن تحذر السهر الذي يضر زوجتك ويضرك، ويسبب أيضًا فساد دينك، فإن السهر شره عظيم، قد تضيع معه صلاة الفريضة، قد يكون مع أناس من أهل الشر يضرونك ويجرونك إلى أنواع الفساد، فاحذر. الرسول ﷺ نهى عن السمر بعد العشاء، فالسنة أن تأتي إلى بيتك بعد العشاء، وأن تنام مع أهلك، تستريح في بيتك، تدع السهر بعد العشاء. ويجب على الرجل أن يحذر صحبة الأشرار، صحبة الأشرار شرها عظيم، فالواجب الحذر من صحبة الأشرار، والواجب العناية بصحبة الأخيار، وعدم السهر، والعناية بالصلوات الخمس، والمحافظة عليها في الجماعة، وحسن الخلق مع الزوجة، وطيب الكلام مع الزوجة، هكذا، كما قال ﷺ: خياركم خياركم لنسائهم والله يقول وهو أعظم: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] ويقول سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13285/نصيحة-في-حسن-تعامل-الزوج-مع-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56116.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":14796,"question":"سماحة الشيخ، يقول السائل من ليبيا: ما حكم الإسلام في طول فترة الزواج، أي من يوم السبت إلى يوم الأحد من الأسبوع الثاني. علمًا بأن هذه المدة من العادات والتقاليد عندنا، وما حكم الغناء في الأفراح، واستعمال الطبول؟جزاكم الله خيرًا.","title":"مدة بقاء الزوج عند زوجته أيام العرس","answer":"الجواب: إذا تزوج امرأة وليس عنده غيرها يقيم عندها دائمًا الحمد لله، يبيت عندها دائمًا، لها ليلة من أربع، ويوم من أربعة أيام، أما إذا كان نكحها على غيرها، فهذا بيّن النبي ﷺ حكمه، إذا تزوج امرأة على امرأة إن كانت المرأة المتزوجة بكرًا أقام عندها سبعًا، خصها بسبع ليال، ثم يدور، كل واحدة لها ليلة بعد السبع، وإن كانت الزوجة الجديدة ليست بكرًا، بل ثيبًا، أقام عندها ثلاثًا، يخصها بثلاث، ثم يدور بينهما، كل واحدة يعطيها ليلة، ويعدل بينهن، هذا إذا كان عنده زوجة، ونكح زوجة أخرى، فإنه إن كانت بكرًا جديدة أقام عندها يعني: خصها بسبع ليالٍ، ثم يقسم بينهما، وإن كانت الزوجة الجديدة ثيبًا قد تزوجت قبله خصها بثلاث ليالي، أول ما يتزوجها، ثم يدور، ليلة عند هذه وليلة عند هذه، يعدل، والنهار كذلك يعدل بينهما. أما إن كان ما عنده إلا هي فهو عندها في جميع الليالي والأيام، الحمد لله، نعم. المقدم: الحمد لله، أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13290/مدة-بقاء-الزوج-عند-زوجته-ايام-العرس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56119.mp3","categories":["الحقوق الزوجية"]},{"id":14900,"question":"هذا السائل مصري، ومقيم في الزلفي، رمز لاسمه: بـ (ع. أ. ع) يقول: سماحة الشيخ، صديق لي يسأل عن حكم رجل متزوج، ويميل إلى الزوجة الثانية على الرغم من موافقة الزوجة الأولى، مع مراعاة أيضًا الزوجة الأولى، فما الحكم في ذلك؟مأجورين.","title":"ما حكم الميل إلى إحدى الزوجات برضى الباقيات؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالواجب على الزوج أن يعدل بين الزوجتين، أو الثلاث أو الأربع، هذا الواجب عليه، لكن إذا أخص إحداهن بشيء برضا الباقيات، فلا بأس إذا رضين، ولكن العدل بينهن واجب في قسمه، في ليله ونهاره، فالواجب عليه أن يعدل، وفي النفقة كذلك، إلا إذا كانت إحداهن عندها أولاد كل ينفق عليه بقدر ما عنده من الأولاد، فإن العدل أمر لازم، يقول النبي ﷺ لما أخبر عن حاله مع نسائه: اللهم إنه كان يقسم، فيعدل، ويقول: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك ويقول ﷺ: من كانت له زوجتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالواجب العدل والتحري في قسمه وفي غير ذلك، إلا ما يتعلق بالقلوب فهذا إلى الله، كونه يجامع هذه أكثر، أو يحصل له أنس مع هذه أكثر هذا يتعلق بالقلوب ما له قدرة، لكن في القسم والنفقة، هذا يجب عليه أن يعدل. أما في الحب والجماع فلا يجب فيه العدل، بل على حسب ما يتيسر من شهوته، وإذا كان لإحداهن أطفال والأخرى ليس لها أطفال ينفق على هذه بقدر أطفالها، وهذه بقدر حاجتها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13399/ما-حكم-الميل-الى-احدى-الزوجات-برضى-الباقيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56201.mp3","categories":["الحقوق الزوجية"]},{"id":14902,"question":"يقول في آخر أسئلته: زوجتي موظفة، هل من حقي أن آخذ من راتبها إذا كنت في حاجة إليه، أو جزء منه، وإذا كنت غير مستفيد من راتبها، هل أجعلها لا تعمل وتجلس في البيت؟","title":"حكم الأخذ من راتب الزوجة ومنعها من العمل","answer":"الجواب: إن كانت قد شرطت عليك عند الزواج أنها تعمل، والراتب لها، فليس لك حق في ذلك.  أما إن كانت لم تشرط عليك فلك أن تمنعها، ولك أن تتفق معها على نصف الراتب، أو أقل أو أكثر؛ لأنك أحق بها، وأولى بها في بقائها في بيتك، والقيام بحاجاتك، إذا كانت لم تشترط عليك عند العقد أن تقوم بالتدريس، فلك الحق أن تمنع، ولك الحق أن تأذن، وإذا اتفقتما على شيء فالصلح جائز بينكما، نصف الراتب أو ثلث الراتب، أو كل الراتب، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/13401/حكم-الاخذ-من-راتب-الزوجة-ومنعها-من-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56203.mp3","categories":["الحقوق الزوجية"]},{"id":14944,"question":"وهذه رسالة المستمع (س. ق. ع) يقول: رجل أراد السفر لطلب العلم، وله أهل من الزوجة والأولاد، وشاور مع زوجته في طلاقها، وعدم نفقتها، وقالت: لا تطلقني، وقد عفوت عن نفقتي وخلافه، فهل تبقى بدون نفقة ولا يضره شيء أم لا؟","title":"حكم تنازل المرأة عن النفقة مقابل عدم طلاقها","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالحق للمرأة لا لغيرها، فإذا سمحت عن نفقتها فلا حرج، ويجوز للزوج إبقاؤها في عصمته من دون أن ينفق عليها إذا سمحت، ومتى عادت وطلبت النفقة فإنه يخير، إما أن ينفق، وإما أن يطلق، نعم.","link":"https://binbaz.org.sa/fatwas/13440/حكم-تنازل-المراة-عن-النفقة-مقابل-عدم-طلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_649/nour_64901.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":15073,"question":"في آخر أسئلة هذه السائلة تقول: سماحة الشيخ، هل يجوز للمرأة أن تمتنع عن زوجها إذا كان سهرها معه يسبب في تركه لصلاة الفجر؟ هل يجوز للمرأة أن تمنعه من نفسها؟","title":"هل تمتنع من زوجها إذا كان سهره يضيع صلاة الفجر؟","answer":"الجواب: عليها أن تنصحه، وأن تحل المشكلة بالكلام الطيب، حتى يزول المحذور، إما بتأجيل حاجته إليها بعد الفجر، أو بتقديم ذلك في أول الليل؛ حتى لا يكون ذلك سببًا للسهر، وإضاعة صلاة الفجر، تحل المشكل بالكلام الطيب، والأسلوب الحسن، لا بالامتناع، تعالج الموضوع حتى يحصل المطلوب من دون إضاعة صلاة الفجر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13567/هل-تمتنع-من-زوجها-اذا-كان-سهره-يضيع-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56405.mp3","categories":["الحقوق الزوجية","قضايا المرأة"]},{"id":15088,"question":"أيضًا يقول أحمد محمود من السودان: هل يجوز للزوج الكذب على زوجته في بعض الأمور الزوجية، والتي يرى فيها صلاح لحياته الزوجية؟","title":"ما حكم كذب الرجل على امرأته والعكس؟","answer":"الجواب: لا حرج في أن يكذب الرجل على زوجته في أشياء تنفعهما جميعًا، فيكون فيها خير للجميع، ولا يتعدى ضررها على أحد، لا بأس بذلك، وهكذا الزوجة لها أن تكذب على زوجها، فيما يزيد المحبة، ويصفي الجو بينهما، كل ذلك لا حرج فيه، إذا كان الكذب من أحدهما على الآخر لا يضر أحدًا من الناس، وإنما يختص بهما، ومصالحهما، فلا بأس بذلك. وقد ثبت عن النبي ﷺ أنه رخص في الكذب بين الزوجين فيما بينهما، قالت أم كلثوم -رضي الله عنها- بنت عقبة بن أبي معيط \"لم أسمع النبي يرخص -عليه الصلاة والسلام- في شيء من الكذب إلا في ثلاث: في الحرب، والإصلاح بين الناس، وحديث الرجل امرأته، والمرأة زوجها\" فهذه الثلاث لا حرج في الكذب في الإصلاح بين الناس، وفي الحرب، وفيما يتعلق بحديث الرجل مع امرأته، والمرأة مع زوجها، فيما يصلح شأنهما، نعم.","link":"https://binbaz.org.sa/fatwas/13580/ما-حكم-كذب-الرجل-على-امراته-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_655/nour_65502.mp3","categories":["الحقوق الزوجية"]},{"id":15131,"question":"وردتنا رسالة من بيشة، بعث بها المرسل يحيى سعد مخيلي الشهراني، يقول: تزوجت فتاة، وكان عمرها سبعة عشر سنة، ثم بقيت عند أهلها سبعة عشر سنة أخرى، وأنا لم أدخل بها، وأنها تحبني وأحبها، ولكن أهلها منعوها من الزواج الفعلي، أي: الدخول بالمعنى المعروف، وأخيرًا طلقتها، ثم خطبت زوجة أخرى، وحصل معها ما حصل مع الأولى، فهل أطلقها؟ أم أن هناك رأيًا للشرع آخر؟علمًا بأنني متزوج من امرأة، وعندي منها أطفال، وأنا أرغب في الزواج من الثانية، وفقكم الله.","title":"حكم منع الولي موليته من الدخول على زوجها بعد العقد","answer":"الجواب: الواجب على أولياء الزوجة أولياء المرأة وأهلها من أم وأخت وخالة ونحو ذلك، أن يساعدوا على الخير، وأن يشجعوا على الجمع بين الرجل وأهله، وأن لا يعطلوا المرأة عن زوجها، لا قبل العقد، ولا بعد العقد.  فإذا تم العقد فالواجب البدار بإدخالها على زوجها، وتمكينه منها؛ حتى يحصل المقصود بالنكاح من قضاء الوطر، وعفة الفرج، وغض البصر، ووجود النسل والذرية للجميع، هذا هو الواجب، ولا يجوز لأمها ولا لأبيها ولا لأوليائها تعطيلها من الزواج، ولا تعطيلها من دخولها على زوجها بعد العقد، هذا هو الواجب عليهم. وكثير من الناس -والعياذ بالله- لا يبالي بموليته، ولا يهتم منها، بل يعطلها كثيرًا؛ إما لخدمتها في بيته، وإما لرعيها غنمه، وإما لغضبه على أمها، أو غضبه عليها لأسباب صار ذلك؛ فيظلمها، ويتعدى عليها، ويحبسها عن الزواج لما في نفسه من الشر عليها، أو على أمها، أو على إخوتها الخاصين بها، أو نحو ذلك، وهذا ظلم وعدوان لا يجوز، بل الواجب عليه أن يتقي الله، وأن يبادر بتزويج موليته، سواء كان أخاها، أو أباها أو عمها، وأن لا يعطلها، ثم إذا تم العقد فالواجب أيضًا أن لا يعطلها، بل عليه -الولي- أن يبادر بإدخالها على زوجها، أو إدخاله عليها إن كان الدخول عليها في بيتهم، أما التعطيل فهو منكر، وهذا واقع في كثير من الناس، يعطلون بناتهم وأخواتهم لأسباب خبيثة ظالمة، إما لتخدم بيته، وتخدم زوجته، أو لتخدمه في رعي غنمه، أو لأسباب أخرى، وهذا لا شك أنه منكر وحرام عليه، وإثم وظلم. وبعد العقد كذلك لا يجوز تعطيلها أيضًا، بل يجب البدار بإدخالها على زوجها، وتمكينه منها، حتى يحصل المقصود من النكاح، والله يقول -جل وعلا-: وَمَنْ يَظْلِمْ مِنْكُمْ نُذِقْهُ عَذَابًا كَبِيرًا [الفرقان:19] فالظلم قبيح، وشره عظيم، ويقول ﷺ: اتقوا الظلم، فإن الظلم ظلمات يوم القيامة وحبس النساء عن الزواج -سواء كن بنات أو أخوات أو غيرهن- ظلم وعدوان، وهكذا حبسهن بعد العقد، وعدم إدخالهن على أزواجهن ظلم وعدوان.  فأرجو ممن يسمع كلامي هذا أن يبلغه غيره، وأن ينصح من يعلم منه هذا العمل الخبيث هذا المنكر؛ فينصحه لله، ويحرضه على تزويج موليته، وعدم حبسها ظلمًا وعدوانًا. وعلى ولاة الأمور إذا علموا ذلك أن يعاقبوا من فعل هذا، على القضاة والأمراء وولاة الأمور جميعًا عليهم أن يعاقبوا من عرف بهذا الظلم لموليته؛ فإنه يستحق العقاب ردعًا له ولأمثاله عن هذا الظلم، والقاضي أخص بهذا؛ فإنه يعلم من هذه الأمور ما لا يعلمه غيره، فالواجب على القضاة أن يهتموا بهذا، وأن يحكموا بتعزير وتأديب من يعرف بهذا الأمر رجاء السلامة من هذا الظلم لهؤلاء النساء، نعم، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13632/حكم-منع-الولي-موليته-من-الدخول-على-زوجها-بعد-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_657/nour_65704.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":15361,"question":"السائل أبو معاوية الأردن، عمان، يقول في هذا  سماحة الشيخ الراتب التي تأخذه الزوجة إذا كانت موظفة، هل هو من حقها لوحدها، أم للزوج فيه نصيب؟ بمعنى: إذا كان يترتب على عملها أن يتنازل الزوج عن بعض حقوقه؟فوجهونا بهذا السؤال.","title":"حكم أخذ الزوج من راتب زوجته","answer":"الجواب: الحكم في هذا على ما اتفقا عليه إذا اتفقا على أن النصف للزوج أو الربع أو الثلث أو أقل أو أكثر فلا بأس المسلمون على شروطهم، والصلح جائز بين المسلمين إلا صلحًا حرم حلالًا، أو أحل حرامًا فإذا اتفق معها أنها تعمل موظفة مدرسة، أو ممرضة، أو طبيبة، واتفق معها على أن له النصف أو الثلث أو الربع أو الراتب كله، فلا بأس، الحق لا يعدوهما. أما إن كان مشروطًا في العقد شرط، اشترطت عليه في العقد أن راتبها لها، وأنه يقدم على أنها موظفة، مدرسة، ممرضة، طبيبة أو غير ذلك، وأن راتبها لها، إذا شرط عليه هذا فإنه لا حظ له فيه، لا حق له، إلا بشيء تسمح به، لقوله ﷺ: المسلمون على شروطهم لكن إن سمحت بشيء فلا بأس؛ لقول الله سبحانه: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4] إذا طابت نفسها بشيء من راتبها قليل أو كثير فلا بأس، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13864/حكم-اخذ-الزوج-من-راتب-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49904.mp3","categories":["الحقوق الزوجية","الشروط والعيوب في النكاح","قضايا المرأة"]},{"id":15373,"question":"سماحة الشيخ، هذه أختنا (م. ن. هـ) من الرياض، كتبت الحقيقة رسالة بأسلوبها الخاص، وتذكر بأنها زوجة لديها سبعة من الأولاد وبنت، زوجها تزوج عليها، تقول: لقد استشارها في ذلك، ووافقت فقط أن يعدل بينها وبين ضرتها، وتزوج، ولكنه -تقول- خان العهد الذي بيننا وهو العدل؛ لذلك فإنه لا يسأل عن أولاده، ولا يرد السلام عندما أسلم عليه، ويهددني دائمًا بالطلاق، ويميل إلى زوجته الأخرى في جميع أمورها. سماحة الشيخ تقول: هل يجب علي الصبر في ذلك، أم أشتكيه إلى الشرع أو إلى المحكمة؟مأجورين.","title":"حكم من يميل إلى زوجته الأخرى","answer":"الجواب: الواجب عليه أن يعدل، وأن يتقي الله سبحانه، هذا هو الواجب عليه، أن يعدل بينكما في القسم، وغيره، هذا الواجب عليه، فإن لم يعدل فأنت بالخيار إن شئت صبرت وسامحتيه، وإن شئت طلبت الطلاق، قولي: طلقني أو اعدل، فإذا أبى ارفعي الأمر إلى المحكمة، إما أن يعدل، وإما أن يطلق، إلا أن ترضي وتصبري، فلا بأس.  فإذا لم يعدل، ولم يطلق، فلك أن ترفعي إلى المحكمة أنت أو وليك إلى المحكمة؛ ليلزمه بالطلاق أو بالعدل، نسأل الله للجميع الهداية. المقدم: اللهم آمين، سماحة الشيخ، ميل كثير من الأزواج بعد أن يعددوا هل من كلمة توجيهية لهؤلاء؟\nالشيخ: الواجب على من كان عنده زوجتان أو ثلاث أو أربع، الواجب عليه أن يعدل في القسم وغيره، هذا هو الواجب؛ لأن الله أوجب العدل على الأزواج، وكان النبي ﷺ كان يقسم بين أزواجه ويعدل، ويقول: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك كان يقسم بين نسائه ويعدل، وهو خير الناس وأفضلهم -عليه الصلاة والسلام-. فالواجب على من كان عنده زوجتان أو ثلاث أو أربع أن يعدل بينهن، وكذلك في النفقة إلا إذا كان عند إحداهن أولاد أكثر ينفق عليها بقدر حاجتها، بقدر حاجاتها وأولادها، كل واحدة بقدر حاجتها وأولادها، وعليه أن يقسم بينهن بالسوية في الليل والنهار، ويتقي الله في البشاشة وطلاقة الوجه، مع كل واحدة، لا يعبس في واحدة وينشرح للأخرى، عليه أن يتقي الله، وأن يراقب الله؛ لأن الله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ[النساء:19] هذا هو الواجب عليه، ويقول ﷺ: من كان له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالواجب العدل أو الطلاق، إما أن يعدل، وإما أن يطلق، إلا أن تسمح، تقول: أنا سامحه، لا بأس تجيني متى شئت فلا بأس، سودة لما أراد النبي ﷺ طلاقها قالت: «يا رسول الله، أبقني في حبالك، وأنا سامحة عن حقي لـعائشة» فأسقطت حقها وأبقاها النبي ﷺ، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13876/حكم-من-يميل-الى-زوجته-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56704.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":15424,"question":"ننتقل إلى رسالة من السائلة (ف. م) مكة المكرمة، تقول: هل يحق للزوج أن يمنع زوجته من زيارة والديها، وهل لها أن تذهب دون علمه؟أفيدونا بذلك.","title":"حكم منع الزوجة من زيارة أهلها","answer":"الجواب: نعم، إذا كان في ذلك مضرة، إذا كان والداها يخببانها عليه، أو يدعوانها إلى المعاصي، والشرك له أن يمنعها، أما إذا كان لا والداها لا يأمرانها إلا بالخير، وليس هناك مضرة من زيارتها لوالديها، ليس له منعها من ذلك في الأوقات المناسبة التي يراها؛ لأن منعها من العقوق، لكن يحدد لها الأوقات المناسبة، ويأذن لها فيها.  أما إذا كانت الزيارة لوالديها تسبب شرًا؛ لأنهما يدعوانها إلى الباطل، إلى الشرك، إلى المعاصي، إلى النشوز، فلا مانع أن يمنعها من ذلك، من أجل أن زيارتها ضرر عليه وعليها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13933/حكم-منع-الزوجة-من-زيارة-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50005.mp3","categories":["الحقوق الزوجية"]},{"id":15636,"question":"السائلة (آمنة . خ. خ) من المدينة النبوية، تقول: هل يجوز للرجل أن يترك زوجته في المنزل ويذهب للحج أو العمرة دون أن يصطحب معه الزوجة؟","title":"حكم سفر الرجل للحج دون اصطحاب زوجته","answer":"الجواب: نعم، يجوز له أن يدعها في البيت، ويذهب للحج، أو العمرة، أو للصلاة، أو للجهاد، أو لحاجاته الخاصة في التجارة؛ لا بأس بذلك، وإذا كانت تستوحش يجعل عندها من الخدم من يؤنسها، أو يسمح لها تذهب إلى أهلها عند أهلها للوحشة التي تصيبها، أو إذا كان عليها خطر تذهب عند أهلها، أو يكون عندها من أهلها من يؤنسها يجمع بين المصلحتين، إذا كان عندها من يؤنسها مثل بنات وأخوات فالحمد لله، إذا كان ما عندها من يؤنسها يكون عندها خادمة أو خادمات للأنس، أو تذهب إلى أهلها حتى تبقى عندهم إلى أن يرجع.  ولا يلزمه أن يذهب معها كلما سافر، له أن يسافر للحج أو للعمرة أو للتجارة، وما أشبه ذلك، وتبقى في البيت هي، لكن مثلما تقدم: إذا كانت تستوحش يجعل عندها ما يزيل وحشتها من الخادمات، أو تذهب إلى أهلها، وإذا كان عندها بنات كبيرات أو أخوات زالت الوحشة، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/14177/حكم-سفر-الرجل-للحج-دون-اصطحاب-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57118.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحقوق الزوجية"]},{"id":15775,"question":"سؤاله الأخير في هذه الحلقة يقول: إنّ والده تزوج بامرأة أخرى، وحينئذٍ أساء معاملة والدته إساءة بالغة، رغم أن والدته يصفها بأنها محسنة إلى والده، فما هو توجيه سماحتكم؟جزاكم الله خيرًا.","title":"توجيه لمن يسيء تعامل الزوجة الأولى","answer":"الجواب: الواجب نصيحة الوالد، وترغيبه في العدل، وتحذيره من الجور؛ لأنه يأثم بذلك، الواجب عليه العدل بين الزوجتين، وفي الحديث الصحيح يقول النبي ﷺ: من كانت له امرأتان، فمال إلى إحداهما، جاء يوم القيامة وشقه مائل فهي عقوبة ظاهرة، نسأل الله العافية.  فالمقصود: أن الواجب العدل، كذلك الواجب أن ينصح الوالد، ويحرض على العدل، والوالدة توصى بالصبر والتحمل ومسامحة الوالد، حتى يجتمع الشمل، وحتى يهديه الله إذا رأى منها السماح، والكلام الطيب، قد يرجع إلى الصواب، ويخضع، ويقدر لها شعورها الطيب، وإذا أبى إلا عدم العدل، فلها أن تطلب الطلاق، إن أحبت الطلاق لها أن تطلب الطلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14368/توجيه-لمن-يسيء-تعامل-الزوجة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74205.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":15984,"question":"هذا سؤال من السائلة مسلمة من العراق، محافظة ديالي، تقول: أنا امرأة متزوجة، ولي أربعة أطفال، وقد تزوج زوجي امرأة ثانية، ولها أطفال أيضًا، والمشكلة أنه لا يعدل في معاملته بيننا، فقد انصرف عني كليًا، حتى كأنه لا وجود لي في البيت، وأطفالي يدرسون، ويحتاجون إلى مصاريف الدراسة، ولكنه لا يعطيهم، وأنا لا أستطيع أن أطلب منه، وللعلم فنحن نسكن والزوجة الثانية في نفس المسكن، وأخشى على أطفالي من الضياع من هجره للجميع، وعدم اهتمامه، فما رأيكم في هذا؟","title":"توجيه لمن لا يعدل في تعامله بين زوجتيه","answer":"الجواب: الواجب عليه تقوى الله، الواجب على الزوج أن يتقي الله، وأن يعدل، قد قال النبي ﷺ: من كان له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل فالعدل واجب في النفقة بينهما والمساواة بينهما في القسمة، فإذا جار على السائلة فهذا عليه إثم في ذلك إلا إذا كان خيرها بين الطلاق وبين الصبر، فلا حرج عليه، إذا خيرها واختارت البقاء معه على ظلمه وعدم عدله فلا بأس عليه إذا خيرها، أما أنه يمنع الطلاق، ويمنع العدل، فهذا لا يجوز له. أما أولاده فعليه نفقتهم، والواجب عليه مطلقًا طلق أو لم يطلق، عليه أن يعدل في أولاده، ويحسن إليهم، ويقوم بحاجاتهم حسب طاقته، وإذا استطاعت أن تأخذ من ماله شيئًا لحاجتها فلا بأس، إذا كان لديها مال واستطاعت السائلة أن تأخذ من ماله شيئًا بغير علمه قدر حاجتها بالمعروف لأولادها ولها فلا حرج، فقد ثبت عن النبي ﷺ أنه رخص لامرأة أبي سفيان أن تأخذ من ماله بالمعروف ما يكفيها ويكفي بنيها، فإذا وجدت له مالًا تستطيع أن تأخذ منه شيئًا لها ولأولادها بغير علمه بالمعروف من غير تبذير ومن غير إسراف، فلا حرج في ذلك -إن شاء الله-، وإن لم تستطع فينبغي لها أن تتصل بأقاربه وإخوانه والذين يعزهم ويقدرهم حتى ينصحوه، حتى يشيروا عليه، لعله يهتدي، ولعله يقوم بالواجب. وينبغي لها أن تكثر من سؤال الله له الهداية حتى يوفق للعدل، وإن كان هناك حاكم شرعي في الأحوال الشخصية، يمكن أن ترفع الأمر إليه، فلا مانع من أن ترفع إليه حتى يلزمه بالعدل، ولكن مهما أمكن أن يكون ذلك من طريق المصلحين من أقاربه وجيرانه والناس الذين يعزهم فهو أولى، الإصلاح بينها وبينه من طريق الإخوان الطيبين حتى ينفق وحتى يعدل، فهذا أولى من الشكوى وأحوط وأقرب إلى السلامة، نسأل الله للجميع الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/14612/توجيه-لمن-لا-يعدل-في-تعامله-بين-زوجتيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_680/nour_68007.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":16002,"question":"هل ما يقدمه الزوج لأهل زوجته الأخرى من صدقات أو هدايا هل يؤثر ذلك في العدل بين الزوجات؟","title":"هل يشترط العدل بين أهل الزوجات؟","answer":"الجواب: لا بأس بذلك، لا حرج -إن شاء الله-، لا يؤثر، المهم العدل بينهما في أنفسهما، أما إذا أعطى أهل إحدى زوجتيه لفقرهم، أو لإحسانهم إليه، أو لأسباب أخرى، فليس هذا من باب العدل بين الزوجات، لا حرج عليه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14622/هل-يشترط-العدل-بين-اهل-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74710.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":16048,"question":"إذا عقد على فتاة هل يجوز لها أن تخلع الحجاب أمام خطيبها قبل الدخول بها؟ أثابكم الله.","title":"ما يباح من المرأة المعقود عليها","answer":"الجواب: نعم لها أن تخلعه، إذا عقد عليها هي زوجة فتخلع الحجاب، وله أيضًا جماعها هي زوجة، لكن يدع ذلك الجماع إذا كان يخشى من ذلك فتنة أن يطلقها، أو يدعى عليه أنها زنا. فالمقصود: أنه لا يجامعها إلا على بصيرة، على علم من أهلها، وخلوة بها، مع علم أهلها، أو عند الزفاف المشهور المعروف. فالحاصل: أنها زوجة، يباح له النظر إليها، ويباح لها خلع خمارها، ويباح له أن يجامعها ما لم يخش فتنة في ذلك، فيتأخر الجماع إلى أن يحصل الدخول الشرعي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14693/ما-يباح-من-المراة-المعقود-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_802/nour_80204.mp3","categories":["الحقوق الزوجية","قضايا المرأة"]},{"id":16125,"question":"من ساجر رسالة بعث بها أحد الإخوة المستمعين يقول: المرسل (ق. ل. م) يقول: سماحة الشيخ! أرجو أن تتفضلوا ببيان حق الزوج على زوجته؛ ذلك لأن هناك الشكوى من كثير من الرجال من عصيان النساء، واستمساكهن برأيهن، جزاكم الله خيرًا.","title":"حق الزوج على زوجته","answer":"الجواب: الواجب على الزوجة طاعة زوجها في المعروف، وعدم عصيانه في الجماع، والخدمة إذا كانت من أهل الخدمة، وفي عدم خروجها من بيتها، وفي غير ذلك من الأمور التي ليس فيها معصية، حق عليها أن تسمع وتطيع لزوجها. وقد جاء في هذا الباب أحاديث كثيرة تأمر بذلك، ومن ذلك قوله ﷺ في الحديث الصحيح: إذا دعا الرجل امرأته إلى فراشه، فأبت أن تجيء؛ لعنتها الملائكة حتى تصبح فالواجب عليها السمع والطاعة لزوجها في المعروف، لا في المعاصي. وهكذا الزوج عليه أن يعاشرها بالمعروف، ويتقي الله، ولا يظلمها، لا في قوله، ولا في عمله، كما قال الله سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وقال سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] يعني: كما أن عليهن العشرة بالمعروف فلهن أيضًا لهن العشرة بالمعروف، فهو عليه أن يعاشرها بالمعروف، بالكلام الطيب، والسيرة الحميدة، والنفقة المناسبة التي تجب على مثله، وعليها هي السمع والطاعة في المعروف، وأن تجيبه إلى حاجته، وأن تقوم بخدمته في بيته، وأن تحذر معصيته في خروج، أو غيره، وإذا قام كل واحد بما يجب عليه؛ استقامت الأحوال، واستمرت العشرة الطيبة، وإذا كان كل واحد يريد الحق لنفسه، ولا يؤدي ما عليه؛ فسدت الحال، وأدى ذلك إلى الطلاق. أما الخدمة ففيها تفصيل إذا كانت المرأة؛ يخدم مثلها، ولم تسمح بالخدمة، فإنه يخدمها إذا تيسر ذلك. أما إذا كان العرف في قبيلته، أو في بلده أنها تخدم زوجها؛ فإنها تخدمه كما يفعل بنات جنسها في قبيلتها وجماعتها؛ لأن الله يقول -جل وعلا-: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] فالمعروف هو المتعارف بين الناس في كل بلد، وفي كل زمان، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14781/حق-الزوج-على-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74917.mp3","categories":["الحقوق الزوجية"]},{"id":16181,"question":"يقول: هل يجوز للزوج الكذب على زوجته في أمور لا يقدر على تنفيذها، مثلًا تطلب منه شراء شيء معين، وليس باستطاعته شراؤه، كيف توجهون الناس؟ وهل للزوجة أن تأخذ من مال زوجها دون علمه؟ وجهونا جزاكم الله خيرًا.","title":"حكم الكذب بين الزوجين والأخذ من مال الزوج بغير علمه","answer":"الجواب: للزوج أن يكذب عليها، ولها أن تكذب عليه فيما بينهما، أو في مصالحهما إذا كان الكذب لا يضر أحدًا غيرهما، إنما يختص بهما، فله أن يكذب عليها ويقول: سوف أشتري كذا، وسوف أحضر لك كذا؛ حتى يسكتها ويرضيها، ولها أن تقول ذلك: سوف أفعل معك، وسوف لا أخالفك، وسوف لا أذهب إلى البيت الفلاني؛ حتى يهدأ غضبه، ولو كانت كاذبة لما ثبت عن النبي ﷺ من حديث أم كلثوم بنت عقبة بن أبي معيط -رضي الله عنها- قالت -رضي الله عنها-: \"لم أسمع النبي ﷺ يرخص في شيء من الكذب إلا في ثلاث: الحرب، والإصلاح بين الناس، وحديث الرجل امرأته، والمرأة زوجها\" وذلك فيه مصالح حتى تهدأ الحال بينهما، وحتى يزول الغضب منه، أو منها بالأوعاد التي فيها كذب، لا يضر أحدًا من الناس، وهذا مجرب، ونافع، ولا حرج فيه، والحمد لله.  ولها أن تأخذ من ماله بغير علمه حاجتها من دون إسراف ولا تبذير، إذا كان حاجة؛ فلها أن تأخذ حاجتها من ماله من طعام، أو نقود، أو ملابس من غير علمه، لكن في غير إسراف، ولا تبذير؛ لأنه ثبت عن النبي ﷺ أن هند بنت عتبة قالت: «يا رسول الله! إن أبا سفيان -يعني: زوجها- رجل شحيح، لا يعطيني من النفقة ما يكفيني، ويكفي بني، فهل لي أن آخذ من ماله ما يكفيني ويكفي بني بغير إذنه؟ فقال النبي ﷺ: نعم. خذي من ماله بالمعروف ما يكفيك ويكفي بنيك بالمعروف، يعني: من غير إسراف، ولا تبذير حسب المعتاد، حسب الحاجة، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14855/حكم-الكذب-بين-الزوجين-والاخذ-من-مال-الزوج-بغير-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75017.mp3","categories":["الحقوق الزوجية"]},{"id":16470,"question":"يقول في سؤال آخر: عندما يتوفى للزوجة قريب من ابن، أو أخ، أو أب تمتنع عن فراش زوجها فترة طويلة تصل إلى سنة كاملة، فهل يحق لها ذلك؟ وهل هناك فترة للحزن؟ وإذا اتفق الزوج وزوجته على أن يحزنا على ابنهما فترة سنة، فهل هناك من حرج؟ أفيدونا أفادكم الله.","title":"حرمة هجر المرأة فراش زوجها إلا لعذر","answer":"الجواب: هذا لا يجوز، ليس لها أن تعصي زوجها، وتهجر فراشه، لا يومًا، ولا أكثر، بل يجب عليها طاعة زوجها في المعروف، وتمكينه من نفسها إذا أراد جماعها، وليس هناك مانع من مرض، ولا حيض، ولا نفاس. فالواجب عليها طاعته، وتمكينه من نفسها، قال تعالى في كتابه العظيم: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وقال تعالى: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] قال النبي ﷺ: أيما امرأة باتت، وزوجها عليها ساخط؛ لعنتها الملائكة حتى تصبح وفي لفظ: كان الذي في السماء ساخطًا عليها حتى يرضى عنها وهذا وعيد عظيم.  المقدم: نعيد هذا الحديث مرة أخرى. الشيخ: يقول النبي ﷺ: أيما امرأة باتت وزوجها عليها ساخط؛ لعنتها الملائكة حتى تصبح وفي لفظ آخر يقول ﷺ: إذا باتت المرأة، وزوجها عليها ساخط؛ كان الذي في السماء ساخطًا عليها يعني: الله، وملائكته، وهذا وعيد عظيم. فالواجب على المرأة السمع والطاعة لزوجها في المعروف، وعدم هجر الفراش، ولو مات قريبها، إن كان أبوها، أو ابنها، أو خالها، أو عمها، وليس لها أن تغير من حالها أكثر من ثلاثة أيام، يقول النبي ﷺ: لا تحد امرأة على ميت فوق ثلاث، إلا على زوج أربعة أشهر وعشرًا فليس لها الإحداد على أبيها، أو أمها، أو أخيها، أو ابنها أكثر من ثلاث، ثلاث لا بأس تترك الزينة. أما تعصي زوجها لا، لا تعصي زوجها، لا في الثلاث، ولا في غيرها، لكن لا مانع أن تدع الزينة مثل الملابس الجميلة، أو الطيب في هذه الثلاث من أجل موت أخيها، أوأبيها، أو أمها، أو نحو ذلك. أما الزوج فالمدة أربعة أشهر وعشرًا إذا مات، يقول ﷺ: لا تحد امرأة على ميت فوق ثلاث، إلا على زوج؛ فإنها تحد عليه أربعة أشهر وعشرًا. فالواجب على النساء أن يتقين الله، وهكذا الرجال على الجميع تقوى الله  وعلى المرأة أن تتقي الله في زوجها، وأن تطيعه في المعروف، وأن لا تهجر فراشه من أجل موت قريب، أو غيره، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15197/حرمة-هجر-المراة-فراش-زوجها-الا-لعذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81306.mp3","categories":["الحقوق الزوجية"]},{"id":16771,"question":"هذا سائل يقول: زوج اعتاد بين فينة، وأخرى أن يأخذ من مال زوجته بدعوى مواجهة أعباء الحياة، على الرغم من رفضها لذلك، هل الرفض من الزوجة يعني النشوز؟","title":"حكم رفض الزوجة إعطاء زوجها من مالها","answer":"الجواب: ليس هذا من النشوز، بل هذا مالها لها الحق أن تمنع، وليس له أن يأخذ مالها بغير حق، النشوز: عصيانها فيما يجب عليها، هذا النشوز، كونها تعصيه فيما يجب عليها، كأن تمنعه من نفسها، أو من المبيت معه، أو ما أشبه ذلك مما هو واجب عليها، هذا هو النشوز، أما كونها تمنعه مالها؛ فليس هذا من النشوز، بل هذا حق لها، إن طابت نفسها؛ فلا بأس، وإلا فليس له جبرها، ولا غصبها؛ لأن الله يقول -جل وعلا-: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4] فإذا لم تطب نفسها فليس له ظلمها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15513/حكم-رفض-الزوجة-اعطاء-زوجها-من-مالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58502.mp3","categories":["الحقوق الزوجية"]},{"id":16872,"question":"تقول في سؤال آخر: مر ما يقارب أكثر من تسعة عشر عامًا، وأبي هاجر لأمي، ولا يفي لها بحقوق الزوجية التي شرعها الله بين الزوجين، ولا تزال الحال هذه حتى اليوم، وأمي موجودة في البيت تقوم على رعاية شؤوننا، فما الحكم والحال هذه؟ هل تعتبر مطلقة بمرور الفترة المذكورة؟ جزاكم الله خيرًا.","title":"حكم هجر الزوجة عدة سنوات","answer":"الجواب: هذا فيه تفصيل: إن كانت تريد الطلاق، أو العدل، ولم يفعل؛ فهو يأثم بذلك، بهذا الهجر، أما إذا كان قد خيرها، وقال لها: إن شئت الطلاق؛ طلقتك، وإلا أنا ما يمكن أن أعدل بينك، وبين ضرتك، أو لا يمكن أن أقوم بواجبك من جهة النفقة، أو من جهة المراجعة، والجماع، إذا كان قال لها ذلك؛ فهو معذور، ولا حرج عليه، أما إن كان هجرها، وتركها، ولم يطلقها، وهي تطلب الطلاق؛ فهذا لا يجوز له، يأثم بذلك، وإن كان عندها أولاد فعليه النفقة عليهم. المقصود: أن هذا الهجر إن كان عن إعلام لها، وإخبار لها منه أنه لا يستطيع القيام بحقها، وأنه مستعد لطلاقها، ولكن لم تطلب الطلاق؛ فلا حرج عليه؛ لأنها هي التي رضيت بهذا الشيء، وقد بقيت سودة مع النبي ﷺ مدة طويلة، وهي في عصمته، ولم يكن يقسم لها؛ لأنها رضيت بذلك، وجعلت يومها لعائشة، رضي الله عنها. فالمقصود: أن هذا إذا كان عن رضا منها، وموافقة؛ فلا بأس، أما إذا كان هو جبرها، لم يطلقها، ولم يعطها حقها؛ فهو يأثم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15625/حكم-هجر-الزوجة-عدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82418.mp3","categories":["الحقوق الزوجية"]},{"id":17049,"question":"تقول السائلة يا سماحة الشيخ: تزوجت وأنا صغيرة، ولم أكن أعرف حقوق الزوج، وغرر بي أحدهم حيث تطلقت من زوجي، وظلمت زوجي، وأنا الآن نادمة، فماذا يلزمني حفظكم الله؟ وأرجو يا سماحة الشيخ أن تدعو له بالخير، وبتيسير الرزق، وأنا أتمنى العودة له، فما توجيهكم حفظكم الله؟","title":"الحث على إحسان معاملة المرأة لزوجها","answer":"الجواب: التوجيه أن عليك التوبة إلى الله مما فعلت من التقصير، الندم والتوبة إلى الله، وسؤاله المغفرة  وعدم العودة إلى مثل ذلك مع الزوج الجديد، وإذا عدت إليه إن كان الطلاق طلقة واحدة، أو طلقتين له العود إليك، وعليك الجد في إحسان المعاشرة إذا عدت إليه بالكلام الطيب والأسلوب الحسن، والسمع، والطاعة في المعروف، وعدم المعاكسة، هكذا ينبغي للزوجة، الله يقول سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ويقول ﷺ: استوصوا بالنساء خيرًا.  ويقول في حق النساء: على المرأة ألا تأذن في بيت زوجها إلا بإذنه، ولا يطأ فراشها أحد إلا بإذنه وعليها السمع والطاعة لزوجها في المعروف، فعلى المرأة السمع والطاعة لزوجها في المعروف، والعناية بإكرامه، والإحسان إليه؛ لأن حقه عليها أكبر وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228]. وهو عليه أن يستوصي بها خيرًا، وألا يظلمها، وأن يحسن عشرتها، لكن حقه عليها أكبر، فعليها أن تسمع وتطيع في المعروف، وأن تعينه في أمور بيته، وأن تكرمه حتى تستقيم الحال بينها وبينه، لكن لا تطيعه في المعاصي، إنما تكرمه في لباسه، وفي فراشه، وفي تمكينه من نفسها إذا أرادها، وفي غير هذا من شؤون البيت، ومع أولاده وأهل بيته، ووالديه، ونحو ذلك، يكون لها سيرة حسنة معه، ومع والديه، ومع أقاربه حتى تشكر، ويدعى لها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15838/الحث-على-احسان-معاملة-المراة-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58724.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17071,"question":"تقول السائلة: بأن زوجها شحيح لا يعطيها ما يكفيها وأولادها من مصاريف البيت، وأدوات المدرسة.. وغير ذلك، هل يحل لها أن تأخذ من ماله بدون علمه؟","title":"حكم أخذ المرأة من مال زوجها البخيل","answer":"الجواب: نعم، إذا كان يقصر في نفقة البيت لها أن تأخذ من ماله بغير علمه، إذا قصر في نفقتها ونفقة أولاده منها لها أن تأخذ بالمعروف من غير إسراف، ولا تبذير، لكن بالمعروف؛ لأن هند بنت عتبة امرأة أبي سفيان -رضي الله عنهما- قالت: «يا رسول الله، إن أبا سفيان رجلٌ شحيح، لا يعطيني من النفقة ما يكفيني، ويكفي بني، فهل آخذ من ماله ما يكفيني؟ قال: نعم. خذي من ماله بالمعروف ما يكفيك، ويكفي بنيك خذي من ماله بالمعروف يعني: من غير إسراف، ولا تبذير. نعم. المقدم: إذًا يا سماحة الشيخ بعض الأخوات يقلن: هل النفقة محددة مثلًا أو معينة؟ الجواب: غير محددة حسب الحاجة، تختلف بحسب الغلاء والرخص، حسب حاجة الأولاد، وكثرتهم، وقلتهم، حسب الحاجة ... الوسط، مثلما قال الله -جل وعلا- في عباده الصالحين: وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَلِكَ قَوَامًا [الفرقان:67] وقال -جل وعلا-: وَلا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ وَلا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُومًا مَحْسُورًا [الإسراء:29] المغلولة: البخيل، والبسط كل البسط: هذا المسرف، المبذر. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15876/حكم-اخذ-المراة-من-مال-زوجها-البخيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58811.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17232,"question":"تقول: يا سماحة الشيخ -هذه الأخت الطبيبة- أبي عليه ديونٌ، رغم أنه يشتغل، إلا أنه لا يستطيع تسديد هذه الديون، ولقد طلب منا نحن الأخوات البنات على مساعدته، واتفقن مع أخواتي على مبلغٍ محدد يدفع من الكل، زوجي يرفض أن أساعد أهلي، بالرغم من، أولًا: أصرف على نفسي، وعلى ابنتي، وعلى البيت من كل النواحي: إيجار، وكهرباء، ومأكل، وملبس، وغير ذلك، بل العكس أنا أساعده بالرغم من أن راتبه كبير، زوجي يصرف جميع ما يملك من الراتب على أهله، لبناء بيتٍ لأبيه، وأنا لم أعترض، بل العكس أساعده، المبلغ الذي أساعد به أهلي يعتبر جزءًا بسيطًا بالنسبة للراتب الذي أتقاضاه، أهلي موجودون في المنطقة التي أدرس بها، وهم الذين ساعدوني في أمور الحياة، مثلًا: لو احتجت الذهاب إلى مكان ما، أو طبيب، وغير ذلك، لعل لكم توجيه؟","title":"ما حكم إعانة المرأة لوالدها وزوجها رافض؟","answer":"الجواب: نعم، الواجب مساعدة والدك، عليكم أن تساعدوا الوالد، النبي ﷺ يقول: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم فعليكم أن تساعدوا والدكم، ولو لم يرض الزوج، ما له حق يمنعكم، ولو منعكم ما له حق، عليكم أن تساعدوا الوالد، ولو لم يرض الزوج، هذا من أهم الصلة، ومن أهم البر، فعليكن أن تساعدن والدكن في قضاء دينه، وفي نفقة بيته، ولو لم يرض الزوج. نعم.","link":"https://binbaz.org.sa/fatwas/16060/ما-حكم-اعانة-المراة-لوالدها-وزوجها-رافض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59109.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":17234,"question":"تقول -من أسئلتها سماحة الشيخ-: إذا كان الزوج لا يعامل الزوجة بالرفق واللين، ولكن بالهجر والتجريح، وذلك في كل مشكلة لا أوافقه في الرأي، هل الهجر في الإسلام هو الهجر في كل شيء من مسؤولية البيت؟ بالإضافة إلى الفراش، يعني: الهجر في الكلام، والمعاملة السيئة، طول فترة الهجر؟","title":"كيفية معاملة الزوجة عند نشوزها","answer":"الجواب: الواجب على الزوج، مثلما قال ﷺ: استوصوا بالنساء خيرًا والله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19].. ويقول سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] والهجر له أسباب، كما قال تعالى: وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ [النساء:34] هذا الهجر إذا خاف نشوزها، أو عصيانها له، وظهرت أمارات ذلك منها؛ فله حينئذٍ ما ذكره الله -جل وعلا- أوله: الوعظ، يذكرها وينصحها، ثم بعد ذلك -بعد الوعظ- الهجر، كونه ما ينام معها في فراش، ينام وحده، أو يعطيها قفاه، تأديبًا لها، ثم الضرب بعد ذلك، ضربًا خفيفًا غير مبرح، كما قاله النبي ﷺ، ضربًا خفيفًا غير مبرح، إذا لم ينفع الوعظ، والهجر. نعم.","link":"https://binbaz.org.sa/fatwas/16062/كيفية-معاملة-الزوجة-عند-نشوزها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59111.mp3","categories":["الحقوق الزوجية"]},{"id":17261,"question":"هذا السائل أخوكم في الله يقول: سماحة الشيخ حفظكم الله، زوجتي امرأة ملتزمة، وأحمد الله على ذلك، وهي ملتزمة بأمور الدين، وغير ملتزمة بتعليماتي الخاصة، فهي دائمًا تعاند، وتخالف أوامري في وضع البيت، وفي تربية الأبناء، وعندما أسألها: لماذا أنت دائمًا مخالفة؟ تجاوب وتقول: بأنها تنسى، وهي تنسى في اليوم أكثر من عشر مرات، وهذه المخالفة في كل يوم على مدار السنة، مما أدى بي إلى هجرها في المضجع بعد الوعظ والنصيحة، وأيضًا لم تتغير، وأيضًا مما أدى بي إلى ضربها ضربًا خفيفًا جدًا، ثم قامت وجمعت ملابسها، وأغراضها، وذهبت إلى بيت أهلها، فما حكم هذا التصرف الذي مني ومنها؟ ولا أخفيكم يا سماحة الشيخ في الطلاق في نيتي، فأفيدوني مأجورين؟","title":"كيفية معاملة الزوجة حال تعنتها","answer":"الجواب: المشروع لك يا أخي الصبر والاحتساب، وعدم التكلف، الرسول يقول ﷺ: استوصوا بالنساء خيرًا ويقول الرب -جل وعلا-: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] فإذا كانت تقول: إنها ناسية؛ فينبغي لك أن ترفق بها ما دامت تعتذر بالنسيان، فينبغي الرفق، والصبر، والاحتساب، وعدم العجلة في الضرب، والكلام السيئ، هكذا ينبغي للمؤمن مع زوجته؛ لأن الله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ويقول النبي ﷺ: استوصوا بالنساء خيرًا، فإنهن خلقن من ضلع أعوج، فإن ذهبت تقيمه كسرته، وإلا لم يزل أعوجًا وفي اللفظ الآخر: وكسرها طلاقها.  فالأفضل لك يا أخي الصبر، والاحتساب، وعدم العجلة في الأمور، والحرص على وصيتها، ونصيحتها حتى تستقيم -إن شاء الله- ولا تعجل. والضرب الخفيف إذا اجتهد الزوج لا بأس الضرب الخفيف؛ لأن الله قال: وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ [النساء:34] لكن هذه ما هي ناشزة، ولا تخاف نشوزها، لكن عندها تساهل في قبول التعليمات، فإذا صبرت عليها، واحتسبت الأجر في ذلك، وصدقتها في قولها: إنها ناسية يكون هذا أقرب، ولقوله -جل وعلا-: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ولقول النبي ﷺ: استوصوا بالنساء خيرًا نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16098/كيفية-معاملة-الزوجة-حال-تعنتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59212.mp3","categories":["الحقوق الزوجية"]},{"id":17413,"question":"إذا غضبت الزوجة على زوجها فما الواجب أن تفعله في ذلك؟","title":"واجب المرأة تجاه زوجها","answer":"الجواب: الواجب عليها عدم العصيان لزوجها، وعدم المخالفة لأوامره الشرعية والمباحة، عليها السمع والطاعة لأوامره الشرعية والمباحة، وعليها كف الأذى. وهو كذلك عليه أيضًا كف الأذى عنها، وأن يعاملها بالحسنى، وأن يستوصي بها خيرًا، وعليهما التعاون على البر والتقوى، فإذا وجد ما يغضبها؛ فلا حرج عليها، إذا سبها، وغضبت؛ لا حرج، لكن عليها أن تجاهد نفسها، وعليها أن تنصحه عن السب والشتم، تقول له: اتق الله، هذا لا يجوز لك.. بالكلام الطيب. ولا شك أن الأذى منه يوجب غضبها، يسبب الغضب، لكن عليها أن تجتهد، وأن تتحمل، وأن تحرص على السمع والطاعة في المعروف، وأن تنصحه عما يقع منه من الغضب، والشتم، أو الضرب حتى تزول المشكلة بينهما مهما أمكن، فإن لم يفعل ذلك؛ فلها الخروج إلى بيت أهلها، والرفع إلى المحكمة.  المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16279/واجب-المراة-تجاه-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77114.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17435,"question":"سماحة الشيخ، أمامي رسالة مكونة من صفحتين، لا أدري هل أقرأ هاتين الصفحتين؟ أم أقرأ ما لخصته عنها؟الشيخ: الملخص يكفي.المقدم: ملخص ما في هذه الرسالة: أن صاحبها يشكو من زوجته شكوى فيها كثير من المرارة، فهو يقول: إنها تصر على الذهاب لأهلها في كل أسبوع، ثم إنها تدفع الراتب كاملًا إلى أهلها، مع العلم أنه هو الذي يذهب بها إلى المدرسة، ويعيدها أيضًا إلى المدرسة، وهي تترك البيت كثيرًا في سبيل هذه الوظيفة، ثم يقول: إنها تهمل رعاية البيت، والطفل، وتترك كل ذلك للخادمة، وهي كثيرة الذهاب والإياب إلى الناس، ويرجو من سماحتكم التوجيه؟ جزاكم الله خيرًا.","title":"نصيحة لمن تؤذي زوجها ولا تطيعه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، سيد ولد آدم، وعلى آله وأصحابه، ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد.  فإن الواجب على كل زوجة أن تسمع، وتطيع لزوجها في المعروف، وليس لها أن تذهب إلى أهلها إلا بإذنه، ولا إلى غير أهلها إلا بإذنه، وهكذا التدريس ليس لها أن تدرس إلا بإذنه إلا أن يكون قد شرط عليه عند العقد، فـ المسلمون على شروطهم وإلا فليس لها أن تدرس إلا بإذنه. وكونها تذهب إلى أهلها كل أسبوع ليس لها ذلك إلا بإذنك، فينبغي لك أن تلاحظ الموضوع، وأن تنظر في المصلحة، فإن رأيت أن في ذهابها مصلحة؛ فلا بأس مراعاة لخاطر والديها، وحرصًا على سلامة القلوب، وبقاء المودة، وإن تيسر أن يكون ذهابها إليهم في أكثر من ذلك، كعشرة أيام، أو نصف شهر، فلا بأس، تتفق أنت والوالدان، والمرأة على الشيء الذي فيه المصلحة للجميع، وفيه كسب رضاك، وعدم التسبب في الفراق. وهكذا ليس لها الخروج لغير أهلها إلا بإذنك، والواجب عليها أن تلزم البيت، وتعتني بالأولاد، وتربيتهم التربية الطيبة، ولا ينبغي أن تكلهم إلى الخادمة، بل ينبغي أن تعتني بهم هي، وأن تجتهد في تربيتهم، والإحسان إليهم، وإذا كانوا يفهمون تحرص على تربيتهم التربية الإسلامية، وتوجيههم إلى الخير. أما الراتب فهو لها، لكن ينبغي لها أن تعطيك بعض الشيء في مقابل تعبك، وذهابك، وإيابك، وتسميحًا لخاطرك ولا سيما إذا كنت محتاجًا، فإن المشروع لها أن تساعدك؛ لأن الله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول النبي ﷺ: من كان في حاجة أخيه كان الله في حاجته ويقول النبي ﷺ: والله في عون العبد ما كان العبد في عون أخيه فنصيحتي لها أن تساعدك من الراتب، والواجب عليها أن تسمع، وتطيع لك في كل شيء، ليس فيه معصية لله  لا في ذهابها إلى أهلها، ولا في غيرهم. أما وجود الخادمة لديكم فأنت قد أخطأت في الإتيان بالخادمة، هي التي سببت هذه المشاكل، أبعد الخادمة حتى تقيم في البيت هي، وتقوم بأولادها، وخدمة البيت، فإبعاد الخادمة هو الطريق إلى ... السلامة من ذهابها إلى أهلها، وغيرهم في كل وقت، ثم الخادمة وجودها عندك فيه خطر عليك، وعلى دينك، وليس في البيت غيرها، والرسول ﷺ قال: لا يخلون رجل بامرأة فإن الشيطان ثالثهما فوجودها في البيت، والمرأة خارج البيت في الدرس، أو عند أهلها فيه خطر عظيم.  فنصيحتي لك إبعاد الخادمة، وردها إلى أهلها، وأن تقوم الزوجة بما يتعلق بالبيت، ولو تركت التدريس، هذه نصيحتي لكما جميعًا، ونسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، إذًا الأولى في هذه الأمور الحياة الزوجية؟ الشيخ: نعم، على كل منهما العناية بالحياة الزوجية، والحرص على بقائها على الوجه الشرعي من دون معصية لله . فالمقصود: أن المشروع لك أيها الأخ أن تعتني بحفظ زوجتك، وبقائها في البيت، وأن تعمل كل الأسباب التي تبعدها عن الخروج إلا بإذنك. المقدم: جزاكم الله خيرًا، لعل هذه الرسالة تتيح لنا الفرصة سماحة الشيخ كي ما نسأل: إذا ما أراد الإنسان أن يتزوج من موظفة، فما هي الشروط التي تنصحونه أن يشترطها حتى تكون الحياة الزوجية مستقيمة؟ الشيخ: هو يعمل بالأصلح، إن رأى الموافقة على بقائها في الوظيفة؛ فلا بأس، وإن رأى اشتراط ترك الوظيفة: فلا بأس، هو أعلم بنفسه، وهذا شيء يرجع إلى علمه، وإلى حاجته، وإلى تقديره، فإذا تيسر بقاؤها في الوظيفة الطيبة، وفي البيت من يقوم مقامها في إصلاح البيت، كأمه، وأخواته، ونحو ذلك، وإلا فالأصلح ألا يقبل موظفة، بل يتزوج امرأة غير موظفة؛ حتى تقيم في بيته، وحتى تعتني بالبيت، وحتى يرتاح إليها، إذا جاء من عمله وجدها. والمقصود بكل حال: هو أن ينظر فيما هو أصلح له في دينه، ودنياه مع الموظفة، وغيرها. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/16296/نصيحة-لمن-توذي-زوجها-ولا-تطيعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83601.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17461,"question":"تقول السائلة: والدي متزوج من امرأة ثانية منذ أكثر من عشر سنوات، وهو لا ينفق على أمي، ولا على إخوتي، وإنما ينفق على زوجته الأخرى، وأولادها الذين هم إخوتي من أبي بحجة أنه لا يستطيع النفقة على أمي وإخوتي، والحجة بأن إخوتي قد توظفوا ولهم رواتب، مع العلم أن منهم من لم يزل طالبًا، ويأخذ المصروف من أخته الموظفة، ومن أخيه الموظف، فما الحكم؟ تقول: إن والدي يطلب من إخوتي أن يعطوه من رواتبهم، ويغضب إذا لم يعطوه، مع أن والدي موظف، ويتقاضى راتبًا شهريًا، لكن هو يقول: بأنه مديون، وعليه ديون كثيرة، لكن الله أعلم، على العموم إذا كانت الحالة كما ذكرت لكم فهل لي أن أدفع زكاة أموالي لوالدي؟ أفتوني مأجورين.","title":"حكم ترك الزوج النفقة على الزوجة الأولى","answer":"الجواب: يلزم الوالد النفقة على زوجته الأولى إذا كان أولادها لا يقومون بها، أما إذا كان أولادها يكفونها المؤونة، وقد أنفقوا عليها كفوا؛ لأن أولاده له، حقه عليهم كبير، والرسول ﷺ يقول: أنت ومالك لأبيك فإذا كفوه مؤونة أمهم، وأنفقوا عليها؛ كفى والحمد لله، أما إذا لم يكفوه، وهي تطلب النفقة مخيرة، إن شاءت صبرت، وإن شاءت قالت: طلقني، تطلب الطلاق إن لم تصبر، وإلا صبرت، وإن أنفق عليها أولاده كفوه المؤونة، والحمد لله، ولا حرج عليه. وإن طلب منهم شيئًا فعليهم أن يعطوه من مالهم ما لا يضرهم، أما إذا كان يضرهم، ولا يستطيعون؛ فلا يلزمهم ذلك، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] لكن ما داموا يستطيعون؛ فعليهم أن يرضوه، ويعطوه من رواتبهم ما يعينه على قضاء دينه، وعلى النفقة على زوجته الجديدة، يقول النبي ﷺ: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم ويقول ﷺ: أنت ومالك لأبيك حق الوالد عظيم.  فالواجب عليهم أن يجتهدوا في إرضائه وفي مساعدته، ويقوموا بأمهم، وإذا كانت أمهم لا تصبر، وتقول: أبي النفقة من الزوج، تخيره تقول، تطلب الطلاق، إلا إذا قام أولاده بالنفقة فلا حق لها؛ لأن نفقة أولاده كنفقته، إذا أنفقوا عليها بما يكفيها الحمد لله، أما إذا ما أنفقوا عليها، ولا أنفق هو؛ فلها طلب الطلاق، نعم. المقدم: العدل بين الزوجات أمر مطلوب، هل لكم في ختام هذا ... ؟ الشيخ: العدل واجب، لكن إذا كان أولادها ينفقون عليها هم يقومون مقامه، والحمد لله ما يسمى جائرًا، أولاده يقومون مقامه في النفقة عليها، لكن عليه أن يقسم لها مثلما يقسم لضرتها، نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16329/حكم-ترك-الزوج-النفقة-على-الزوجة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77217.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17621,"question":"من إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (خ. ك. ز)، من الباحة، تقول فيها: إنها امرأة تبلغ من العمر قرابة الأربعين عامًا، عشت مع زوجي وشاركته السراء والضراء، ولي منه ستة أولاد ذكور وأربع بنات غير الذين توفاهم الله في صغرهم، ولكنه إذا غضب لأي أمر من أمور دنياه سواء كان ذلك الأمر من أجل البيت أو خارج البيت يقول لي أقوالاً تشيب الرءوس منها ظلمًا وبهتانًا ولكني أصبر وأقول: هذا زوجي وأبو عيالي وسوف ألقى الجزاء على صبري، لكن الذي أود السؤال عنه قوله حينما يغضب يردد قوله قائلاً: ثلاث كلمات وتخرجين من البيت، لا علم لي عن تلك الثلاث الكلمات ما هي؟! ولكن كما هو معروف أنها كلمات الفصل بين الرجل والمرأة، فما رأيكم في قول هذا الرجل جزاكم الله خيرًا؟","title":"حكم الإكثار من تهديد الرجل أهله بالطلاق","answer":"الجواب: نوصيك بالصبر والاحتساب، والدعاء له بالهداية، وأن الله يوفقه ويهديه حتى يحفظ لسانه، وحتى يصون لسانه من الكلمات البذيئة، فالدعاء أمر مطلوب من المرأة والرجل، جميعًا، الله يقول: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] وهو سبحانه القائل: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ [البقرة:186] وأنت مشكورة على الصبر، والاحتساب، والتحمل من هذا الرجل الذي يتكلم بما لا ينبغي إذا غضب، مع النصيحة له في وقت الهدوء، تنصحينه بالكلام الطيب والتحمل وعدم إطلاق الكلمات التي تؤذي وتضر؛ لأنه يأثم بها وتضره.\nأما قوله: ثلاث كلمات وتخرجين، هذا لا يضرك، مادام ما قالها لا يضر، إذا كان قال ثلاث.. معناه يتوعد، معناها الوعيد، يعني: تأدبي وإلا طلقت فهذا معناه الوعيد، لا يضرك، ولا حرج عليك فيه من باب الوعيد. نعم.","link":"https://binbaz.org.sa/fatwas/16548/حكم-الاكثار-من-تهديد-الرجل-اهله-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_843/nour_84301.mp3","categories":["الحقوق الزوجية"]},{"id":17654,"question":"تقول: إنني أعلم أن الزوج النار أو الجنة للزوجة، ولهذا فأنا أتقي الله في هذا الزوج، والحمد لله، وهو دائمًا يدعو الله لي، ولكن في بعض الأحيان قد يحدث خلاف، أو يفعل ما يغضبني، وأنا أكتم غضبي خوفًا من الله ، وأسأل الله أن يقدر لي كل خير، فهل يمكن للزوجة أن تغضب من زوجها؟ وإلى أي حد؟ وهل يجازي الله من كتمت غضبها عن زوجها؟ جزاكم الله خيرًا؟","title":"حكم غضب الزوجة على زوجها","answer":"الجواب: نعم، نعم، أنت مأجورة على كظم الغيظ، وعلى خيرٍ عظيم، والله يقول سبحانه في كتابه العظيم، في وصف أهل الجنة، الذين قال فيهم جل وعلا: وَسَارِعُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمَوَاتُ وَالأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ ۝ الَّذِينَ يُنْفِقُونَ فِي السَّرَّاءِ وَالضَّرَّاءِ وَالْكَاظِمِينَ الْغَيْظَ وَالْعَافِينَ عَنِ النَّاسِ وَاللَّهُ يُحِبُّ الْمُحْسِنِينَ [آل عمران:133-134] فكظم الغيظ من صفات المتقين، الموعودين بالجنة والكرامة، فأنت على خير إذا صبرت، وكظمت الغيظ، من أجل إرضاء زوجك، ومن أجل إحسان العشرة، ومن أجل جمع الشمل، أنت على خيرٍ عظيم.\nوالواجب عليه هو أيضًا أن يجتهد في إحسان العشرة، والبعد عن أسباب الغضب، عليكما جميعًا التعاون على البر والتقوى، وعلى ترك الأسباب التي تحدث الغضب، والغيظ، والمؤمن يجتهد في الأسباب الطيبة مع زوجته، ومع أهل بيته، ومع إخوانه المسلمين، والمؤمنة كذلك، كلٌ منكما عليه أن يجتهد، والله سبحانه يعين العبد إذا اتقاه، وصبر، يعينه سبحانه، هو جل وعلا يعين عباده المتقين، ويسهل لهم أمورهم، كما قال سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ، فاستعيني بالله واصبري، وادعي له بالتوفيق، وهو كذلك عليه أن يستعين بالله، وأن يصبر، وأن يتباعد عن أسباب إغاظتك مهما أمكن.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16584/حكم-غضب-الزوجة-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72704.mp3","categories":["الحقوق الزوجية","قضايا المرأة"]},{"id":17665,"question":"من الدمام المستمعة: (ف. غ. ص)، تقول: هل يجوز للزوج أن يرى جسم زوجته؟ جزاكم الله خيرًا.","title":"ما يحل أن يراه الرجل من زوجته","answer":"الجواب: نعم، له أن يرى جسمها، ولها أن ترى جسمه، مكشوفين، لهما أن يناما في ثوبٍ واحد، وفي كساءٍ واحد، فالذي أباح له أن يجامعها، أباح له النظر لها من باب أولى؛ لأن الجماع أشد وأعظم، فإذا أباح الله له الجماع، فكونه يلمس فرجها، أو يرى فرجها، أو يرى بدنها كله، كل ذلك لا بأس به. نعم، وهي كذلك. نعم، ولهذا كان النبي ﷺ يغتسل مع نسائه، يغتسلان جميعًا في محلٍ واحد، يراها، وتراه، قالت عائشة رضي الله عنها، وهكذا قالت أم سلمة، كانا يغتسلان جميعًا من إناءٍ واحد، في محلٍ واحد، مكشوفين، وهو أفضل الناس، وخير الناس، وأتقى الناس لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16596/ما-يحل-ان-يراه-الرجل-من-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72709.mp3","categories":["الحقوق الزوجية"]},{"id":17720,"question":"هذه أخت مستمعة لهذا البرنامج تقول: أود من سماحة الشيخ أن يقدم نصيحة لزوجي، فزوجها تقول: مع أنه ملتزم بشعائر الدين ومؤدي للصلوات ومن الذين يخافون الله، إلا أنه يعاملها بقسوة مع أنها تقول: أنا وإياه نؤدي العبادات في أوقاتها وأولادنا- والحمد لله- على عبادة دائمة، هل من نصيحة سماحة الشيخ؟","title":"وصية للأزواج بحسن العشرة مع زوجاتهم","answer":"الجواب: نعم، نوصي جميع الأزواج بتقوى الله، والرفق بالزوجات، وإحسان العشرة، وعدم الغلظة وعدم سوء الكلام، قال الله تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وقال جل وعلا: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228]، وقال النبي ﷺ: استوصوا بالنساء خيرًا.\nفالواجب على الأزواج المعاشرة الطيبة والكلام الطيب والأسلوب مع الزوجة الطيب وعدم الشدة وعدم العنف؛ لا في الكلام، ولا في غيره. هذا هو الواجب على الأزواج. والزوجة كذلك عليها أن تعامل زوجها بالكلام الطيب والأسلوب الحسن والسمع والطاعة في المعروف، كل منهما عليه أن يعين الآخر على الخير، الله يقول جل وعلا: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، فعليها وعلى زوجها التعاون على البر والتقوى بالكلام الطيب والأسلوب الحسن والمسارعة إلى كل ما يرضي الآخر مما أباح الله، نسأل الله للجميع الهداية.\nالمقدم: أحسن الله إليكم وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16673/وصية-للازواج-بحسن-العشرة-مع-زوجاتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59527.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17904,"question":"رسالة من أحد الإخوة المستمعين يقول: أنا أعمل في المملكة العربية السعودية في بقالة صغيرة الحجم تكسب في اليوم مبلغًا يتراوح بين مائتين أو ثلاثمائة ريال، ولدي زبائن وأنا متزوج ومقيم هنا ولدي طفلة ومصاريف عائلية أخرى لا أستطيع أن أصرف على الوالد أو الوالدة؛ لأن لدي أخوين بالإضافة إلى أسرتي فأحد إخواني الكبار رفض أن يساعدني لمد الأسرة فما هو رأيكم جزاكم الله خيرًا؟الشيخ: أعد. يقول: أنا أعمل في المملكة في بقالة صغيرة الحجم تكسب في اليوم مكسبًا يتراوح بين مائتين أو ثلاثمائة ريال، ولدي زبائن وأنا متزوج ومقيم هنا ولدي طفلة ومصاريف عائلية أخرى لا أستطيع أن أصرف على الوالد أو الوالدة، ولدي أخوان بالإضافة إلى أسرتي لكن أحد إخوتي رفض أن يساعدني في مصاريف الوالدين فما هو توجيهكم لي ولإخوتي؟ جزاكم الله خيرًا.","title":"وجوب النفقة على الوالدين","answer":"الجواب: عليك أن تصرف على الوالدين والأولاد إذا كان الوالدان عاجزين لا يستطيعان الكسب والنفقة على أنفسهما من مالهما فتقسم ما لديك وما تحصل بين الجميع حسب طاقتك بين أولادك وأبويك ونفسك وزوجتك حسب الطاقة، وعلى أخويك أن يساعدا في ذلك، يلزمهما أن يساعدا في نفقة والديهما إذا كانا يستطيعان ذلك، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، ونفقة أولادك وأبويك إذا كانا عاجزين عليك وهكذا زوجتك، وعلى أخويك أن يساعدا إذا كانا يستطيعان من مالهما أو من كسبهما وهذا واجب، هذا من بر الوالدين الواجب على الأولاد، ويكون التوزيع على حسب الطاقة، توزيع ما لديك يصنع به الطعام للجميع وتشتري كسوة للجميع حسب طاقتك، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم.\nالمقدم: جزاكم الله خيرًا، يسأل عن أخيه الذي لم يساعده في الصرف على الوالدين؟\nالشيخ: إن شاء رفع أمره إلى الحاكم وإن شاء صبر، إن شاء رفعت أمره إلى الحاكم حتى يُلزمه إذا كان يستطيع، أما إذا كان عاجزًا فليس لك العدوان عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16927/وجوب-النفقة-على-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84606.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17922,"question":"من الأردن جرش، المستمعة: فاطمة محمد، تسأل سماحتكم بعض الأسئلة، فتقول: لي زوج يمنعني من زيارة أقاربي دون سبب، مثل: دار الخال، أو دار خالتي، ودار عمتي، وهكذا، فهل يأثم هذا الزوج في الشرع؟ أم لا؟ وهل أطيعه في منعه ذلك؟ جزاكم الله خيرًا.","title":"حكم طاعة الزوج في عدم زيارة الأقارب","answer":"الجواب: الواجب طاعة الزوج، الواجب طاعة الزوج إذا منعها من الخروج إلى العمة، أو الخالة، طاعته، لكن لا ينبغي له أن يمنع؛ إذا كانت الخالة والعمة ليس بهما محذور، ولا يخشى من زيارتهما مضرة، فلا يمنع من صلة الرحم، ولكن قد يكون له مقاصد، وقد يكون له أسباب، وقد تكون الزيارة فيها مضار.\nفالحاصل؛ أنه إذا كان المنع لا وجه له؛ فلا ينبغي له ذلك، لا يعينها على قطيعة الرحم، أما إذا كان هناك أسباب تمنع الزيارة، لأن الزيارة تضر هذه الزوجة، تضر زوجها؛ لأنهم يخببونها عليه، أو لأن عندهم منكراتٍ لا يحب أن تذهب إليهم، فتشاهدها، أو ما أشبه ذلك، فله حق في هذا المنع. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16933/حكم-طاعة-الزوج-في-عدم-زيارة-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72820.mp3","categories":["الحقوق الزوجية","قضايا المرأة"]},{"id":17958,"question":"هذه السائلة من جدة أختكم رمزت لاسمها بـ (أ. أ. ع) تقول: سماحة الشيخ! هل يحق للمرأة أن تأخذ من مال زوجها دون أن يعلم؟ علمًا بأن زوجها لا يعطيها ما يكفيها، وهي قد تكون محتاجة لذلك المال كي تشتري لها أشياء، لها ولأطفالها، أو تعطي والدتها، علمًا بأن هذا الزوج لا يشتري لها ولأطفالها إلا في عيد الفطر فقط، وعندما يسأل: من أين لك هذا الشيء؟ تقول له: من أمي، أو من أختي، فهل هذا جائز؟","title":"حكم أخذ المرأة من مال زوجها دون علمه","answer":"الجواب: نعم، إذا كان الزوج لا يقوم بالواجب لها أن تأخذ من ماله بالمعروف ما يكفيها وما يكفي أولادها، في الصحيحين عن عائشة رضي الله عنها أن هند بنت عتبة بن ربيعة زوجة أبي سفيان بن حرب، وأبو سفيان من سادات قريش ومن رؤساء قريش، اشتكت على النبي ﷺ بعد الفتح - بعد فتح مكة - اشتكت عليه وقالت: «يا رسول الله! إن أبا سفيان رجل شحيح لا يعطيني ما يكفيني ويكفي بني إلا ما أخذته من ماله بغير علمه فهل لي ذلك؟ فقال ﷺ: خذي من ماله بالمعروف ما يكفيك ويكفي بنيك يعني: ولو لم يعلم خذي من ماله بالمعروف ما هو بالإسراف والتبذير خذي من ماله بالمعروف ما يكفيك ويكفي بنيك. فإذا كان الزوج بخيلًا أو لا يبالي فللزوجة أن تأخذ من ماله بغير علمه ما يكفيها ويكفي أولادها بالمعروف، هذا لا حرج فيه.\nلكن لا تأخذ ما تعطي ... أمها وأباها لا. تأخذ ما يكفيها هي وأولادها وخدمها اللي في البيت بالمعروف، أما أن تأخذ شيئًا تعطيه الناس إلا برضاه إلا الشيء الذي جرت العادة به فضول الطعام، فضول الشراب، الشيء الذي جرت العادة بالصدقة به لا بأس. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17001/حكم-اخذ-المراة-من-مال-زوجها-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78019.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":18460,"question":"يقول السائل محمد من جمهورية مصر العربية: رجل يريد أن يتزوج زوجة ثانية على زوجته الأولى، هل لها الحق أي: الزوجة الأولى، أن تطلب ملابس وذهبا مثل الزوجة الثانية في الزواج، أم ماذا يفعل تجاهها؟","title":"هل يلزم مساواة الزوجة الأولى بالثانية في يوم زواجها؟","answer":"الجواب: لا، لا يلزمه ذلك، يلزمه الإنفاق عليها بالمعروف، وأما ما يعطيه الزوجة الجديدة من مهر وغيره هذا يختص بالجديدة، لا يلزمه أن يعطي تلك مثلها، ولكن يقسم للجديدة يقسم لها ثلاث إذا كانت ما هي ببكر، وإن كانت بكرًا يقسم لها سبعًا، الجديدة، ثم يعدل، ثم يقسم بين الجميع. وأما أنه يعطيها مثلما أعطى الجديدة من مهر وحلي وملابس شرطتها عليه فلا، لكن يعطيها بعد.. يقسم بينهم بعد الكسوة وغيرها بعدين بعد الزواج، يسوي بينهم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17539/هل-يلزم-مساواة-الزوجة-الاولى-بالثانية-في-يوم-زواجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78507.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":18504,"question":"السائلة أم بلال من اليمن تقول: بأنها متزوجة ولديها أولاد، تقول: ووالدي في حالة غير ميسورة، وعند حاجته للمال يأتي إلي لطلب المال، في حين لا يوجد لدي مال، فأضطر للأخذ من مال زوجي دون علمه، فهل أأثم في ذلك؟","title":"حكم إعطاء المرأة والدها من مال زوجها بغير علمه","answer":"الجواب: نعم. ليس لك الأخذ من ماله إلا بإذنه، استأذنيه، قولي: إن والدي في حاجة، واستأذنيه لا بأس، أما أن تأخذي من مال زوجك بغير علم من أجل أبيك هذا منكر، ظلم، لا يجوز. نسأل الله العافية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/17605/حكم-اعطاء-المراة-والدها-من-مال-زوجها-بغير-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78609.mp3","categories":["الحقوق الزوجية"]},{"id":18593,"question":"الأخت السائلة يا سماحة الشيخ! تذكر وتقول في سؤالها: إذا كان الزوج لا ينفق على الزوجة، ولا يقوم بشيء من حقوقها، فهل تجب طاعته؟","title":"حكم طاعة المرأة زوجها إذا كان لا يؤدي حقها","answer":"الجواب: إذا كان لا يؤدي حقها لا تلزمها طاعته حتى يؤدي حقها.","link":"https://binbaz.org.sa/fatwas/17698/حكم-طاعة-المراة-زوجها-اذا-كان-لا-يودي-حقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91811.mp3","categories":["الحقوق الزوجية"]},{"id":18771,"question":"هذه سائلة للبرنامج أرسلت بسؤالين تقول السائلة (س. م. أ. الزهراني) تقول: سماحة الشيخ، ما حكم الرجل الذي يسيء المعاملة لجيرانه، ويتحدث عنهم بالسيئ، ويمنع أهله من زيارتهم؟ وهل يجوز لزوجته أن تقوم بزيارتهم دون علمه؟","title":"حكم زيارة المرأة لجيرانها دون إذن زوجها","answer":"الجواب: لا يجوز إيذاء الجيران، بل الواجب إكرامهم، والإحسان إليهم يقول النبي ﷺ: من كان يؤمن بالله واليوم الآخر فليكرم جاره وفي اللفظ الآخر: من كان يؤمن بالله واليوم الآخر فلا يؤذي جاره وهكذا كل مسلم ما يجوز إيذاؤه، فالواجب على المسلم أن يتقي الله في جيرانه، وأن يكرمهم، وأن يحذر إيذاءهم. أما أنت فليس لك الخروج إلا بإذنه، ليس للمرأة الخروج إلا بإذن زوجها إلا لعلة شرعية. المقصود: أن الواجب السمع والطاعة للزوج في المعروف، إلا إذا كان الخروج لأمر ضروري، كالتقصير في نفقتها، وعدم إطعامها بألا تجد في البيت ما يقوم بحالها من الطعام والشراب للضرورة، أو ما أشبهه من الضرورات التي تقع فيها المرأة كأن تخشى انهدام البيت عليها لعيبه، أو خشية سقوطه، أو لأسباب ضرورية.  المقصود: أن الواجب السمع والطاعة للزوج في المعروف، ومن ذلك عدم الخروج إلا بإذنه، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17897/حكم-زيارة-المراة-لجيرانها-دون-اذن-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79103.mp3","categories":["الحقوق الزوجية"]},{"id":18785,"question":"رسالة سماحة الشيخ وصلت من إحدى الأخوات المستمعات، وكتبتها في حالة تأثر، أختصر منها ما يلي:سماحة الشيخ، أنا زوجة أخشى الله دائمًا، وأحس أنه يراقبني في كل وقت، ولكن ابتلاني الله بزوج لا يخشى الله في شيء، وثقت فيه كل الثقة في بداية زواجنا، ولكن اتضح لي بعد ذلك أنه لا يستحق هذه الثقة، فقد خدعني وغشني، وظل يجري وراء رغباته، وهو لا يراعي مشاعري ولا أحاسيسي، وأنا أخشى على أولادي من سير أبيهم الفاسد؛ لأن الحديث يقول: «عفوا تعف نساؤكم» وكلما ذكرته بغض البصر سخر من ذلك، ويسخر أيضًا إذا قلت له أن يتوب ويستقيم.سماحة الشيخ، ما حكم الدين في مثل هذا الزوج الخائن المخادع الغشاش، أرجو توجيه كلمة له حتى يستيقظ ضميره، ويرجع عن هذه التصرفات؛ لأنه أصبح في نظري رمزًا للخيانة والغدر وعدم الوفاء والإخلاص، وليست عنده النفس اللوامة، أرجو تذكيره بأن الله يراقبه، وسوف يسأله عن وقته، وتجيب عيناه ورجلاه ويداه.سماحة الشيخ، لقد شاعت الفوضى، وضاع الأمان من حياتنا الزوجية، وضاع الاستقرار والهدوء، وحل القلق والتوتر النفسي بسبب تصرفات رب الأسرة الذي كان من المفروض أن يكون رمزًا للاستقامة، وتوفير الأمن والأمان.أرجو تذكير زوجي بأن الزوج يجب عليه ألا يسهر ولا يضحك ولا يمزح إلا مع زوجته، ولا ينظر إلا لزوجته ما دامت مستقيمة، وعلى خلق كريم، إن تصرفاته هذه جعلتني أحس بأنني أتعس زوجة، فكيف يكون المستقبل مع مثله إلا إن لم يتب عن ذلك، وأنا أتمنى من الله أن تكون هداية زوجي على يد برنامجكم جعله الله نورًا للجميع.وأخيرًا: السلام عليكم ورحمة الله وبركاته.التوقيع: زوجة.","title":"وصية لزوج يقارف المحرمات ولا يؤدي حق زوجته","answer":"الجواب: هذا السؤال وهذا الخبر فيه إجمال، وعدم تفصيل، ونصيحتي للزوج أن يتقي الله  في زوجته، وأن يقوم بحقها، وأن يعتني بها كما أمر الله، وأن يحذر ما حرم الله عليه من الزنا ووسائل الزنا والنظر إلى النساء، فالله -جل وعلا- يقول: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ [النور:30] فهو إن كان مؤمنًا مأمور بهذا قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ [النور:30]. فوصيتي لك -أيها الزوج- أن تتقي الله في هذه الزوجة، وأن ترعى حقوقها، وأن تحسن إليها، وأن ترفق بها، وأن تحذر ما حرم الله عليك من سائر المعاصي من الزنا ووسائل الزنا وغير هذا مما حرم الله . أما ما يتعلق بالضحك والمزح ونحو ذلك فهذا ليس خاصًا بالزوجة، ومطالبته بألا يضحك إلا معك ولا يمزح إلا معك هذا عدوان منك لا وجه له، فلا بأس أن يضحك مع أولاده، ومع أمه، ومع أخواته، ومع أصدقائه ولا بأس أن يمزح معهم بالحق من غير إكثار يجره إلى باطل، هذا ليس لك التحجر عليه فيه، إنما يحرم عليه أن يضر بك، أو يمنع شيئًا من حقك، أما الأمور الأخرى التي أباحها الله له فليس لك أن تتحجري عليه فيها لا في زيارة أحبابه وإخوانه الطيبين، ولا في الضحك مع بعض أهله وأصدقائه، ولا في المزح مع من شاء مزحًا ليس فيه ما حرم الله بل مزحًا بحق. المقصود: أن عليك -أيها الأخت في الله- بالإنصاف، فاطلبي حقك فقط، ولا تطلبي ما ليس لك، وعليك بالرفق والأسلوب الحسن، والصبر الجميل، حتى يهديه الله، وحتى يقوم بالواجب ما دام مسلمًا يصلي، ويخاف الله  لكنه قد يقصر في حقك، فعليك أن تسألي حقك بالرفق والأسلوب الحسن، والكلام الطيب، والواجب عليه هو أن يتقي الله فيك، وأن ينصفك، وأن يعطيك حقوقك، هذا هو الواجب عليه. كما أنه يجب عليه وعلى غيره من جميع المسلمين والمسلمات الحذر مما حرم الله، والبعد عن معاصٍ الله، والوقوف عند حدود الله، فإن في ذلك السعادة في الدنيا والآخرة، وفي انتهاك المعاصي الخطر العظيم والعاقبة الوخيمة إلا لمن من الله عليه بالتوبة، رزق الله الجميع التوفيق والهداية، والله أعلم، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم، إذا كانت صاحبة الرسالة -سماحة الشيخ- من مجتمع مختلط، وقد لاحظت أن زوجها لا يتورع من الضحك والمزاح مع الأجنبيات، فهل لكم من كلمة؟ الشيخ: هذا دخل في الكلام، فإن مزاحه مع أجنبية أو ضحكه إذا كان وسيلة إلى الفاحشة، أو مع سفورها، أو مع خلوة بها كل هذا لا يجوز. المقدم: بعض العادات أو بعض الذنوب يعتقد البعض أنها موروثة، هل لكم من كلمة شيخ عبد العزيز ؟\nالشيخ: الذنوب والمعاصي غير موروثة، الله يقول: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] أما كونه قد يقتدي، نعم قد يقتدي بأسلافه، ولكن يجب على الإنسان أن يحذر ذلك، وأن يبتعد عن الشر؛ لأن أولاده قد يتأسون به، قد يخشى عليه أنه جرهم إلى هذا بفعله، ويخشى عليه من إثم ذلك؛ لقوله ﷺ: من دل على خير فله مثل أجر فاعله وقال في الشق الثاني: ومن دعا إلى ضلالة كان عليه من الإثم مثل آثام من تبعه قد يكون فعله لذلك نوع من الدعوة، فينبغي له الحذر. المقدم: أوردت أختنا جزءًا من حديث «عفوا تعف نساؤكم» هل من شرح لهذا الجزء؟ لو تكرمتم. الشيخ: هذا الحديث مشهور، ولكن لا أعرف حال سنده، ولكن التجارب واقعة فإن الغالب أن من عف عفت نساؤه، ومن رتع في الحرام قد يبتلى في نسائه بذلك، نسأل الله السلامة. تتأسى به زوجته، ويتأسى به بناته، ولا حول ولا قوة إلا بالله، إذا عرفوا منه الفساد، فالواجب الحذر لئلا تقع زوجته وبناته وأخواته في مثلما وقع فيه بأسبابه، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17912/وصية-لزوج-يقارف-المحرمات-ولا-يودي-حق-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90605.mp3","categories":["الحقوق الزوجية"]},{"id":18838,"question":"كثير من الزيجات تفشل -سماحة الشيخ- وإذا فكر الزوجان في أسبابها، وجدوا أن لذلك أصلًا فيما يعتقدون، فمثلًا: تزوجت وهي كارهة، أو تزوج وهو كاره، فإذا فشل الزواج؛ أعادوا ذلكم إلى تلكم الأسباب التي ذكرت.","title":"من أسباب الفشل في الحياة الزوجية","answer":"الجواب: له أسباب، الفشل له أسباب، منها: عدم حب الرجل للمرأة، ومنها عدم حبها للرجل، وأن تظن أنها تصلح معه، ولا صلحت معه؛ لأنها رأت من أخلاقه ما نفرها منه، وقد يكون رأى من أخلاقها ما نفره منها؛ فيحصل البغضاء والكراهة. ومنها المعاصي، معصية الرجل، أو معصية المرأة، قد يكون الرجل سكيرًا، سيئ الأخلاق؛ فتنفر منه المرأة، ولا تريده، قد تكون هي كذلك سيئة الأخلاق؛ ينفر منها الرجل ولا يريدها، قد تكون كثرة المعاصي والتساهل فيما حرم الله عليها، فالأسباب كثيرة، أسباب النفرة بين الزوجين كثيرة، نعم. المقدم: إذا صادف أن أصيب الزوج أو الزوجة بآفة أو بمرض مزمن، أو ما أشبه ذلك، هل للكراهة أو لإجبار النفس على ذلكم الزواج علاقة بهذا المرض أو بتلكم الآفة سماحة الشيخ؟ الشيخ: هذا لا شك أنه من المنفر، إذا وجد آفة مثل خرس في المرأة، مثل صمم في أذنيها. المقدم: بعد الزواج يعني؟ الشيخ: بعد الزواج، مثل البرص، مثل العمى، مثل كذا قد ينفر منها الزوج، ويريد غيرها، فلا بأس عليه إذا طلقها، إن صبر عليها، واحتسب، وأنفق عليها؛ فهذا أفضل وخير، وإن طلقها فلا حرج عليه، الله أباح الطلاق للحاجة، وهي كذلك قد ترى من زوجها آفة قد يصاب بجنون، قد يصاب ببرص، قد يصاب بأشياء أخرى تنفرها منه؛ فلها العذر في طلب الفراق، وأن تعطيه ماله الذي دفع إليها، وقد لا يكتب الله بينهما محبة فتنفر منه وتبغضه، كما جرى لامرأة ثابت بن قيس، فخالعت زوجها على حديقة أعطاها إياها. فالحاصل: أنه له أسباب، فإذا وجدت أسباب جديدة بعد الزواج في الزوج نفرت المرأة منه، أو في الزوجة نفرت الزوج منها؛ فلا حرج في الطلاق. وإذا كان البلاء من الزوج، كان فيه شيء كرهته بسبب ذلك؛ فإنها تعطيه حقه إلا أن يسمح عن حقه ويرضى بالطلاق من دون شيء، فهذا إليه، لكن إذا كانت هي التي أبغضته وكرهته لأسباب شرعية، لأسباب سوء عشرة، أو لأسباب بغضاء وقعت في قلبها؛ فإنها تعطيه ماله، أما إن كان الأسباب منه: ظلمها، تعدى عليها، أو تعاطى المسكرات، أو أشباه ذلك مما ينفرها منه، فلا حق له في المال، ولها أن تنفر منه، ولها أن تطالب بالطلاق؛ لأنه أساء عشرتها بما تعاطاه من ظلمه لها، وسوء عشرته لها، وتعاطيه المسكرات، أو سهره بالليل، فلا ينام معها إلا يسيرًا، وما أشبه ذلك من الآفات التي تنفر المرأة من زوجها، وهو الظالم لها في ذلك؛ فإن هذا عذر لها في طلب الطلاق ولا حق له في المهر؛ لأنه هو الظالم، وأعظم من ذلك ترك الصلاة، نعوذ بالله، فإنه يكفر بذلك، وليس لها البقاء معه بعد ذلك حتى يتوب إلى الله، فلها أن تخرج إلى أهلها، وتمنعه من نفسها، حتى يصلي، حتى يتوب، وهكذا إذا تركت الصلاة هي؛ فإنها تكفر بذلك، وعليه أن ينصحها، ويؤدبها ويجاهدها، فإذا لم ترجع لم يحل له بقاؤها معه لكفرها؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر نسأل الله العافية، وهذا بلاء خطير وواقع كثير، ولا حول ولا قوة إلا بالله، نسأل الله للمسلمين الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17989/من-اسباب-الفشل-في-الحياة-الزوجية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_878/nour_87807.mp3","categories":["الحقوق الزوجية"]},{"id":19036,"question":"في آخر أسئلة السائلة من اليمن أم رشيدة اليمن الخضراء تقول: إذا دعاني الزوج من أجل أن يعلمني العلم الشرعي ولم أجبه؛ حيث إنني أغلب الأوقات مشغولة في البيت، هل أعتبر بذلك آثمة؟","title":"امتناع الزوجة عن التعلم بسبب أعمال البيت","answer":"الجواب: يخشى عليك من ذلك، الواجب عليك طاعة زوجك إذا دعاك أجيبي إذا دعاك أجيبي، إما أن يأمرك بشيء وإما أن تكون له حاجة فالواجب عليك أن تجيبيه، إلا من ضرورة لا تستطيعين معها الإجابة وإلا فالواجب الإجابة. نعم.","link":"https://binbaz.org.sa/fatwas/18206/امتناع-الزوجة-عن-التعلم-بسبب-اعمال-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88306.mp3","categories":["العالم والمتعلم","الحقوق الزوجية"]},{"id":19166,"question":"لدي زوجة وهي تعمل وتأخذ مرتب إذا أخذته منها أو أخذت البعض فهل يكون حلالًا أم حرامًا؟ جزاكم الله خيرًا.","title":"حكم أخذ الرجل راتب زوجته أو بعضه","answer":"الجواب: مرتبها لها، ومن مالها؛ إلا إذا سمحت لك بالراتب كله أو ببعضه سماحًا واضحًا، لا شبهة فيه؛ فلا بأس عليك؛ لقول الله  في سورة النساء: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا[النساء:4]. فإذا طابت نفسها بالراتب أو ببعض الراتب فلا حرج عليك، أما إن كنت توعدها بالطلاق، أو بالهجر، أو بالأذى؛ إن لم تعطك فهذا لا يجوز لك لأنها ما طابت نفسها بذلك، ولكن خوفًا منك، أو من طلاقك؛ سلمت لك المال أو بعض المال، لا فلا يجوز هذا، ولكن عليك بالكلام الطيب، والعشرة الطيبة؛ فإن سمحت بشيء فالحمد لله، وإلا فدعها ومالها، وأنفق عليها واصبر، وقم بالواجب، وأحسن الخلق خيركم خيركم لأهله، والرسول يقول ﷺ: البر حسن الخلق فعليك بحسن الخلق، وعدم الأذى والهجر لزوجتك بغير حق، ولا تكن سفيهًا، ولا تكن أيضًا سيء الخلق مع أهلك الله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ[النساء:19] هكذا يقول ربنا ، ويقول سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ[البقرة:228]. فالواجب أن تعاشرها بالكلام الطيب، والوجه المنبسط، والسيرة الحميدة، والإنفاق المناسب .. في الفراش وفي غير ذلك، تكون جيدًا في الفراش وفي غيره، بالخلق الحسن، بالكلام الطيب، وانبساط الوجه، وكف الأذى والضرب الذي بغير حق، هكذا يجب على الزوج. وعليها هي أيضًا أن تفعل مثل ذلك الخلق الطيب، والأسلوب الحسن، والكلام الطيب، والسيرة الحميدة، والسمع والطاعة لك في المعروف، هذا هو الواجب عليكما جميعًا، ومالها لها، ومالك لك، إلا إذا طبت نفسًا لها بشيء، أو طابت نفسها بشيء لك؛ فالأمر واسع والحمد لله، وإذا كانت لم تشرط عليك أنها تعمل فأنت بالخيار، إما أن تسمح لها، وراتبها لها، وإما أن تمنعها من العمل، وتبقى في البيت والحمد لله، أما إذا كان مشروطًا عليك أنها تعمل فالمسلمون على شروطهم، ويجب عليك أن تمكنها من شرطها لقول النبي ﷺ: إن أحق الشروط أن يوفى به ما استحللتم به الفروج متفق على صحته. فالواجب عليك تمكينها من أداء وظيفتها من تدريس وغيره كما شرط عليك ومالها لها إلا أن تسمح لك بشيء منه أو بكله وهي رشيدة فلا بأس عليك، والحمد لله لكن من دون إكراه، من دون ظلم لها وإيذاء لها إذا سمحت من دون إكراه ومن دون أذى فلا بأس والحمد لله. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18354/حكم-اخذ-الرجل-راتب-زوجته-او-بعضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79806.mp3","categories":["الحقوق الزوجية"]},{"id":19168,"question":"أخونا أيضًا يسأل عن حكم خروج المرأة إلى الأسواق، أو إلى الجيران دون أن يعلم زوجها؟","title":"حكم خروج المرأة إلى الأسواق والجيران دون علم الزوج","answer":"الجواب: ليس لها أن تخرج إلى الأسواق، ولا إلى الجيران إلا بإذنه، إلا إذا أعطاها إذنًا مطلقًا أن تخرج لما تشاء من حاجاتها فلا بأس، وإلا فعليها أن تتقيد بالسمع والطاعة، إذا كان قد قام بحاجتها ولم يقصر فلا تخرج إلا بإذنه، أما إذا كان لا يبالي بها، ولا يعطيها حاجتها فلها أن تخرج لحاجتها، كشراء الخبز، وكشراء الماء، ونحو هذا مما تحتاج إليه، أو استعارة بعض الحاجة من جيرانها؛ لأنه مقصر، أما إذا أعطاها حاجتها المعتادة، فليس لها أن تخرج إلا بإذنه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18379/حكم-خروج-المراة-الى-الاسواق-والجيران-دون-علم-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_887/nour_88707.mp3","categories":["الحقوق الزوجية"]},{"id":19203,"question":"الواقع كدت سماحة الشيخ أطلب من سماحتكم نصيحة إلى الأخوات المتزوجات، فكثير من الإخوة عندما يتزوج وهذه نيته يريد على الأقل أن يكتسب الإنفاق على أخت مسلمة لا عائل لها، زوجته تغادر المنزل وتقوم وتولول وتفسد أولاده عليه وتؤنبهم عليه أيضًا.","title":"حكم تذمر النساء من تعدد الزوجات والإنكار على الأزواج","answer":"الجواب:\n\nهذا منكر مثلما سمعت، هذا منكر وليس لها أن تفعل ذلك، ليس لأي زوجة أن تنكر على زوجها ذلك، وليس لها أن تعترض عليه، وليس لها أن تسيء إليه، ولا إلى أولاده، وإنما فعل ما أباح الله له.\n\nنعم، إذا ظلم، إذا جار عليها.. إذا لم يعدل فلها أن تتكلم، ولها أن تشكوه إلى المحكمة إلا أن تصبر وتحتسب، أما ما دام لم تر منه إلا الخير، أو حتى الآن ما بعد فعل شيئًا فإنها تصبر وتحتسب، وترجو الله أن يقدر لها الأصلح، وأن يعينها على الصبر، وسوف يجعل الله فرجًا ومخرجًا يقول الله  في كتابه العظيم: فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا [النساء:19]، ويقول سبحانه: كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَكُمْ وَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَكُمْ وَعَسَى أَنْ تُحِبُّوا شَيْئًا وَهُوَ شَرٌّ لَكُمْ وَاللَّهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [البقرة:216].\n\nفالله هو اللي يعلم ، فربما كان هذا الزواج سببًا لعطفه عليها ومزيد محبته لها؛ لأنه رأى من الثانية ما لم ير من الأولى، ورأى أن خصال الأولى أحسن وأن سيرتها أطيب، وأن دينها أكمل، فيعطف عليها أكثر، وربما طلق الثانية وزاد حبه للأولى، فلا ينبغي لها أن تجزع من هذا، فربما كان خيرًا لها، وإن نجح في زواجه وعدل بينهما فالحمد لله، المؤمن يحب لأخيه ما يحب لنفسه، فينبغي لها أن تحب لأخواتها في الله أن يرزقهن الله أزواجًا وذريات، هكذا المؤمن مع أخيه، يقول النبي ﷺ: لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه.\nوهكذا لا تؤمن المؤمنة حتى تحب لأختها ما تحب لنفسها، هذا معنى كلامه عليه الصلاة والسلام؛ لأن قوله يعم الرجال والنساء، والله المستعان. نعم.\nالمقدم: والله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18400/حكم-تذمر-النساء-من-تعدد-الزوجات-والانكار-على-الازواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_888/nour_88807.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":19204,"question":"ننتقل بعد هذا إلى قضايا أخرى ورسائل أخرى، فرسالة وصلت إلى البرنامج من المستمع ( علي. س.س.) من الجنوب، أخونا يسأل سماحة الشيخ عن الحكم فيمن يعدد الزوجات، وهل يصغي إلى الأقوال القائلة بأن ذلك يخالف الفطرة؟ وجهونا جزاكم الله خيرًا.","title":"ترك تعدد الزوجات سبب في كثرة العوانس في البيوت","answer":"الجواب: قد شرع الله  لعباده تعدد النساء إذا استطاع الزوج ذلك، ولم يخف الجور والعول في قوله جل وعلا: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3] ، وقد تزوج النبي ﷺ عدة من النساء، وتوفي ﷺ وعنده تسع، وهذا من خصائصه عليه الصلاة والسلام فيما زاد عن أربع. أما الأمة فليس لهم إلا أربع فقط، قد فرق النبي ﷺ بين من أسلم على أكثر من أربع، وأمره أن يفارق الزائد، وخيره أن يختار أربعًا ويفارق ما زاد على ذلك. فالواجب على المسلم أن يقف عند حد الله، وأن لا يزيد على ما شرع الله وهو الأربع، فإذا استطاع أن يتزوج أربعًا وقام بحقهن فلا حرج عليه في ذلك، بل ذلك أفضل له إذا استطاع ذلك لما في ذلك من المصالح من: عفة فرجه، وغض بصره، وتكثير الأمة، وتكثير النسل الذي قد ينفع الله به الأمة، وقد يعبد الله ويدعو لوالديه فيحصل لهم بذلك الخير العظيم. ولولا أنه أمر مطلوب وأمر مشروع وفيه مصالح جمة لما فعله النبي عليه الصلاة والسلام، فهو أفضل الناس وخير الناس وأحرصهم على كل خير عليه الصلاة والسلام، وقد جعل الله في تزوجه بالعدد الكثير من النساء مصالح كثيرة في تبليغ الدعوة ونشر الإسلام من طريق النساء، ومن طريق الرجال. فإذا تزوج المؤمن ثنتين أو ثلاثًا أو أربعًا لمصالح شرعية؛ لأنه يحتاج إلى ذلك، أو لقصد تكثير الأولاد أو لقصد كمال العفة وكمال غض البصر؛ لأنه قد لا تكفيه الواحدة أو الاثنتان أو الثلاث، فكل هذا أمر مطلوب شرعي، ولا يجوز لأي مسلم ولا لأي مسلمة الاعتراض على ذلك، ولا يجوز انتقاد ذلك، ولا يجوز لأي إذاعة ولا أي تلفاز أن ينشر ما يعارض ذلك، بل يجب على جميع وسائل الإعلام أن تقف عند حدها، وليس لها أن تنكر هذا الأمر المشروع، ولا يجوز لمن يقوم على وسائل الإعلام أن ينشر مقالًا لمن يعترض على ذلك، لا في الوسائل المقروءة ولا في الوسائل المسموعة، ولا في الوسائل المرئية، بل يجب على وزراء الإعلام في الدول الإسلامية أن يحذروا ذلك، وأن يتقوا الله وأن يبتعدوا عما حرم الله . وهل يرضى مسلم أن تبقى النساء عوانس في البيوت! والإنسان يستطيع يأخذ ثنتين وثلاثًا وأربعًا، هذا لا يجوز أن يفعله مسلم أو يراه مسلم يخاف الله ويرجوه. وهل يجوز لمسلمة تخاف الله وترجوه أن تنكر ذلك، وهي تعلم يقينًا أن كونها مع زوج عنده زوجة أو زوجتان أو ثلاث خير لها من بقائها بدون زوج حتى تموت عانسة لا زوج لها، وربما رزقها الله بهذا الزوج الذي ليس لها إلا جزء منه، ربما رزقها الله ذرية صالحة تنفعها في الدنيا والآخرة، وربما حصل لها بذلك عفة فرجها وغض بصرها وحسن سمعتها وسلامة عرضها. فالواجب على الدول الإسلامية عامة وعلى حكومتنا خاصة إظهار هذا الأمر وتأييد هذا الأمر، والإنكار على من عارض هذا الأمر في أي وسيلة مرئية أو مسموعة أو مقروءة، بل يجب إنكار ذلك. وإنه ليسوءني كثيرًا ويسوء كل مسلم يخاف الله أن يسمع في إذاعة أو يشاهد في تلفاز أو يقرأ في صحيفة من يعترض على شرع الله، ويدعو إلى الاقتصار على الواحدة، إلا على الوجه الشرعي إذا خاف ألا يقوم بالواجب، أو عجز عن أن يقوم باثنتين، فهذا قد وضحه الله  لكن من استطاع أن يتزوج ثنتين أو ثلاثًا أو أربعًا فلا حرج عليه، بل هو مأجور ومشكور إذا نوى بذلك إظهار دين الله وتكثير الأمة وغض بصره وإحصان فرجه، والإحسان إلى أخواته في الله المحتاجات إلى النكاح، فهو مشكور ومأجور. والواجب على جميع المسلمين وعلى جميع المسلمات أن يرضوا بما شرع الله، وأن يحذروا الاعتراض على ما شرعه الله، وأن يخافوا نقمته سبحانه وعقابه في اعتراضهم ومخالفتهم لأمر الله ، وقد قال الله  في كتابه العظيم: ذَلِكَ بِأَنَّهُمْ كَرِهُوا مَا أَنزَلَ اللَّهُ فَأَحْبَطَ أَعْمَالَهُمْ [محمد:9] ، فأخشى على من كره هذا المشروع أن يحبط عمله وأن يخرج من دينه وهو لا يشعر، نسأل الله العافية. وقال تعالى: ذَلِكَ بِأَنَّهُمُ اتَّبَعُوا مَا أَسْخَطَ اللَّهَ وَكَرِهُوا رِضْوَانَهُ فَأَحْبَطَ أَعْمَالَهُمْ [محمد:28].\nفالمقصود أنه يجب على المؤمن أن يرضى بما شرعه الله، وأن يبغض ما أبغضه الله، وأن يكره ما كرهه الله، وأن يحب ما أحبه الله في جميع الأمور، إذا كان مسلمًا مؤمنًا يخاف الله ويرجوه، نسأل الله للجميع الهداية والسلامة. المقدم: اللهم آمين، جزاكم الله خيرًا الواقع سماحة الشيخ وأنتم تتفضلون بهذا التوجيه المخلص كثيرًا ما نسمع عن كثرة العوانس في البيوت، لعل لكم من كلمة سماحة الشيخ؟ الشيخ: هذا ثابت عندنا، ولهذا نوصي جميع النساء أن لا يمتنعن من الزوج الذي عنده زوجة، نوصيهن جميعًا أن يحرصن على عفتهن وسمعتهن الحسنة، وعلى حفظ فروجهن وغض أبصارهن، وعلى حفظ أعراضهن أن يبادرن بالزواج ولو كن جارات، ولو كانت ثانية أو ثالثة أو رابعة، فأنا أوصي بهذا، وأسأل الله أن يهدينا جميعًا لما يرضيه، وأوصي الأزواج القادرين أن يتزوجوا وأن يعفوا كثيرًا من نساء أمتهم، وأن يحرصوا على تكثير النسل، وعلى حفظ فروجهم وغض أبصارهم بما أحل الله لا ما حرم الله. كثير من الناس -نعوذ بالله- يأبى أن يتزوج ثانية، ولكنه يرضى بالصديقات فيما حرم الله، وتعلم زوجته ذلك، وذلك قد يكون أحب إليها من زوجة مسلمة على الوجه الشرعي، فهي تعلم عنه أنه يذهب إلى المحرمات وإلى الصديقات وإلى الزنا، ولكن لا يهمها ذلك، لكن لو تزوج لغضبت وأنكرت ولا حول ولا قوة إلا بالله، فترضى بالحرام أو تقر الحرام ولكن لا ترضى بالحلال، هذه من المصائب، ومن ضعف الدين ومن ضعف الإيمان وقلة البصيرة، نسأل الله الهداية والسلامة. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18399/ترك-تعدد-الزوجات-سبب-في-كثرة-العوانس-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_888/nour_88806.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":19520,"question":"تقول السائلة سماحة الشيخ: تذكر بأنها فتاة تبلغ من العمر خمسة عشر عامًا، زوجوها الأهل تقول: من قريب لهم لا ترضاه، ويحصل -تقول-: بينها وبينه مشاجرة دائمًا، وتشعر بالهم والحزن، وتؤدي الطلبات كلها ما عدا تقول: عند النوم، هل تأثم بذلك؟ وماذا يلزمها ويلزم هذا الزوج؟","title":"نصيحة لزوجة امتنعت عن فراش زوجها","answer":"الجواب: عليها السمع والطاعة لزوجها وتمكينه من نفسها، لو كانت صادقة ما دخلت عليه، ما دام دخلت عليه فهذا علامة إنها رضيت. فعليها السمع والطاعة للزوج، وتمكينه من نفسها، وعليها الخلق الكريم والتلطف حتى تصلح الحال بينهما. نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18765/نصيحة-لزوجة-امتنعت-عن-فراش-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93932.mp3","categories":["الحقوق الزوجية"]},{"id":19657,"question":"تقول هذه السائلة يا سماحة الشيخ، امرأة كانت تأخذ من المصروف الذي خصصه لها زوجها، فتشتري حاجات مباحة لأناس لا يرغب فيهم هذا الزوج، ثم حصل الفراق بينها وبينه وهي نادمة الآن، فهل عليها إثم؟ وكيف الخلاص من ذلك إن كان ذنبًا؟","title":"حكم أخذ الزوجة من مال زوجها بغير إذنه","answer":"الجواب: ليس لها ذلك، ليس لها أن تخرج من ماله إلا بإذنه، ما دام نهاها أن تعطيهم ليس لها أن تعطيهم إلا بإذنه إلا من مالها، فإذا طلقها وهي تعرف ما أخرجت، فالأحوط لها أن ترده عليه أو تستأذنه أو تستبيحه تقول له: إني فعلت كذا سامحني، أو ترد عليه ما أخذت. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18941/حكم-اخذ-الزوجة-من-مال-زوجها-بغير-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95011.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":19703,"question":"الواجب في العدل بين النساء هل هو في المبيت والنفقة فقط؟","title":"فيم يكون العدل بين النساء","answer":"الجواب: في القسم والنفقة، كلٌّ على قدره، يقول ﷺ: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك، يقسم بينهم، والنفقة على حسب أحوالهن، فمَن كانت عندها عيال فإنَّ نفقتها أكثر، كلٌّ على قدره.","link":"https://binbaz.org.sa/fatwas/21693/فيم-يكون-العدل-بين-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D9%81%D9%8A%D9%85%20%D9%8A%D9%83%D9%88%D9%86%20%D8%A7%D9%84%D8%B9%D8%AF%D9%84%20%D8%A8%D9%8A%D9%86%20%D8%A7%D9%84%D9%86%D8%B3%D8%A7%D8%A1.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]}]
